const e=JSON.parse(`[{"id":"a1-lin","level":"A1","title":"Lin's Day","topic":"學校生活","words":69,"paras":["Lin is a nursing student. She is twenty years old. She lives in Taichung with her parents.","Every morning, Lin gets up at six. She eats bread and drinks milk. Then she takes the bus to school. Her classes start at eight.","Lin likes her anatomy class, but it is hard. After school, she studies in the library. She goes home at seven and has dinner with her family."],"zh":"林是護理系學生，二十歲，和父母住在台中。她每天六點起床，吃麵包喝牛奶，搭公車上學，八點上課。她喜歡解剖學但覺得很難。放學後在圖書館讀書，七點回家和家人吃晚餐。","qs":[{"type":"main","q":"What is this text mainly about?","options":["A day in Lin's life","How to take the bus","Lin's parents' jobs"],"answer":0,"why":"整篇都在說林一天做的事，從起床到晚餐。"},{"type":"detail","q":"How does Lin go to school?","options":["Her father drives her.","She walks.","She takes the bus."],"answer":2,"why":"第二段：She takes the bus to school.","evidence":"Then she takes the bus to school."},{"type":"reference","q":"In \\"but it is hard\\", what does \\"it\\" mean?","options":["Her anatomy class","The library","The bus"],"answer":0,"why":"it 指前面剛提到的 anatomy class（解剖學課）。","evidence":"Lin likes her anatomy class, but it is hard."},{"type":"detail","q":"Where does Lin study after school?","options":["At home","In the library","On the bus"],"answer":1,"why":"After school, she studies in the library.","evidence":"After school, she studies in the library."},{"type":"detail","q":"When does Lin start classes?","options":["At seven","At eight","At six"],"answer":1,"why":"八點是開始上課的時間；六點是起床，七點是回家。","evidence":"Her classes start at eight."}],"band":"hard"},{"id":"a1-clinic","level":"A1","title":"At the Clinic","topic":"看診","words":76,"paras":["Tom has a bad cold. He has a sore throat and a runny nose. Today he goes to a small clinic near his home.","A nurse asks his name and his date of birth. She checks his temperature. It is 37.8°C. \\"You have a slight fever,\\" she says.","The doctor gives Tom some medicine. \\"Take it three times a day, after meals,\\" the nurse tells him. \\"Drink a lot of water and get some rest.\\""],"zh":"湯姆重感冒，喉嚨痛、流鼻水，今天去家附近的小診所。護理師問他姓名和生日，量體溫 37.8 度，說他有點發燒。醫師開藥，護理師說一天三次飯後吃，多喝水多休息。","qs":[{"type":"detail","q":"Why does Tom go to the clinic?","options":["He has a bad cold.","He broke his arm.","He needs a new job."],"answer":0,"why":"第一句：Tom has a bad cold.","evidence":"Tom has a bad cold."},{"type":"vocab","q":"In this text, \\"slight\\" in \\"a slight fever\\" means…","options":["no","very high","a little"],"answer":2,"why":"37.8°C 只比正常高一點，所以 slight 是「輕微的、一點點」。","evidence":"\\"You have a slight fever,\\""},{"type":"detail","q":"When should Tom take the medicine?","options":["Three times a day, after meals","When he feels hungry","Before bed only"],"answer":0,"why":"Take it three times a day, after meals.","evidence":"\\"Take it three times a day, after meals,\\""},{"type":"detail","q":"Who checks Tom's temperature?","options":["The doctor","The nurse","Tom's mother"],"answer":1,"why":"A nurse … She checks his temperature. She 指 the nurse。","evidence":"She checks his temperature."},{"type":"detail","q":"Who gives Tom some medicine?","options":["His mother","The doctor","The nurse"],"answer":1,"why":"文章說是醫師給湯姆藥；護理師說明題目中的服藥方式。","evidence":"The doctor gives Tom some medicine."}],"band":"hard"},{"id":"a1-water","level":"A1","title":"Drink Water","topic":"健康","words":71,"paras":["Our body needs water. When we do not drink enough water, we can feel tired. We can also get a headache.","Many people only drink water when they are thirsty. But it is better to drink a little water many times a day.","On hot days and after exercise, we need more water. Coffee and sweet drinks are not the same as water. Try to carry a water bottle with you."],"zh":"身體需要水，喝不夠會累、頭痛。很多人口渴才喝，但最好一天分很多次喝一點。天熱和運動後需要更多水。咖啡和含糖飲料跟水不一樣，試著隨身帶水壺。","qs":[{"type":"main","q":"What is the best title for this text?","options":["How to make coffee","The best sweet drinks","Why and how to drink water"],"answer":2,"why":"全文說為什麼要喝水、怎麼喝。"},{"type":"detail","q":"What can happen if we do not drink enough water?","options":["We feel tired.","We grow taller.","We sleep less."],"answer":0,"why":"When we do not drink enough water, we can feel tired.","evidence":"we can feel tired"},{"type":"detail","q":"When do we need more water?","options":["Before dinner only","On cold mornings","On hot days and after exercise"],"answer":2,"why":"On hot days and after exercise, we need more water.","evidence":"On hot days and after exercise, we need more water."},{"type":"detail","q":"What does the writer suggest?","options":["Carry a water bottle.","Drink coffee instead of water.","Drink only when you are thirsty."],"answer":0,"why":"最後一句：Try to carry a water bottle with you.","evidence":"Try to carry a water bottle with you."},{"type":"vocab","q":"A person who is \\"thirsty\\" feels a need to…","options":["put on a coat","drink something","go to sleep"],"answer":1,"why":"thirsty 是「口渴的」，不是累或冷。文章接著談喝水。","evidence":"Many people only drink water when they are thirsty."}],"band":"hard"},{"id":"a1-grandma","level":"A1","title":"My Grandmother","topic":"家人","words":72,"paras":["My grandmother is seventy-eight years old. She lives with us. She has high blood pressure, so she takes medicine every morning.","I help her check her blood pressure. We write the numbers in a small notebook. Then we show the notebook to her doctor every month.","My grandmother walks in the park every evening. She says walking makes her feel happy. I want to be a nurse because I like helping her."],"zh":"我奶奶七十八歲，跟我們住，有高血壓，每天早上吃藥。我幫她量血壓，把數字寫在小本子上，每個月給醫師看。她每天傍晚去公園走路，說走路讓她開心。我想當護理師，因為我喜歡幫她。","qs":[{"type":"detail","q":"Why does the grandmother take medicine?","options":["She cannot sleep.","She has high blood pressure.","She has a cold."],"answer":1,"why":"She has high blood pressure, so she takes medicine.","evidence":"She has high blood pressure, so she takes medicine every morning."},{"type":"detail","q":"What do they do with the notebook?","options":["They read stories in it.","They give it to the park.","They show it to the doctor every month."],"answer":2,"why":"Then we show the notebook to her doctor every month.","evidence":"Then we show the notebook to her doctor every month."},{"type":"reference","q":"\\"She says walking makes her feel happy.\\" Who is \\"She\\"?","options":["The doctor","The grandmother","The writer"],"answer":1,"why":"這段一直在說 my grandmother，She 就是奶奶。","evidence":"She says walking makes her feel happy."},{"type":"evidence","q":"Which sentence shows why the writer wants to be a nurse?","options":["\\"We write the numbers in a small notebook.\\"","\\"She lives with us.\\"","\\"I like helping her.\\""],"answer":2,"why":"because 後面就是原因：I like helping her。","evidence":"I want to be a nurse because I like helping her."},{"type":"detail","q":"How old is the grandmother?","options":["Seventy-eight","Sixty-eight","Eighty-seven"],"answer":0,"why":"第一句直接寫 seventy-eight，也就是七十八歲。","evidence":"My grandmother is seventy-eight years old."}],"band":"hard"},{"id":"a1-hospital","level":"A1","title":"The Hospital Map","topic":"醫院","words":69,"paras":["Welcome to City Hospital. The main door is on Park Road. The information desk is next to the main door.","The pharmacy is on the first floor, behind the information desk. The X-ray room is on the second floor. The children's ward is on the third floor.","Visiting hours are from 2 p.m. to 8 p.m. Please wash your hands before you enter a ward. Thank you."],"zh":"歡迎來到市立醫院。正門在公園路，服務台在正門旁。藥局在一樓服務台後面，X 光室在二樓，兒科病房在三樓。探病時間下午兩點到晚上八點，進病房前請洗手。","qs":[{"type":"detail","q":"Where is the pharmacy?","options":["On the first floor, behind the information desk","Next to the X-ray room","On the third floor"],"answer":0,"why":"The pharmacy is on the first floor, behind the information desk.","evidence":"The pharmacy is on the first floor, behind the information desk."},{"type":"detail","q":"Which floor is the children's ward on?","options":["The first floor","The second floor","The third floor"],"answer":2,"why":"The children's ward is on the third floor.","evidence":"The children's ward is on the third floor."},{"type":"detail","q":"Can you visit a patient at 9 p.m.?","options":["Only on weekends","Yes, any time","No, visiting hours end at 8 p.m."],"answer":2,"why":"Visiting hours are from 2 p.m. to 8 p.m.，九點已經過了。","evidence":"Visiting hours are from 2 p.m. to 8 p.m."},{"type":"vocab","q":"A \\"ward\\" in a hospital is…","options":["a kind of medicine","a doctor's office","a room or area where patients stay"],"answer":2,"why":"children's ward 是兒科病房；ward 是病人住的病房區。","evidence":"The children's ward is on the third floor."},{"type":"main","q":"What can a visitor learn from this notice?","options":["How to prepare medicine","Where hospital places are and when to visit","How to take an X-ray picture"],"answer":1,"why":"文章列出各處位置和探病時間，沒有教操作儀器或配藥。"}],"band":"hard"},{"id":"a1-family","level":"A1","title":"My Family","topic":"家人","words":72,"paras":["There are five people in my family. My father is a bus driver. My mother is a teacher. They are both forty-eight years old.","I am twenty. I have one brother and one sister. My brother Kevin is sixteen. He likes basketball. My sister Mei is ten. She likes to draw.","We live in a small apartment in Tainan. On Sundays, we eat dinner at my grandparents' house. I love my family."],"zh":"我家有五個人。爸爸是公車司機，媽媽是老師，他們都四十八歲。我二十歲，有一個弟弟和一個妹妹。弟弟 Kevin 十六歲，喜歡籃球；妹妹 Mei 十歲，喜歡畫畫。我們住在台南的一間小公寓。星期天我們會到爺爺奶奶家吃晚餐。我愛我的家人。","qs":[{"type":"detail","q":"What is the father's job?","options":["He is a teacher.","He is a bus driver.","He is a doctor."],"answer":1,"why":"第一段：My father is a bus driver.（爸爸是公車司機）；teacher 是媽媽。","evidence":"My father is a bus driver."},{"type":"detail","q":"How many children are there in the family?","options":["Two","Five","Three"],"answer":2,"why":"作者自己，加上一個弟弟、一個妹妹，一共三個小孩。five 是全家的人數。","evidence":"I have one brother and one sister."},{"type":"reference","q":"In \\"They are both forty-eight years old,\\" who are \\"They\\"?","options":["The writer's father and mother","Kevin and Mei","The grandparents"],"answer":0,"why":"They 指前面兩句剛提到的 my father 和 my mother。","evidence":"They are both forty-eight years old."},{"type":"detail","q":"Where does the family eat dinner on Sundays?","options":["At a restaurant","In their apartment","At the grandparents' house"],"answer":2,"why":"最後一段：On Sundays, we eat dinner at my grandparents' house.","evidence":"On Sundays, we eat dinner at my grandparents' house."},{"type":"detail","q":"What does Kevin like?","options":["Driving buses","Basketball","Drawing"],"answer":1,"why":"Kevin 後面的 He 指弟弟；畫畫是妹妹的喜好。","evidence":"He likes basketball."}],"band":"mid"},{"id":"a1-weekend","level":"A1","title":"My Saturday","topic":"日常","words":67,"paras":["On Saturday, I do not go to school. I get up at nine and eat breakfast with my mother.","In the morning, I clean my room and wash my clothes. Then I go to the supermarket. I buy fruit, eggs, and milk.","In the afternoon, I play basketball with my friends in the park. At night, I watch a movie at home. Saturday is my favorite day."],"zh":"星期六我不用上學。我九點起床，和媽媽一起吃早餐。早上我打掃房間、洗衣服，然後去超市買水果、蛋和牛奶。下午我和朋友在公園打籃球。晚上我在家看電影。星期六是我最喜歡的一天。","qs":[{"type":"main","q":"What is this text about?","options":["What the writer does on Saturday","How to play basketball","The writer's school"],"answer":0,"why":"整篇從起床講到晚上，都是星期六做的事。"},{"type":"detail","q":"What time does the writer get up on Saturday?","options":["At six","At nine","At noon"],"answer":1,"why":"第一段：I get up at nine.","evidence":"I get up at nine and eat breakfast with my mother."},{"type":"detail","q":"What does the writer buy at the supermarket?","options":["Bread and tea","Clothes and shoes","Fruit, eggs, and milk"],"answer":2,"why":"I buy fruit, eggs, and milk.（水果、蛋和牛奶）","evidence":"I buy fruit, eggs, and milk."},{"type":"vocab","q":"\\"Saturday is my favorite day.\\" Here \\"favorite\\" means…","options":["the one I like best","the busiest","the last"],"answer":0,"why":"favorite 是「最喜歡的」。星期六不用上學、可以打球看電影，所以是最喜歡的一天。","evidence":"Saturday is my favorite day."},{"type":"detail","q":"What does the writer do at night?","options":["Buy food at the supermarket","Watch a movie at home","Play basketball in the park"],"answer":1,"why":"晚上在家看電影；打球是下午，買東西在上午。","evidence":"At night, I watch a movie at home."}],"band":"hard"},{"id":"a1-room","level":"A1","title":"My Room","topic":"住處","words":72,"paras":["This is my room. It is small, but it is clean. There is a bed next to the window.","My desk is in front of the bed. There are many books on the desk. My computer is on the desk, too. My bag is under the chair.","There is a picture of my family on the wall. I study in my room every night. I like my room because it is quiet."],"zh":"這是我的房間。它很小，但是很乾淨。窗戶旁邊有一張床。書桌在床的前面，桌上有很多書，我的電腦也在桌上。我的包包在椅子下面。牆上有一張全家福照片。我每天晚上在房間讀書。我喜歡我的房間，因為它很安靜。","qs":[{"type":"detail","q":"Where is the bed?","options":["Next to the window","Under the desk","In front of the door"],"answer":0,"why":"There is a bed next to the window.（next to 是「在…旁邊」）","evidence":"There is a bed next to the window."},{"type":"detail","q":"What is under the chair?","options":["The computer","The bag","The books"],"answer":1,"why":"My bag is under the chair.（under 是「在…下面」）；電腦和書在桌上。","evidence":"My bag is under the chair."},{"type":"reference","q":"In \\"because it is quiet,\\" what does \\"it\\" mean?","options":["The wall","The picture","The room"],"answer":2,"why":"it 指同一句前面的 my room。","evidence":"I like my room because it is quiet."},{"type":"detail","q":"Which is true about the room?","options":["It is big and dirty.","It is small and clean.","It has no window."],"answer":1,"why":"第一段：It is small, but it is clean.；床在窗戶旁邊，所以有窗戶。","evidence":"It is small, but it is clean."},{"type":"detail","q":"What is on the wall?","options":["A school bag","A family picture","A computer"],"answer":1,"why":"牆上是全家福；電腦在桌上，書包在椅子下面。","evidence":"There is a picture of my family on the wall."}],"band":"hard"},{"id":"a1-breakfast","level":"A1","title":"The Breakfast Shop","topic":"飲食","words":69,"paras":["There is a breakfast shop near my school. It opens at six in the morning and closes at eleven.","The shop sells sandwiches, egg pancakes, and noodles. A sandwich is thirty dollars. A cup of milk tea is twenty dollars.","I go there every morning before class. I usually buy an egg pancake and a cup of soy milk. The owner is very nice. She always says, \\"Good morning!\\""],"zh":"我的學校附近有一家早餐店，早上六點開，十一點關。店裡賣三明治、蛋餅和麵。三明治三十元，一杯奶茶二十元。我每天早上上課前都會去，通常買一份蛋餅和一杯豆漿。老闆人很好，她總是說「早安！」","qs":[{"type":"detail","q":"When does the shop close?","options":["At six in the morning","At eleven","At noon"],"answer":1,"why":"It opens at six in the morning and closes at eleven. opens 是開門，closes 是關門。","evidence":"It opens at six in the morning and closes at eleven."},{"type":"detail","q":"How much are a sandwich and a cup of milk tea together?","options":["Thirty dollars","Twenty dollars","Fifty dollars"],"answer":2,"why":"三明治 30 元，加一杯奶茶 20 元，一共 50 元。"},{"type":"detail","q":"What does the writer usually buy?","options":["An egg pancake and soy milk","A sandwich and milk tea","Noodles and water"],"answer":0,"why":"I usually buy an egg pancake and a cup of soy milk.（蛋餅和豆漿）","evidence":"I usually buy an egg pancake and a cup of soy milk."},{"type":"reference","q":"\\"I go there every morning.\\" Where is \\"there\\"?","options":["The school","The breakfast shop","The writer's home"],"answer":1,"why":"前兩段都在講 the breakfast shop，there 指那家早餐店。","evidence":"I go there every morning before class."},{"type":"detail","q":"How often does the writer visit the shop?","options":["Every evening after dinner","Every morning before class","Only on weekends"],"answer":1,"why":"every morning 是每天早上，before class 是上課前。","evidence":"I go there every morning before class."}],"band":"hard"},{"id":"a1-weather","level":"A1","title":"This Week's Weather","topic":"天氣","words":68,"paras":["Here is the weather for this week in Taipei.","Monday and Tuesday are sunny and hot. Please drink a lot of water. Wednesday is cloudy, but it is not cold. It is rainy on Thursday and Friday, so take an umbrella with you.","The weekend is cool and windy. It is a good time to walk in the park, but you need a jacket. Have a nice week!"],"zh":"這是台北這一週的天氣。星期一和星期二晴朗炎熱，請多喝水。星期三多雲，但是不冷。星期四和星期五會下雨，所以要帶傘。週末涼爽有風，很適合去公園散步，但是需要穿外套。祝你有愉快的一週！","qs":[{"type":"detail","q":"How is the weather on Monday?","options":["Sunny and hot","Rainy","Cool and windy"],"answer":0,"why":"Monday and Tuesday are sunny and hot.（晴朗又熱）","evidence":"Monday and Tuesday are sunny and hot."},{"type":"detail","q":"Which days are rainy?","options":["Monday and Tuesday","Saturday and Sunday","Thursday and Friday"],"answer":2,"why":"It is rainy on Thursday and Friday.（星期四和星期五下雨）","evidence":"It is rainy on Thursday and Friday, so take an umbrella with you."},{"type":"detail","q":"What do you need on the weekend?","options":["An umbrella","A jacket","A lot of water"],"answer":1,"why":"週末涼又有風，you need a jacket（外套）。雨傘是星期四、五用的。","evidence":"It is a good time to walk in the park, but you need a jacket."},{"type":"main","q":"What is this text?","options":["A weather report for one week","A story about a park","A letter to a friend"],"answer":0,"why":"第一句就說 Here is the weather for this week，後面一天一天講天氣。"},{"type":"detail","q":"What is Wednesday like?","options":["Rainy and cold","Cloudy but not cold","Sunny and hot"],"answer":1,"why":"星期三是多雲，但不冷；晴熱的是星期一和星期二。","evidence":"Wednesday is cloudy, but it is not cold."}],"band":"hard"},{"id":"a1-dog","level":"A1","title":"My Dog Lucky","topic":"寵物","words":75,"paras":["I have a dog. His name is Lucky. He is three years old. He is white and has short legs.","Lucky likes to eat and sleep. He eats two times a day. He does not like baths, so he runs away when he sees water.","Every evening, I walk Lucky in the park. He plays with other dogs there. When I come home from school, he is always at the door. He makes me happy."],"zh":"我有一隻狗，名字叫 Lucky。牠三歲，白色，腿短短的。Lucky 喜歡吃和睡，一天吃兩次。牠不喜歡洗澡，所以看到水就跑走。每天傍晚我帶 Lucky 去公園散步，牠在那裡和其他的狗玩。我放學回家時，牠總是在門口。牠讓我很開心。","qs":[{"type":"detail","q":"What does Lucky look like?","options":["He is black and big.","He is white and has short legs.","He is brown and has long ears."],"answer":1,"why":"He is white and has short legs.（白色、腿短）","evidence":"He is white and has short legs."},{"type":"detail","q":"How often does Lucky eat?","options":["Once a day","Three times a day","Twice a day"],"answer":2,"why":"two times a day 就是 twice a day，一天兩次。","evidence":"He eats two times a day."},{"type":"detail","q":"Why does Lucky run away when he sees water?","options":["He does not like baths.","He is thirsty.","He wants to swim."],"answer":0,"why":"so 前面是原因：He does not like baths（不喜歡洗澡）。","evidence":"He does not like baths, so he runs away when he sees water."},{"type":"reference","q":"\\"He plays with other dogs there.\\" Where is \\"there\\"?","options":["At school","At the door","In the park"],"answer":2,"why":"前一句說 I walk Lucky in the park，there 指公園。","evidence":"He plays with other dogs there."},{"type":"main","q":"Which topic connects all three paragraphs?","options":["Different kinds of dog food","Lucky and his daily life","Rules for dogs at school"],"answer":1,"why":"年齡、外表、吃飯、散步和迎接主人都在介紹 Lucky。"}],"band":"hard"},{"id":"a1-note","level":"A1","title":"A Note from Mom","topic":"便條","words":69,"paras":["Dear Jay,","I am at work today. I will be home at seven. Your lunch is in the fridge. Please heat it before you eat.","After lunch, please do two things. First, take the clothes inside, because it may rain this afternoon. Second, feed the cat at five. Her food is on the kitchen table.","Do not play games all day. Call me if you need help.","Love,\\nMom"],"zh":"親愛的 Jay：我今天要上班，七點會到家。你的午餐在冰箱裡，吃之前請先加熱。午餐後請做兩件事：第一，把衣服收進來，因為今天下午可能會下雨；第二，五點餵貓，牠的食物在廚房的桌上。不要整天打電動。需要幫忙就打電話給我。愛你的媽媽","qs":[{"type":"detail","q":"Where is Jay's lunch?","options":["On the kitchen table","In the fridge","At Mom's office"],"answer":1,"why":"Your lunch is in the fridge.（在冰箱裡）；廚房桌上的是貓的食物。","evidence":"Your lunch is in the fridge."},{"type":"detail","q":"Why should Jay take the clothes inside?","options":["Because it may rain","Because they are dirty","Because Mom needs them at work"],"answer":0,"why":"because 後面是原因：it may rain this afternoon（下午可能下雨）。","evidence":"First, take the clothes inside, because it may rain this afternoon."},{"type":"detail","q":"What should Jay do at five?","options":["Call Mom","Eat lunch","Feed the cat"],"answer":2,"why":"Second, feed the cat at five.（五點餵貓）","evidence":"Second, feed the cat at five."},{"type":"reference","q":"\\"Please heat it before you eat.\\" What is \\"it\\"?","options":["The fridge","The lunch","The cat's food"],"answer":1,"why":"it 指前一句的 your lunch：午餐吃之前先加熱。","evidence":"Please heat it before you eat."},{"type":"detail","q":"When will Mom be home?","options":["At noon","At seven","At five"],"answer":1,"why":"媽媽七點回家；五點是餵貓的時間。","evidence":"I will be home at seven."}],"band":"hard"},{"id":"a1-market","level":"A1","title":"The Night Market","topic":"休閒","words":73,"paras":["There is a night market near my home. It is open every Friday and Saturday night.","Many people go there after dinner. They can eat fried chicken, noodles, and fruit. They can also buy cheap clothes and shoes. The food smells very good.","My favorite food at the night market is stinky tofu. My sister does not like it, so she always buys a cup of bubble tea. We go home at ten."],"zh":"我家附近有一個夜市，每個星期五和星期六晚上營業。很多人晚餐後去那裡，可以吃炸雞、麵和水果，也可以買便宜的衣服和鞋子。食物聞起來很香。我在夜市最喜歡吃臭豆腐。我妹妹不喜歡，所以她總是買一杯珍珠奶茶。我們十點回家。","qs":[{"type":"detail","q":"When is the night market open?","options":["Every night","On Friday and Saturday nights","On Sunday mornings"],"answer":1,"why":"It is open every Friday and Saturday night.（每個星期五、六晚上）","evidence":"It is open every Friday and Saturday night."},{"type":"detail","q":"What can people buy at the night market?","options":["Cheap clothes and shoes","Books and pens","Cars and bikes"],"answer":0,"why":"They can also buy cheap clothes and shoes.（便宜的衣服和鞋子）","evidence":"They can also buy cheap clothes and shoes."},{"type":"reference","q":"\\"My sister does not like it.\\" What is \\"it\\"?","options":["Bubble tea","The night market","Stinky tofu"],"answer":2,"why":"it 指前一句的 stinky tofu（臭豆腐）；她不喜歡，所以改買珍珠奶茶。","evidence":"My sister does not like it, so she always buys a cup of bubble tea."},{"type":"vocab","q":"\\"Cheap\\" clothes are clothes that…","options":["cost a lot of money","do not cost much money","are very old"],"answer":1,"why":"cheap 是「便宜的」，相反是 expensive（貴的）。","evidence":"They can also buy cheap clothes and shoes."},{"type":"detail","q":"When do the writer and the sister go home?","options":["At midnight","At ten","At eight"],"answer":1,"why":"最後一句說十點回家，不是夜市開門的時間。","evidence":"We go home at ten."}],"band":"hard"},{"id":"a1-library","level":"A1","title":"Library Rules","topic":"公告","words":67,"paras":["Welcome to the school library. The library is open from eight in the morning to nine at night, Monday to Friday. It is closed on weekends.","You can borrow five books for two weeks. Please bring your student card.","Please be quiet in the library. Do not eat or drink here. You can use your phone, but you cannot talk on it. Thank you for your help."],"zh":"歡迎來到學校圖書館。圖書館星期一到星期五，從早上八點開到晚上九點，週末不開。你可以借五本書，借兩個星期，請帶學生證。在圖書館請保持安靜，不要在這裡吃東西或喝飲料。可以用手機，但是不能講電話。謝謝你的配合。","qs":[{"type":"detail","q":"When is the library closed?","options":["On Mondays","At eight in the morning","On weekends"],"answer":2,"why":"It is closed on weekends.（週末不開）","evidence":"It is closed on weekends."},{"type":"detail","q":"How long can you keep the books?","options":["For two weeks","For five days","For one month"],"answer":0,"why":"You can borrow five books for two weeks. five 是可以借幾本，two weeks 才是可以借多久。","evidence":"You can borrow five books for two weeks."},{"type":"vocab","q":"To \\"borrow\\" a book means to…","options":["buy it","take it and give it back later","write it"],"answer":1,"why":"borrow 是「借（進來）」：拿走，之後要還。","evidence":"You can borrow five books for two weeks."},{"type":"detail","q":"Which of these is OK in the library?","options":["Eating a sandwich","Talking on the phone","Reading a message on your phone"],"answer":2,"why":"可以用手機（You can use your phone），但不能講電話；也不能吃東西。","evidence":"You can use your phone, but you cannot talk on it."},{"type":"detail","q":"How many books can a student borrow?","options":["Nine","Five","Two"],"answer":1,"why":"five books 是五本書；two weeks 是可以借多久。","evidence":"You can borrow five books for two weeks."}],"band":"hard"},{"id":"a1-teeth","level":"A1","title":"Clean Teeth","topic":"健康","words":71,"paras":["Your teeth are important. You use them to eat and to talk. Clean teeth also give you a nice smile.","Brush your teeth two times a day, in the morning and before bed. Brush for two minutes each time. Do not brush too hard.","Sweet food and sweet drinks are bad for your teeth. Drink water after you eat candy. Visit the dentist for check-ups. Your dentist tells you how often."],"zh":"牙齒很重要，你用它們吃東西和說話。乾淨的牙齒也讓你笑起來好看。一天刷兩次牙，早上和睡前各一次，每次刷兩分鐘，不要刷太用力。甜食和含糖飲料對牙齒不好，吃完糖果後要喝水。要定期看牙醫檢查，多久去一次聽牙醫的建議。","qs":[{"type":"main","q":"What is this text about?","options":["How to take care of your teeth","How to cook sweet food","How to become a dentist"],"answer":0,"why":"整篇在說牙齒為什麼重要、怎麼刷牙、什麼對牙齒不好。"},{"type":"detail","q":"How long should you brush each time?","options":["Six months","Two minutes","Two hours"],"answer":1,"why":"Brush for two minutes each time.（每次兩分鐘）。","evidence":"Brush for two minutes each time."},{"type":"reference","q":"\\"You use them to eat and to talk.\\" What are \\"them\\"?","options":["Your hands","Sweet drinks","Your teeth"],"answer":2,"why":"them 指前一句的 your teeth。","evidence":"You use them to eat and to talk."},{"type":"detail","q":"What is bad for your teeth?","options":["Water","Sweet food and sweet drinks","A nice smile"],"answer":1,"why":"Sweet food and sweet drinks are bad for your teeth.（甜食和含糖飲料）","evidence":"Sweet food and sweet drinks are bad for your teeth."},{"type":"detail","q":"How often does the text say to brush your teeth?","options":["After every drink","Twice a day","Once a week"],"answer":1,"why":"two times a day 是一天兩次；兩分鐘是每次的時間長度。","evidence":"Brush your teeth two times a day, in the morning and before bed."}],"band":"hard"},{"id":"a2-first-shift","level":"A2","title":"My First Day on the Ward","topic":"實習","words":128,"paras":["Last Monday was my first day of clinical practice. I was very nervous. I woke up at five, but I could not eat breakfast.","When I arrived at the hospital, my teacher introduced me to Ms. Huang, a senior nurse. She showed me the ward and explained the patients' charts. She spoke quickly, so I wrote everything in my notebook.","In the afternoon, I helped Ms. Huang take a patient's blood pressure. My hands were shaking, and I made a mistake the first time. Ms. Huang was patient. She said, \\"Everyone makes mistakes at the beginning. Try again slowly.\\" The second time, I did it correctly.","I was tired when I got home, but I felt proud. I learned that asking questions is better than pretending to understand."],"zh":"上週一是我第一天實習，很緊張，五點起床卻吃不下早餐。老師把我介紹給資深護理師黃小姐，她帶我看病房、解釋病歷，講很快所以我全記在本子上。下午幫她量血壓，手在抖第一次弄錯，她很有耐心說大家一開始都會錯，慢慢再來，第二次就對了。回家很累但很驕傲，學到問問題比假裝聽懂好。","qs":[{"type":"main","q":"What is the main idea of the text?","options":["How to measure blood pressure at home","Why Ms. Huang became a nurse","The writer's nervous but successful first day of practice"],"answer":2,"why":"文章從緊張開始，到最後覺得驕傲，是第一天實習的經過。"},{"type":"detail","q":"Why did the writer write everything in a notebook?","options":["Because Ms. Huang spoke quickly","Because the teacher asked for homework","Because the writer forgot a pen"],"answer":0,"why":"She spoke quickly, so I wrote everything in my notebook. so 前面是原因。","evidence":"She spoke quickly, so I wrote everything in my notebook."},{"type":"vocab","q":"\\"Ms. Huang was patient.\\" Here \\"patient\\" means…","options":["very busy","a person in hospital","calm and kind when someone is slow or makes mistakes"],"answer":2,"why":"這裡 patient 是形容詞「有耐心的」，後面她說慢慢再試一次就是證據。","evidence":"Ms. Huang was patient."},{"type":"detail","q":"What happened the second time the writer took blood pressure?","options":["The patient left.","Ms. Huang did it instead.","The writer did it correctly."],"answer":2,"why":"The second time, I did it correctly.","evidence":"The second time, I did it correctly."},{"type":"evidence","q":"Which sentence shows what the writer learned?","options":["\\"I woke up at five.\\"","\\"Asking questions is better than pretending to understand.\\"","\\"My hands were shaking.\\""],"answer":1,"why":"I learned that… 後面就是學到的事。","evidence":"I learned that asking questions is better than pretending to understand."},{"type":"detail","q":"What time did the writer wake up?","options":["At seven","At eight","At five"],"answer":2,"why":"作者五點醒來。文章沒有說七點或八點起床。","evidence":"I woke up at five, but I could not eat breakfast."}],"band":"hard"},{"id":"a2-sleep","level":"A2","title":"Sleep and Students","topic":"健康","words":121,"paras":["Many students do not get enough sleep. Some stay up late to study for tests. Others use their phones in bed until midnight.","Sleep is important for learning. While we sleep, the brain stores the things we learned during the day. When students sleep less, they often find it harder to remember new words and ideas.","Too little sleep can also change our mood. Tired people are more likely to feel stressed or angry. They may also eat more snacks.","Here are some simple ideas. Go to bed at about the same time every night. Put your phone away thirty minutes before bed. If you have a test, study a little every day instead of studying all night before the test."],"zh":"很多學生睡不夠，有人熬夜讀書，有人在床上滑手機到半夜。睡眠對學習很重要，睡覺時大腦會把白天學的東西存起來，睡少比較難記新字。睡太少也會影響心情，比較容易緊張生氣，也可能吃更多零食。建議每天差不多時間睡、睡前三十分鐘放下手機、考試要每天讀一點而不是前一晚熬夜。","qs":[{"type":"main","q":"What is the writer's main point?","options":["Phones are bad for everyone.","Snacks help students study.","Sleep helps learning, so students should sleep enough."],"answer":2,"why":"第二段說睡眠對學習重要，最後一段給建議，主旨是要睡夠。"},{"type":"detail","q":"According to the text, what does the brain do while we sleep?","options":["It stores what we learned.","It stops working.","It makes us hungry."],"answer":0,"why":"While we sleep, the brain stores the things we learned during the day.","evidence":"the brain stores the things we learned during the day"},{"type":"reference","q":"\\"They may also eat more snacks.\\" Who are \\"They\\"?","options":["Doctors","Tired people","Teachers"],"answer":1,"why":"前一句的主詞是 Tired people，They 指他們。","evidence":"Tired people are more likely to feel stressed or angry."},{"type":"detail","q":"What does the writer suggest before a test?","options":["Study a little every day.","Do not study at all.","Study all night."],"answer":0,"why":"study a little every day instead of studying all night。instead of 是「而不是」。","evidence":"study a little every day instead of studying all night before the test"},{"type":"vocab","q":"In \\"change our mood\\", \\"mood\\" means…","options":["how we feel","what we eat","where we live"],"answer":0,"why":"後面說 stressed or angry，都是感覺，所以 mood 是「心情」。","evidence":"Too little sleep can also change our mood."},{"type":"evidence","q":"Which sentence gives a clear action about phone use before sleep?","options":["Some stay up late to study for tests.","Tired people are more likely to feel stressed or angry.","Put your phone away thirty minutes before bed."],"answer":2,"why":"這一句直接說睡前三十分鐘把手機放下，另外兩句是現象或影響。","evidence":"Put your phone away thirty minutes before bed."}],"band":"hard"},{"id":"a2-handwash","level":"A2","title":"Clean Hands Save Lives","topic":"感染控制","words":120,"paras":["Germs are very small, so we cannot see them. They live on door handles, phones, and money. When we touch these things and then touch our eyes or mouth, germs can enter our body.","Washing hands is one of the easiest ways to stop the spread of germs. Use soap and clean water, and scrub all parts of your hands for at least twenty seconds. Don't forget your thumbs and the skin between your fingers.","In hospitals, hand hygiene is even more important. Patients are often weak, and germs can make them very sick. Nurses clean their hands before and after they touch a patient. When their hands are not visibly dirty, they can also use hand rub with alcohol."],"zh":"細菌很小看不到，住在門把、手機和錢上。摸了再碰眼睛嘴巴，細菌就會進入身體。洗手是阻止細菌傳播最簡單的方法之一：用肥皂和清水，搓洗手的每個部位至少二十秒，別忘了拇指和指縫。在醫院手部衛生更重要，因為病人比較虛弱。護理師碰病人前後都要清潔雙手，手沒有明顯髒污時也可以用含酒精的乾洗手。","qs":[{"type":"detail","q":"How long should you scrub your hands?","options":["At least twenty seconds","One minute only when you are sick","About five seconds"],"answer":0,"why":"scrub all parts of your hands for at least twenty seconds","evidence":"for at least twenty seconds"},{"type":"detail","q":"Why is hand hygiene even more important in hospitals?","options":["Patients are often weak.","Hospitals have no soap.","Nurses like clean hands."],"answer":0,"why":"Patients are often weak, and germs can make them very sick.","evidence":"Patients are often weak, and germs can make them very sick."},{"type":"detail","q":"When can nurses use alcohol hand rub?","options":["Never","When their hands are not visibly dirty","Only after eating"],"answer":1,"why":"When their hands are not visibly dirty, they can also use hand rub with alcohol.","evidence":"When their hands are not visibly dirty, they can also use hand rub with alcohol."},{"type":"vocab","q":"\\"Scrub\\" in \\"scrub all parts of your hands\\" means…","options":["look at","dry with a towel","rub hard to clean"],"answer":2,"why":"洗手時「用力搓洗」叫 scrub。"},{"type":"main","q":"What is the purpose of this text?","options":["To explain why and how to clean hands","To sell soap","To describe a hospital building"],"answer":0,"why":"全文說細菌怎麼傳播、怎麼洗手、醫院為什麼更重要。"},{"type":"reference","q":"In \\"They live on door handles, phones, and money\\", what are \\"They\\"?","options":["Nurses","Patients","Germs"],"answer":2,"why":"They 接在 germs 後面，指細菌等病原體，不是護理師或病人。","evidence":"They live on door handles, phones, and money."}],"band":"hard"},{"id":"a2-walk","level":"A2","title":"A Walk a Day","topic":"健康","words":106,"paras":["Mr. Lee is sixty-five. Last year, his doctor told him that his blood sugar was too high. The doctor said, \\"You should be more active.\\"","At first, Mr. Lee did not like exercise. He thought the gym was too expensive and too far from his home. Then his granddaughter had an idea. \\"Let's walk together after dinner,\\" she said.","Now they walk for thirty minutes almost every evening. They talk about school and about the news. After six months, Mr. Lee's blood sugar was lower than before, and he felt more energetic. \\"Walking is free,\\" he says, \\"and I get to spend time with my granddaughter.\\""],"zh":"李先生六十五歲，去年醫師說他血糖太高，應該多活動。他一開始不喜歡運動，覺得健身房太貴太遠。孫女提議晚餐後一起散步。現在他們幾乎每晚走三十分鐘，聊學校和新聞。半年後他的血糖比以前低，也更有精神。他說走路免費，又能陪孫女。","qs":[{"type":"detail","q":"Why didn't Mr. Lee want to go to the gym?","options":["His doctor said no.","It was too expensive and too far.","He was too busy at work."],"answer":1,"why":"He thought the gym was too expensive and too far from his home.","evidence":"He thought the gym was too expensive and too far from his home."},{"type":"detail","q":"Whose idea was the evening walk?","options":["His granddaughter's","His wife's","The doctor's"],"answer":0,"why":"Then his granddaughter had an idea. \\"Let's walk together…\\"","evidence":"Then his granddaughter had an idea."},{"type":"detail","q":"What changed after six months?","options":["His blood sugar was lower.","He joined a gym.","He stopped talking to his granddaughter."],"answer":0,"why":"Mr. Lee's blood sugar was lower than before","evidence":"Mr. Lee's blood sugar was lower than before"},{"type":"vocab","q":"\\"He felt more energetic.\\" \\"Energetic\\" means…","options":["sad","full of energy, not tired","very hungry"],"answer":1,"why":"跟 tired 相反，energetic 是「精力充沛的」。"},{"type":"main","q":"What is the best title?","options":["Why gyms are expensive","A day at school","How walking helped Mr. Lee"],"answer":2,"why":"全文說走路怎麼改善他的血糖和生活。"},{"type":"detail","q":"Who first told Mr. Lee to be more active?","options":["His granddaughter","A gym worker","His doctor"],"answer":2,"why":"醫師先建議增加活動；孫女後來提出一起散步的具體做法。","evidence":"The doctor said, \\"You should be more active.\\""}],"band":"mid"},{"id":"a2-message","level":"A2","title":"A Message from the Head Nurse","topic":"職場訊息","words":122,"paras":["Hi everyone,","There will be a fire drill on Thursday at 10 a.m. When you hear the alarm, please follow the plan on the wall next to the nurses' station. Do not use the elevators.","Patients who can walk should go to the stairs with a staff member. Patients who cannot walk will stay in their rooms, and a team will help them. Please keep the exit doors clear. Tell the nurse in charge which patients use oxygen, and do not turn off any oxygen unless she asks you to.","The drill will take about twenty minutes. If you are on a break at that time, please come back to the ward by 9:50.","Thank you,\\nMs. Chen, Head Nurse"],"zh":"大家好：週四早上十點有消防演習。聽到警報請照護理站旁牆上的計畫走，不要搭電梯。能走的病人由工作人員陪同走樓梯，不能走的留在病房由小組協助。請保持出口淨空；告訴負責的護理師哪些病人在用氧氣，除非她要你關，不要自己關氧氣。演習約二十分鐘，那時在休息的人請九點五十前回病房。護理長陳小姐","qs":[{"type":"main","q":"Why did Ms. Chen write this message?","options":["To change the visiting hours","To explain the plan for a fire drill","To invite staff to a party"],"answer":1,"why":"整封訊息在說週四消防演習要怎麼做。"},{"type":"detail","q":"Where is the plan?","options":["In the elevator","In Ms. Chen's office","On the wall next to the nurses' station"],"answer":2,"why":"follow the plan on the wall next to the nurses' station","evidence":"follow the plan on the wall next to the nurses' station"},{"type":"detail","q":"What will happen to patients who cannot walk?","options":["They will stay in their rooms and a team will help them.","They will use the elevators.","They will go home."],"answer":0,"why":"Patients who cannot walk will stay in their rooms, and a team will help them.","evidence":"Patients who cannot walk will stay in their rooms, and a team will help them."},{"revision":1,"type":"detail","q":"A nurse's break includes the 10 a.m. drill. What should she do?","options":["Go to the stairs at 10:30.","Come back to the ward by 9:50.","Stay on break until 11."],"answer":1,"why":"If you are on a break at that time, please come back to the ward by 9:50.","evidence":"If you are on a break at that time, please come back to the ward by 9:50."},{"type":"vocab","q":"A \\"drill\\" here is…","options":["a tool for making holes","a kind of medicine","a practice for an emergency"],"answer":2,"why":"fire drill 是消防演習，是為了緊急狀況做的練習。"},{"type":"detail","q":"About how long will the drill take?","options":["Ten minutes","Fifty minutes","Twenty minutes"],"answer":2,"why":"twenty minutes 是演習的長度；10 a.m. 是開始時間。","evidence":"The drill will take about twenty minutes."}],"band":"hard"},{"id":"a2-tainan","level":"A2","title":"An Email from Tainan","topic":"電子郵件","words":110,"paras":["Hi Emma,","How are you? Last weekend, I visited my cousin in Tainan. I took the train on Friday night, and she met me at the station.","On Saturday, we rode bikes around the old city. We saw an old fort and took a lot of pictures. The weather was hot, so we stopped for mango ice. It was delicious! In the evening, we walked to a night market and tried beef soup.","On Sunday, it rained all morning. We stayed home and cooked lunch together. I came back to Taichung at six.","Next time, you should come with us. I think you will love the food.","Take care,\\nYu-ting"],"zh":"嗨 Emma：妳好嗎？上週末我去台南找我表姊。我星期五晚上搭火車，她到車站接我。星期六我們在老城區騎腳踏車，看了一座古堡，拍了很多照片。天氣很熱，所以我們停下來吃芒果冰，好好吃！傍晚我們走去夜市，喝了牛肉湯。星期天下了一整個早上的雨，我們待在家一起煮午餐。我六點回到台中。下次妳應該跟我們一起來，我想妳會愛上那裡的食物。保重，Yu-ting","qs":[{"type":"main","q":"Why did Yu-ting write this email?","options":["To tell Emma about her trip to Tainan","To ask Emma for money","To say sorry for being late"],"answer":0,"why":"整封信在說上週末去台南做了什麼，最後邀 Emma 下次一起去。"},{"type":"detail","q":"How did Yu-ting get to Tainan?","options":["By bike","By train","By bus"],"answer":1,"why":"I took the train on Friday night.（搭火車）；腳踏車是到了台南才騎的。","evidence":"I took the train on Friday night, and she met me at the station."},{"type":"detail","q":"Why did they stop for mango ice?","options":["It was raining.","They were lost.","The weather was hot."],"answer":2,"why":"so 前面是原因：The weather was hot（天氣很熱）。","evidence":"The weather was hot, so we stopped for mango ice."},{"type":"reference","q":"\\"It was delicious!\\" What was delicious?","options":["The beef soup","The mango ice","The lunch"],"answer":1,"why":"It 指前一句剛提到的 mango ice；牛肉湯是後面才說的。","evidence":"It was delicious!"},{"type":"detail","q":"What did they do on Sunday morning?","options":["They stayed home and cooked.","They rode bikes.","They visited an old fort."],"answer":0,"why":"星期天早上下雨：We stayed home and cooked lunch together. 騎車和看古堡是星期六。","evidence":"We stayed home and cooked lunch together."},{"type":"detail","q":"When did Yu-ting travel to Tainan?","options":["On Saturday morning","On Sunday evening","On Friday night"],"answer":2,"why":"信裡說星期五晚上搭火車，星期六才開始騎車遊覽。","evidence":"I took the train on Friday night, and she met me at the station."}],"band":"mid"},{"id":"a2-wallet","level":"A2","title":"The Lost Wallet","topic":"生活故事","words":111,"paras":["Last Tuesday, Ming lost his wallet on the bus. He did not notice until he tried to buy lunch. His money, his student card, and his bank card were all inside. He felt terrible.","Ming called the bus company, but they did not have his wallet. He went home and told his mother. \\"Don't worry,\\" she said. \\"Maybe someone will return it.\\"","Two days later, a police officer called. An old woman found the wallet under a seat and took it to the police station. Nothing was missing.","Ming wanted to thank her, so he bought some fruit and visited her. She smiled and said, \\"Just help someone else next time.\\""],"zh":"上星期二，Ming 在公車上弄丟了皮夾。他一直到要買午餐時才發現。他的錢、學生證和提款卡都在裡面，他覺得糟透了。Ming 打電話給公車公司，但是他們沒有他的皮夾。他回家告訴媽媽。媽媽說：「別擔心，也許有人會送回來。」兩天後，一位警察打電話來。一位老太太在座位下面找到皮夾，把它送到警察局。裡面的東西一樣都沒少。Ming 想謝謝她，所以買了一些水果去拜訪她。她笑著說：「下次你也幫助別人就好了。」","qs":[{"type":"main","q":"What is the story mainly about?","options":["A student who lost his wallet and got it back","A bus driver who lost his job","An old woman who needed money"],"answer":0,"why":"故事從丟皮夾開始，到有人撿到送回來、Ming 去道謝結束。"},{"type":"detail","q":"When did Ming notice that his wallet was gone?","options":["When he got on the bus","When the police called","When he tried to buy lunch"],"answer":2,"why":"He did not notice until he tried to buy lunch. not … until … 是「直到…才…」。","evidence":"He did not notice until he tried to buy lunch."},{"type":"detail","q":"Who found the wallet?","options":["A police officer","An old woman","Ming's mother"],"answer":1,"why":"An old woman found the wallet under a seat. 警察只是打電話通知的人。","evidence":"An old woman found the wallet under a seat and took it to the police station."},{"type":"vocab","q":"\\"Nothing was missing.\\" This means…","options":["Everything was still in the wallet.","The wallet was empty.","The wallet was lost again."],"answer":0,"why":"missing 是「不見的」；nothing was missing 就是沒有東西不見，全部都在。","evidence":"Nothing was missing."},{"type":"detail","q":"How did Ming thank the woman?","options":["He gave her money.","He wrote her a letter.","He bought some fruit and visited her."],"answer":2,"why":"he bought some fruit and visited her（買水果去拜訪她）。","evidence":"Ming wanted to thank her, so he bought some fruit and visited her."},{"type":"detail","q":"What was inside the wallet?","options":["A phone, a key, and a ticket","Fruit, a letter, and a photograph","Money, a student card, and a bank card"],"answer":2,"why":"文章列出錢、學生證和銀行卡；水果是後來道謝時買的。","evidence":"His money, his student card, and his bank card were all inside."}],"band":"hard"},{"id":"a2-cafe","level":"A2","title":"My Part-Time Job","topic":"打工","words":119,"paras":["Last summer, I got my first part-time job at a small coffee shop. I worked three days a week, from seven in the morning to noon.","On the first day, I was slow. I forgot a customer's order and gave another customer the wrong change. My manager, Mr. Wu, did not get angry. He showed me how to use the cash register again.","After two weeks, I could make most of the drinks by myself. I also learned to smile and say hello to every customer. Some of them remembered my name.","I only made a little money, but I learned to be on time and to work with other people. I want to work there again next summer."],"zh":"去年夏天，我在一家小咖啡店找到第一份打工。我一週工作三天，從早上七點到中午。第一天我動作很慢，忘了一位客人點的東西，還找錯錢給另一位客人。我的店長吳先生沒有生氣，他再教我一次怎麼用收銀機。兩個星期後，大部分的飲料我都可以自己做了。我也學會對每位客人微笑、打招呼，有些客人還記得我的名字。我只賺了一點錢，但是我學會準時，也學會和別人一起工作。明年夏天我想再去那裡打工。","qs":[{"type":"detail","q":"When did the writer work?","options":["Every day, all day","Three days a week, in the morning","Only on weekends, at night"],"answer":1,"why":"I worked three days a week, from seven in the morning to noon.（一週三天，早上七點到中午）","evidence":"I worked three days a week, from seven in the morning to noon."},{"type":"detail","q":"What mistake did the writer make on the first day?","options":["The writer came late.","The writer broke a cup.","The writer gave a customer the wrong change."],"answer":2,"why":"gave another customer the wrong change：找錯錢。change 在這裡是「零錢、找的錢」。","evidence":"I forgot a customer's order and gave another customer the wrong change."},{"type":"detail","q":"What did Mr. Wu do after the mistakes?","options":["He showed the writer how to use the cash register again.","He got angry and shouted.","He told the writer to go home."],"answer":0,"why":"Mr. Wu did not get angry（沒有生氣），而是再教一次怎麼用收銀機。","evidence":"He showed me how to use the cash register again."},{"type":"reference","q":"\\"Some of them remembered my name.\\" Who are \\"them\\"?","options":["The drinks","The customers","The managers"],"answer":1,"why":"them 指前一句的 every customer（客人們）。","evidence":"Some of them remembered my name."},{"type":"evidence","q":"Which sentence shows what the writer learned from the job?","options":["\\"I only made a little money.\\"","\\"I worked three days a week.\\"","\\"I learned to be on time and to work with other people.\\""],"answer":2,"why":"I learned to… 後面就是學到的事：準時、和別人一起工作。","evidence":"I learned to be on time and to work with other people"},{"type":"vocab","q":"Working \\"on time\\" means…","options":["working without other people","finishing every drink quickly","arriving at the planned time"],"answer":2,"why":"on time 是準時；不是獨自工作，也不是所有動作都很快。","evidence":"I only made a little money, but I learned to be on time and to work with other people."}],"band":"mid"},{"id":"a2-class-ad","level":"A2","title":"Evening English Class","topic":"廣告","words":115,"paras":["Do you want to speak English with more confidence? Join our evening English class!","Time: Tuesdays and Thursdays, 7:00 p.m. to 8:30 p.m.","Place: Room 302, City Library","Teacher: Ms. Sarah Brown from Canada","Price: NT$2,000 for eight weeks","The class is for adults who studied English before but are afraid to speak. Each class has only ten students, so everyone gets a chance to talk. We practice everyday topics, such as ordering food, asking for directions, and seeing a doctor.","The first class is free. Come and try it on March 3. To sign up, call 2555-0134 or visit the front desk of the library before February 28."],"zh":"你想更有自信地說英文嗎？來參加我們的晚間英文課！時間：每週二、四晚上七點到八點半。地點：市立圖書館 302 教室。老師：來自加拿大的 Sarah Brown 老師。費用：八週新台幣 2,000 元。這門課是給以前學過英文、但不敢開口的成人。每班只有十位學生，所以每個人都有機會說話。我們練習日常主題，例如點餐、問路和看醫生。第一堂課免費，歡迎 3 月 3 日來試上。報名請在 2 月 28 日前打 2555-0134，或到圖書館櫃台。","qs":[{"type":"main","q":"What is this text?","options":["An advertisement for an English class","A letter from a teacher to a student","A library rule about books"],"answer":0,"why":"有時間、地點、老師、費用和報名方式，是招生廣告。"},{"type":"detail","q":"How many times a week does the class meet?","options":["Once","Twice","Eight times"],"answer":1,"why":"Tuesdays and Thursdays：每週二和週四，一週兩次。eight 是總共八週。","evidence":"Time: Tuesdays and Thursdays, 7:00 p.m. to 8:30 p.m."},{"type":"detail","q":"Who is this class for?","options":["Children who are new to English","Teachers from Canada","Adults who are afraid to speak English"],"answer":2,"why":"The class is for adults who studied English before but are afraid to speak.（學過但不敢說的成人）","evidence":"The class is for adults who studied English before but are afraid to speak."},{"type":"detail","q":"Why does everyone get a chance to talk?","options":["Because each class has only ten students","Because the first class is free","Because the teacher is from Canada"],"answer":0,"why":"so 前面是原因：Each class has only ten students（每班只有十個人）。","evidence":"Each class has only ten students, so everyone gets a chance to talk."},{"type":"detail","q":"What should you do if you want to join?","options":["Send an email to Ms. Brown","Call or visit the library's front desk before February 28","Go to Room 302 on February 28"],"answer":1,"why":"To sign up（報名），call … or visit the front desk of the library before February 28.","evidence":"To sign up, call 2555-0134 or visit the front desk of the library before February 28."},{"type":"detail","q":"How much does it cost to try the first class?","options":["NT$2,000","NT$250","Nothing"],"answer":2,"why":"第一堂免費；兩千元是八週課程的費用。","evidence":"The first class is free."}],"band":"hard"},{"id":"a2-typhoon","level":"A2","title":"A Typhoon Day","topic":"天氣","words":127,"paras":["Last September, a strong typhoon came to Taiwan. The day before, my father checked the windows, and my mother bought rice, noodles, and bottled water. Schools and offices were closed the next day.","In the morning, the wind was very loud and the rain hit the windows hard. At ten o'clock, the lights went out. We had no power for five hours. We could not watch TV or charge our phones, so we played cards and talked. My grandmother told us stories about typhoons when she was a child.","The power came back in the afternoon, and in the evening the rain stopped. Some trees on our street fell down, but nobody was hurt. It was a scary day, but I enjoyed the time with my family."],"zh":"去年九月，一個強烈颱風來到台灣。前一天，爸爸檢查了窗戶，媽媽買了米、麵和瓶裝水。隔天學校和公司都放假。早上風聲很大，雨重重打在窗戶上。十點的時候停電了，我們五個小時沒有電，不能看電視也不能幫手機充電，所以我們玩撲克牌、聊天。奶奶跟我們說她小時候遇到颱風的故事。下午電來了，傍晚雨也停了。我們街上有些樹倒了，但是沒有人受傷。那是可怕的一天，但我很喜歡和家人在一起的時光。","qs":[{"type":"detail","q":"What did the writer's mother do before the typhoon?","options":["She checked the windows.","She bought food and water.","She went to the office."],"answer":1,"why":"my mother bought rice, noodles, and bottled water（買了食物和水）；檢查窗戶的是爸爸。","evidence":"The day before, my father checked the windows, and my mother bought rice, noodles, and bottled water."},{"type":"detail","q":"How long was the power out?","options":["For ten hours","All day and all night","For five hours"],"answer":2,"why":"We had no power for five hours.（五個小時）；ten 是停電的時間點（十點）。","evidence":"We had no power for five hours."},{"type":"vocab","q":"\\"The lights went out.\\" This means…","options":["The lights stopped working.","The lights became brighter.","Someone took the lights outside."],"answer":0,"why":"go out 用在燈、火上是「熄滅」。下一句 We had no power（沒有電）就是線索。","evidence":"At ten o'clock, the lights went out."},{"type":"detail","q":"What did the family do when there was no power?","options":["They watched TV.","They slept all day.","They played cards and talked."],"answer":2,"why":"不能看電視、不能充電，so we played cards and talked（玩牌、聊天）。","evidence":"We could not watch TV or charge our phones, so we played cards and talked."},{"type":"main","q":"How did the writer feel about the day?","options":["It was boring and sad.","It was scary, but the family time was nice.","It was the best day of the year."],"answer":1,"why":"最後一句：It was a scary day, but I enjoyed the time with my family.","evidence":"It was a scary day, but I enjoyed the time with my family."},{"type":"detail","q":"Who told stories about childhood typhoons?","options":["The father","The mother","The grandmother"],"answer":2,"why":"祖母說的是她小時候遇到颱風的故事。","evidence":"My grandmother told us stories about typhoons when she was a child."}],"band":"hard"},{"id":"a2-cooking","level":"A2","title":"My First Dinner","topic":"生活故事","words":130,"paras":["Last Mother's Day, I decided to cook dinner for my family. It was my first time cooking a full meal, so I watched some videos first.","I planned three dishes: fried rice, tomato and egg soup, and a salad. I went to the market in the morning and bought everything. In the afternoon, I started to cook.","The salad was easy. The soup was fine, too. But I put too much salt in the fried rice, and the bottom of the pan burned a little. The kitchen was a mess.","At dinner, my mother ate two bowls of rice. \\"It's a little salty,\\" she said, \\"but it's the best meal this year.\\" My father washed all the dishes. Next time, I will taste the food before I add more salt."],"zh":"去年母親節，我決定幫家人煮晚餐。那是我第一次煮一整頓飯，所以我先看了一些影片。我計畫煮三道菜：炒飯、番茄蛋花湯和沙拉。早上我去市場把東西都買齊，下午開始煮。沙拉很簡單，湯也還可以。可是炒飯我放了太多鹽，鍋底還有點燒焦。廚房一團亂。晚餐時，媽媽吃了兩碗飯。她說：「有點鹹，但這是今年最棒的一餐。」爸爸洗了所有的碗盤。下次我會先嚐味道，再決定要不要加鹽。","qs":[{"type":"main","q":"What is the text mainly about?","options":["The writer's first time cooking dinner for the family","How to buy food at a market","A famous restaurant"],"answer":0,"why":"從決定煮飯、買菜、煮壞一點點，到家人吃得開心，都是第一次煮晚餐的經過。"},{"type":"detail","q":"Why did the writer watch videos first?","options":["Because the writer was bored","Because it was the writer's first time cooking a full meal","Because the market was closed"],"answer":1,"why":"so 前面是原因：It was my first time cooking a full meal（第一次煮一整頓飯）。","evidence":"It was my first time cooking a full meal, so I watched some videos first."},{"type":"detail","q":"What went wrong with the fried rice?","options":["It was too sweet.","There was not enough rice.","It had too much salt."],"answer":2,"why":"I put too much salt in the fried rice（放了太多鹽），所以媽媽說有點鹹。","evidence":"But I put too much salt in the fried rice, and the bottom of the pan burned a little."},{"type":"vocab","q":"\\"The kitchen was a mess.\\" This means the kitchen was…","options":["very clean","dirty and untidy","too small"],"answer":1,"why":"a mess 是「一團亂」：又髒又亂。","evidence":"The kitchen was a mess."},{"type":"detail","q":"How did the mother feel about the dinner?","options":["She was happy with it.","She was angry about the salt.","She did not eat anything."],"answer":0,"why":"她吃了兩碗飯，還說這是今年最棒的一餐；雖然有點鹹，還是很開心。","evidence":"At dinner, my mother ate two bowls of rice."},{"type":"detail","q":"Who washed the dishes after dinner?","options":["The mother","The writer","The father"],"answer":2,"why":"文章最後說爸爸洗了全部的碗盤。","evidence":"My father washed all the dishes."}],"band":"hard"},{"id":"a2-eyes","level":"A2","title":"Rest Your Eyes","topic":"健康","words":126,"paras":["Many people look at screens for hours every day. We use phones on the bus, computers at work, and tablets in bed. After a long day, our eyes can feel dry and tired, and some people get headaches.","Eye doctors often suggest the 20-20-20 rule. Every twenty minutes, look at something about twenty feet (six meters) away for twenty seconds. This gives the small muscles in your eyes a short rest.","There are other easy things you can do. Keep the screen about an arm's length from your face. Remember to blink, because we blink less when we look at a screen. Turn on a light when you read at night. If your eyes still hurt after a few days, see an eye doctor."],"zh":"很多人每天看螢幕好幾個小時。我們在公車上用手機、上班用電腦、在床上用平板。一整天下來，眼睛會覺得又乾又累，有些人還會頭痛。眼科醫師常建議「20-20-20 法則」：每二十分鐘，看大約二十英尺（六公尺）遠的東西二十秒。這樣可以讓眼睛裡的小肌肉休息一下。還有其他簡單的方法：螢幕離臉大約一個手臂的距離；記得眨眼，因為我們看螢幕時眨眼的次數會變少；晚上閱讀要開燈。如果過了幾天眼睛還是不舒服，就去看眼科醫師。","qs":[{"type":"main","q":"What is the main idea of the text?","options":["Screens can tire our eyes, and simple habits can help.","Phones are better than computers.","Everyone needs glasses."],"answer":0,"why":"第一段說看螢幕眼睛會累，後兩段教幾個簡單的習慣。"},{"type":"detail","q":"In the 20-20-20 rule, how long should you look away?","options":["Twenty minutes","Twenty seconds","Twenty hours"],"answer":1,"why":"每二十分鐘（every twenty minutes）看遠方 twenty seconds（二十秒）。兩個 twenty 不要弄混。","evidence":"Every twenty minutes, look at something about twenty feet (six meters) away for twenty seconds."},{"type":"detail","q":"Why should we remember to blink?","options":["Because blinking makes the screen brighter","Because the light is off","Because we blink less when we look at a screen"],"answer":2,"why":"because 後面是原因：看螢幕時眨眼的次數會變少。","evidence":"Remember to blink, because we blink less when we look at a screen."},{"type":"vocab","q":"In \\"Eye doctors often suggest the 20-20-20 rule,\\" \\"suggest\\" means…","options":["say that it is a good idea","say that it is wrong","forget"],"answer":0,"why":"suggest 是「建議」：告訴你這樣做比較好。","evidence":"Eye doctors often suggest the 20-20-20 rule."},{"type":"detail","q":"What should you do if your eyes still hurt after a few days?","options":["Buy a new phone","See an eye doctor","Read in the dark"],"answer":1,"why":"最後一句：If your eyes still hurt after a few days, see an eye doctor.","evidence":"If your eyes still hurt after a few days, see an eye doctor."},{"type":"reference","q":"In \\"This gives the small muscles in your eyes a short rest\\", what does \\"This\\" refer to?","options":["Using a tablet in bed","Reading without a light","Looking at something far away for a short time"],"answer":2,"why":"This 指前一句短暫看向遠處的做法，不是使用平板或關燈閱讀。","evidence":"This gives the small muscles in your eyes a short rest."}],"band":"hard"},{"id":"a2-grandpa","level":"A2","title":"Visiting Grandpa","topic":"醫院","words":127,"paras":["Last month, my grandfather fell in the bathroom and broke his leg. He had surgery and stayed in the hospital for a week. I visited him every day after class.","On the second day, he was in pain and did not want to eat. A nurse named Ms. Lin came in. She did not hurry. She asked him about the pain, gave him his medicine, and then talked with him about his garden. Soon he was smiling.","Later, she showed him how to move from the bed to a wheelchair safely. She also taught my mother how to help him at home.","My grandfather went home last Friday. He still needs a walker, but he is getting stronger. I will never forget how kind Ms. Lin was."],"zh":"上個月，我爺爺在浴室跌倒，摔斷了腿。他開了刀，住院一個星期。我每天下課後都去看他。第二天他很痛，不想吃東西。一位姓林的護理師走進來，她不急不忙，先問他痛的情形，給他吃藥，然後跟他聊他的花園。沒多久他就笑了。後來，她教他怎麼安全地從床上移到輪椅上，也教我媽媽回家後怎麼幫他。爺爺上星期五出院了。他還需要用助行器，但是越來越有力氣。我永遠不會忘記林護理師有多親切。","qs":[{"type":"detail","q":"Why was the grandfather in the hospital?","options":["He had a bad cold.","He broke his leg.","He worked there."],"answer":1,"why":"第一句：my grandfather fell in the bathroom and broke his leg（跌倒摔斷腿）。","evidence":"Last month, my grandfather fell in the bathroom and broke his leg."},{"type":"detail","q":"What did Ms. Lin talk about with the grandfather?","options":["His garden","His job","The weather"],"answer":0,"why":"talked with him about his garden（跟他聊他的花園）。","evidence":"She asked him about the pain, gave him his medicine, and then talked with him about his garden."},{"type":"reference","q":"\\"She also taught my mother how to help him at home.\\" Who is \\"She\\"?","options":["The writer's mother","The writer","Ms. Lin"],"answer":2,"why":"這一段的 she 都是林護理師；她教的對象才是 my mother。","evidence":"She also taught my mother how to help him at home."},{"type":"vocab","q":"A \\"walker\\" in this text is…","options":["a person who likes walking","a tool that helps a person walk","a kind of medicine"],"answer":1,"why":"腿斷了剛出院，still needs a walker：這裡是「助行器」，幫忙走路的器具。","evidence":"He still needs a walker, but he is getting stronger."},{"type":"main","q":"What does the writer think of Ms. Lin?","options":["She was too slow.","She talked too much.","She was kind and helpful."],"answer":2,"why":"最後一句：I will never forget how kind Ms. Lin was.","evidence":"I will never forget how kind Ms. Lin was."},{"type":"detail","q":"How long did Grandpa stay in the hospital?","options":["Two days","One month","One week"],"answer":2,"why":"住院一週；第二天是護理師協助他的那一天，上個月是受傷時間。","evidence":"He had surgery and stayed in the hospital for a week."}],"band":"hard"},{"id":"a2-plans","level":"A2","title":"A Change of Plans","topic":"訊息","words":117,"paras":["Amy: Hi Ben! Are we still going to the movies tonight?","Ben: I'm sorry, Amy. I can't go. My boss asked me to work late because a coworker is sick. I will finish at nine.","Amy: That's OK. The movie starts at seven, so that's too late. How about tomorrow?","Ben: Tomorrow is Saturday. I'm free all day! There is a show at two in the afternoon and another at eight.","Amy: Let's see the afternoon one. Then we can have dinner after the movie. I'll buy the tickets online.","Ben: Great. I'll pay for dinner because I changed our plans. Where should we meet?","Amy: In front of the theater at one forty. Don't be late!"],"zh":"Amy：嗨 Ben！我們今晚還要去看電影嗎？ Ben：對不起，Amy，我不能去。老闆要我加班，因為有同事生病了。我九點才會下班。 Amy：沒關係。電影七點開始，那樣太晚了。明天呢？ Ben：明天是星期六，我整天有空！下午兩點有一場，晚上八點還有一場。 Amy：看下午那一場吧，這樣看完可以去吃晚餐。我上網買票。 Ben：太好了。晚餐我請，因為是我改了計畫。我們在哪裡碰面？ Amy：一點四十分在電影院前面。不要遲到！","qs":[{"type":"detail","q":"Why can't Ben go to the movies tonight?","options":["He is sick.","He has to work late.","He has no money."],"answer":1,"why":"老闆要他加班（work late）；生病的是同事，不是 Ben。","evidence":"My boss asked me to work late because a coworker is sick."},{"type":"reference","q":"Amy says, \\"Let's see the afternoon one.\\" Which show does she mean?","options":["The show tonight at seven","The show on Saturday at eight","The show on Saturday at two"],"answer":2,"why":"one 代替 show。Ben 說明天（星期六）下午兩點和晚上八點各一場，下午那場就是兩點。","evidence":"Amy: Let's see the afternoon one."},{"type":"detail","q":"Who will buy the movie tickets?","options":["Amy","Ben","Ben's boss"],"answer":0,"why":"Amy 說：I'll buy the tickets online.（我上網買票）","evidence":"I'll buy the tickets online."},{"type":"detail","q":"Why will Ben pay for dinner?","options":["Because Amy bought lunch","Because he changed their plans","Because it is his birthday"],"answer":1,"why":"because 後面是原因：I changed our plans（是他改了計畫）。","evidence":"I'll pay for dinner because I changed our plans."},{"type":"detail","q":"Where and when will they meet?","options":["At Ben's office at nine","At a restaurant at seven","In front of the theater at one forty"],"answer":2,"why":"最後一則訊息：In front of the theater at one forty.（一點四十分在電影院前面）","evidence":"Amy: In front of the theater at one forty."},{"type":"main","q":"What do Amy and Ben decide in this conversation?","options":["A new job for Ben","A birthday gift for a coworker","A new time for a movie and dinner"],"answer":2,"why":"兩人因加班改看電影時間，接著約好吃飯與碰面地點。"}],"band":"mid"},{"id":"a2-flu-notice","level":"A2","title":"Flu Shots at Sunshine Clinic","topic":"診所公告","words":136,"paras":["Flu season is coming. Sunshine Clinic will give flu shots from October 1 to November 30.","You do not need an appointment. Just come on a weekday between 9 a.m. and 5 p.m. Please bring your ID card and your health insurance card. The shot is free for children and for adults over sixty-five. For other people, it costs NT$500.","Before the shot, a nurse will check your temperature and ask a few questions. If you have a fever that day, please come back when you feel better. Tell the nurse if you had a problem after a shot before, or if you have any allergies.","After the shot, please sit in the waiting area for thirty minutes. Your arm may feel a little sore for one or two days. This is normal."],"zh":"流感季節快到了。陽光診所從 10 月 1 日到 11 月 30 日提供流感疫苗接種。不需要預約，平日早上九點到下午五點直接來就可以。請帶身分證和健保卡。兒童和 65 歲以上的成人免費，其他人要付新台幣 500 元。打針前，護理師會幫你量體溫，並問幾個問題。如果當天發燒，請等身體好一點再來。如果你以前打針後有不舒服，或是有任何過敏，請告訴護理師。打完針後，請在等候區坐三十分鐘。手臂可能會有一點痠痛一兩天，這是正常的。","qs":[{"type":"main","q":"What is this notice about?","options":["Getting a flu shot at a clinic","A new doctor at the clinic","The clinic's new address"],"answer":0,"why":"整張公告在說流感疫苗：什麼時候打、帶什麼、多少錢、打完要注意什麼。"},{"type":"detail","q":"Who has to pay NT$500 for the shot?","options":["A six-year-old child","A thirty-year-old adult","A seventy-year-old adult"],"answer":1,"why":"兒童和 65 歲以上免費，其他人（for other people）要付 500 元，所以是三十歲的成人。","evidence":"The shot is free for children and for adults over sixty-five."},{"type":"detail","q":"What should you do if you have a fever on that day?","options":["Get the shot anyway","Go to the waiting area","Come back when you feel better"],"answer":2,"why":"If you have a fever that day, please come back when you feel better.（好一點再來）","evidence":"If you have a fever that day, please come back when you feel better."},{"type":"detail","q":"What should you do after the shot?","options":["Sit in the waiting area for thirty minutes","Go home right away","Check your temperature every hour"],"answer":0,"why":"After the shot, please sit in the waiting area for thirty minutes.（在等候區坐三十分鐘）","evidence":"After the shot, please sit in the waiting area for thirty minutes."},{"type":"reference","q":"\\"This is normal.\\" What is normal?","options":["Having a fever for a week","A little soreness in the arm for a day or two","Having a problem after every shot"],"answer":1,"why":"This 指前一句：手臂痠痛一兩天（a little sore for one or two days）。","evidence":"This is normal."},{"type":"detail","q":"Which days does the notice offer flu shots?","options":["Sundays only","Every night","Weekdays"],"answer":2,"why":"weekday 指平日；這是這間虛構診所公告中的服務時間。","evidence":"Just come on a weekday between 9 a.m. and 5 p.m."}],"band":"hard"},{"id":"b1-night","level":"B1","title":"Working Night Shifts","topic":"護理工作","words":192,"paras":["Hospitals never close, so many nurses have to work at night. A typical night shift starts in the evening and finishes the next morning. For some nurses, nights are quieter than days, and they have more time to talk with patients. For others, the night is the hardest part of the job.","The main problem is that the human body has an internal clock. This clock tells us to feel sleepy when it is dark and to be awake when it is light. When people work all night, they go against this clock. As a result, they may feel very tired at around three or four in the morning, which is exactly when careful work is still needed.","Experienced nurses use several strategies to cope. They take short breaks, drink water, and eat light meals instead of heavy ones. After the shift, they wear sunglasses on the way home and sleep in a dark, quiet room. Some also try to keep a similar sleep time on their days off, although this is not always possible with family life.","Night work is not easy, but with good planning, many nurses manage it safely."],"zh":"醫院不打烊，很多護理師要上夜班。有人覺得夜班比較安靜、有時間跟病人聊；有人覺得最辛苦。主要問題是人體有生理時鐘，天黑想睡、天亮清醒；整晚工作違反這個時鐘，凌晨三四點特別累，偏偏那時還需要細心。資深護理師的方法：短暫休息、喝水、吃清淡；下班戴墨鏡回家、在暗又安靜的房間睡；休假也盡量維持類似作息，雖然有家庭不一定做得到。好好規劃就能安全應付夜班。","qs":[{"type":"main","q":"What is the text mainly about?","options":["How to become a night nurse","Why hospitals should close at night","Why night shifts are hard and how nurses cope"],"answer":2,"why":"第二段講困難的原因，第三段講應對方法。"},{"type":"detail","q":"According to the text, when do night nurses often feel very tired?","options":["At around 3 or 4 a.m.","At the start of the shift","At lunchtime"],"answer":0,"why":"they may feel very tired at around three or four in the morning","evidence":"they may feel very tired at around three or four in the morning"},{"type":"reference","q":"In paragraph 2, \\"this clock\\" refers to…","options":["the nurse's watch","the clock on the ward wall","the body's internal clock"],"answer":2,"why":"前一句說 the human body has an internal clock，this clock 指它。","evidence":"The main problem is that the human body has an internal clock."},{"type":"vocab","q":"\\"To cope\\" (paragraph 3) is closest in meaning to…","options":["to copy someone","to stop working","to deal with a difficult situation"],"answer":2,"why":"後面列出的都是撐過夜班的方法，cope 是「應付、處理困難」。","evidence":"Experienced nurses use several strategies to cope."},{"type":"evidence","q":"Which sentence shows that keeping the same sleep time is difficult for some nurses?","options":["\\"They take short breaks, drink water, and eat light meals.\\"","\\"…although this is not always possible with family life.\\"","\\"Hospitals never close.\\""],"answer":1,"why":"although 帶出限制：有家庭生活時不一定做得到。","evidence":"although this is not always possible with family life"},{"type":"detail","q":"Why do nurses wear sunglasses on the way home?","options":["To look fashionable","To keep light from waking up the body clock","Because it is raining"],"answer":1,"why":"推論題：文章說光讓身體清醒；下班要回家睡，所以戴墨鏡擋光。這題要把第二段和第三段連起來。","evidence":"they wear sunglasses on the way home and sleep in a dark, quiet room"},{"type":"tfng","q":"Some nurses find night shifts quieter than day shifts.","options":["True","False","Not Given"],"answer":0,"why":"第一段明確指出對某些護理師而言，夜班比白天安靜。","evidence":"For some nurses, nights are quieter than days, and they have more time to talk with patients."}],"band":"hard"},{"id":"b1-sugar","level":"B1","title":"The Hidden Sugar in Drinks","topic":"營養衛教","words":177,"paras":["Bubble tea, soda, and fruit juice are popular in Taiwan, especially among young people. Many of these drinks contain a surprising amount of sugar. A large cup of sweet milk tea can contain more sugar than a person should have in a whole day.","Sugar in drinks is a special problem because it does not make us feel full. If we eat a piece of cake, we usually eat less at the next meal. But after a sweet drink, most people eat the same amount of food as usual. Over time, these extra calories can lead to weight gain. Too much sugar is also linked to tooth decay and type 2 diabetes.","This does not mean that people can never enjoy a sweet drink. Health educators suggest small changes. Ask for less sugar or no sugar when you order. Choose a smaller cup. Drink water or unsweetened tea with meals, and keep sweet drinks for special occasions.","Nurses often teach these ideas to patients. Simple, practical advice is usually more helpful than telling people to stop completely."],"zh":"珍奶、汽水、果汁在台灣很受歡迎，很多含糖量驚人，一大杯甜奶茶的糖可能超過一天該吃的量。飲料的糖特別麻煩，因為喝了不會飽：吃蛋糕下一餐會少吃，喝甜飲料卻照常吃，久了多的熱量會讓人變胖，糖太多也和蛀牙、第二型糖尿病有關。這不代表永遠不能喝，衛教人員建議小改變：點少糖或無糖、選小杯、吃飯配水或無糖茶、甜飲料留到特別場合。護理師常教這些，簡單實用的建議比叫人完全不喝更有效。","qs":[{"type":"main","q":"What is the writer's main purpose?","options":["To say that bubble tea should be banned","To compare cake and soda prices","To explain the problem with sugary drinks and give practical advice"],"answer":2,"why":"先講問題，再給建議，最後說護理師怎麼衛教。"},{"type":"detail","q":"Why is sugar in drinks a special problem?","options":["It does not make us feel full.","It is more expensive than food.","It makes drinks cold."],"answer":0,"why":"because it does not make us feel full","evidence":"it does not make us feel full"},{"type":"detail","q":"Which of these is NOT suggested in paragraph 3?","options":["Drink juice with every meal.","Choose a smaller cup.","Ask for less sugar."],"answer":0,"why":"第三段建議少糖、小杯、配水或無糖茶；沒有說每餐喝果汁。注意題目的 NOT。"},{"type":"vocab","q":"\\"Tooth decay\\" is most likely…","options":["a kind of drink","a dentist's tool","damage to teeth"],"answer":2,"why":"跟糖有關的牙齒問題，decay 是「腐壞」，tooth decay 是蛀牙。","evidence":"Too much sugar is also linked to tooth decay"},{"type":"evidence","q":"Which sentence supports the idea that advice should be realistic?","options":["\\"Simple, practical advice is usually more helpful than telling people to stop completely.\\"","\\"Bubble tea, soda, and fruit juice are popular in Taiwan.\\"","\\"A large cup of sweet milk tea can contain more sugar than a person should have in a whole day.\\""],"answer":0,"why":"最後一句直接說簡單實用的建議比完全禁止更有幫助。","evidence":"Simple, practical advice is usually more helpful than telling people to stop completely."},{"type":"reference","q":"What does \\"these ideas\\" in the last paragraph refer to?","options":["Instructions for opening a drink shop","The practical changes for reducing sugary drinks","The different prices of cake and soda"],"answer":1,"why":"these ideas 承接第三段的少糖、小杯、配水或無糖茶等建議。"},{"type":"detail","q":"For which times does paragraph 3 suggest keeping sweet drinks?","options":["Every meal during the day","Special occasions","Every time a person feels tired"],"answer":1,"why":"第三段明確說把甜飲留給特別場合。","evidence":"Drink water or unsweetened tea with meals, and keep sweet drinks for special occasions."}],"band":"easy"},{"id":"b1-interpreter","level":"B1","title":"When Patients Speak Another Language","topic":"跨文化照護","words":157,"paras":["Hospitals in many countries care for patients who do not speak the local language well. In the United States, for example, nurses may meet patients who speak Spanish, Chinese, Vietnamese, or many other languages.","When a nurse and a patient cannot understand each other, mistakes can happen. A patient may not understand how to take a medicine, or a nurse may miss an important symptom. For this reason, many hospitals provide professional interpreters, either in person or by phone or video.","It might seem easier to ask a family member to translate, but this can cause problems. Family members may not know medical words. They may also change the message because they want to protect the patient from bad news. Children should not be asked to interpret for their parents about serious health matters.","Nurses who speak two languages are very valuable. Still, even bilingual staff need to know when a professional interpreter is the safer choice."],"zh":"很多國家的醫院會照顧不太會說當地語言的病人，例如美國的護理師可能遇到說西班牙語、中文、越南語等的病人。互相聽不懂就可能出錯：病人不懂怎麼吃藥，或護理師漏掉重要症狀，所以很多醫院提供專業口譯，現場或電話、視訊。叫家人翻譯看似簡單卻有問題：可能不懂醫學詞、可能為了保護病人改掉壞消息，嚴重的健康問題不應讓小孩幫父母翻譯。雙語護理師很寶貴，但也要知道什麼時候找專業口譯比較安全。","qs":[{"type":"detail","q":"Why do many hospitals provide professional interpreters?","options":["Because family members are too busy","Because patients ask for them to save money","Because misunderstandings can cause mistakes"],"answer":2,"why":"For this reason… 指前一句：聽不懂會出錯。","evidence":"For this reason, many hospitals provide professional interpreters"},{"type":"detail","q":"Which is a reason the text gives for NOT using family members?","options":["They may change the message.","They speak too slowly.","They charge too much."],"answer":0,"why":"They may also change the message because they want to protect the patient from bad news.","evidence":"They may also change the message"},{"type":"reference","q":"In paragraph 3, \\"They\\" in \\"They may also change the message\\" refers to…","options":["interpreters","family members","nurses"],"answer":1,"why":"前一句主詞是 Family members。","evidence":"Family members may not know medical words."},{"type":"vocab","q":"\\"Bilingual\\" (paragraph 4) means…","options":["working at night","very experienced","able to speak two languages"],"answer":2,"why":"前一句 Nurses who speak two languages，bilingual 就是雙語的。","evidence":"Nurses who speak two languages are very valuable."},{"type":"main","q":"What is the writer's opinion?","options":["Professional interpreters are often the safer choice.","Patients should learn English before going to hospital.","Children are the best interpreters."],"answer":0,"why":"第三段說家人翻譯的問題，最後一段說即使雙語人員也要知道何時找專業口譯更安全。"},{"type":"detail","q":"Which interpreter formats are mentioned in paragraph 2?","options":["Only a written list without conversation","Only a relative speaking in person","In person, by phone, or by video"],"answer":2,"why":"第二段最後一句列出現場、電話或視訊口譯。","evidence":"For this reason, many hospitals provide professional interpreters, either in person or by phone or video."},{"type":"evidence","q":"What conclusion is supported by the last sentence?","options":["Bilingual staff never need further help","Knowing two languages does not remove every need for professional interpretation","Professional interpreters are needed only for children"],"answer":1,"why":"最後一句說即使雙語人員也須知道何時專業口譯比較安全。","evidence":"Still, even bilingual staff need to know when a professional interpreter is the safer choice."}],"band":"mid"},{"id":"b1-falls","level":"B1","title":"Preventing Falls at Home","topic":"社區護理","words":160,"paras":["Falls are a common reason why older adults go to hospital. A fall can lead to a broken hip, a head injury, or a long time in bed. Even when there is no serious injury, many older people become afraid of falling again, so they move less and become weaker.","Many falls happen at home, and many of them can be prevented. Community nurses often visit older people to look for risks. Common risks include poor lighting, loose rugs, wet bathroom floors, and things left on the stairs. Some medicines, such as sleeping pills, can also make people dizzy.","Small changes can make a big difference. Installing grab bars in the bathroom, using night lights, and wearing shoes with good grip are simple steps. Regular exercise that improves balance and leg strength is also helpful.","Families play an important role too. When they understand the risks, they can help keep the home safe and encourage their parents to stay active."],"zh":"跌倒是長者住院的常見原因，可能造成髖骨骨折、頭部受傷或長期臥床；就算沒有重傷，很多人會怕再跌而少動、變得更虛弱。很多跌倒發生在家裡，也多半能預防。社區護理師會家訪找風險：燈光不足、地毯鬆動、浴室地板濕、樓梯上堆東西，有些藥（如安眠藥）也會讓人頭暈。小改變效果很大：浴室裝扶手、用小夜燈、穿止滑的鞋，規律做增強平衡和腿力的運動。家人了解風險後也能幫忙維持居家安全、鼓勵長輩多活動。","qs":[{"type":"detail","q":"According to paragraph 1, why do some older people become weaker after a fall?","options":["They eat too much.","They take more sleeping pills.","They are afraid of falling again, so they move less."],"answer":2,"why":"many older people become afraid of falling again, so they move less and become weaker","evidence":"so they move less and become weaker"},{"type":"detail","q":"Which is NOT mentioned as a fall risk at home?","options":["Loose rugs","Poor lighting","Loud music"],"answer":2,"why":"第二段列出燈光、地毯、濕地板、樓梯雜物、藥物，沒有提到音樂。"},{"type":"vocab","q":"\\"Grab bars\\" are most likely…","options":["bathroom lights","bars you hold to stop yourself from falling","a kind of chocolate"],"answer":1,"why":"裝在浴室、用來防跌：grab 是「抓」，grab bars 是扶手。","evidence":"Installing grab bars in the bathroom"},{"type":"evidence","q":"Which sentence tells us that medicine can increase the risk of falling?","options":["\\"Families play an important role too.\\"","\\"Falls are a common reason why older adults go to hospital.\\"","\\"Some medicines, such as sleeping pills, can also make people dizzy.\\""],"answer":2,"why":"頭暈會增加跌倒風險，安眠藥是例子。","evidence":"Some medicines, such as sleeping pills, can also make people dizzy."},{"type":"main","q":"What is the best title?","options":["Falls at home: risks and prevention","How to build stairs","Why older people should stay in bed"],"answer":0,"why":"全文說跌倒的影響、居家風險和預防。"},{"type":"reference","q":"Who does \\"they\\" in \\"they can help keep the home safe\\" refer to?","options":["The sleeping pills mentioned earlier","Families","Only the community nurses"],"answer":1,"why":"前一句以 Families 為主詞，下一句 they 指家人。"},{"type":"detail","q":"Which abilities does the exercise mentioned in paragraph 3 aim to improve?","options":["Balance and leg strength","Reading speed and memory","Only hand strength"],"answer":0,"why":"第三段最後一句明確提到平衡與腿部力量。","evidence":"Regular exercise that improves balance and leg strength is also helpful."}],"band":"easy"},{"id":"b2-semmelweis","level":"B2","title":"The Doctor Who Asked Others to Wash Their Hands","topic":"醫學史","words":245,"ielts":true,"paras":["In the 1840s, the Vienna General Hospital had two maternity clinics. Women gave birth in both, but many more mothers died of childbed fever in the first clinic than in the second. The difference was so well known that some women begged to be admitted to the second clinic, and a few even preferred to give birth in the street.","Ignaz Semmelweis, a young Hungarian doctor working in the first clinic, wanted to understand why. He noticed that the first clinic was staffed by doctors and medical students, while the second was run by midwives. Importantly, the doctors and students often came directly from performing autopsies on dead bodies.","When a colleague died after being cut by a student's knife during an autopsy, with an illness similar to childbed fever, Semmelweis formed a theory. He believed that 'particles' from the bodies were being carried on the doctors' hands to the women. In 1847, he required staff to wash their hands in a chlorinated lime solution before examining patients. Deaths in the first clinic fell dramatically.","Despite these results, many doctors rejected his ideas. Some were offended by the suggestion that they themselves were causing deaths, and germ theory had not yet been developed to explain the findings. Semmelweis died in 1865, long before his work was widely accepted. Today, he is remembered as an early pioneer of hand hygiene, a practice that remains one of the most effective ways to prevent infections in hospitals."],"zh":"1840 年代維也納總醫院有兩個產科病房，第一病房死於產褥熱的產婦遠多於第二病房，有些產婦拜託進第二病房，甚至寧願在街上生。匈牙利年輕醫師塞麥爾維斯在第一病房工作，發現第一病房由醫師和醫學生負責，第二病房由助產士負責，而醫師和學生常剛做完大體解剖就直接過來。一位同事解剖時被學生的刀割傷後死亡，病況類似產褥熱，他推論屍體的「微粒」被醫師的手帶到產婦身上。1847 年他要求工作人員檢查病人前用含氯石灰溶液洗手，第一病房死亡率大幅下降。但很多醫師不接受，有人覺得被冒犯，當時也還沒有細菌理論。他 1865 年過世，遠早於他的研究被普遍接受。今天他被視為手部衛生的先驅。","qs":[{"type":"heading","q":"Choose the best heading for paragraph B (the 2nd paragraph).","options":["Women's fear of hospitals","A key difference between the two clinics","A theory is tested","Why his work was ignored"],"answer":1,"why":"第二段在比較兩個病房由誰負責、醫師剛做完解剖，是兩個病房的關鍵差異。"},{"type":"heading","q":"Choose the best heading for paragraph D (the 4th paragraph).","options":["Rejection, and recognition later","How childbed fever spreads today","A key difference between the two clinics","A theory is tested"],"answer":0,"why":"第四段說當時被拒絕，後來才被認可。"},{"revision":1,"type":"tfng","q":"Statement: More mothers died of childbed fever in the first clinic than in the second clinic.","options":["True","False","Not Given"],"answer":0,"why":"第一段直接比較兩間診所死於產褥熱的人數，第一間較多。","evidence":"many more mothers died of childbed fever in the first clinic than in the second"},{"type":"tfng","q":"Statement: The midwives in the second clinic also performed autopsies.","options":["True","False","Not Given"],"answer":2,"why":"文章只說醫師和學生常做解剖，沒提助產士有沒有做。沒寫到 → Not Given（不是 False）。","evidence":"the doctors and students often came directly from performing autopsies"},{"type":"tfng","q":"Statement: Most doctors accepted Semmelweis's ideas immediately.","options":["True","False","Not Given"],"answer":1,"why":"第四段：Semmelweis died in 1865, long before his work was widely accepted —— 他過世時，他的想法都還沒被普遍接受，所以「大多數醫師立刻接受」跟文章相反 → False。（many doctors rejected his ideas 只說「很多人」反對，單靠這句還不能推出「大多數」；真正的證據是「很久以後才被普遍接受」。）","evidence":"long before his work was widely accepted"},{"type":"detail","q":"What did Semmelweis require in 1847?","options":["Washing hands in a chlorinated lime solution before examining patients","Closing the first clinic","Stopping all autopsies"],"answer":0,"why":"he required staff to wash their hands in a chlorinated lime solution before examining patients","evidence":"he required staff to wash their hands in a chlorinated lime solution before examining patients"},{"type":"vocab","q":"\\"Dramatically\\" in \\"Deaths … fell dramatically\\" is closest to…","options":["by accident","by a large amount","slowly"],"answer":1,"why":"dramatically 表示變化很大、很明顯。"},{"type":"evidence","q":"Why did the colleague’s illness help Semmelweis form a theory?","options":["It proved that midwives were performing the same autopsies as the doctors.","It showed that no change in hand hygiene could affect deaths from childbed fever.","It suggested that something from an autopsy could also be involved in childbed fever."],"answer":2,"why":"同事在解剖時被劃傷後，出現類似產褥熱的病症，讓 Semmelweis 把解剖接觸與產婦疾病連在一起，提出手部傳播的假說；這不是單憑一個病例就證明全部原因。","evidence":"When a colleague died after being cut by a student's knife during an autopsy, with an illness similar to childbed fever, Semmelweis formed a theory."},{"type":"detail","q":"What made some doctors feel offended?","options":["The claim that midwives were paid too much","The closure of both maternity clinics","The suggestion that their own actions were causing deaths"],"answer":2,"why":"文章明確指出，部分醫師被「自己造成死亡」的暗示冒犯；並未提到薪資或關閉病房。","evidence":"Some were offended by the suggestion that they themselves were causing deaths, and germ theory had not yet been developed to explain the findings."},{"type":"tfng","q":"Statement: The death of a colleague helped lead Semmelweis to form his theory.","options":["True","False","Not Given"],"answer":0,"why":"第三段交代同事因解剖時被刀割傷，染上類似產褥熱的疾病而過世。這件事促使他提出解釋。","evidence":"When a colleague died after being cut by a student's knife during an autopsy, with an illness similar to childbed fever, Semmelweis formed a theory.","additional":true},{"type":"tfng","q":"Statement: Germ theory had already been developed when doctors first rejected his findings.","options":["True","False","Not Given"],"answer":1,"why":"末段說醫師反對他時，當時尚未發展出可解釋結果的微生物致病理論。","evidence":"germ theory had not yet been developed to explain the findings.","additional":true}],"band":"mid"},{"id":"b2-telehealth","level":"B2","title":"Nursing at a Distance","topic":"遠距醫療","words":205,"ielts":true,"paras":["Not long ago, almost all nursing care required the nurse and the patient to be in the same room. Today, telehealth allows some care to be delivered through phone calls, video visits, and devices that send health data from a patient's home to a hospital.","Supporters point out several benefits. Patients who live far from a hospital, or who find it difficult to travel, can receive advice without a long journey. People with long-term conditions, such as heart failure, can have their weight or blood pressure checked every day, so that nurses notice warning signs early. Some studies suggest this kind of monitoring can reduce hospital admissions for certain patients.","However, telehealth also has limits. A nurse cannot touch a swollen leg or smell an infected wound through a screen. Older patients may struggle with technology, and families without a stable internet connection may be left out. There are also concerns about privacy when personal health information is sent online.","Most experts agree that telehealth will not replace face-to-face care but will become part of it. For future nurses, this means new skills: clear communication on camera, careful questioning when physical examination is not possible, and knowing when a patient must be seen in person."],"zh":"不久前幾乎所有護理照護都要護理師和病人在同一個房間；現在遠距醫療可以用電話、視訊和把居家健康數據傳到醫院的裝置提供部分照護。支持者指出好處：住得遠或行動不便的人不用長途奔波；心衰竭等慢性病人可以每天測體重或血壓，讓護理師及早發現警訊；有研究顯示這種監測可能減少某些病人住院。但也有限制：隔著螢幕摸不到腫脹的腿、聞不到感染傷口的味道；長者可能不會用科技；網路不穩的家庭可能被排除；健康資料上網也有隱私疑慮。多數專家認為遠距醫療不會取代面對面照護，而是成為其中一部分；未來的護理師需要新技能：鏡頭前清楚溝通、無法身體檢查時仔細問診、知道什麼時候病人一定要親自來。","qs":[{"type":"heading","q":"Choose the best heading for paragraph B (the 2nd paragraph).","options":["The history of hospitals","Advantages of care at a distance","What telehealth cannot do","Skills for the future"],"answer":1,"why":"第二段列出支持者說的好處。"},{"type":"heading","q":"Choose the best heading for paragraph C (the 3rd paragraph).","options":["Skills for the future","How to buy a device","Advantages of care at a distance","Problems and limits"],"answer":3,"why":"However 開頭，接著說限制和問題。"},{"type":"tfng","q":"Statement: Telehealth can help nurses notice warning signs early in some patients.","options":["True","False","Not Given"],"answer":0,"why":"第二段：so that nurses notice warning signs early → True。","evidence":"so that nurses notice warning signs early"},{"type":"tfng","q":"Statement: Telehealth is cheaper than face-to-face care for all patients.","options":["True","False","Not Given"],"answer":2,"why":"文章沒有比較費用 → Not Given。小心不要用自己的常識答題。"},{"type":"tfng","q":"Statement: Experts believe telehealth will completely replace face-to-face care.","options":["True","False","Not Given"],"answer":1,"why":"最後一段：will not replace face-to-face care → False。","evidence":"telehealth will not replace face-to-face care"},{"type":"detail","q":"According to paragraph C, why might some families be left out?","options":["They do not have a stable internet connection.","They live too close to the hospital.","They do not have long-term conditions."],"answer":0,"why":"families without a stable internet connection may be left out","evidence":"families without a stable internet connection may be left out"},{"type":"evidence","q":"Which phrase shows a skill future nurses will need?","options":["\\"a swollen leg\\"","\\"careful questioning when physical examination is not possible\\"","\\"a long journey\\""],"answer":1,"why":"最後一段列出新技能，這是其中之一。","evidence":"careful questioning when physical examination is not possible"},{"type":"vocab","q":"In paragraph C, what does \\"left out\\" mean?","options":["Asked to leave a hospital building immediately","Placed outside while equipment is repaired","Unable to take part in or benefit from the service"],"answer":2,"why":"這裡接在沒有穩定網路的家庭後面，表示可能無法參與或使用遠距服務。"},{"type":"tfng","q":"Statement: The passage reports concerns about the privacy of health information sent online.","options":["True","False","Not Given"],"answer":0,"why":"第三段把個人健康資訊在線上傳送時的隱私和取得設備的障礙一起列為限制。","evidence":"There are also concerns about privacy when personal health information is sent online.","additional":true}],"band":"easy"},{"id":"b2-shortage","level":"B2","title":"Why Nurses Leave","topic":"護理職場","words":181,"ielts":true,"paras":["In many countries, hospitals report that it is difficult to keep enough nurses. The problem is not only training new nurses but also keeping experienced ones. When nurses leave the profession early, hospitals lose skills that took years to build.","Surveys of nurses often point to heavy workloads as a main reason for leaving. When one nurse is responsible for too many patients, there is little time for anything beyond essential tasks. Many nurses say this is stressful not only because they are tired, but because they feel they cannot give the quality of care they were trained to provide.","Other factors include irregular shifts, low pay compared with the level of responsibility, and limited opportunities for career development. Experiences of verbal abuse from patients or visitors can also make the job harder.","Some hospitals have tried to respond. Measures include safer staffing levels, mentoring programs for new graduates, flexible scheduling, and support services for staff wellbeing. Researchers note that no single measure is enough on its own; nurses are more likely to stay when several of these improvements work together."],"zh":"很多國家的醫院表示很難留住足夠的護理師，問題不只是培養新人，還有留住資深人員；太早離開會讓醫院失去多年累積的技能。調查常指出工作量太大是主要離職原因：一人顧太多病人，只能做最必要的事；很多人說壓力大不只是累，而是覺得無法提供受訓時學到的照護品質。其他因素包括輪班不規律、薪水和責任不成比例、升遷發展機會少，還有被病人或訪客言語暴力。有些醫院開始回應：更安全的人力比、新人導師制、彈性排班、員工身心支持。研究者指出沒有單一措施就夠，多項改善一起做，護理師才更可能留下來。","qs":[{"type":"heading","q":"Choose the best heading for paragraph B (the 2nd paragraph).","options":["How hospitals are responding","Training new nurses","The history of nursing","Too much work, too little time"],"answer":3,"why":"第二段在說工作量太大、時間不夠。"},{"type":"heading","q":"Choose the best heading for paragraph D (the 4th paragraph).","options":["Too much work, too little time","How hospitals are responding","Why patients complain","Pay in other countries"],"answer":1,"why":"Some hospitals have tried to respond… 接著列措施。"},{"type":"tfng","q":"Statement: According to surveys, heavy workload is a main reason nurses leave.","options":["True","False","Not Given"],"answer":0,"why":"第二段第一句 → True。","evidence":"Surveys of nurses often point to heavy workloads as a main reason for leaving."},{"type":"tfng","q":"Statement: Nurses feel stressed only because they are physically tired.","options":["True","False","Not Given"],"answer":1,"why":"文章說 not only because they are tired, but because…，所以「只因為累」是錯的 → False。","evidence":"not only because they are tired"},{"type":"tfng","q":"Statement: Mentoring programs are more effective than flexible scheduling.","options":["True","False","Not Given"],"answer":2,"why":"文章列了兩者，但沒有比較哪個比較有效 → Not Given。"},{"type":"detail","q":"What do researchers say about the measures?","options":["None of them help.","Several improvements working together help most.","One measure is enough."],"answer":1,"why":"no single measure is enough on its own; nurses are more likely to stay when several of these improvements work together","evidence":"nurses are more likely to stay when several of these improvements work together"},{"type":"vocab","q":"\\"Verbal abuse\\" (paragraph C) means…","options":["a medical test","a kind of shift","hurtful or threatening words"],"answer":2,"why":"verbal 是「言語的」，abuse 是「傷害、虐待」，合起來是言語暴力。"},{"type":"evidence","q":"Why would training new nurses alone leave part of the problem unresolved?","options":["The departure of experienced nurses also removes accumulated skills.","New nurses are never able to learn essential tasks.","The article says hospitals already have too many experienced nurses."],"answer":0,"why":"作者把培養新人和留住資深人員分開談；資深人員離職也會帶走多年累積的技能。","evidence":"When nurses leave the profession early, hospitals lose skills that took years to build."},{"type":"tfng","q":"Statement: The hospitals described have also offered programmes to nurses planning to retire.","options":["True","False","Not Given"],"answer":2,"why":"第四段點名新畢業護理師的導師計畫和一般支援服務，全文沒提退休前的計畫。","evidence":"Measures include safer staffing levels, mentoring programs for new graduates, flexible scheduling, and support services for staff wellbeing.","additional":true}],"band":"easy"},{"id":"br43-r1","level":"B2","title":"The Night the Lights Went Out","topic":"橋接 43：敘事時態","words":315,"unit":48,"paras":["It was just after two in the morning, and most of the patients on Ward 7 were sleeping. I was checking the drip of an elderly man in Bed 12 while my colleague, Ming, was writing up her notes at the nurses' station. Outside, a storm had been building for hours, but none of us had paid much attention to it.","Then, without any warning, the lights went out. For a few seconds the ward was completely dark and silent, apart from the rain hitting the windows. A patient called out in fear. I remember thinking that I had never heard the ward so quiet before. Then the emergency lights came on, and the machines beside the beds began to beep as they switched to battery power.","Ming and I knew what to do, because the hospital had run a power-cut drill only two weeks earlier. She went to check the patients who were on oxygen, while I walked from bed to bed with a torch, telling people that they were safe and that the power would soon return. Mr. Wu in Bed 3, who had arrived that afternoon after a fall, was trying to climb out of bed. He was confused and thought he was at home. I sat with him and held his hand until he calmed down.","The main power came back after about twenty minutes, but it felt much longer. When the day staff arrived at seven, we told them everything that had happened. The head nurse said that the drill had clearly been worth the time it took.","I used to think that drills were a waste of time. I used to stand at the back and check my phone while the trainer was talking. That night changed my mind. Now, whenever we practise for an emergency, I pay attention, because I know that one day it might be real."],"zh":"凌晨兩點多，病房大多數病人在睡。作者正在幫 12 床的老先生檢查點滴，同事 Ming 在護理站寫紀錄；外面的暴風雨已經醞釀好幾個小時，但沒人注意。突然停電，病房一片黑，有病人害怕地叫出聲；接著緊急照明亮起，床邊的機器切換到電池而嗶嗶叫。因為兩週前醫院才做過停電演練，她們知道怎麼做：Ming 去看用氧氣的病人，作者拿手電筒逐床安撫。當天下午跌倒住院的 3 床吳先生搞不清楚狀況想爬下床，作者握著他的手直到他平靜。大約二十分鐘後復電。作者以前覺得演練浪費時間，那一晚之後改觀，現在每次演練都認真聽。","qs":[{"type":"main","q":"What is the passage mainly about?","options":["How a nurse and her colleague handled a power cut at night","Why storms often cause power cuts in hospitals","How to train new nurses for night shifts"],"answer":0,"why":"整篇在講停電那一晚她們怎麼處理，最後說作者對演練的看法改變了。"},{"type":"detail","q":"What was the writer doing when the lights went out?","options":["Writing notes at the nurses' station","Checking a patient's drip","Talking to the head nurse"],"answer":1,"why":"第一段：I was checking the drip…——過去進行式 was checking 是停電那一刻正在做的事；在寫紀錄的是 Ming。","evidence":"I was checking the drip of an elderly man in Bed 12"},{"type":"tfng","q":"Statement: The hospital had practised for a power cut before that night.","options":["True","False","Not Given"],"answer":0,"why":"had run 是過去完成式：在停電「之前」就做過演練（two weeks earlier）→ True。","evidence":"the hospital had run a power-cut drill only two weeks earlier"},{"type":"reference","q":"In \\"until he calmed down\\", who does \\"he\\" refer to?","options":["Ming","Mr. Wu","The man in Bed 12"],"answer":1,"why":"前面兩句都在講 3 床的吳先生（Mr. Wu），he 指他。","evidence":"I sat with him and held his hand until he calmed down."},{"type":"tfng","q":"Statement: The writer has always taken emergency drills seriously.","options":["True","False","Not Given"],"answer":1,"why":"used to 表示「以前這樣、現在不是了」：她以前覺得演練浪費時間，那晚之後才改觀 → False。","evidence":"I used to think that drills were a waste of time."},{"type":"heading","q":"Which heading best fits paragraph C (paragraph 3)?","options":["Investigating why the storm began","Introducing a new hospital building","Putting earlier preparation into action"],"answer":2,"why":"第三段描述兩位護理師把先前演練用在停電現場，分工查看與安撫病人。"},{"type":"vocab","q":"In paragraph C, \\"calmed down\\" means that Mr. Wu became…","options":["more physically active","ready to leave the hospital","less frightened or upset"],"answer":2,"why":"作者坐在旁邊握住他的手，直到他由混亂、想下床轉為較平靜。"},{"type":"evidence","q":"What does the final paragraph suggest about the writer’s future behaviour?","options":["She plans to avoid every future night shift.","She believes preparation is unnecessary when colleagues are present.","She now sees emergency practice as relevant to real work."],"answer":2,"why":"作者把未來認真參與演練的原因連到實際可能遇到的緊急狀況。","evidence":"Now, whenever we practise for an emergency, I pay attention, because I know that one day it might be real."}],"band":"easy"},{"id":"br43-r2","level":"B2","title":"Mary Seacole: The Nurse Who Went Anyway","topic":"橋接 43：敘事時態","words":281,"unit":48,"paras":["Mary Seacole was born in Kingston, Jamaica, in 1805. Her mother ran a boarding house and was known as a 'doctress', a woman who treated sick people with traditional medicine. As a girl, Mary used to watch her mother at work, and by the time she was a young woman, she had learned a great deal about caring for the sick.","As an adult, Seacole travelled widely. In the early 1850s she was living in Panama when cholera broke out there. She had seen the disease before in Jamaica, so she knew how to nurse people through it, and she treated many patients.","In 1854, news reached Britain that British soldiers were dying in the Crimean War, many of them from disease rather than from their wounds. Seacole travelled to London and offered to go to the war as a nurse. However, her application was turned down. She later wrote that she wondered whether this had happened because of the colour of her skin.","Seacole did not give up. She decided to pay for the journey herself. With a business partner, she set up the 'British Hotel' near the battlefront, a place where officers could buy food and supplies and where sick and wounded soldiers could get care. She often rode out to the battlefield itself, carrying medicine and food.","When the war ended, Seacole returned to London with very little money, as her business had failed. In 1857 she published a book about her life, which became popular. For many years after her death in 1881 she was largely forgotten, but in 2016 a statue of her was put up in the grounds of St Thomas' Hospital in London."],"zh":"瑪麗．西戈爾 1805 年生於牙買加京斯敦，母親經營寄宿旅館，也用傳統醫術照顧病人；她從小看母親工作，長大時已經學會很多照顧病人的知識。成年後她到處旅行，1850 年代初住在巴拿馬時遇上霍亂，因為之前在牙買加就見過這種病，所以知道怎麼照護。1854 年英國士兵在克里米亞戰爭中大量死亡，很多是死於疾病。她到倫敦申請當隨軍護士卻被拒絕，她後來寫道懷疑是因為膚色。她沒有放棄，自費前往，和合夥人在前線附近開了「英國旅館」，賣食物補給，也照顧傷病士兵，還常騎馬到戰場送藥和食物。戰後她生意失敗、幾乎沒錢；1857 年出版自傳並暢銷。她 1881 年過世後長期被遺忘，2016 年倫敦聖湯瑪士醫院立了她的雕像。","qs":[{"type":"detail","q":"How did Mary Seacole first learn about caring for the sick?","options":["By training at a hospital in London","By watching her mother","By working as a soldier's assistant"],"answer":1,"why":"第一段：As a girl, Mary used to watch her mother at work——used to 是小時候常做的事。","evidence":"As a girl, Mary used to watch her mother at work"},{"type":"detail","q":"Why did Seacole know how to treat cholera patients in Panama?","options":["She had studied it at university.","She had seen the disease before in Jamaica.","A doctor in Panama had taught her."],"answer":1,"why":"had seen 是過去完成式：到巴拿馬「之前」就在牙買加見過霍亂。","evidence":"She had seen the disease before in Jamaica"},{"type":"tfng","q":"Statement: The British government paid for Seacole's journey to the war.","options":["True","False","Not Given"],"answer":1,"why":"文章說她被拒絕之後決定自己出錢（pay for the journey herself）→ False。","evidence":"She decided to pay for the journey herself."},{"type":"tfng","q":"Statement: The British Hotel was the largest building near the battlefront.","options":["True","False","Not Given"],"answer":2,"why":"文章只說旅館在前線附近、賣什麼、照顧誰，完全沒提大小 → Not Given。"},{"type":"vocab","q":"In paragraph 3, 'turned down' is closest in meaning to…","options":["refused","lost","made smaller"],"answer":0,"why":"her application was turned down：申請被「拒絕」，後面她才決定自己去。","evidence":"However, her application was turned down."},{"type":"heading","q":"Which heading best fits paragraph D (paragraph 4)?","options":["Receiving official payment for the journey","Retiring permanently from nursing","Finding her own way to help near the battlefront"],"answer":2,"why":"第四段在申請被拒後，描述她自行付旅費並成立提供物資與照護的場所。"},{"type":"evidence","q":"What does the final paragraph suggest about public recognition of Seacole?","options":["It changed over time rather than remaining constant.","It ended permanently when her business failed.","It was strongest only during her childhood."],"answer":0,"why":"文中先說她死後長期被遺忘，再提到 2016 年立像，顯示評價與紀念會隨時間改變。","evidence":"For many years after her death in 1881 she was largely forgotten, but in 2016 a statue of her was put up in the grounds of St Thomas' Hospital in London."},{"type":"detail","q":"What did Seacole publish in 1857?","options":["A government report on hospital spending","A map of the battlefield","A book about her life"],"answer":2,"why":"最後一段明確交代 1857 年出版的是自傳性質的書。","evidence":"In 1857 she published a book about her life, which became popular."},{"type":"tfng","q":"Statement: Seacole returned to London after the war with very little money.","options":["True","False","Not Given"],"answer":0,"why":"最後一段直接說 very little money，並解釋她的事業失敗。","evidence":"When the war ended, Seacole returned to London with very little money, as her business had failed."},{"type":"tfng","q":"Statement: Seacole never left the British Hotel to visit the battlefield.","options":["True","False","Not Given"],"answer":1,"why":"第四段說她常親自騎馬到戰場，並帶著藥品和食物。","evidence":"She often rode out to the battlefield itself, carrying medicine and food.","additional":true}],"band":"mid"},{"id":"br43-held","level":"B2","title":"The Wrong Bus","topic":"橋接 43：敘事時態","words":247,"unit":48,"held":true,"paras":["On the first morning of my clinical placement, I woke up an hour early. I had laid out my uniform the night before, and I had checked the bus route three times. I was determined not to be late.","At the bus stop, I was reading my notes on infection control when a bus pulled up. I glanced at the number, saw a seven, and climbed on. Only after ten minutes did I realise that I had taken the number 17, not the number 7. By then, we were heading in completely the wrong direction.","I got off at the next stop and stood on the pavement, feeling sick. My phone battery was almost dead, because I had been studying on it all morning. I used to panic in situations like this, but my placement teacher had told us something useful: 'When things go wrong, call early.' So I called the ward and explained what had happened.","The nurse who answered was calm. She told me which bus to take and said that the morning handover would not start until half past seven. When I finally walked onto the ward, twenty minutes late and out of breath, she was waiting for me. 'You called before we started worrying,' she said. 'That's exactly what we want from a nurse.'","I still feel embarrassed when I think about that morning. But I learned two things: check the number twice, and when you make a mistake, tell someone straight away."],"zh":"實習第一天作者提早一小時起床，前一晚就把制服準備好、公車路線查了三次。在公車站讀感染控制筆記時，她瞄到號碼有個 7 就上車，十分鐘後才發現搭的是 17 號，方向完全相反。她下車時手機快沒電（整個早上都在用手機讀書）。她以前遇到這種事會慌，但實習老師說過「出狀況就早點打電話」，於是她打給病房說明。接電話的護理師很冷靜，告訴她搭哪班車，說交班七點半才開始。她遲到二十分鐘、氣喘吁吁地到病房，那位護理師說：「你在我們開始擔心之前就打來了，這正是我們希望護理師做的。」她學到兩件事：號碼看兩次；犯錯就馬上告訴別人。","qs":[{"type":"main","q":"What is the main lesson the writer learned?","options":["Taking the bus is not a good way to get to work.","It is better to report a problem early than to hide it.","Students should not study on their phones."],"answer":1,"why":"最後一段：when you make a mistake, tell someone straight away；護理師也稱讚她早點打電話。"},{"type":"detail","q":"Why did the writer get on the wrong bus?","options":["She did not look at the number carefully.","The bus driver gave her wrong information.","Her usual bus had been cancelled."],"answer":0,"why":"她只是 glanced（瞄一眼），看到 7 就上車，其實是 17。","evidence":"I glanced at the number, saw a seven, and climbed on."},{"type":"evidence","q":"Which sentence best shows that the writer had prepared carefully?","options":["I had laid out my uniform the night before, and I had checked the bus route three times.","I got off at the next stop and stood on the pavement, feeling sick.","I still feel embarrassed when I think about that morning."],"answer":0,"why":"過去完成式 had laid out、had checked：出門「之前」就準備好了。","evidence":"I had laid out my uniform the night before, and I had checked the bus route three times."},{"type":"tfng","q":"Statement: The writer's phone was almost out of battery because she had used it to study.","options":["True","False","Not Given"],"answer":0,"why":"because I had been studying on it all morning：電快沒了的原因就是整個早上用它讀書 → True。","evidence":"My phone battery was almost dead, because I had been studying on it all morning."},{"revision":1,"type":"tfng","q":"Statement: The nurse told the writer that the morning handover had already started.","options":["True","False","Not Given"],"answer":1,"why":"她說早班交接要到七點半才開始，與交接已經開始的敘述相反。","evidence":"said that the morning handover would not start until half past seven."},{"type":"heading","q":"Which heading best fits paragraph C (paragraph 3)?","options":["Discovering that the placement was cancelled","Choosing a new nursing course","Using earlier advice when a problem occurs"],"answer":2,"why":"第三段寫下車後的困境，再帶出老師的建議與打電話告知的行動。"},{"type":"vocab","q":"In paragraph B, \\"glanced at\\" means…","options":["copied down carefully","asked someone to explain","looked at briefly"],"answer":2,"why":"作者只匆匆看車號而看錯，因此 glanced at 是快速看一下。"},{"type":"tfng","q":"Statement: The nurse who answered the telephone had worked on that ward for ten years.","options":["True","False","Not Given"],"answer":2,"why":"文章交代她如何回應與提供路線，沒有交代她在病房工作的年資；不能推論是十年，也不能推論不是。","evidence":"The nurse who answered was calm."}],"band":"easy"},{"id":"br44-r1","level":"B2","title":"Your Clinical Placement: What to Expect","topic":"橋接 44：未來安排、未來進行式和未來完成式","words":262,"unit":49,"paras":["Dear second-year students, your first clinical placement starts on Monday, 3 March, and lasts four weeks. This email explains what you will be doing and what you will need to bring. Please read it carefully before your orientation meeting next Friday.","During the first week, you won't be working with patients on your own. Instead, each of you will be following an experienced nurse, called your mentor, for the whole shift. You will be watching how your mentor plans the day, talks to patients and records information. Your mentor will be expecting you to ask questions, so please do not be shy.","From the second week, you will be taking care of one or two patients yourselves, with your mentor checking your work. By the end of the second week, you will have practised taking vital signs, giving oral medication under supervision and writing simple nursing notes. In week three, you will be presenting a short case study to your group.","The morning shift starts with handover at 7:30 a.m., so please arrive by 7:15. Please bring your student ID card, a watch with a second hand, and a small notebook. Phones must be kept in your locker during the shift.","By the time the placement finishes, you will have completed about 120 hours on the ward. On the last day, you and your mentor will be meeting to discuss your progress. If you have any questions before then, I will be holding an online question session this Wednesday at 6 p.m. Best wishes, Ms. Lin, Clinical Coordinator"],"zh":"臨床實習協調員林老師寫給二年級學生的信：第一次實習 3 月 3 日（週一）開始，為期四週。第一週不會自己照顧病人，而是每個人整個班次都跟著自己的導師（一位資深護理師），看她怎麼安排一天、跟病人溝通、做紀錄，導師會期待學生發問。第二週起自己照顧一到兩位病人，導師會檢查；第二週結束前會練習量生命徵象、在督導下給口服藥、寫簡單的護理紀錄；第三週要向小組報告個案。早班七點半交班，請七點十五分前到，帶學生證、有秒針的手錶和小筆記本，手機要放置物櫃。實習結束時會累積約 120 小時，最後一天和導師面談進度；週三晚上六點有線上問答。","qs":[{"type":"main","q":"What is the main purpose of this email?","options":["To tell students what will happen during their placement","To invite students to apply for a job","To explain how to become a mentor"],"answer":0,"why":"開頭就說這封信說明 what you will be doing and what you will need to bring。"},{"type":"detail","q":"What will students be doing in the first week?","options":["Caring for two patients alone","Following an experienced nurse","Presenting a case study"],"answer":1,"why":"will be following 是未來進行式：第一週那段時間「正在」跟著導師。照顧病人是第二週，報告是第三週。","evidence":"each of you will be following an experienced nurse, called your mentor, for the whole shift"},{"type":"tfng","q":"Statement: By the end of week two, students will have practised giving oral medication under supervision.","options":["True","False","Not Given"],"answer":0,"why":"By the end of the second week, you will have practised…——未來完成式：在第二週結束「之前」就會練過 → True。","evidence":"By the end of the second week, you will have practised taking vital signs, giving oral medication under supervision"},{"type":"tfng","q":"Statement: Students may keep their phones with them during the shift if the phones are on silent.","options":["True","False","Not Given"],"answer":1,"why":"信上說手機一定要放在置物櫃（must be kept in your locker），沒有「靜音就可以」→ False。","evidence":"Phones must be kept in your locker during the shift."},{"type":"tfng","q":"Statement: The online question session will be recorded for students who cannot attend.","options":["True","False","Not Given"],"answer":2,"why":"只說週三晚上六點有線上問答，沒提會不會錄影 → Not Given。"},{"type":"heading","q":"Which heading best fits paragraph C (paragraph 3)?","options":["Working alone from the first morning","Increasing responsibility with supervision","Cancelling the case study requirement"],"answer":1,"why":"第三段說第二週開始照護少數病人，但仍有人檢查，之後加入案例報告。"},{"type":"vocab","q":"In paragraph C, \\"under supervision\\" means…","options":["without anyone knowing the activity is happening","after all placement requirements have ended","with an experienced person overseeing the activity"],"answer":2,"why":"supervision 指督導與監督；文章也說 mentor 會檢查工作。"},{"type":"evidence","q":"Which conclusion about students’ questions is supported by the email?","options":["Questions are an expected part of the learning process.","Asking questions automatically leads to failure.","Questions are permitted only after all four weeks."],"answer":0,"why":"帶教者期待學生發問，因此不確定時提問是預期的學習活動。","evidence":"Your mentor will be expecting you to ask questions, so please do not be shy."},{"type":"tfng","q":"Statement: Students will discuss their progress with their mentors on the last day.","options":["True","False","Not Given"],"answer":0,"why":"末段說實習的最後一天，學生會與指導護理師討論自己的進步。","evidence":"On the last day, you and your mentor will be meeting to discuss your progress.","additional":true}],"band":"easy"},{"id":"br44-r2","level":"B2","title":"The Year Ahead: Planning Your Final Year","topic":"橋接 44：未來安排、未來進行式和未來完成式","words":269,"unit":49,"paras":["For many nursing students, the final year feels like a race. You will be finishing your last clinical placements, writing reports and, at the same time, preparing for the licensing exam. Without a plan, it is easy to feel that you are always running behind.","Experienced teachers suggest starting with the end in mind. Write down the date of your exam, and then work backwards. Ask yourself: what will I need to have finished by then? For example, if your exam is in July, you might decide that by the end of March you will have reviewed every subject once, and by the end of May you will have done at least three full practice tests.","Next, look at the weeks when you will be busy with other things. If you know that you will be working night shifts on a placement in April, do not plan heavy study for that month. Instead, plan short review sessions, such as fifteen minutes of flashcards on the bus.","It also helps to tell other people about your plan. If your family knows that you will be studying every Saturday morning, they are less likely to ask you to do other things at that time. Some students form study groups and agree on goals: 'By next Friday, we'll have finished the cardiovascular chapter.'","Finally, remember to plan rest. A student who is studying fourteen hours a day in June will probably be exhausted by July. This time next year, you will be wearing your own uniform and working as a qualified nurse. The aim is to arrive there healthy, not burnt out."],"zh":"對很多護理系學生來說，最後一年像在賽跑：要完成最後的實習、寫報告，同時準備國考，沒有計畫就會一直覺得落後。老師建議從終點往回推：寫下考試日期，問自己到那時要完成什麼——例如七月考，就訂三月底前每科都複習過一次、五月底前至少做完三回完整模擬考。接著看哪幾週會忙別的事，例如四月實習要上大夜，就別排重的讀書計畫，改成短時間複習，像在公車上看十五分鐘字卡。把計畫告訴別人也有幫助：家人知道你每週六早上要讀書，就比較不會那時找你做別的事；有些人組讀書會一起訂目標。最後要記得安排休息：六月每天讀十四小時的人，到七月大概已經累垮。明年這時候你會穿著自己的制服當正式護理師，目標是健康地抵達，而不是燃燒殆盡。","qs":[{"type":"main","q":"What is the writer's main advice?","options":["Study as many hours as possible every day.","Make a plan that works backwards from the exam date.","Avoid clinical placements in the final year."],"answer":1,"why":"第二段的核心：Write down the date of your exam, and then work backwards，後面幾段都是怎麼排這個計畫。"},{"type":"detail","q":"According to paragraph 3, what should students do in a month with night shifts?","options":["Plan short review sessions instead of heavy study","Stop studying completely","Take more practice tests"],"answer":0,"why":"第三段：do not plan heavy study… Instead, plan short review sessions。","evidence":"Instead, plan short review sessions"},{"type":"reference","q":"In \\"they are less likely to ask you to do other things\\", what does \\"they\\" refer to?","options":["Other students","The student's family","Teachers"],"answer":1,"why":"同一句前半句的主詞是 your family，they 指家人。","evidence":"If your family knows that you will be studying every Saturday morning, they are less likely to ask you to do other things at that time."},{"type":"vocab","q":"In paragraph 5, 'burnt out' is closest in meaning to…","options":["extremely tired from too much work","unable to find a job","badly injured in a fire"],"answer":0,"why":"前一句說每天讀十四小時會 exhausted（累垮），burnt out 就是長期太累、耗盡。","evidence":"The aim is to arrive there healthy, not burnt out."},{"type":"tfng","q":"Statement: The writer says study groups always produce better exam results.","options":["True","False","Not Given"],"answer":2,"why":"文章只說有些人組讀書會一起訂目標，沒說讀書會的成績一定比較好 → Not Given。"},{"type":"heading","q":"Which heading best fits paragraph A (paragraph 1)?","options":["Completing all placements before starting exam preparation","Competing demands in the final year","Choosing the first subject for a study group"],"answer":1,"why":"第一段同時提到最後階段實習、報告與考照準備，說明多種要求並行，以及沒有計畫時容易覺得落後。"},{"type":"evidence","q":"Why does the writer suggest sharing a study plan with family?","options":["It makes the family responsible for taking the exam.","It guarantees that the student will pass.","It may reduce requests that conflict with protected study time."],"answer":2,"why":"家人知道固定讀書時段，就較不會在那時安排其他事；這不是保證成績。","evidence":"If your family knows that you will be studying every Saturday morning, they are less likely to ask you to do other things at that time."},{"type":"tfng","q":"Statement: In the example of a July exam, the student might aim to finish at least three full practice tests by the end of May.","options":["True","False","Not Given"],"answer":0,"why":"第二段的例子直接列出五月底前至少三份完整模擬考；這是可能的計畫，不是所有學生的硬性規定。","evidence":"For example, if your exam is in July, you might decide that by the end of March you will have reviewed every subject once, and by the end of May you will have done at least three full practice tests."}],"band":"easy"},{"id":"br44-held","level":"B2","title":"Orientation Week for New Staff","topic":"橋接 44：未來安排、未來進行式和未來完成式","words":260,"unit":49,"held":true,"paras":["Welcome to Riverside General Hospital. We are delighted that you are joining our nursing team. Your orientation week begins on Monday, 1 September. During this week you will not be assigned any patients. Instead, you will be getting to know the hospital, its systems and the people you will be working with.","On Monday morning, you will be attending a welcome talk by the Director of Nursing, followed by a tour of the main building. In the afternoon, the IT team will be setting up your account for the electronic health record system, so please bring your staff card.","Tuesday and Wednesday are training days. You will be practising emergency procedures, including basic life support, in our simulation centre. By Wednesday afternoon, you will have completed the fire safety course, which every member of staff must pass before working on a ward.","On Thursday, you will be spending the whole day on the ward where you will work, shadowing a senior nurse. This is a good chance to learn the ward routine and to ask questions. On Friday, you will be meeting your preceptor, an experienced nurse who will support you during your first three months.","By the end of the week, you will have met most of the people you need to know, and you will have a clear idea of what your first month will look like. Lunch will be provided every day in the staff canteen. If you are unable to attend any part of the programme, please let the education office know as soon as possible."],"zh":"歡迎新進護理人員的信：新人訓練週 9 月 1 日（週一）開始，這週不會分配病人，而是認識醫院、系統和同事。週一上午聽護理部主任致詞、參觀主大樓，下午資訊組會幫你開電子病歷帳號，所以要帶員工證。週二、週三是訓練日，在模擬中心練習急救流程（含基本救命術）；週三下午前要完成消防安全課程，所有員工都要通過才能上病房。週四整天到自己未來的病房跟著資深護理師見習；週五和你的臨床輔導員（preceptor）見面，她會在前三個月支持你。週末時你會認識大部分需要認識的人，也會清楚第一個月的樣子。每天在員工餐廳供應午餐；不能參加的部分要盡快告訴教育室。","qs":[{"type":"main","q":"What is this text mainly about?","options":["The plan for new nurses' first week","How to apply for a job at the hospital","The history of Riverside General Hospital"],"answer":0,"why":"整封信一天一天說明新人訓練週要做什麼。"},{"type":"detail","q":"Why should new staff bring their staff card on Monday?","options":["To get free lunch","So that their computer account can be set up","To enter the simulation centre"],"answer":1,"why":"週一下午資訊組要幫你開電子病歷帳號，so please bring your staff card。","evidence":"the IT team will be setting up your account for the electronic health record system, so please bring your staff card"},{"type":"tfng","q":"Statement: New staff must pass the fire safety course before they work on a ward.","options":["True","False","Not Given"],"answer":0,"why":"消防課程 every member of staff must pass before working on a ward → True。","evidence":"which every member of staff must pass before working on a ward"},{"type":"tfng","q":"Statement: New nurses will look after two patients on Thursday.","options":["True","False","Not Given"],"answer":1,"why":"第一段就說這一週不會分配任何病人（not be assigned any patients），週四是見習 → False。","evidence":"During this week you will not be assigned any patients."},{"type":"vocab","q":"In paragraph 4, a 'preceptor' is…","options":["a nurse who supports a new nurse during the first months","a computer system for patient records","a patient who has just been admitted"],"answer":0,"why":"逗號後面就是解釋：an experienced nurse who will support you during your first three months。","evidence":"your preceptor, an experienced nurse who will support you during your first three months"},{"type":"heading","q":"Which heading best fits paragraph C (paragraph 3)?","options":["Choosing meals for the staff canteen","Meeting patients without a supervisor","Completing required safety training"],"answer":2,"why":"第三段說明兩天的緊急應變與消防訓練，重點是安全準備。"},{"type":"evidence","q":"What can be inferred about the purpose of the orientation week?","options":["It is intended to replace all later support from a preceptor.","Its main goal is to test how many patients each nurse can manage.","It provides preparation before staff take responsibility for patients."],"answer":2,"why":"首段明說這週不分配病人，接著安排了解環境與系統，可推知先做上工準備。","evidence":"During this week you will not be assigned any patients."},{"type":"tfng","q":"Statement: The provided lunches will include a vegetarian option every day.","options":["True","False","Not Given"],"answer":2,"why":"只說每天供應午餐，沒有列餐點內容或素食選項；不能由供餐推出菜單。","evidence":"Lunch will be provided every day in the staff canteen."}],"band":"easy"},{"id":"br45-r1","level":"B2","title":"Reading the Clues: Sudden Confusion in Older Patients","topic":"橋接 45：推測","words":277,"unit":50,"paras":["Mrs. Huang, an 82-year-old woman, had been on the orthopaedic ward for three days after a hip operation. She had been chatting happily with the nurses every morning. But on the fourth morning, she did not recognise her own daughter and kept asking where she was. Her daughter was shocked. 'She must be getting dementia,' she said.","The nurse, however, was not so sure. Dementia usually develops slowly, over months or years. Mrs. Huang had changed overnight. A sudden change like this is called delirium, and in older patients it can have many causes, including infection, dehydration, pain and certain medicines.","The nurse began to look for clues. Mrs. Huang's water jug was still full from the night before, so she might not have been drinking enough. Her temperature was slightly raised, and her urine was dark and smelled strong. 'She could have a urinary tract infection,' the nurse thought. She also checked the medication chart. A new sleeping pill had been started two nights earlier. That might have played a part too.","The nurse did not try to make a diagnosis herself. Instead, she reported her observations to the doctor clearly: what had changed, when it had changed and what she had noticed. Tests later showed that Mrs. Huang did have an infection. With antibiotics, fluids and a change in her medicines, she was back to her usual self within a few days.","This case shows why nurses should never assume that confusion in an older person is 'just old age'. A family member may conclude that nothing can be done, but a careful nurse asks a different question: what must have changed, and why?"],"zh":"82 歲的黃太太髖關節手術後在骨科病房住了三天，每天早上都跟護理師聊得很開心；第四天早上卻認不出自己的女兒、一直問自己在哪裡。女兒嚇到，說她一定是失智了。護理師不這麼確定：失智通常是幾個月、幾年慢慢發生，黃太太卻是一夜之間改變。這種突然的改變叫譫妄，老人家的原因很多，包括感染、脫水、疼痛和某些藥物。護理師開始找線索：水壺從前一晚到現在還是滿的，可能喝得不夠；體溫稍高、尿色深而且味道重，可能是泌尿道感染；兩天前開始吃一種新的安眠藥，也可能有影響。她沒有自己下診斷，而是清楚地向醫師報告觀察：什麼改變了、什麼時候改變、注意到什麼。檢查證實是感染，用了抗生素、補充水分、調整藥物後，幾天內就恢復了。這個案例說明不能把老人的混亂當成「只是老了」，細心的護理師會問：一定是哪裡改變了？為什麼？","qs":[{"type":"main","q":"What is the main point of the passage?","options":["Older patients often get dementia after operations.","Sudden confusion can have a cause that needs to be looked for.","Families should not visit patients after surgery."],"answer":1,"why":"整篇是護理師不接受「一定是失智」，找線索、報告，最後找到原因；最後一段說要問 what must have changed, and why。"},{"type":"detail","q":"Why did the nurse doubt that Mrs. Huang had dementia?","options":["Because dementia usually develops slowly, but Mrs. Huang changed overnight","Because Mrs. Huang's daughter was a doctor","Because Mrs. Huang was too young for dementia"],"answer":0,"why":"第二段：失智通常慢慢發生（over months or years），黃太太卻是一夜之間改變。","evidence":"Mrs. Huang had changed overnight."},{"type":"evidence","q":"Which clue suggested that Mrs. Huang might not have been drinking enough?","options":["Her water jug was still full from the night before.","A new sleeping pill had been started.","She did not recognise her daughter."],"answer":0,"why":"水壺從前一晚到現在還是滿的 → so she might not have been drinking enough（might have + 過去分詞：推測過去）。","evidence":"Mrs. Huang's water jug was still full from the night before"},{"type":"tfng","q":"Statement: The nurse told the doctor that Mrs. Huang had a urinary tract infection.","options":["True","False","Not Given"],"answer":1,"why":"護理師心裡想「可能」是泌尿道感染（could have），但她沒有自己下診斷，只報告觀察 → False。","evidence":"The nurse did not try to make a diagnosis herself."},{"type":"tfng","q":"Statement: Mrs. Huang's daughter visited her every day.","options":["True","False","Not Given"],"answer":2,"why":"文章只說第四天早上女兒在場，沒說她是不是每天來 → Not Given。"},{"type":"heading","q":"Which heading best fits paragraph D (paragraph 4)?","options":["Proving the daughter’s first conclusion correct","Ignoring changes that occur overnight","Communicating observations and obtaining further assessment"],"answer":2,"why":"第四段描述護理師報告觀察、後續檢查與處置，不是自行確診。"},{"type":"vocab","q":"In paragraph E, \\"assume\\" means…","options":["accept as true without checking sufficiently","record every observation in detail","ask a specialist to review a test"],"answer":0,"why":"作者提醒不要把突然混亂直接當成老化，assume 是尚未充分查證就認定。"},{"type":"evidence","q":"Why did the nurse consider more than one possible explanation?","options":["The daughter had already proved that no illness was present.","The observations suggested several possible contributing factors.","The medicine chart showed that no medicine had changed."],"answer":1,"why":"護理師除飲水與感染線索，也注意到新藥可能有影響，沒有只憑一個線索下結論。","evidence":"That might have played a part too."},{"type":"detail","q":"Which recent change did the nurse find in the medicine chart?","options":["All medicines had been stopped a month earlier.","A new antibiotic had been started before the operation.","A sleeping pill had been started two nights earlier."],"answer":2,"why":"第三段列出的用藥變動是兩晚前開始一種安眠藥。","evidence":"A new sleeping pill had been started two nights earlier."}],"band":"mid"},{"id":"br45-r2","level":"B2","title":"What Old Bones Can Tell Us","topic":"橋接 45：推測","words":316,"unit":50,"paras":["When archaeologists find a human skeleton, they cannot ask the person any questions. Instead, they have to work like detectives, using small clues to build a picture of a life that ended long ago.","Bones can reveal a surprising amount. The shape of the pelvis, for example, usually shows whether the person was male or female. The teeth give clues about age: a skeleton with all its adult teeth, but with little wear on them, probably belonged to a young adult. Heavy wear suggests that the person must have eaten rough, hard food for many years.","Some of the most interesting clues are injuries. A break that has healed means the person lived for weeks or even years afterwards, because bone takes time to repair itself. A break that shows no sign of healing is harder to read. The person might have died at or around the time of the injury, but the bone could also have broken after death, for example under the weight of the soil. Archaeologists have to look at other details, such as the shape and colour of the broken edges, before they can say which is more likely.","Healed injuries can also tell us something about how people treated each other. Imagine a skeleton with a badly broken thigh bone that healed. A person with such an injury could not have walked, hunted or gathered food for many weeks. They can't have survived alone. Someone must have brought them food and water, kept them warm and protected them. In other words, someone must have cared for them.","Of course, archaeologists have to be careful. Bones alone may not tell the whole story, and different experts sometimes reach different conclusions from the same evidence. But when the clues point in the same direction, they allow us to imagine the lives, and sometimes the kindness, of people who lived thousands of years ago."],"zh":"考古學家找到人骨時沒辦法問問題，只能像偵探一樣用小線索拼出很久以前的生活。骨頭透露的資訊多得驚人：骨盆形狀通常看得出男女；牙齒是年齡線索——成人牙齒都在但磨損少，大概是年輕人；磨損很重表示這個人一定長年吃粗硬的食物。受傷也是重要線索：骨折癒合了，代表他之後又活了幾週甚至幾年，因為骨頭要時間才能長好；骨折完全沒有癒合就比較難判斷——這個人可能是在受傷當時或前後死亡，但骨頭也可能是死後才斷的（例如被土壓斷），考古學家要再看斷口的形狀和顏色等其他細節，才能說哪一種比較可能。癒合的傷也透露人與人之間怎麼相待：大腿骨嚴重骨折又癒合的人，好幾週不可能走路、打獵或採集食物，不可能獨自活下來，一定有人送食物和水、幫他保暖、保護他——也就是有人照顧過他。當然考古學家必須小心：光靠骨頭不一定看得到全貌，不同專家對同樣的證據有時會有不同結論；但線索都指向同一方向時，我們就能想像幾千年前的人怎麼生活，有時還能看見他們的善良。","qs":[{"type":"main","q":"What is the passage mainly about?","options":["How archaeologists use clues from bones to learn about past lives","Why ancient people often broke their legs","How to look after a broken thigh bone"],"answer":0,"why":"第一段就說考古學家像偵探用小線索拼出過去的生活，後面一段段舉骨盆、牙齒、骨折的例子。"},{"type":"detail","q":"What does heavy wear on the teeth suggest?","options":["The person was very young.","The person ate rough, hard food for many years.","The person died from an injury."],"answer":1,"why":"must have eaten：根據磨損「很確定」推測過去吃了很多年粗硬的食物。","evidence":"Heavy wear suggests that the person must have eaten rough, hard food for many years."},{"type":"detail","q":"What can archaeologists conclude from a break that shows no sign of healing, on its own?","options":["The person lived for years after the injury.","Not enough to be sure: the person might have died around the time of the injury, or the bone might have broken after death.","The person was cared for by others."],"answer":1,"why":"沒有癒合只能說「可能」在受傷前後死亡（might have died），骨頭也可能是死後才斷的（could have broken after death），要再看斷口等其他細節；癒合了才確定之後還活著。單一線索不夠時用 might／could，不用 must。","evidence":"The person might have died at or around the time of the injury, but the bone could also have broken after death"},{"type":"reference","q":"In paragraph 4, in \\"They can't have survived alone\\", who does \\"They\\" refer to?","options":["Archaeologists","The person with the broken thigh bone","The people who brought food and water"],"answer":1,"why":"前一句的主詞是 A person with such an injury；they 用來指這個（性別不明的）人。can't have survived = 推測過去「不可能」活下來。","evidence":"They can't have survived alone."},{"type":"tfng","q":"Statement: Experts always agree about what bones show.","options":["True","False","Not Given"],"answer":1,"why":"最後一段：不同專家有時會從同樣的證據得出不同結論 → False。","evidence":"different experts sometimes reach different conclusions from the same evidence"},{"type":"heading","q":"Which heading best fits paragraph D (paragraph 4)?","options":["How archaeologists choose a holiday destination","Why every injury caused immediate death","What a healed injury may suggest about care"],"answer":2,"why":"第四段從癒合的腿骨傷勢推論他人提供照顧與生活協助。"},{"type":"vocab","q":"In paragraph B, \\"reveal\\" is closest to…","options":["show or make known","hide from view","replace with a new object"],"answer":0,"why":"骨骼能提供資訊，因此 reveal 在這裡是顯示、揭露。"},{"type":"evidence","q":"What attitude does the writer recommend when interpreting bones?","options":["Accept the first explanation without comparing alternatives.","Treat disagreement as proof that bones contain no information.","Use the evidence while recognising that interpretations have limits."],"answer":2,"why":"最後一段提醒骨骼未必提供全貌，同一證據也可能有不同解釋。","evidence":"Bones alone may not tell the whole story, and different experts sometimes reach different conclusions from the same evidence."},{"type":"tfng","q":"Statement: The skeleton discussed in paragraph D was discovered in northern Europe.","options":["True","False","Not Given"],"answer":2,"why":"第四段請讀者想像一具腿骨受傷又癒合的骨骼，沒有提供出土地點；不能自行補上北歐。","evidence":"Imagine a skeleton with a badly broken thigh bone that healed."}],"band":"mid"},{"id":"br45-held","level":"B2","title":"The Mystery of the Thank-You Card","topic":"橋接 45：推測","words":255,"unit":50,"held":true,"paras":["One Monday morning, a small blue envelope appeared on the desk at the nurses' station on Ward 9. Inside was a card with a drawing of a cat and four words: 'Thank you for everything.' There was no name, and nobody had seen who had left it.","The nurses started guessing. 'It must be from Mr. Lo,' said Grace. 'He went home on Saturday, and he was always talking about his cat.' But Peter shook his head. 'It can't be from Mr. Lo. He broke his right wrist, and he writes with his right hand. This writing is very neat. He couldn't have written it himself.'","'Maybe his wife wrote it for him,' Grace suggested. Peter thought for a moment. 'She might have. But look at the envelope. It's completely dry, and it rained heavily all weekend. Whoever left it must have come in this morning, after the rain stopped.' 'Unless it was in a bag,' said Grace. 'Then it could have stayed dry.'","Then Lily, a student nurse, noticed something else. The cat had been drawn with a purple crayon, the kind of crayon that young children use. 'It might have been a child,' she said. 'Didn't Mr. Lo's granddaughter visit him every afternoon? She was always drawing.'","At lunchtime, the mystery was solved. Mr. Lo's granddaughter came back to pick up a scarf that he had left behind. When she saw the card on the desk, she smiled shyly. 'Grandpa told me what to write,' she said. 'I did the cat by myself.'"],"zh":"某個週一早上，9 病房護理站桌上出現一個藍色小信封，裡面的卡片畫了一隻貓，寫著「謝謝你們所做的一切」，沒有署名，也沒人看到是誰放的。護理師們開始猜：Grace 說一定是週六出院的羅先生，他老是聊他的貓；Peter 搖頭說不可能，羅先生右手腕骨折，他又是用右手寫字，這字很工整，他不可能自己寫。Grace 說也許是太太代寫，Peter 說有可能，但信封完全是乾的，整個週末都在下大雨，放卡片的人一定是今天早上雨停後才來的；Grace 說除非信封放在袋子裡，那樣也可能是乾的。學生護理師 Lily 又注意到：貓是用紫色蠟筆畫的，那是小孩用的蠟筆，可能是小孩畫的——羅先生的孫女不是每天下午都來、一直在畫畫嗎？中午謎底揭曉：羅先生的孫女回來拿他忘了帶走的圍巾，看到卡片害羞地笑著說：「爺爺告訴我要寫什麼，貓是我自己畫的。」","qs":[{"type":"main","q":"What is the story mainly about?","options":["Nurses using clues to work out who left a card","A patient who lost his cat","Why it rained all weekend"],"answer":0,"why":"整篇是護理師們一個線索一個線索推測卡片是誰留的，最後解開謎底。"},{"type":"detail","q":"Why did Peter think Mr. Lo couldn't have written the card himself?","options":["Mr. Lo had broken his right wrist.","Mr. Lo could not write English.","Mr. Lo had left the hospital a week earlier."],"answer":0,"why":"Peter 說羅先生右手腕骨折、他又用右手寫字，字卻很工整 → He couldn't have written it himself。","evidence":"He broke his right wrist, and he writes with his right hand."},{"type":"evidence","q":"Which clue made Peter think that the card had been left that morning?","options":["The envelope was completely dry.","The card had a drawing of a cat.","The writing was very neat."],"answer":0,"why":"整個週末下大雨，信封卻是乾的，Peter 就推測是今天早上雨停後才放的（must have come）。這只是推測：Grace 馬上提醒，放在袋子裡也可能是乾的。","evidence":"It's completely dry, and it rained heavily all weekend."},{"type":"vocab","q":"In \\"Whoever left it must have come in this morning\\", 'whoever' means…","options":["the person who did it, although we do not know who","everyone who came to the ward","nobody at all"],"answer":0,"why":"whoever = 不管是誰、那個（不知道是誰的）人。","evidence":"Whoever left it must have come in this morning"},{"type":"tfng","q":"Statement: Mr. Lo's granddaughter wrote the words without any help.","options":["True","False","Not Given"],"answer":1,"why":"她說 Grandpa told me what to write：字是爺爺告訴她要寫什麼，只有貓是自己畫的 → False。","evidence":"'Grandpa told me what to write,' she said."},{"type":"heading","q":"Which heading best fits paragraph D (paragraph 4)?","options":["The writer of the card directly confirms her identity","A dry envelope establishes the time of delivery","A new clue in the cat drawing"],"answer":2,"why":"第四段新增紫色蠟筆畫的線索，Lily 把它連到常畫畫的孫女；這時仍是推測，當事人要到下一段才確認。"},{"type":"detail","q":"Why did Mr. Lo’s granddaughter return at lunchtime?","options":["To ask the nurses to draw another cat","To collect a scarf he had left behind","To pay for a new wristband"],"answer":1,"why":"最後一段明確交代回來拿的是祖父遺留的圍巾。","evidence":"Mr. Lo's granddaughter came back to pick up a scarf that he had left behind."},{"type":"evidence","q":"What makes the final explanation stronger than the earlier guesses?","options":["The colour blue proves exactly who owns an envelope.","Every nurse had seen the card being delivered.","The person who made the card explains her own involvement."],"answer":2,"why":"最後孫女直接說明祖父提供文字、自己畫貓，屬於當事人的確認。","evidence":"'I did the cat by myself.'"}],"band":"easy"},{"id":"br46-r1","level":"B2","title":"A Near Miss on Ward 5","topic":"橋接 46：第三類假設","words":294,"unit":51,"paras":["Late one evening on a busy medical ward, a nurse named Annie prepared a dose of insulin for a patient called Mr. Chen Wei. A few minutes later, she walked into Room 12, where a patient called Mr. Chen Wen-li was sleeping. The names were similar, the two men were about the same age, and both of them had diabetes.","Annie was about to give the injection when she stopped and checked the patient's wristband. The name on the band was not the one on her chart. She went back to the nurses' station, found the right patient and gave him his insulin. Nobody was harmed.","If Annie hadn't checked the wristband, Mr. Chen Wen-li would have received a dose of insulin that he did not need, and his blood sugar could have dropped dangerously low. Looking back, Annie said that she had been rushing because three call bells were ringing at the same time. 'If I had been less busy, I wouldn't have walked into the wrong room in the first place,' she admitted.","Annie reported the near miss, even though no harm had been done. The ward manager thanked her. Because of her report, the ward made two changes. Patients with similar names are now placed in rooms far apart, and a bright 'name alert' sticker is put on their charts and wristbands. Staff must also check two identifiers, such as the patient's full name and date of birth, before giving any medicine.","Some nurses worry that reporting a mistake will get them into trouble. But if Annie had kept quiet, the same thing might have happened to another nurse, and next time the patient might not have been so lucky. A near miss, the ward manager says, is a free lesson."],"zh":"某天晚上在忙碌的內科病房，護理師 Annie 幫病人陳偉準備了一劑胰島素，幾分鐘後走進 12 號房，裡面睡的是陳文立——名字很像、年紀差不多、兩人都有糖尿病。她正要打針時停下來核對手圈，發現名字和她的單子不一樣，於是回護理站找到正確的病人。沒有人受傷。如果她沒核對手圈，陳文立就會打到不需要的胰島素，血糖可能危險地降低。她回想當時三個呼叫鈴同時在響，自己太趕；她承認，如果沒那麼忙，一開始就不會走錯房間。雖然沒造成傷害，她還是通報了這次「跡近錯失」，護理長謝謝她。病房因此做了兩項改變：名字相近的病人房間分開，病歷和手圈貼上醒目的「姓名警示」貼紙；給藥前一定要核對兩種身分資料，例如全名和生日。有些護理師擔心通報會惹麻煩，但如果 Annie 沒說，同樣的事可能發生在別人身上，下一位病人可能就沒那麼幸運。護理長說，跡近錯失是一堂免費的課。","qs":[{"type":"main","q":"What is the main purpose of the passage?","options":["To show how one reported near miss led to safer practice","To explain how insulin works","To describe a nurse who lost her job"],"answer":0,"why":"從差點出錯、通報、到病房改流程，最後說 a near miss is a free lesson。"},{"type":"detail","q":"Why did Annie walk into the wrong room?","options":["She had been rushing because several call bells were ringing.","The room numbers had been changed.","The patient had moved to another bed."],"answer":0,"why":"第三段：she had been rushing because three call bells were ringing at the same time。","evidence":"she had been rushing because three call bells were ringing at the same time"},{"type":"detail","q":"What could have happened if Annie had not checked the wristband?","options":["The patient's blood sugar could have dropped dangerously low.","The patient would have missed his medicine.","The patient would have been moved to another ward."],"answer":0,"why":"If Annie hadn't checked…, … could have dropped dangerously low：第三類假設，說「當時沒發生」的後果。","evidence":"his blood sugar could have dropped dangerously low"},{"type":"tfng","q":"Statement: Patients with similar names are now placed in rooms close to each other.","options":["True","False","Not Given"],"answer":1,"why":"改成 far apart（分開很遠），不是靠近 → False。","evidence":"Patients with similar names are now placed in rooms far apart"},{"type":"tfng","q":"Statement: Annie was given an award for reporting the near miss.","options":["True","False","Not Given"],"answer":2,"why":"文章只說護理長謝謝她（thanked her），沒提到獎項 → Not Given。"},{"type":"heading","q":"Which heading best fits paragraph B (paragraph 2)?","options":["Rushing to answer several call bells","Introducing ward-wide changes after a report","A wristband check catches the mistake"],"answer":2,"why":"第二段寫 Annie 在注射前查手環，發現姓名與紀錄不符，回去找到正確病人，當下阻止了錯誤給藥。"},{"type":"vocab","q":"A \\"near miss\\" in this passage is…","options":["an injury that must have caused permanent disability","an error caught before it causes harm","a routine event that contains no mistake"],"answer":1,"why":"這裡藥物差點給錯人，但在造成傷害前被發現，所以是差點出錯的事件。"},{"type":"evidence","q":"Why does the manager describe a near miss as a lesson?","options":["It proves that the same problem can never happen again.","It can reveal a problem before a later patient is harmed.","It makes checking patient identity unnecessary."],"answer":1,"why":"最後一段指出若不通報，別人可能再犯，而且下次可能造成傷害。","evidence":"But if Annie had kept quiet, the same thing might have happened to another nurse, and next time the patient might not have been so lucky."},{"type":"detail","q":"Which pair is given as an example of two patient identifiers?","options":["Room number and the colour of the bed","Age and whether the patient has diabetes","Full name and date of birth"],"answer":2,"why":"原文明確舉出全名與出生日期；病室、年齡或疾病相似不能取代文中這組辨識資訊。","evidence":"Staff must also check two identifiers, such as the patient's full name and date of birth, before giving any medicine."}],"band":"mid"},{"id":"br46-r2","level":"B2","title":"The Dirty Dish That Changed Medicine","topic":"橋接 46：第三類假設","words":294,"unit":51,"paras":["In the summer of 1928, the Scottish scientist Alexander Fleming went on holiday. Before he left his laboratory at St Mary's Hospital in London, he piled up a number of glass dishes in which he had been growing bacteria. He was not known for keeping a tidy lab.","When he came back in September, he started sorting through the dishes. On one of them, he noticed something strange. A mould had grown on the dish, and around it the bacteria had disappeared. Something produced by the mould seemed to be killing them. Fleming called this substance 'penicillin'.","Historians often point out how much luck was involved. If Fleming had cleaned his dishes before his holiday, he would never have seen the mould. If the weather had been different that summer, the mould and the bacteria might not have grown in the way they did. And if Fleming hadn't looked at the dish carefully before throwing it away, the discovery might have been lost.","However, luck was not enough. Fleming found it very difficult to produce penicillin in large amounts, and for about ten years little progress was made. Then, around 1940, a team at the University of Oxford led by Howard Florey and Ernst Chain found a way to purify it and showed that it could cure infections, first in animals and then in people. During the Second World War, factories began to make it on a large scale, and it saved many soldiers who would otherwise have died from infected wounds.","In 1945, Fleming, Florey and Chain shared the Nobel Prize. Fleming himself often said that he had found something he was not looking for. But, as the story shows, an accident only matters if someone notices it and understands what it means."],"zh":"1928 年夏天，蘇格蘭科學家弗萊明去度假，離開倫敦聖瑪麗醫院的實驗室前，把一堆培養細菌的玻璃皿疊在一起——他的實驗室向來不太整齊。九月回來整理時，他發現其中一個培養皿長了黴菌，黴菌周圍的細菌都不見了，好像黴菌產生的某種物質把細菌殺死了；他把這種物質叫做盤尼西林。歷史學家常指出這裡面有很多運氣：如果他度假前把培養皿洗乾淨，就永遠不會看到黴菌；如果那年夏天天氣不同，黴菌和細菌可能不會那樣生長；如果他丟掉前沒仔細看，這個發現可能就沒了。但光有運氣不夠：弗萊明很難大量生產盤尼西林，大約十年沒什麼進展；1940 年左右，牛津大學由弗洛里和柴恩帶領的團隊找到純化的方法，證明它能治療感染，先在動物、後在人身上。二戰期間工廠大量生產，救了很多原本會死於傷口感染的士兵。1945 年三人共同獲得諾貝爾獎。弗萊明常說自己找到的是沒在找的東西；但這個故事說明，意外只有在有人注意到、而且懂得它的意義時才重要。","qs":[{"type":"detail","q":"What did Fleming notice on one of the dishes?","options":["The bacteria around a mould had disappeared.","The dish had been broken.","The bacteria had grown much faster."],"answer":0,"why":"第二段：around it the bacteria had disappeared——黴菌周圍的細菌不見了。","evidence":"around it the bacteria had disappeared"},{"type":"evidence","q":"Which sentence shows that Fleming's lab was not very tidy?","options":["He was not known for keeping a tidy lab.","Fleming called this substance 'penicillin'.","In 1945, Fleming, Florey and Chain shared the Nobel Prize."],"answer":0,"why":"not known for keeping a tidy lab = 他的實驗室向來不以整齊出名。","evidence":"He was not known for keeping a tidy lab."},{"type":"tfng","q":"Statement: Fleming was able to produce large amounts of penicillin soon after his discovery.","options":["True","False","Not Given"],"answer":1,"why":"第四段：他很難大量生產，大約十年沒什麼進展 → False。","evidence":"Fleming found it very difficult to produce penicillin in large amounts"},{"type":"reference","q":"In paragraph 4, in \\"it could cure infections\\", what does \\"it\\" refer to?","options":["The University of Oxford","Penicillin","The Second World War"],"answer":1,"why":"found a way to purify it and showed that it could cure infections——兩個 it 都指盤尼西林。","evidence":"found a way to purify it and showed that it could cure infections"},{"type":"main","q":"What is the writer's main point in the last paragraph?","options":["Fleming did not deserve the Nobel Prize.","A lucky accident matters only when someone notices and understands it.","Most discoveries in medicine are accidents."],"answer":1,"why":"最後一句：an accident only matters if someone notices it and understands what it means。"},{"type":"heading","q":"Which heading best fits paragraph D (paragraph 4)?","options":["Counting the dishes before a holiday","Why Fleming chose to travel to Scotland","Turning an observation into a usable medicine"],"answer":2,"why":"第四段從難以量產，寫到純化、驗證與工廠生產，重點是發現後續的開發。"},{"type":"vocab","q":"In paragraph D, \\"on a large scale\\" means…","options":["without any organised production","inside a very small dish","in substantial quantities"],"answer":2,"why":"工廠大量製造，large scale 指規模大，不是實驗皿的大小。"},{"type":"detail","q":"Who shared the Nobel Prize in 1945?","options":["All scientists who worked in London","Only Fleming and the soldiers he treated","Fleming, Florey and Chain"],"answer":2,"why":"第五段直接列出共同獲獎的三人。","evidence":"In 1945, Fleming, Florey and Chain shared the Nobel Prize."},{"type":"tfng","q":"Statement: Fleming counted the bacteria in every dish each morning before his holiday.","options":["True","False","Not Given"],"answer":2,"why":"文章只說他把培養細菌的玻璃皿堆起來，沒有描述每天計數的習慣；不能從有培養細菌推出天天計數。","evidence":"Before he left his laboratory at St Mary's Hospital in London, he piled up a number of glass dishes in which he had been growing bacteria."}],"band":"mid"},{"id":"br46-held","level":"B2","title":"Why Hospitals Want You to Report Mistakes","topic":"橋接 46：第三類假設","words":256,"unit":51,"held":true,"paras":["In the past, many hospitals dealt with mistakes by looking for someone to blame. A nurse who gave the wrong dose might be punished, and everyone else would learn one lesson: if you make a mistake, keep quiet. As a result, many errors were never reported, and the same problems happened again and again.","Today, many hospitals try to build what is called a 'just culture'. The idea is that most errors are not caused by bad people but by bad systems: confusing labels, tired staff, unclear instructions. If a hospital only punishes individuals, it never fixes the system, and the next person falls into the same trap.","Consider a common type of case. Two medicines come in boxes that look almost the same. A nurse picks up the wrong box and notices just in time. If she had been punished for the near miss, she would probably have kept it to herself. Because she reported it, the pharmacy changed the way the boxes were stored, and other nurses were warned.","Aviation is often given as an example. Pilots are encouraged to report their own errors, and in some systems these reports are confidential. Many experts believe that this openness has helped make flying much safer than it used to be.","A just culture does not mean that nobody is ever responsible. Staff who take dangerous shortcuts on purpose can still face consequences. But the main question changes from 'Who did this?' to 'Why did this happen, and how can we stop it from happening again?'"],"zh":"過去很多醫院處理錯誤的方式是找人來怪：給錯劑量的護理師可能被懲罰，其他人學到的是「犯錯就閉嘴」，結果很多錯誤沒被通報，同樣的問題一再發生。現在很多醫院想建立「公正文化」：大部分錯誤不是壞人造成的，而是壞的系統——容易混淆的標籤、疲累的人員、不清楚的指示；只懲罰個人，系統永遠不會修好，下一個人又會掉進同樣的陷阱。例如兩種藥的盒子幾乎一樣，護理師拿錯了、及時發現；如果她因為這次跡近錯失被罰，大概就不會說出來；因為她通報了，藥局改了盒子的擺放方式，也提醒了其他護理師。航空業常被拿來當例子：鼓勵機師通報自己的錯誤，有些制度還會保密；很多專家認為這種開放讓飛行比以前安全得多。公正文化不代表沒有人要負責，故意走危險捷徑的人還是會有後果；但主要的問題從「是誰做的？」變成「為什麼會發生？怎麼避免再發生？」","qs":[{"type":"main","q":"What is the passage mainly about?","options":["Why many hospitals now encourage staff to report errors","How pilots are trained","How to store boxes of medicine"],"answer":0,"why":"整篇在講從「找人來怪」轉成「公正文化」、鼓勵通報錯誤的原因。"},{"type":"detail","q":"According to paragraph 2, what causes most errors?","options":["Bad people","Bad systems","New medicines"],"answer":1,"why":"most errors are not caused by bad people but by bad systems。","evidence":"most errors are not caused by bad people but by bad systems"},{"type":"detail","q":"What happened because the nurse in paragraph 3 reported the near miss?","options":["She was punished.","The pharmacy changed how the boxes were stored.","The medicine was taken off the market."],"answer":1,"why":"Because she reported it, the pharmacy changed the way the boxes were stored。","evidence":"the pharmacy changed the way the boxes were stored"},{"type":"tfng","q":"Statement: In a just culture, staff are never responsible for anything.","options":["True","False","Not Given"],"answer":1,"why":"最後一段第一句就說公正文化不代表沒有人要負責 → False。","evidence":"A just culture does not mean that nobody is ever responsible."},{"type":"tfng","q":"Statement: The idea of a just culture was first developed in Taiwan.","options":["True","False","Not Given"],"answer":2,"why":"文章完全沒提公正文化從哪裡開始 → Not Given。"},{"type":"heading","q":"Which heading best fits paragraph E (paragraph 5)?","options":["Accountability alongside learning from mistakes","Making every error report public","Removing all responsibility from staff"],"answer":0,"why":"第五段說公正文化仍有責任，但核心轉為原因與預防，而非只找人怪罪。"},{"type":"vocab","q":"In paragraph D, \\"confidential\\" means…","options":["required to be published in a newspaper","automatically deleted before anyone reads it","kept private rather than openly shared with everyone"],"answer":2,"why":"confidential 指資訊受到保密，不代表沒有人查看或直接刪除。"},{"type":"evidence","q":"Why might punishment alone fail to prevent another error?","options":["It may leave the conditions that contributed to the error unchanged.","It means that no worker will ever make a decision again.","It ensures that every label becomes clearer immediately."],"answer":0,"why":"作者說只懲罰個人而不修正系統，下一人仍可能落入同樣問題。","evidence":"If a hospital only punishes individuals, it never fixes the system, and the next person falls into the same trap."},{"type":"tfng","q":"Statement: The nurse in the medicine-box example had received special packaging training the previous week.","options":["True","False","Not Given"],"answer":2,"why":"故事說拿錯相似盒子後及時發現，但沒有交代上週受訓情形。","evidence":"A nurse picks up the wrong box and notices just in time."}],"band":"mid"},{"id":"br47-r1","level":"B2","title":"Letter to My Younger Self","topic":"橋接 47：願望和遺憾","words":283,"unit":52,"paras":["Dear Young Nurse, I am writing this after thirty years on the wards, and I wish someone had written a letter like this to me when I started. I was nervous, proud and very tired, and I made almost every mistake a new nurse can make. Here is what I have learned.","First, ask questions. In my first year, I pretended to understand things that I didn't, because I was afraid of looking stupid. Once, I wasn't sure how to set up a pump, and I should have asked my senior. Instead, I guessed. Luckily, she noticed in time. I wish I had understood earlier that good nurses ask; it is the dangerous ones who never do.","Second, look after your body. I used to lift patients without help because I wanted to finish quickly. Now, at fifty-four, I have back pain almost every day. If only I had used the lifting equipment and asked for a hand. Your back has to last your whole career.","Third, do not take everything home with you. Some days, you will lose a patient, or a family will shout at you, or you will feel that you did not do enough. I spent years replaying those days at night instead of sleeping. I should have talked to my colleagues more. Many of them were carrying the same feelings.","Finally, do not stop learning. I wish I were twenty-two again, with all the new things you will see: new treatments, new technology, new ways of caring. I don't regret becoming a nurse, not for one day. But I wish I had enjoyed the journey a little more and worried a little less. With love, An Old Nurse"],"zh":"一位做了三十年的護理師寫信給年輕護理師：她真希望當年有人寫這樣的信給她。第一，要發問：她第一年怕看起來很笨，不懂裝懂；有一次不確定怎麼裝輸液幫浦，應該問學姊卻自己猜，還好學姊及時發現。她希望自己早點明白，好護理師會發問，不問的才危險。第二，照顧身體：她以前為了快點做完，常常不找人幫忙就搬病人，現在五十四歲幾乎天天背痛——要是當初有用移位設備、請人幫忙就好了。第三，不要把所有事都帶回家：有些日子會失去病人、被家屬吼、覺得自己做得不夠；她好幾年晚上一直重播那些日子而睡不著，她應該多跟同事聊，很多人也背著同樣的感受。最後，不要停止學習：她真希望自己再回到二十二歲，看到新的治療、科技和照護方式。她從來不後悔當護理師，但希望當初多享受一點過程、少擔心一點。","qs":[{"type":"main","q":"What is the main purpose of the letter?","options":["To give advice to new nurses based on the writer's experience","To complain about working conditions","To explain how to use lifting equipment"],"answer":0,"why":"整封信是資深護理師用自己的遺憾給新人建議：發問、照顧身體、別把事情都帶回家、繼續學習。"},{"type":"detail","q":"Why did the writer not ask questions in her first year?","options":["She was afraid of looking stupid.","Her senior was always busy.","She already knew the answers."],"answer":0,"why":"第二段：because I was afraid of looking stupid。","evidence":"because I was afraid of looking stupid"},{"revision":1,"type":"tfng","q":"Statement: The writer has back pain almost every day and wishes she had asked for help when lifting patients.","options":["True","False","Not Given"],"answer":0,"why":"第三段說她現在幾乎天天背痛，也說當初要是用了移位設備、請人幫忙就好了。","evidence":"Now, at fifty-four, I have back pain almost every day. If only I had used the lifting equipment and asked for a hand."},{"type":"vocab","q":"In paragraph 4, 'replaying those days' means…","options":["thinking about those days again and again","working on those days again","playing games on those days"],"answer":0,"why":"replay 本來是重播；她晚上不睡覺一直重播那些日子 = 一直反覆去想。","evidence":"I spent years replaying those days at night instead of sleeping."},{"type":"tfng","q":"Statement: The writer regrets becoming a nurse.","options":["True","False","Not Given"],"answer":1,"why":"I don't regret becoming a nurse, not for one day → False。她後悔的是沒多享受過程。","evidence":"I don't regret becoming a nurse, not for one day."},{"type":"heading","q":"Which heading best fits paragraph D (paragraph 4)?","options":["Planning a career outside healthcare","Learning to operate a new pump","Sharing the emotional burden of difficult days"],"answer":2,"why":"第四段談把困難經驗帶回家、反覆想，以及應與同事交流的反思。"},{"type":"evidence","q":"What does the closing paragraph suggest about the writer’s view of nursing?","options":["She believes the entire career was a mistake.","She values the career while wishing she had approached it differently.","She thinks further learning should stop after the first year."],"answer":1,"why":"作者明說不後悔當護理師，遺憾的是希望少擔心、多享受過程。","evidence":"I don't regret becoming a nurse, not for one day."},{"type":"tfng","q":"Statement: The writer spent all thirty years at the same hospital.","options":["True","False","Not Given"],"answer":2,"why":"第一段說在病房工作三十年，未說是否都在同一家醫院。","evidence":"Dear Young Nurse, I am writing this after thirty years on the wards, and I wish someone had written a letter like this to me when I started."},{"type":"tfng","q":"Statement: The writer’s senior noticed the pump problem before it was too late.","options":["True","False","Not Given"],"answer":0,"why":"第二段說作者不懂裝置就用猜的，幸好資深同事及時發現。","evidence":"Luckily, she noticed in time.","additional":true}],"band":"easy"},{"id":"br47-r2","level":"B2","title":"Ask Dr. Lee: 'I Wish I Had Chosen a Different Major'","topic":"橋接 47：願望和遺憾","words":318,"unit":52,"paras":["Dear Dr. Lee, I am a second-year nursing student, and I think I made the wrong choice. My parents wanted me to study nursing because it is a stable job, and I agreed without really thinking about it. Now I find anatomy boring, and my first placement was exhausting. All my friends seem to love their majors. I wish I had studied design instead. Should I quit? Lost in Taichung","Dear Lost, first, thank you for being so honest. Many students feel exactly the way you do in their second year, but very few say it out loud. Feeling bored or tired does not necessarily mean you chose the wrong path. The second year is often the hardest: the subjects are difficult, and you have not yet seen the parts of the job that many nurses find most rewarding.","That said, your feelings deserve to be taken seriously. Before you make any big decision, try to find out more. Talk to nurses who work in different areas. A busy emergency room is very different from a school clinic or a research job. You might discover a side of nursing that suits you better than you imagined.","It is also worth asking what exactly you wish were different. If you wish you had more creative work, there may be ways to combine your interests. Some nurses design health education materials, and others work on hospital apps. On the other hand, if you are sure that you would be happier in another field, it is not too late to change. Many people switch careers, and the knowledge you have gained will not be wasted.","Whatever you decide, try not to make the decision only to please others, or only because of one bad month. You shouldn't have to live your parents' dream, but you also shouldn't throw away two years of work without looking carefully at your options. Dr. Lee"],"zh":"一位護理系二年級學生寫信給專欄：父母覺得護理是穩定的工作，她沒多想就答應了；現在覺得解剖學很無聊、第一次實習累壞了，朋友好像都很愛自己的科系，她真希望當初讀設計，問該不該休學。李醫師回信：謝謝她這麼誠實，很多二年級學生都有一樣的感覺，只是很少人說出口；覺得無聊或疲累不一定代表選錯路，二年級常是最難的一年，還沒看到這份工作最有成就感的部分。不過她的感受應該被認真對待：做重大決定前先多了解，去問不同領域的護理師——忙碌的急診和學校保健室、研究工作很不一樣。也值得問自己到底希望哪裡不同：如果想要更有創意的工作，有些護理師設計衛教教材，有些做醫院 App；如果確定在別的領域會更快樂，現在改也不嫌晚，學到的知識不會白費。不論怎麼決定，不要只為了讓別人開心，或只因為一個糟糕的月份就決定。","qs":[{"type":"detail","q":"Why did the student choose nursing?","options":["Because she loved anatomy","Because her parents wanted her to and it is a stable job","Because her friends were studying nursing"],"answer":1,"why":"第一段：My parents wanted me to study nursing because it is a stable job。","evidence":"My parents wanted me to study nursing because it is a stable job"},{"type":"tfng","q":"Statement: According to Dr. Lee, feeling bored always means you chose the wrong major.","options":["True","False","Not Given"],"answer":1,"why":"does not necessarily mean = 不一定代表；「一定代表選錯」跟原文相反 → False。","evidence":"Feeling bored or tired does not necessarily mean you chose the wrong path."},{"type":"detail","q":"What does Dr. Lee suggest the student do before deciding?","options":["Quit immediately","Talk to nurses who work in different areas","Ask her friends for advice"],"answer":1,"why":"第三段：Talk to nurses who work in different areas。","evidence":"Talk to nurses who work in different areas"},{"type":"reference","q":"In paragraph 4, in \\"others work on hospital apps\\", who are \\"others\\"?","options":["Other students","Other nurses","Other parents"],"answer":1,"why":"Some nurses design…, and others work on…——others = other nurses。","evidence":"Some nurses design health education materials, and others work on hospital apps."},{"type":"main","q":"What is Dr. Lee's overall advice?","options":["Stay in nursing no matter what.","Quit and study design.","Find out more and make the decision carefully, for herself."],"answer":2,"why":"她沒有叫學生留下或離開，而是先多了解、想清楚，不要只為了別人或一個壞月份決定。"},{"type":"heading","q":"Which heading best fits paragraph D (paragraph 4)?","options":["Exploring ways to combine interests or change direction","Proving that design is always a better subject","Listing the entry requirements of one university"],"answer":0,"why":"第四段先談把創作興趣結合護理，也承認認真評估後轉領域是可能選項。"},{"type":"vocab","q":"In paragraph B, \\"rewarding\\" is closest to…","options":["giving a sense of value or satisfaction","requiring no effort or study","providing an immediate cash prize"],"answer":0,"why":"這裡談工作中讓人覺得值得的部分，不是指獎金或完全不費力。"},{"type":"evidence","q":"Which possibility challenges the idea that nursing and creativity must be separate?","options":["Every nurse is required to become a professional designer.","A student can avoid all decisions by following friends.","Nurses may create education materials or help develop apps."],"answer":2,"why":"健康教育材料與醫院應用程式都是文章提出的結合創作興趣的例子。","evidence":"Some nurses design health education materials, and others work on hospital apps."},{"type":"tfng","q":"Statement: The student has already received the highest mark in a university design course.","options":["True","False","Not Given"],"answer":2,"why":"來信只有說希望當初選設計，未提上過設計課或該課成績。","evidence":"I wish I had studied design instead."}],"band":"mid"},{"id":"br47-held","level":"B2","title":"What People Regret Most","topic":"橋接 47：願望和遺憾","words":280,"unit":52,"held":true,"paras":["Everyone has regrets. Some are small, such as 'I shouldn't have eaten that second piece of cake', and some stay with us for years. Psychologists who study regret have found some interesting patterns in what people regret and when.","One finding is that the kind of regret seems to change over time. In the short term, people often regret things they did: an angry message they sent, money they spent, something they said in a meeting. Over the long term, however, people more often regret things they did not do. Looking back on their lives, many say things like 'I wish I had travelled more' or 'I wish I had told her how I felt.'","Why might this be? One explanation is that we usually take action to fix the results of our mistakes. If you send an unkind message, you can apologise. But a chance you never took stays open in your imagination. You can always wonder what might have happened, and the imagined result is often better than reality would have been.","Regret is not only negative. Researchers point out that it can help us learn. A student who thinks 'I should have started revising earlier' may plan better for the next exam. The problem comes when people replay the same regret again and again without changing anything.","For nurses, this is useful knowledge. Patients near the end of life sometimes talk about their regrets, and listening without judging can be an important part of care. And for students, the research offers a simple lesson: when you are not sure whether to try something new, remember that, years later, you may be more likely to regret not trying."],"zh":"每個人都有遺憾，有些很小（「我不該吃第二塊蛋糕」），有些跟著我們好多年。研究遺憾的心理學家發現了一些模式：遺憾的種類似乎會隨時間改變——短期內，人常後悔「做了」的事，像傳出的氣話、花掉的錢、會議上說的話；長期來看，人比較常後悔「沒做」的事，回顧人生時常說「真希望我多去旅行」「真希望我有告訴她我的感受」。一種解釋是：做錯的事我們通常會採取行動補救，傳了不客氣的訊息可以道歉；但沒把握的機會會一直留在想像裡，你永遠可以猜想本來可能發生什麼，而想像的結果常比現實更好。遺憾不只是負面的，研究者指出它能幫助我們學習：想著「我應該早點開始複習」的學生，下次考試可能會計畫得更好；問題在於一再重播同樣的遺憾卻什麼都不改。對護理師來說，臨終病人有時會談起遺憾，不帶評判地傾聽是照護的重要部分；對學生來說，不確定要不要嘗試新事物時，記得多年後你可能更容易後悔「沒試」。","qs":[{"type":"main","q":"What is the passage mainly about?","options":["Patterns in what people regret, and what we can learn from them","How to apologise after sending an angry message","Why travelling is good for your health"],"answer":0,"why":"整篇講心理學家發現的遺憾模式（短期後悔做了、長期後悔沒做）、原因，以及對護理和學習的意義。"},{"type":"detail","q":"In the short term, what do people often regret?","options":["Things they did","Things they did not do","Places they did not visit"],"answer":0,"why":"In the short term, people often regret things they did；長期才比較後悔沒做的事。","evidence":"In the short term, people often regret things they did"},{"type":"evidence","q":"Which sentence explains why a missed chance can stay with us?","options":["But a chance you never took stays open in your imagination.","Everyone has regrets.","Regret is not only negative."],"answer":0,"why":"沒把握的機會會一直留在想像裡（stays open in your imagination），所以一直放不下。","evidence":"But a chance you never took stays open in your imagination."},{"type":"tfng","q":"Statement: Researchers say that regret can help people learn.","options":["True","False","Not Given"],"answer":0,"why":"Researchers point out that it can help us learn → True。","evidence":"Researchers point out that it can help us learn."},{"type":"tfng","q":"Statement: Nurses should tell patients not to talk about their regrets.","options":["True","False","Not Given"],"answer":1,"why":"文章說不帶評判地傾聽是照護的重要部分，跟「叫病人不要說」相反 → False。","evidence":"listening without judging can be an important part of care"},{"type":"heading","q":"Which heading best fits paragraph B (paragraph 2)?","options":["How people repair the consequences of mistakes","How the focus of regret changes over time","Using regret to plan for the next examination"],"answer":1,"why":"第二段對比短期常後悔做過的事、長期更常後悔沒做的事，重點是遺憾的焦點隨時間改變。"},{"type":"vocab","q":"In this passage, \\"regret\\" means…","options":["certainty that the future is already decided","a written plan for a hospital shift","sadness about a past action or missed opportunity"],"answer":2,"why":"全文的遺憾涉及過去做過的事與沒把握的機會。"},{"type":"evidence","q":"When is regret presented as potentially useful?","options":["When someone repeats the same thought without doing anything","When it leads someone to change a later plan or action","When it prevents a person from considering future choices"],"answer":1,"why":"學生後悔太晚複習，下一次更早安排，展現把遺憾轉為調整。","evidence":"A student who thinks 'I should have started revising earlier' may plan better for the next exam."},{"type":"tfng","q":"Statement: All the psychological studies mentioned were carried out in the United States.","options":["True","False","Not Given"],"answer":2,"why":"開頭提到研究遺憾的心理學家，未交代研究在哪個國家進行，更沒有說全部在美國。","evidence":"Psychologists who study regret have found some interesting patterns in what people regret and when."}],"band":"mid"},{"id":"br48-r1","level":"B2","title":"Florence Nightingale, Who Counted the Dead","topic":"橋接 48：非限定關係子句","words":296,"unit":53,"paras":["Florence Nightingale, who is often called the founder of modern nursing, was born in 1820 in the Italian city of Florence, which gave her her name. Her family was wealthy, and her parents expected her to marry and live a comfortable life. Nightingale, however, believed that she had a calling to care for the sick.","In 1854, during the Crimean War, she travelled with a group of nurses to a British army hospital in Scutari, which is now part of Istanbul. Conditions there were terrible. The wards, where wounded soldiers lay close together, were dirty and crowded, and there were rats everywhere. Far more soldiers were dying from diseases such as cholera and typhus than from their wounds.","Nightingale and her nurses cleaned the wards, washed the soldiers' clothes and organised proper meals. At night, she walked through the wards carrying a lamp, which is why soldiers called her 'the Lady with the Lamp'. After a government commission improved the drains and the water supply, the death rate at the hospital fell sharply.","What is less well known is that Nightingale was also a gifted statistician. She kept careful records of how many soldiers died and why. She then presented the data in colourful diagrams, which made the message clear even to people who did not like numbers: most of the deaths could have been prevented. Her work helped to persuade the government to improve conditions in army hospitals. She later became the first woman to be elected a member of the Royal Statistical Society.","In 1860, Nightingale opened a training school for nurses at St Thomas' Hospital in London, which helped to turn nursing into a respected profession. She died in 1910. Today, International Nurses Day is celebrated on 12 May, which was her birthday."],"zh":"南丁格爾常被稱為現代護理的創始人，1820 年生於義大利佛羅倫斯，名字就來自這座城市。她家境富裕，父母期待她結婚、過舒適的生活，但她相信照顧病人是她的使命。1854 年克里米亞戰爭期間，她帶著一群護士到斯庫塔里（今伊斯坦堡的一部分）的英軍醫院：環境很糟，傷兵擠在骯髒的病房裡，到處是老鼠，死於霍亂、斑疹傷寒等疾病的士兵遠比死於傷口的多。她們清潔病房、洗衣服、安排正常的餐點；她晚上提著燈巡視病房，所以士兵叫她「提燈天使」。政府派來的委員會改善排水和供水後，醫院的死亡率大幅下降。比較少人知道的是，她也是很有天分的統計學家：她仔細記錄士兵死亡的人數和原因，再畫成彩色圖表，讓不喜歡數字的人也看得懂——大部分死亡本來可以避免。她的工作說服政府改善軍醫院，她後來也成為第一位當選皇家統計學會會員的女性。1860 年她在倫敦聖湯瑪士醫院創辦護理學校，幫助護理成為受尊重的專業。她 1910 年過世；今天的國際護師節是 5 月 12 日，就是她的生日。","qs":[{"type":"detail","q":"Why was Florence Nightingale called 'the Lady with the Lamp'?","options":["She invented a new kind of lamp.","She walked through the wards at night carrying a lamp.","She lit the lamps in the streets of London."],"answer":1,"why":"第三段：At night, she walked through the wards carrying a lamp, which is why…——which 指前面整件事。","evidence":"At night, she walked through the wards carrying a lamp"},{"type":"tfng","q":"Statement: More soldiers in the hospital died from disease than from their wounds.","options":["True","False","Not Given"],"answer":0,"why":"Far more soldiers were dying from diseases… than from their wounds → True。","evidence":"Far more soldiers were dying from diseases such as cholera and typhus than from their wounds."},{"type":"detail","q":"What did her diagrams show?","options":["That most of the deaths could have been prevented","That the war was almost over","That nurses needed higher pay"],"answer":0,"why":"冒號後面就是圖表要傳達的訊息：most of the deaths could have been prevented。","evidence":"most of the deaths could have been prevented"},{"type":"reference","q":"In paragraph 1, in \\"which gave her her name\\", what does \\"which\\" refer to?","options":["Her family","The city of Florence","The year 1820"],"answer":1,"why":"逗號前面就是 the Italian city of Florence；非限定的 which 補充說明這座城市。","evidence":"the Italian city of Florence, which gave her her name"},{"type":"tfng","q":"Statement: Nightingale wrote several books about statistics.","options":["True","False","Not Given"],"answer":2,"why":"文章說她做紀錄、畫圖表、當選統計學會會員，沒提她寫過統計學的書 → Not Given。"},{"type":"heading","q":"Which heading best fits paragraph D (paragraph 4)?","options":["Describing Nightingale’s childhood holidays","Explaining the design of the nurses’ uniforms","Using numbers to argue for reform"],"answer":2,"why":"第四段主題是統計紀錄、圖表與說服政府改善，不只是列死亡數字。"},{"type":"vocab","q":"In paragraph D, \\"persuade\\" means…","options":["prevent someone from seeing information","convince someone to accept an idea or take action","ask someone to repeat a name"],"answer":1,"why":"Nightingale 以證據說服政府改善，persuade 指使人接受想法或採取行動。"},{"type":"evidence","q":"Why were the diagrams useful for a wider audience?","options":["They communicated the meaning of the data to people uncomfortable with numbers.","They removed the need to collect records beforehand.","They showed that every death had exactly the same cause."],"answer":0,"why":"圖表讓不喜歡數字的人也能理解主要訊息，並非不需要資料。","evidence":"She then presented the data in colourful diagrams, which made the message clear even to people who did not like numbers: most of the deaths could have been prevented."},{"type":"detail","q":"What future did Nightingale’s parents originally expect for her?","options":["A permanent move to the Crimean battlefield","A career running a statistics society from childhood","Marriage and a comfortable life"],"answer":2,"why":"第一段直接說父母期待她結婚、過舒適生活。","evidence":"Her family was wealthy, and her parents expected her to marry and live a comfortable life."}],"band":"mid"},{"id":"br48-r2","level":"B2","title":"Welcome to Sunrise Hospital","topic":"橋接 48：非限定關係子句","words":242,"unit":53,"paras":["Welcome to Sunrise Hospital, which has served the people of southern Taiwan since 1978. This short guide will help you find your way around during your first visit.","The main entrance is on Harbor Road, where you will also find the bus stop and the taxi rank. As you come in, you will see the information desk, which is open from 7 a.m. to 9 p.m. The volunteers there, most of whom are retired teachers and nurses, can answer questions in Mandarin, Taiwanese and English.","The outpatient clinics are on the first and second floors. Our emergency department, which is open 24 hours a day, has its own entrance at the back of the building. Please do not use the main entrance in an emergency, because it is further from the treatment rooms.","On the third floor is the children's ward, whose walls were painted by local art students. Next to it is the family room, where parents can rest, make tea and take a shower. The rooftop garden, which was opened in 2019, is a quiet place for patients and visitors to get some fresh air. It is closed when it rains.","Visiting hours are from 11 a.m. to 8 p.m. In the intensive care unit, where patients need extra rest, only two visitors are allowed at a time. If you have any questions, please ask any member of staff, all of whom wear blue name badges."],"zh":"歡迎來到朝陽醫院，1978 年起服務南台灣。這份簡介幫你第一次來時找到路：正門在港口路，公車站和計程車招呼站也在那裡；進門會看到服務台，早上七點到晚上九點開放，那裡的志工大多是退休老師和護理師，可以用國語、台語和英語回答問題。門診在一、二樓；急診 24 小時開放，入口在大樓後面，緊急狀況請不要走正門，因為離治療室比較遠。三樓是兒科病房，牆壁是在地美術系學生畫的；旁邊是家屬休息室，家長可以休息、泡茶、洗澡。屋頂花園 2019 年啟用，是病人和訪客呼吸新鮮空氣的安靜地方，下雨時關閉。探病時間是上午十一點到晚上八點；加護病房的病人需要多休息，一次只能兩位訪客。有問題可以問任何工作人員，他們都戴藍色名牌。","qs":[{"type":"main","q":"What is the purpose of this text?","options":["To help visitors find their way around the hospital","To advertise jobs at the hospital","To explain the history of southern Taiwan"],"answer":0,"why":"第一段：This short guide will help you find your way around，後面一層一層介紹位置和規定。"},{"type":"detail","q":"Who are most of the volunteers at the information desk?","options":["Students from a local art school","Retired teachers and nurses","Doctors from the emergency department"],"answer":1,"why":"most of whom are retired teachers and nurses：whom 指前面的 volunteers。","evidence":"most of whom are retired teachers and nurses"},{"type":"detail","q":"Why should people not use the main entrance in an emergency?","options":["It is closed at night.","It is further from the treatment rooms.","It is only for visitors."],"answer":1,"why":"第三段最後：because it is further from the treatment rooms。","evidence":"because it is further from the treatment rooms"},{"type":"tfng","q":"Statement: The rooftop garden is open in all weather.","options":["True","False","Not Given"],"answer":1,"why":"It is closed when it rains：下雨會關，不是任何天氣都開 → False。","evidence":"It is closed when it rains."},{"type":"tfng","q":"Statement: Children are allowed to visit patients in the intensive care unit.","options":["True","False","Not Given"],"answer":2,"why":"只說加護病房一次限兩位訪客，沒說小孩能不能進去 → Not Given。"},{"type":"heading","q":"Which heading best fits paragraph D (paragraph 4)?","options":["Instructions for reaching emergency treatment","A history of hospital transport","Spaces that support families and provide a quiet break"],"answer":2,"why":"第四段介紹兒童病房旁的家庭休息室與屋頂花園。"},{"type":"vocab","q":"In paragraph E, \\"at a time\\" means…","options":["simultaneously","for the entire history of the hospital","only during the first minute of a visit"],"answer":0,"why":"only two visitors at a time 是同一時間兩位，不是整天總共只能兩位。"},{"type":"evidence","q":"A visitor is still unsure where to go. Which action is supported by the guide?","options":["Assume that every person near the taxi rank works for the hospital.","Enter any ward and search without asking anyone.","Ask a staff member identified by a blue name badge."],"answer":2,"why":"最後一句請有問題的人詢問工作人員，並說明辨識用的藍色名牌。","evidence":"If you have any questions, please ask any member of staff, all of whom wear blue name badges."}],"band":"easy"},{"id":"br48-held","level":"B2","title":"Virginia Apgar and the Ten-Point Score","topic":"橋接 48：非限定關係子句","words":291,"unit":53,"held":true,"paras":["One minute after birth, almost every baby born in a modern hospital is assessed using the Apgar score, which takes only a few seconds. It was named after Virginia Apgar, an American doctor whose simple idea has helped to save a great many newborn lives.","Apgar, who was born in 1909, originally wanted to be a surgeon. However, she was advised to choose anaesthesia instead, a field in which few doctors worked at the time. She went on to become a leading anaesthesiologist in New York, where she worked closely with mothers giving birth.","In the early 1950s, Apgar noticed a problem. Doctors and nurses had no quick, standard way to decide whether a newborn baby needed help. Babies who were having trouble breathing were sometimes not noticed until it was too late. In 1952 she proposed a simple scoring system, which she published the following year.","The score looks at five signs: the baby's skin colour, heart rate, reflexes, muscle tone and breathing. Each sign is given 0, 1 or 2 points, so the total is between 0 and 10. The test is done at one minute and again at five minutes after birth. The score helps the team describe the newborn’s condition and response to any resuscitation. If the baby needs help to breathe at birth, the team assesses breathing and heart rate immediately and starts any needed support without waiting for the score.","Later, the five signs were turned into a memory aid that uses the letters of her name: Appearance, Pulse, Grimace, Activity and Respiration. Apgar, who later worked on preventing birth defects, died in 1974. Her score, which is still used around the world, remains one of the simplest and most useful tools in medicine."],"zh":"在現代醫院出生的嬰兒，出生一分鐘時幾乎都會做亞培格評分，只要幾秒鐘便能完成。它以美國醫師維吉妮亞．亞培格命名，她的簡單點子救了很多新生兒。她 1909 年出生，原本想當外科醫師，卻被建議改走麻醉——當時很少醫師投入的領域；後來她成為紐約頂尖的麻醉科醫師，和生產中的媽媽密切合作。1950 年代初她發現一個問題：醫護人員沒有快速、標準的方法判斷新生兒需不需要幫助，有呼吸困難的嬰兒有時太晚才被發現。1952 年她提出簡單的評分系統，隔年發表。評分看五個徵象：膚色、心跳、反射、肌肉張力和呼吸，每項 0、1 或 2 分，總分 0 到 10；在出生後一分鐘和五分鐘各做一次，評分協助團隊描述新生兒的狀況及對復甦的反應。新生兒出生時若需要呼吸協助，團隊會立即評估呼吸與心率，直接開始所需的處置。後來這五項被做成用她名字字母的口訣：Appearance、Pulse、Grimace、Activity、Respiration。她後來投入預防出生缺陷，1974 年過世；她的評分至今仍在全世界使用。","qs":[{"type":"main","q":"What is the passage mainly about?","options":["How a doctor created a quick test for newborn babies","How to become an anaesthesiologist","Why babies have trouble breathing"],"answer":0,"why":"整篇在講亞培格評分怎麼來的、怎麼做、為什麼重要。"},{"type":"detail","q":"What problem did Apgar notice?","options":["There was no quick, standard way to check whether a newborn needed help.","There were not enough surgeons in New York.","Mothers did not trust doctors."],"answer":0,"why":"第三段：Doctors and nurses had no quick, standard way to decide whether a newborn baby needed help。","evidence":"Doctors and nurses had no quick, standard way to decide whether a newborn baby needed help."},{"type":"detail","q":"When is the Apgar test done?","options":["Only at one minute after birth","At one minute and again at five minutes after birth","Once a day for the first week"],"answer":1,"why":"The test is done at one minute and again at five minutes after birth。","evidence":"The test is done at one minute and again at five minutes after birth."},{"type":"tfng","q":"Statement: The highest possible Apgar score is 10.","options":["True","False","Not Given"],"answer":0,"why":"五項各 0–2 分，so the total is between 0 and 10 → 最高 10 分，True。","evidence":"so the total is between 0 and 10"},{"type":"tfng","q":"Statement: The Apgar score is no longer used today.","options":["True","False","Not Given"],"answer":1,"why":"Her score, which is still used around the world——現在全世界還在用 → False。","evidence":"Her score, which is still used around the world"},{"revision":1,"type":"heading","q":"Which heading best fits paragraph D (paragraph 4)?","options":["Apgar’s choice of medical school","The manufacture of newborn breathing equipment","The signs, timing and purpose of the score"],"answer":2,"why":"第四段交代五個項目、分數範圍、施測時間，以及它如何協助描述狀況和復甦反應。"},{"type":"vocab","q":"In paragraph C, \\"standard\\" means…","options":["unusually difficult for experienced staff","designed differently for every single baby","based on a common method used consistently"],"answer":2,"why":"文中欠缺的是快速、一致的方法；standard 指共通標準。"},{"revision":1,"type":"evidence","q":"What is a practical purpose of summarising the signs in a score?","options":["It predicts the exact occupation the child will have.","It helps the team describe the newborn’s condition and response to any resuscitation.","It makes further observation unnecessary in every case."],"answer":1,"why":"第四段說評分能協助描述新生兒的狀況及復甦反應。是否開始呼吸支持，要依出生時的即時評估。","evidence":"The score helps the team describe the newborn’s condition and response to any resuscitation."},{"type":"tfng","q":"Statement: Apgar’s first trial of the scoring system included exactly one hundred babies.","options":["True","False","Not Given"],"answer":2,"why":"文章說明提出與發表年份，沒有提供最初試用人數；一百人的數字無法由文中判定。","evidence":"In 1952 she proposed a simple scoring system, which she published the following year."}],"band":"mid"},{"id":"a1-easy-blue-bag","level":"A1","band":"easy","title":"A Blue School Bag","topic":"上學用品","words":48,"paras":["Mei is a nursing student in Taiwan. Her school bag is blue. A small white card is in the front pocket. The card has her name. Mei takes the bag to class. Her English book is inside. Her brother has a green bag. His books stay at home."],"zh":"美是台灣的護理系學生。她的書包是藍色的，前面口袋裡有一張寫著姓名的小白卡。她帶書包去上課，英文課本在裡面。兄弟有綠色書包，他的書留在家裡。","qs":[{"type":"main","q":"What is this passage mostly about?","options":["Mei's school bag","A nursing lesson","Her brother's teacher"],"answer":0,"why":"文章主要介紹美的書包、姓名卡和裡面的課本。"},{"type":"detail","q":"Where is the white card?","options":["On the classroom wall","In the front pocket","Under the English book"],"answer":1,"why":"白卡在前面的口袋裡。","evidence":"A small white card is in the front pocket."},{"type":"detail","q":"What color is her brother's bag?","options":["Blue","White","Green"],"answer":2,"why":"綠色是兄弟的書包（英文沒說是哥哥還是弟弟）；藍色是美的，白色是姓名卡。","evidence":"Her brother has a green bag."},{"type":"detail","q":"Where is Mei’s English book?","options":["In her school bag","On her brother’s desk","Under her bed"],"answer":0,"why":"文中說英文書在書包裡面。","evidence":"Her English book is inside."}]},{"id":"a1-easy-bus-stop","level":"A1","band":"easy","title":"Bus Number Twelve","topic":"上學交通","words":46,"paras":["Kai takes bus number twelve to school. The bus stop is near his house. A red sign shows the number. Kai has a bus card in his pocket. His friend Eva waits at the same stop. Their bus comes at seven. The driver knows their school."],"zh":"凱搭十二號公車上學。站牌在家附近，紅色牌子上有路線號碼。他把公車卡放在口袋裡。朋友伊娃在同一站等車，公車七點到，司機知道他們的學校。","qs":[{"type":"detail","q":"Which bus does Kai take?","options":["Number twenty","Number twelve","Number seven"],"answer":1,"why":"twelve 是路線號碼；seven 是公車到站時間。","evidence":"Kai takes bus number twelve to school."},{"type":"detail","q":"What does the red sign show?","options":["The driver's name","The school phone number","The bus number"],"answer":2,"why":"紅色牌子顯示公車號碼。","evidence":"A red sign shows the number."},{"type":"detail","q":"What time does the bus come?","options":["At seven","At eight","At twelve"],"answer":0,"why":"公車七點來，十二是公車號碼。","evidence":"Their bus comes at seven."},{"type":"main","q":"Which title fits this passage?","options":["A Bus Trip to Taipei","School by Bus","A New Bus Driver"],"answer":1,"why":"文章介紹 Kai 在住家附近搭公車上學。"}]},{"id":"a1-easy-fruit-shop","level":"A1","band":"easy","title":"Dad at the Fruit Shop","topic":"家人的工作","words":48,"paras":["My father works at a fruit shop. The shop is next to our home. He sells apples in the morning. My mother puts oranges in boxes. I write prices on small cards. One apple is twenty dollars. Our cat sleeps under the table. We like our little shop."],"zh":"爸爸在家旁邊的水果店工作，早上賣蘋果。媽媽把柳橙放進箱子，我在小卡片上寫價格。一顆蘋果二十元，貓在桌下睡覺。我們喜歡這間小店。","qs":[{"type":"main","q":"What does the passage describe?","options":["A school lunch","A large hospital","A family fruit shop"],"answer":2,"why":"每個人的工作都與家裡的水果店有關。"},{"type":"detail","q":"Who writes the prices?","options":["The writer","The mother","The father"],"answer":0,"why":"I 指作者，是作者寫價格卡。","evidence":"I write prices on small cards."},{"type":"detail","q":"How much is one apple?","options":["Twelve dollars","Twenty dollars","Two dollars"],"answer":1,"why":"一顆蘋果二十元，別把 twenty 看成 twelve。","evidence":"One apple is twenty dollars."},{"type":"detail","q":"Where does the cat sleep?","options":["In an orange box","Next to the door","Under the table"],"answer":2,"why":"文章說貓睡在桌子底下。","evidence":"Our cat sleeps under the table."}]},{"id":"a1-easy-study-desk","level":"A1","band":"easy","title":"A Desk by the Door","topic":"宿舍讀書","words":49,"paras":["Our dorm room has two desks. My desk is by the door. My roommate uses the desk by the window. I keep a lamp on my desk. My English notebook is beside it. My roommate reads nursing books. I write new words in my notebook. Our room is quiet."],"zh":"宿舍房間有兩張書桌。我的在門邊，室友的在窗邊。我把檯燈放在桌上，旁邊是英文筆記本。室友讀護理書，我寫新單字，房間很安靜。","qs":[{"type":"detail","q":"Where is the writer's desk?","options":["By the door","By the window","Outside the room"],"answer":0,"why":"門邊是作者的桌子；窗邊是室友的。","evidence":"My desk is by the door."},{"type":"detail","q":"What does the roommate read?","options":["Food prices","Nursing books","Bus maps"],"answer":1,"why":"室友讀的是護理書。","evidence":"My roommate reads nursing books."},{"type":"detail","q":"What is on the writer’s desk?","options":["A bowl of fruit","A family photo","A lamp"],"answer":2,"why":"作者在書桌上放一盞檯燈。","evidence":"I keep a lamp on my desk."},{"type":"main","q":"What is this passage about?","options":["Two desks in a dorm room","A lesson in a nursing classroom","Two friends at the library"],"answer":0,"why":"文章介紹宿舍兩張桌子的位置，以及兩位室友怎麼使用。"}]},{"id":"a1-easy-library-card","level":"A1","band":"easy","title":"Nora at the Library Desk","topic":"圖書館","words":48,"paras":["Nora likes the school library. She visits it on Monday. Her student card is in her bag. The librarian checks the card. Nora chooses a book about animals. The book has many pictures. She reads ten pages at her desk. Her favorite picture shows a small brown dog."],"zh":"諾拉喜歡學校圖書館，星期一去借書。學生證在書包裡，館員核對證件。她選一本有很多圖片的動物書，在自己的桌邊讀十頁，最喜歡小棕狗的圖片。","qs":[{"type":"detail","q":"What does the librarian check?","options":["A picture of a dog","Nora's student card","A bus ticket"],"answer":1,"why":"館員核對的是學生證。","evidence":"The librarian checks the card."},{"type":"detail","q":"What is the book about?","options":["Cooking","Nursing","Animals"],"answer":2,"why":"她選的是動物書，不是食譜或護理課本。","evidence":"Nora chooses a book about animals."},{"type":"detail","q":"How many pages does Nora read?","options":["Ten","Two","Twenty"],"answer":0,"why":"Nora 在桌前讀十頁。","evidence":"She reads ten pages at her desk."},{"type":"main","q":"What is this passage about?","options":["Nora’s bookshop job","Nora’s visit to the library","Nora’s class at school"],"answer":1,"why":"文章主要寫 Nora 到圖書館借閱動物書的活動。"}]},{"id":"a1-easy-laundry-basket","level":"A1","band":"easy","title":"The Yellow Basket","topic":"宿舍家事","words":50,"paras":["A yellow basket stands near our room door. My clean shirts are in the basket. My roommate keeps her shirts on a shelf. We wash our clothes on Saturday. I use the machine downstairs. My name is on my basket. My roommate has a blue basket in the same room."],"zh":"房門旁有一個黃色籃子，裡面是我洗好的襯衫。室友把襯衫放在架上。我們星期六洗衣服，我用樓下的洗衣機。黃籃上有我的名字，室友的藍籃也在同一個房間。","qs":[{"type":"main","q":"Which title fits this passage?","options":["A New Shirt from a Shop","A Room with Two Beds","Clothes in Our Room"],"answer":2,"why":"文章集中介紹室友的衣物、洗衣籃和洗衣習慣。"},{"type":"detail","q":"Where are the writer's clean shirts?","options":["In the yellow basket","On the shelf","Inside the machine"],"answer":0,"why":"黃色籃子裡的是作者洗好的襯衫；架上是室友的。","evidence":"My clean shirts are in the basket."},{"type":"detail","q":"When do they wash their clothes?","options":["On Friday","On Saturday","On Monday"],"answer":1,"why":"文中指定星期六洗衣服。","evidence":"We wash our clothes on Saturday."},{"type":"detail","q":"What is on the yellow basket?","options":["A picture of a dog","The washing date","The writer’s name"],"answer":2,"why":"作者名字寫在自己的黃色籃子上。","evidence":"My name is on my basket."}]},{"id":"a1-easy-morning-call","level":"A1","band":"easy","title":"A Call to Grandpa","topic":"家人聯絡","words":49,"paras":["I call my grandfather on Sunday mornings. He lives in Tainan. I live in a school dorm in Taichung. Grandpa asks about my classes. I tell him about my English teacher. He talks about his garden. His flowers are yellow. Our calls are short. We enjoy this time together."],"zh":"我星期日早上打電話給住在台南的爺爺。我住在台中的學校宿舍。爺爺問我的課，我介紹英文老師；他聊花園裡黃色的花。通話時間不長，但我們很享受這段相處。","qs":[{"type":"detail","q":"Where does Grandpa live?","options":["In Tainan","In Taichung","In Taipei"],"answer":0,"why":"爺爺住台南；台中是作者的宿舍所在地。","evidence":"He lives in Tainan."},{"type":"detail","q":"What does Grandpa talk about?","options":["A hospital map","His garden","The writer's bus"],"answer":1,"why":"爺爺分享的是花園的事。","evidence":"He talks about his garden."},{"type":"detail","q":"When does the writer call Grandpa?","options":["On Monday nights","Every afternoon","On Sunday mornings"],"answer":2,"why":"開頭說星期日早上打給阿公。","evidence":"I call my grandfather on Sunday mornings."},{"type":"main","q":"What is this story about?","options":["A phone call with Grandpa","A visit to Grandpa’s garden","An English class in Tainan"],"answer":0,"why":"作者用電話和阿公分享近況，沒有真的去花園。"}]},{"id":"a1-easy-name-badge","level":"A1","band":"easy","title":"A Badge for Class","topic":"護理課堂","words":49,"paras":["Our nursing teacher has a box of name badges. Each student takes one. My badge has my name in English. I wear it on my shirt. My friend Leo sits beside me. His badge is on his bag. The teacher reads our names. She smiles at our new class."],"zh":"護理老師準備了一盒名牌，每位學生拿一個。我的名牌有英文名字，我把它別在襯衫上。里歐坐在旁邊，他的名牌在書包上。老師看著名字，對新班級微笑。","qs":[{"type":"detail","q":"Where does the writer wear the badge?","options":["On a desk","On a shirt","On a bag"],"answer":1,"why":"作者把名牌戴在襯衫上；書包上的是里歐的。","evidence":"I wear it on my shirt."},{"type":"main","q":"What is this story about?","options":["Badges for a hospital visit","Books for an English lesson","Name badges in a new class"],"answer":2,"why":"新班級使用名牌，讓老師認識同學的名字。"},{"type":"detail","q":"Who sits beside the writer?","options":["Leo","The teacher","A nurse from a hospital"],"answer":0,"why":"坐在作者旁邊的朋友叫 Leo。","evidence":"My friend Leo sits beside me."},{"type":"detail","q":"Where is Leo’s badge?","options":["On his chair","On his bag","On the teacher’s desk"],"answer":1,"why":"Leo 的名牌放在書包上。","evidence":"His badge is on his bag."}]},{"id":"a1-easy-campus-map","level":"A1","band":"easy","title":"The Map at the Gate","topic":"校園位置","words":49,"paras":["A map is beside our school gate. The library is near the sports field. The office is next to the library. My classroom is in the tall building. A red star on the map shows the gate. I read the map with my sister. She points to my classroom."],"zh":"校門旁有地圖。圖書館在運動場附近，辦公室在圖書館旁。我的教室在高樓裡，地圖上的紅星代表校門。我和姊妹一起看地圖，她指出我的教室。","qs":[{"type":"main","q":"What does the map show?","options":["Houses on our street","Rooms in a hospital","Places at school"],"answer":2,"why":"地圖顯示學校的圖書館、辦公室、教室等位置。"},{"type":"detail","q":"What is next to the library?","options":["The office","The gate","A bus stop"],"answer":0,"why":"圖書館旁邊的是辦公室。","evidence":"The office is next to the library."},{"type":"detail","q":"What does the red star show?","options":["The sports field","The school gate","The classroom"],"answer":1,"why":"紅星代表校門，不是教室或運動場。","evidence":"A red star on the map shows the gate."},{"type":"detail","q":"Who reads the map with the writer?","options":["The English teacher","A classmate","The writer’s sister"],"answer":2,"why":"作者和姊妹一起看地圖；sister 沒說年紀大小。","evidence":"I read the map with my sister."}]},{"id":"a1-easy-monday-lessons","level":"A1","band":"easy","title":"Monday Lessons","topic":"課表","words":49,"paras":["My Monday lessons start at eight. English is the first class. Our teacher uses pictures in this lesson. Nursing is the next class. I keep two notebooks in my bag. The red notebook is for English. The white notebook is for nursing. Lunch starts at twelve in our school."],"zh":"我星期一八點開始上課，第一堂是英文，老師用圖片教學，下一堂是護理。書包裡有兩本筆記本，紅本記英文，白本記護理，學校十二點開始午餐時間。","qs":[{"type":"detail","q":"Which class comes first on Monday?","options":["English","Nursing","Art"],"answer":0,"why":"第一堂是英文，護理是下一堂。","evidence":"English is the first class."},{"type":"detail","q":"Which notebook is for nursing?","options":["The blue one","The white one","The red one"],"answer":1,"why":"白色筆記本用於護理；紅色用於英文。","evidence":"The white notebook is for nursing."},{"type":"detail","q":"What time does lunch start?","options":["At eight","At ten","At twelve"],"answer":2,"why":"午餐十二點開始，八點是上課時間。","evidence":"Lunch starts at twelve in our school."},{"type":"main","q":"Which title also fits?","options":["Classes and Notebooks for Monday","A Weekend at Home","A Teacher at a Restaurant"],"answer":0,"why":"文章把星期一的課程和各科筆記本連在一起。"}]},{"id":"a1-easy-lunch-order","level":"A1","band":"easy","title":"Two Bowls of Noodles","topic":"學校午餐","words":52,"paras":["Mia buys lunch at the school shop. She orders two bowls of noodles. One bowl is for her friend Jun. Jun waits at a table near the door. Mia carries the food to the table. Jun brings two cups of water. They eat lunch at twelve. Their next class starts at one."],"zh":"米亞在學校餐店買兩碗麵，一碗是朋友俊的。俊在門邊的桌子等，她把餐點端過去，俊拿來兩杯水。他們十二點吃午餐，下一堂課一點開始。","qs":[{"type":"detail","q":"How many bowls does Mia order?","options":["Three","Two","One"],"answer":1,"why":"她替自己和俊買了兩碗麵。","evidence":"She orders two bowls of noodles."},{"type":"detail","q":"Who brings the water?","options":["Mia","The teacher","Jun"],"answer":2,"why":"水是俊拿來的；米亞負責端麵。","evidence":"Jun brings two cups of water."},{"type":"detail","q":"Where does Jun wait?","options":["At a table near the door","At the bus stop","In the classroom"],"answer":0,"why":"Jun 在靠門的桌子旁等。","evidence":"Jun waits at a table near the door."},{"type":"main","q":"What do the friends do together?","options":["Study in the library","Have lunch at school","Cook dinner at home"],"answer":1,"why":"他們在學校同一張桌子吃午餐，分別帶餐點和水。"}]},{"id":"a1-easy-room-key","level":"A1","band":"easy","title":"A Key on a Red Ring","topic":"宿舍物品","words":50,"paras":["I keep my room key on a red ring. The key opens room twenty. My roommate has another key for our room. Her key ring is black. I put my key in my bag at school. At home, it stays in a bowl by the door. The bowl is small."],"zh":"我的房間鑰匙掛在紅色鑰匙圈上，能開二十號房。室友有同房的另一把鑰匙，她的鑰匙圈是黑色。我在學校把鑰匙放書包裡，回家則放門邊的小碗。","qs":[{"type":"main","q":"What is this passage about?","options":["The roommate’s new school bag","The teacher’s classroom door","The writer’s room key"],"answer":2,"why":"文章介紹房間鑰匙的顏色、用途與收放位置。"},{"type":"detail","q":"Which room does the key open?","options":["Room twenty","Room twelve","Room two"],"answer":0,"why":"twenty 是二十，不是 twelve（十二）。","evidence":"The key opens room twenty."},{"type":"detail","q":"What color is the roommate's key ring?","options":["White","Black","Red"],"answer":1,"why":"黑色鑰匙圈是室友的；紅色是作者的。","evidence":"Her key ring is black."},{"type":"detail","q":"Where does the key stay at home?","options":["Under the desk","In a box by the bed","In a bowl by the door"],"answer":2,"why":"回家後鑰匙放在門邊的小碗裡。","evidence":"At home, it stays in a bowl by the door."}]},{"id":"a1-mid-poster-team","level":"A1","band":"mid","title":"Our Class Poster","topic":"小組作業","words":67,"paras":["Our class is making a poster about school life. There is a large sheet of paper on the table. Lisa is drawing our library. She can draw very well. Ben is writing the title at the top. I am choosing photos from our class trip. We can use three photos on this poster. Our teacher is watching our group. She has some extra paper in her bag."],"zh":"我們班正在做校園生活海報，桌上有一大張紙。麗莎畫圖書館，她很會畫畫。班在最上方寫標題，我挑班遊照片，海報能放三張。老師看著我們，包裡有備用的紙。","qs":[{"type":"main","q":"What is the group working on?","options":["A poster about school life","A library borrowing card","A plan for a new hospital"],"answer":0,"why":"大家畫圖、寫標題和選照片，是共同製作校園海報。"},{"type":"detail","q":"Where is Ben writing the title?","options":["In his notebook","At the top of the poster","On the back of a photo"],"answer":1,"why":"標題寫在海報最上方。","evidence":"Ben is writing the title at the top."},{"type":"reference","q":"Who is \\"She\\" in \\"She can draw very well\\"?","options":["The teacher","The writer","Lisa"],"answer":2,"why":"上一句是 Lisa 正在畫圖，因此 She 指 Lisa。","evidence":"She can draw very well."},{"type":"detail","q":"What is Lisa drawing?","options":["The school library","The dining room","The sports field"],"answer":0,"why":"Lisa 正在畫學校圖書館。","evidence":"Lisa is drawing our library."},{"type":"detail","q":"How many photos can the group use?","options":["Five","Three","Two"],"answer":1,"why":"海報可用三張照片，不是全班的人數。","evidence":"We can use three photos on this poster."}]},{"id":"a1-mid-rainy-hall","level":"A1","band":"mid","title":"Waiting in the Hall","topic":"雨天放學","words":64,"paras":["It is raining outside our classroom. Two students are waiting in the hall. Mina has a large umbrella. She can share it with her sister. Their brother is at the school gate. He has his own raincoat. There is a dry bench near the classroom door. Mina is sitting there. Her sister is checking the time on her phone. Their bus comes at four."],"zh":"教室外正在下雨，兩位學生在走廊等候。米娜有大傘，可和姊妹共用。兄弟在校門口，有自己的雨衣。門邊有乾的長椅，米娜坐在那裡，姊妹用手機看時間，公車四點到。","qs":[{"type":"detail","q":"Who can share Mina’s umbrella?","options":["The bus driver","Her sister","Her teacher"],"answer":1,"why":"Mina 可以和姊妹共用雨傘；sister 沒有指定誰年紀大。","evidence":"She can share it with her sister."},{"type":"reference","q":"What place does \\"there\\" refer to?","options":["The bus stop","The school gate","The dry bench"],"answer":2,"why":"前一句提到門邊的乾長椅，there 指那張長椅所在處。","evidence":"Mina is sitting there."},{"type":"detail","q":"Where is Mina’s brother?","options":["At the school gate","On the classroom bench","Inside the bus"],"answer":0,"why":"哥哥或弟弟在校門口；brother 沒有說年紀大小。","evidence":"Their brother is at the school gate."},{"type":"detail","q":"What is the sister doing?","options":["Driving a bus","Checking the time","Drawing an umbrella"],"answer":1,"why":"姊妹正用手機看時間（sister 沒說是姊姊還是妹妹）。","evidence":"Her sister is checking the time on her phone."},{"type":"main","q":"Which idea fits the passage?","options":["Students cleaning the classroom","A family buying clothes","Students waiting to leave on a rainy day"],"answer":2,"why":"雨具、走廊等候和公車時間都與雨天離校有關。"}]},{"id":"a1-mid-phone-charger","level":"A1","band":"mid","title":"A Charger from a Friend","topic":"讀書用品","words":66,"paras":["Tom is studying English in the library. His phone has no power. A charger is on his friend Hana’s desk. She can lend it to him for one hour. There is a socket beside Tom’s chair. He is plugging in the charger. His paper dictionary is open on the desk. Tom can use that book now. Hana is reading a nursing textbook at the next table."],"zh":"湯姆在圖書館讀英文，手機沒電了。朋友花奈桌上有充電器，可以借他一小時。他的椅子旁有插座，正把充電器插上。紙本字典已打開，他現在可以查那本書。花奈在隔壁桌讀護理課本。","qs":[{"type":"main","q":"What problem does Tom have?","options":["His textbook is missing.","His chair is broken.","His phone has no power."],"answer":2,"why":"故事起因是手機沒電，朋友借充電器協助。"},{"type":"detail","q":"How long can Tom borrow the charger?","options":["One hour","One day","One week"],"answer":0,"why":"花奈可借他一小時。","evidence":"She can lend it to him for one hour."},{"type":"reference","q":"In \\"She can lend it to him\\", what is \\"it\\"?","options":["The textbook","The charger","The dictionary"],"answer":1,"why":"it 代替前一句桌上的 charger，不是後面提到的書。","evidence":"She can lend it to him for one hour."},{"type":"detail","q":"Where is the socket?","options":["Under Hana’s desk","Outside the library","Beside Tom’s chair"],"answer":2,"why":"插座在 Tom 的椅子旁邊。","evidence":"There is a socket beside Tom’s chair."},{"type":"detail","q":"What can Tom use right now?","options":["A paper dictionary","Hana’s phone","A hospital computer"],"answer":0,"why":"文章明確提到紙本字典已打開，他可以先用那本。","evidence":"Tom can use that book now."}]},{"id":"a1-mid-lunch-line","level":"A1","band":"mid","title":"The Lunch Line","topic":"學生餐廳","words":66,"paras":["There are two lines in the school cafeteria. The line near the window is for noodles. The other line is for rice. Ken is standing in the rice line. His friend Alice is choosing vegetables beside the counter. Students can get water from a machine near the door. Alice has a bottle in her hand. She is filling it now. Ken is carrying their two trays."],"zh":"學生餐廳有兩排隊伍，靠窗的買麵，另一排買飯。肯在排飯，愛麗絲在櫃檯旁選菜。門邊機器可裝水，她拿著水壺正在裝水，肯則拿著兩人的餐盤。","qs":[{"type":"detail","q":"Which line is Ken in?","options":["The rice line","The noodle line","The water line"],"answer":0,"why":"Ken 排的是 rice line，靠窗的才是麵食隊伍。","evidence":"Ken is standing in the rice line."},{"type":"reference","q":"What does \\"it\\" mean in \\"She is filling it now\\"?","options":["The rice bowl","Her bottle","A tray"],"answer":1,"why":"上一句介紹 Alice 手裡的水壺，it 指水壺。","evidence":"She is filling it now."},{"type":"detail","q":"Where can students get water?","options":["Beside the window","Outside the school","Near the door"],"answer":2,"why":"飲水機在門邊，不在麵食隊伍旁。","evidence":"Students can get water from a machine near the door."},{"type":"detail","q":"What is Alice choosing?","options":["Vegetables","Noodles","Fruit juice"],"answer":0,"why":"Alice 正在餐台旁選蔬菜。","evidence":"His friend Alice is choosing vegetables beside the counter."},{"type":"main","q":"What does the passage show?","options":["How students wash their clothes","How two friends get their lunch","How a cook prepares noodles"],"answer":1,"why":"作者描述排隊、選菜、裝水和拿餐盤的分工。"}]},{"id":"a1-mid-room-plant","level":"A1","band":"mid","title":"A Plant in Our Room","topic":"宿舍生活","words":66,"paras":["There is a small plant on our dorm window shelf. Its leaves are green. My roommate Jo is looking at the soil. It is dry today. She is giving the plant some water. I can move the plant away from our books. There is a tray under the pot. It holds the extra water. Jo likes this plant. She takes a photo of it every week."],"zh":"宿舍窗邊架上有小盆栽，葉子是綠的。室友喬看土壤，今天土很乾，她正在澆水。我可以把盆栽移離書本，花盆下的托盤接住多餘的水。喬喜歡這株植物，每週都拍照。","qs":[{"type":"detail","q":"What is dry today?","options":["Jo’s books","The soil","The tray"],"answer":1,"why":"dry 描述土壤，不是托盤或書本。","evidence":"It is dry today."},{"type":"reference","q":"In \\"It holds the extra water\\", what does \\"It\\" mean?","options":["The window","The shelf","The tray"],"answer":2,"why":"It 指前一句花盆底下的托盤。","evidence":"It holds the extra water."},{"type":"detail","q":"Where is the plant?","options":["On the dorm window shelf","Beside the room door","Under Jo’s bed"],"answer":0,"why":"開頭交代植物在宿舍窗邊的架上。","evidence":"There is a small plant on our dorm window shelf."},{"type":"detail","q":"What does Jo do every week?","options":["Move to another room","Take a photo of the plant","Buy a new pot"],"answer":1,"why":"她每週拍植物的照片。","evidence":"She takes a photo of it every week."},{"type":"main","q":"What are the roommates doing?","options":["Growing food for the whole school","Building a new window","Caring for a room plant"],"answer":2,"why":"文章是宿舍盆栽的日常照顧，沒有談大規模種植。"}]},{"id":"a1-mid-clinic-floors","level":"A1","band":"mid","title":"The Clinic Building","topic":"認識門診","words":69,"paras":["There is a clinic on the first floor of this building. The second floor has a classroom for nursing students. Today our class is visiting it. A nurse is waiting near the stairs. She can show us the classroom door. The clinic has a separate entrance beside the street. Patients can use that entrance. Our teacher is counting the students in the hall. We are ready for our lesson."],"zh":"這棟樓一樓是診所，二樓有護理學生教室，今天我們班來參觀。護理師在樓梯邊等，可帶我們找教室門。診所在路邊有獨立入口，病人可從那裡進入。老師在走廊點人數，大家準備上課。","qs":[{"type":"detail","q":"Which floor has the student classroom?","options":["The first floor","The third floor","The second floor"],"answer":2,"why":"二樓是教室，一樓是診所。","evidence":"The second floor has a classroom for nursing students."},{"type":"reference","q":"What does \\"it\\" refer to in \\"our class is visiting it\\"?","options":["The classroom","The street","A patient’s room"],"answer":0,"why":"上一句介紹二樓的教室，it 指教室。","evidence":"Today our class is visiting it."},{"type":"detail","q":"Where is the clinic entrance?","options":["Behind the teacher’s desk","Beside the street","Inside the classroom"],"answer":1,"why":"診所的獨立入口就在街道旁邊。","evidence":"The clinic has a separate entrance beside the street."},{"type":"detail","q":"Who can show students the classroom door?","options":["A patient","A bus driver","A nurse"],"answer":2,"why":"樓梯邊的護理師可帶學生看教室入口。","evidence":"She can show us the classroom door."},{"type":"main","q":"What is the passage mainly about?","options":["Arriving at a nursing classroom","Taking medicine after lunch","Repairing a hospital lift"],"answer":0,"why":"整篇在介紹學生到教室的位置、帶路人和集合。"}]},{"id":"a1-mid-volunteer-board","level":"A1","band":"mid","title":"Jobs for Open Day","topic":"校園活動","words":66,"paras":["Our school is holding an open day. There are three jobs on the notice board. Students can help at the gate, the library, or the lunch room. I am reading the job list with Yuna. She is choosing the library job. I can speak English with visitors at the gate. Two teachers are checking our names. There is a short meeting in room six at noon."],"zh":"學校正在辦開放參觀日，公布欄有三種工作：校門、圖書館或午餐區協助。我和優娜看工作表，她選圖書館，我可以在校門用英文和訪客交談。兩位老師核對姓名，中午六號教室有短會議。","qs":[{"type":"detail","q":"Which job does Yuna choose?","options":["Helping in the library","Helping in the lunch room","Helping at the gate"],"answer":0,"why":"She 指優娜，她選擇圖書館工作。","evidence":"She is choosing the library job."},{"type":"reference","q":"In \\"our names\\", whose names are these?","options":["The cooks’","The writer’s and Yuna’s","The visitors’"],"answer":1,"why":"前文是作者和優娜選工作，老師核對他們的姓名。","evidence":"Two teachers are checking our names."},{"type":"detail","q":"How many jobs are on the board?","options":["Two","Six","Three"],"answer":2,"why":"佈告欄列三種工作，六是集合教室號碼。","evidence":"There are three jobs on the notice board."},{"type":"detail","q":"Where is the short meeting?","options":["In room six","At the front gate","In the lunch room"],"answer":0,"why":"會議在六號教室，不是選的工作地點。","evidence":"There is a short meeting in room six at noon."},{"type":"main","q":"What are the students doing?","options":["Canceling a school trip","Choosing ways to help on open day","Applying for hospital treatment"],"answer":1,"why":"他們在挑選開放參觀日的協助工作。"}]},{"id":"a1-mid-greeting-practice","level":"A1","band":"mid","title":"A Greeting Practice","topic":"護理英文","words":65,"paras":["Our English class is practicing short greetings. There is a chair beside each desk. One student can sit there as a visitor. The other student is a nursing student. I am saying my name to my partner. She is listening carefully. Her role card has the visitor’s name. We can read our cards during this practice. Our teacher is writing useful words on the board."],"zh":"英文課正在練簡短問候。每張桌旁有椅子，一人坐著扮訪客，另一人扮護生。我正向夥伴說名字，她仔細聽。她的角色卡有訪客姓名，練習時可以看卡片，老師在黑板寫好用單字。","qs":[{"type":"main","q":"What are the students practicing?","options":["Names of body parts","Short greetings in English","Directions from a map"],"answer":1,"why":"同學扮演訪客與護生，練習用英文打招呼。"},{"type":"detail","q":"What can students use during practice?","options":["A food menu","A bus timetable","Their role cards"],"answer":2,"why":"這次練習可以看各自的角色卡。","evidence":"We can read our cards during this practice."},{"type":"reference","q":"Who is \\"She\\" in \\"She is listening carefully\\"?","options":["The writer’s partner","The teacher","A real patient"],"answer":0,"why":"She 接續前一句的 partner。","evidence":"She is listening carefully."},{"type":"detail","q":"Where can the visitor sit?","options":["On the classroom floor","On a chair beside the desk","At the teacher’s board"],"answer":1,"why":"每張桌子旁有椅子，扮演訪客的人可以坐那裡。","evidence":"There is a chair beside each desk."},{"type":"detail","q":"What is the teacher writing?","options":["Visitor phone numbers","Lunch orders","Useful words"],"answer":2,"why":"老師在黑板寫練習可用的單字。","evidence":"Our teacher is writing useful words on the board."}]},{"id":"a1-mid-visitor-map","level":"A1","band":"mid","title":"Help at the Information Desk","topic":"醫院訪客","words":65,"paras":["A visitor is looking at a hospital map. He cannot find the classroom for a public talk. There are two blue buildings on the map. A volunteer is helping him at the information desk. She is pointing to building B. The talk is on its first floor. The visitor can take a small paper map with him. His wife is waiting on a chair nearby."],"zh":"一位訪客正看醫院地圖，找不到公開講座的教室。地圖上有兩棟藍色建築，服務台志工指著 B 棟，講座在那裡的一樓。訪客可以帶小紙地圖，太太在附近椅子等候。","qs":[{"type":"detail","q":"What is the visitor looking for?","options":["A pharmacy counter","His wife’s room","A classroom for a talk"],"answer":2,"why":"他要去公開講座的教室，沒有說要領藥或探病。","evidence":"He cannot find the classroom for a public talk."},{"type":"reference","q":"In \\"its first floor\\", what does \\"its\\" refer to?","options":["Building B","The information desk","The paper map"],"answer":0,"why":"前一句指向 B 棟，所以 its first floor 是 B 棟一樓。","evidence":"The talk is on its first floor."},{"type":"detail","q":"Who is waiting on a chair?","options":["A nursing student","The visitor’s wife","The volunteer’s teacher"],"answer":1,"why":"結尾交代訪客的妻子坐在附近等候。","evidence":"His wife is waiting on a chair nearby."},{"type":"detail","q":"What can the visitor take with him?","options":["The volunteer’s chair","A blue building sign","A small paper map"],"answer":2,"why":"他可以拿一份紙地圖，不是搬走椅子或標示。","evidence":"The visitor can take a small paper map with him."},{"type":"main","q":"What is this passage mainly about?","options":["A volunteer helps a visitor find a place.","A nurse gives a talk about medicine.","A visitor buys a map in a shop."],"answer":0,"why":"訪客找不到教室，志工用地圖幫忙指出位置。"}]},{"id":"a1-mid-shared-kitchen","level":"A1","band":"mid","title":"Dinner in the Shared Kitchen","topic":"宿舍晚餐","words":65,"paras":["There are four students in the dorm kitchen. Jun is cooking rice in a small cooker. His friend is cutting a cucumber on a clean board. Two other students are setting the table. There are six bowls on the shelf. Everyone can use them. Jun is checking the cooker’s light. The rice is not ready yet. We can wash the extra bowls during this time."],"zh":"宿舍廚房有四位學生。俊用小電鍋煮飯，朋友在乾淨砧板上切小黃瓜，另兩位擺餐桌。架上六個碗可共用。俊看電鍋指示燈，飯還沒好，這段時間可以先洗備用的碗。","qs":[{"type":"detail","q":"How many students are in the kitchen?","options":["Four","Six","Two"],"answer":0,"why":"四是人數，六是架上的碗數。","evidence":"There are four students in the dorm kitchen."},{"type":"reference","q":"What does \\"them\\" mean in \\"Everyone can use them\\"?","options":["The lights","The bowls","The students"],"answer":1,"why":"them 指前一句架上的六個碗。","evidence":"Everyone can use them."},{"type":"detail","q":"What is Jun cooking?","options":["Noodles","Soup","Rice"],"answer":2,"why":"Jun 正用小電鍋煮飯。","evidence":"Jun is cooking rice in a small cooker."},{"type":"detail","q":"What are two students doing?","options":["Setting the table","Buying cucumbers","Cleaning the windows"],"answer":0,"why":"兩位學生負責擺餐桌。","evidence":"Two other students are setting the table."},{"type":"main","q":"What is the main activity?","options":["Giving a nursing test","Preparing a shared dinner","Choosing a new dorm"],"answer":1,"why":"四人正在分工準備一餐。"}]},{"id":"a1-mid-online-lesson","level":"A1","band":"mid","title":"An Online English Lesson","topic":"英文學習","words":65,"paras":["Ning is at her desk for an online English lesson. The teacher is showing a picture of a bus station. There are three people in the picture. Ning can see their bags beside a bench. She is typing a short answer in the chat box. Her microphone is off now. The class can read her answer on the screen. Her notebook has today’s new words."],"zh":"寧坐在桌前上線上英文課。老師展示公車站圖片，圖中三個人的包放在長椅旁。寧把短答案打進聊天室，目前麥克風關閉，全班能在螢幕看到答案，她的筆記本記著今日新單字。","qs":[{"type":"detail","q":"What place does the teacher’s picture show?","options":["A dorm kitchen","A bus station","A hospital room"],"answer":1,"why":"老師展示的是公車站圖片。","evidence":"The teacher is showing a picture of a bus station."},{"type":"reference","q":"Who has \\"their bags\\" in the picture?","options":["Ning’s roommates","The online teachers","The three people in the picture"],"answer":2,"why":"their 回指前一句圖裡的三個人。","evidence":"Ning can see their bags beside a bench."},{"type":"detail","q":"How is Ning answering now?","options":["By typing","By speaking into her microphone","By drawing on paper"],"answer":0,"why":"她正在聊天室打字，而且麥克風關閉。","evidence":"She is typing a short answer in the chat box."},{"type":"detail","q":"How many people are in the picture?","options":["Four","Three","Two"],"answer":1,"why":"圖裡一共有三個人。","evidence":"There are three people in the picture."},{"type":"main","q":"What does this passage describe?","options":["Ning catching a bus","Ning buying a microphone","Ning taking part in an online class"],"answer":2,"why":"描述她看圖片、打字回答和記單字的線上上課情況。"}]},{"id":"a1-hard-quiet-corner","level":"A1","band":"hard","title":"The Quiet Practice Corner","topic":"課後口說練習","words":88,"paras":["Every Thursday, our nursing group practices English in the library. The main room is busy, but a small corner near the back is usually quiet. We meet there at four because our last class ends at three thirty. Jia brings picture cards, and I bring a notebook. First, we describe the people on the cards. Then we ask simple questions about their jobs. We speak softly because other students are reading nearby. Our practice ends at four thirty. Everyone puts the cards back in the box before dinner."],"zh":"每週四我們護理小組在圖書館練英文。大空間很忙碌，但後方角落通常安靜。最後一堂課三點半結束，因此四點集合。佳帶圖片卡，我帶筆記本，先描述卡上的人，再問職業。我們輕聲說話，因為旁邊有人閱讀。四點半結束，晚餐前把卡收回盒中。","qs":[{"type":"detail","q":"Why does the group speak softly?","options":["The teacher is sleeping.","The cards are difficult to read.","Other students are reading nearby."],"answer":2,"why":"因為附近還有同學看書，所以這組放輕聲音。","evidence":"We speak softly because other students are reading nearby."},{"type":"reference","q":"What place does \\"there\\" mean?","options":["The quiet corner","Their classroom","The dining room"],"answer":0,"why":"there 指前一句圖書館後方的小角落。","evidence":"We meet there at four because our last class ends at three thirty."},{"type":"vocab","q":"What does \\"usually\\" tell us?","options":["The corner is never quiet.","The corner is quiet most of the time.","The corner is quiet only today."],"answer":1,"why":"usually 表示通常如此，不保證每一次都完全一樣。","evidence":"The main room is busy, but a small corner near the back is usually quiet."},{"type":"detail","q":"Which activity comes first in the practice?","options":["Asking about jobs","Putting the cards away","Describing people on the cards"],"answer":2,"why":"First 後面的活動是描述圖卡上的人。","evidence":"First, we describe the people on the cards."},{"type":"main","q":"What is the main idea?","options":["A group has a regular English practice routine.","A library stops students from meeting.","A teacher changes the dinner time."],"answer":0,"why":"文章交代固定時間、地點、材料、順序和音量，是一套練習安排。"}]},{"id":"a2-easy-room-change","level":"A2","band":"easy","title":"The Wrong Classroom","topic":"課堂小事件","words":102,"paras":["Last Tuesday, I went to room 204 for my English class. The door was open, but the room was empty. I checked my watch. It was ten minutes before nine. My class usually started at nine. I waited outside the door for a short time.","Then my classmate Yun came along the hall. She carried a note from our teacher. Our class was in room 210 that day because the light in room 204 was broken. I followed Yun to the other room. We arrived two minutes before the lesson. I thanked her and put the new room number in my notebook."],"zh":"上週二我去 204 教室上英文，門開著卻沒人，當時八點五十分，課通常九點開始。我在門外等了一會兒。芸帶著老師的便條走來；204 的燈壞了，當天改在 210。我跟她過去，上課前兩分鐘到，向她道謝並記下新教室。","qs":[{"type":"main","q":"What problem did the writer solve?","options":["Finding the changed classroom","Buying a new watch","Repairing a classroom light"],"answer":0,"why":"作者找到了臨時更換的教室；修燈不是作者做的事。"},{"type":"detail","q":"Why was the class in room 210?","options":["The class started earlier.","A light in room 204 was broken.","Room 210 had a new teacher."],"answer":1,"why":"because 後面說明換教室是因為原教室的燈壞了。","evidence":"Our class was in room 210 that day because the light in room 204 was broken."},{"type":"detail","q":"How early did the two students arrive for the lesson?","options":["Ten minutes early","Twenty minutes early","Two minutes early"],"answer":2,"why":"到正確教室時只剩上課前兩分鐘；十分鐘是先前看錶時。","evidence":"We arrived two minutes before the lesson."},{"type":"reference","q":"Who is \\"her\\" in \\"I thanked her\\"?","options":["Yun","The teacher","A student in room 204"],"answer":0,"why":"帶路的是同學芸，所以道謝的對象是她。","evidence":"I thanked her and put the new room number in my notebook."},{"type":"vocab","q":"An \\"empty\\" room has…","options":["no light switch","no people inside","no door"],"answer":1,"why":"第一段說教室沒有任何人，不是沒有門。","evidence":"The door was open, but the room was empty."},{"type":"detail","q":"What did Yun carry?","options":["A new classroom light","The writer’s watch","A note from the teacher"],"answer":2,"why":"芸拿著老師的便條，讓作者知道換教室的消息。","evidence":"She carried a note from our teacher."}]},{"id":"a2-easy-umbrella-return","level":"A2","band":"easy","title":"The Umbrella at the Office","topic":"雨天互助","words":107,"paras":["It rained after our last class on Friday. I opened my bag, but my umbrella was not inside. I looked under my classroom desk. It was not there either. My friend Bo stayed with me in the hall. He had a large umbrella. We walked together to the school office under it.","A teacher showed us a green umbrella beside her desk. It had a small yellow label with my name on it. I remembered my visit to the office that morning. I took my umbrella and thanked the teacher. Bo smiled and went to the bus stop. I walked home with dry books in my bag."],"zh":"星期五最後一堂下課後下雨，我在書包和桌下都找不到傘。博陪我在走廊等，他有大傘，我們共撐到辦公室。老師指給我們看桌旁的綠傘，黃標籤有我的名字。我想起早上來過辦公室，拿回傘並道謝，博去公車站，我背著沒淋濕的書回家。","qs":[{"type":"detail","q":"Where did the writer find the umbrella?","options":["At the bus stop","At the school office","Under the classroom desk"],"answer":1,"why":"找到傘的地方是辦公室；桌下找過但沒有。","evidence":"A teacher showed us a green umbrella beside her desk."},{"type":"vocab","q":"What is a \\"label\\" in this story?","options":["A type of bus ticket","A pocket inside a bag","A small piece showing a name"],"answer":2,"why":"黃色 label 上寫姓名，是辨認物品用的小標籤。","evidence":"It had a small yellow label with my name on it."},{"type":"reference","q":"What does \\"it\\" refer to in \\"under it\\"?","options":["Bo’s umbrella","The classroom desk","The writer’s bag"],"answer":0,"why":"前一句提到博的大傘，兩人一起在傘下走。","evidence":"We walked together to the school office under it."},{"type":"detail","q":"How did the writer recognize the umbrella?","options":["The bus number on it","The name on the yellow label","The books under it"],"answer":1,"why":"標籤寫著作者姓名，提供確定的辨認線索。","evidence":"It had a small yellow label with my name on it."},{"type":"main","q":"Which description best fits Bo?","options":["Angry with the teacher","Careless with his own books","Helpful to his friend"],"answer":2,"why":"博陪找傘並共撐自己的傘到辦公室，表現出幫助朋友。"},{"type":"detail","q":"Where did Bo go at the end?","options":["To the bus stop","To the library","To the writer’s home"],"answer":0,"why":"最後博去公車站，作者則走路回家。","evidence":"Bo smiled and went to the bus stop."}]},{"id":"a2-easy-book-return","level":"A2","band":"easy","title":"A Note in the Library Book","topic":"借書習慣","words":108,"paras":["On Monday evening, I finished a short English story from the school library. I put the book in my bag for the next day. Then I noticed a piece of paper near the last page. It was my list of new words from the story. I took it out and kept it in my English notebook.","The next morning, I returned the book at the library desk. The librarian checked the cover and the pages. She thanked me for keeping the book clean. I chose another story from a shelf near the window. This book had a blue cover. I read the first page during my lunch break."],"zh":"星期一晚上我讀完圖書館的英文故事，把書放進隔天要帶的書包，發現末頁附近夾著自己整理的新單字表，便取出放進筆記本。隔天早上還書，館員檢查封面和書頁並謝謝我保持書本乾淨。我又選了窗邊架上的藍封面故事，午休讀了第一頁。","qs":[{"type":"main","q":"What does the story show about the writer?","options":["A wish to stop reading English","A job at the library desk","Care with a borrowed book and study notes"],"answer":2,"why":"作者收好自己的單字表、還乾淨的書，又借下一本。"},{"type":"detail","q":"What was the piece of paper?","options":["The writer’s word list","A letter from the librarian","A receipt for a new book"],"answer":0,"why":"紙張是作者從故事整理的新單字表。","evidence":"It was my list of new words from the story."},{"type":"detail","q":"Where did the writer keep the paper?","options":["Beside the library window","In an English notebook","Inside the returned book"],"answer":1,"why":"作者拿出紙張並夾進英文筆記本。","evidence":"I took it out and kept it in my English notebook."},{"type":"reference","q":"Who is \\"She\\" in \\"She thanked me\\"?","options":["The writer’s teacher","A classmate","The librarian"],"answer":2,"why":"上一句的 librarian 是接著道謝的人。","evidence":"She thanked me for keeping the book clean."},{"type":"vocab","q":"What does \\"returned\\" mean here?","options":["Gave back","Paid for","Threw away"],"answer":0,"why":"returned a library book 是把借來的書還回去。","evidence":"The next morning, I returned the book at the library desk."},{"type":"detail","q":"When did the writer start the new story?","options":["Before returning the old book","During the lunch break","On Monday evening"],"answer":1,"why":"最後一句交代午休讀新書的第一頁。","evidence":"I read the first page during my lunch break."}]},{"id":"a2-easy-food-budget","level":"A2","band":"easy","title":"Lunch with a Small Budget","topic":"午餐預算","words":107,"paras":["Yesterday, my friend Rui and I bought lunch near school. We had one hundred dollars each. A rice meal cost seventy dollars. A bowl of noodles cost sixty. Rui chose the rice meal. I bought noodles and a twenty-dollar egg. We both drank water from our own bottles.","We sat at a table outside the shop. Rui checked her money and had thirty dollars left. I had twenty dollars left. We wrote the prices in a notebook for our school money project. Our teacher asked each group to record one real meal. We showed her the notebook after lunch. She read it and asked about our choices."],"zh":"昨天睿和我到學校附近買午餐，每人有一百元。飯七十元、麵六十元，睿買飯，我買麵和二十元的蛋，都喝自己水壺的水。我們坐店外算餘額：她剩三十，我剩二十。老師要各組為理財作業記錄一餐真實花費，我們午餐後給她看筆記，她問了選餐理由。","qs":[{"type":"detail","q":"What did the writer buy?","options":["Noodles and an egg","Rice and juice","Two rice meals"],"answer":0,"why":"作者買麵加蛋；睿才選飯。","evidence":"I bought noodles and a twenty-dollar egg."},{"type":"detail","q":"How much did Rui spend?","options":["One hundred dollars","Seventy dollars","Eighty dollars"],"answer":1,"why":"睿買七十元的飯，帶一百元所以剩三十元。","evidence":"A rice meal cost seventy dollars."},{"type":"reference","q":"In \\"She read it\\", what is \\"it\\"?","options":["The menu on the wall","Rui’s bottle","The notebook"],"answer":2,"why":"他們把記錄給老師看，it 指那本筆記。","evidence":"She read it and asked about our choices."},{"type":"vocab","q":"Money \\"left\\" here is money…","options":["still available after buying lunch","lost on the table","borrowed from a friend"],"answer":0,"why":"left 是花費後剩下的錢，不是遺失的錢。","evidence":"Rui checked her money and had thirty dollars left."},{"type":"main","q":"Why did the students write down the meal prices?","options":["To apply for work at the shop","For a school money project","To tell the shop to change its menu"],"answer":1,"why":"記錄花費是老師指定的理財作業。"},{"type":"detail","q":"What did both students drink?","options":["Tea from the shop","Juice from school","Water from their own bottles"],"answer":2,"why":"兩人都喝自己水壺帶的水。","evidence":"We both drank water from our own bottles."}]},{"id":"a2-easy-train-platform","level":"A2","band":"easy","title":"The Train to Aunt’s Town","topic":"搭火車探親","words":103,"paras":["Last Saturday, I took the train to visit my aunt. I bought my ticket at the station machine. The ticket showed the departure time and the train number. I checked the number on the large board above the hall. My train left from platform three.","I walked to the platform and sat near a family with two children. A worker made an announcement, but I did not hear every word. I showed my ticket to him. He pointed to the correct train and smiled. I arrived in my aunt’s town at noon. She waited outside the station with two sandwiches for our lunch."],"zh":"上週六我搭火車去探望阿姨，在機器買票，核對票上的出發時間和車次，以及大廳看板，找到第三月台。我坐在一家人附近，聽不清工作人員廣播，便拿票請他確認。他指出正確列車。我中午抵達，阿姨在站外帶著兩份三明治等我吃午餐。","qs":[{"type":"detail","q":"How did the writer buy the ticket?","options":["From a worker on the train","From a machine","From the aunt"],"answer":1,"why":"作者在車站的售票機買票。","evidence":"I bought my ticket at the station machine."},{"type":"reference","q":"Who is \\"him\\" in \\"I showed my ticket to him\\"?","options":["One of the children","The aunt","The station worker"],"answer":2,"why":"前面剛提到的 worker 是作者詢問的人。","evidence":"I showed my ticket to him."},{"type":"vocab","q":"What is an \\"announcement\\" here?","options":["Spoken information for travelers","A kind of sandwich","A picture on a family’s phone"],"answer":0,"why":"announcement 是向乘客說明資訊的廣播。","evidence":"A worker made an announcement, but I did not hear every word."},{"type":"detail","q":"What did the writer do about the unclear information?","options":["Took a train without checking","Asked the worker using the ticket","Left the station immediately"],"answer":1,"why":"作者把票給工作人員看，得到正確列車的指引。","evidence":"I showed my ticket to him."},{"type":"main","q":"Which lesson fits the writer’s experience?","options":["Every train uses platform three.","Tickets are only sold at noon.","Asking for help can solve travel confusion."],"answer":2,"why":"作者沒完全聽懂便詢問，不能把這次月台和時間套用到所有列車。"},{"type":"detail","q":"What did the aunt bring?","options":["Two sandwiches","Two train tickets","A school notebook"],"answer":0,"why":"阿姨在站外帶著午餐三明治等候。","evidence":"She waited outside the station with two sandwiches for our lunch."}]},{"id":"a2-easy-poster-print","level":"A2","band":"easy","title":"The Missing Picture","topic":"小組報告","words":107,"paras":["Our nursing class held a poster activity last week. My group wrote about people at a hospital. I typed the names of six jobs on our computer. My partner added a picture beside each name. We saved the work and printed one copy in the library.","At first, the poster looked fine. Then we noticed a white space beside the word nurse. The picture was missing from the page. We checked the computer file and found the same empty space there. My partner added the picture again. Our second copy was complete. We put it on the classroom wall and explained the six jobs to another group."],"zh":"上週護理課做介紹醫院工作人員的海報。我打六個職業名稱，夥伴加圖，我們存檔後到圖書館印一份。起初看起來沒問題，卻發現 nurse 旁邊空白；電腦檔案也缺同一張圖。夥伴補圖重印，第二份完整了，我們貼在教室向另一組介紹六個職業。","qs":[{"type":"main","q":"What did the group have to correct?","options":["A wrong hospital address","The number of students in class","A missing picture in the poster"],"answer":2,"why":"問題是 nurse 旁缺圖，不是醫院地址或班級人數。"},{"type":"detail","q":"How many jobs did the poster describe?","options":["Six","Four","Two"],"answer":0,"why":"作者輸入六種工作的名稱。","evidence":"I typed the names of six jobs on our computer."},{"type":"detail","q":"Where did they first print the poster?","options":["In a shop near home","In the library","At a hospital"],"answer":1,"why":"他們在圖書館列印第一份。","evidence":"We saved the work and printed one copy in the library."},{"type":"reference","q":"What does \\"there\\" refer to in \\"the same empty space there\\"?","options":["The classroom wall","The hospital ward","The computer file"],"answer":2,"why":"他們在電腦檔案裡找到同樣的空白。","evidence":"We checked the computer file and found the same empty space there."},{"type":"vocab","q":"What does \\"complete\\" mean here?","options":["Having every needed part","Having no colors","Being the first copy"],"answer":0,"why":"第二份補齊需要的圖，所以 complete 是完整。","evidence":"Our second copy was complete."},{"type":"detail","q":"Who added the picture again?","options":["The other group","The writer’s partner","The librarian"],"answer":1,"why":"文章指定是夥伴重新補上圖片。","evidence":"My partner added the picture again."}]},{"id":"a2-easy-body-model","level":"A2","band":"easy","title":"Names on a Body Model","topic":"護理課初體驗","words":108,"paras":["Our first class in the nursing room was on Wednesday. There was a large body model on the teacher’s desk. She gave each pair of students six word cards. My partner Han read the words aloud. I put the cards beside the correct parts of the model.","At first, I put the card for the knee beside the elbow. Han looked at our textbook and noticed the mistake. We moved the card together. The teacher checked our work and explained the two words again. Then we drew a small picture of each part in our notebooks. The pictures helped me remember the names during our short class quiz."],"zh":"星期三第一次在護理教室上課，老師桌上有人體模型，每兩人拿到六張單字卡。韓念單字，我把卡放到部位旁邊。我起初把膝蓋卡放到手肘旁，韓查課本發現錯誤，我們一起調整。老師確認並再次解釋，後來我們在筆記畫各部位，幫助記住小考的單字。","qs":[{"type":"detail","q":"How many word cards did each pair get?","options":["Six","Two","Ten"],"answer":0,"why":"每一組拿到六張卡，兩個人是一組的人數。","evidence":"She gave each pair of students six word cards."},{"type":"detail","q":"What was the writer’s first mistake?","options":["Drawing a picture on the model","Putting the knee card beside the elbow","Reading every card too loudly"],"answer":1,"why":"作者把膝蓋單字卡放到手肘旁邊。","evidence":"At first, I put the card for the knee beside the elbow."},{"type":"reference","q":"Who is \\"She\\" in \\"She gave each pair\\"?","options":["Han","A patient","The teacher"],"answer":2,"why":"前一句介紹老師的桌子，She 接著指老師。","evidence":"She gave each pair of students six word cards."},{"type":"vocab","q":"What does \\"noticed\\" mean here?","options":["Saw and understood","Forgot completely","Covered with paper"],"answer":0,"why":"Han 查看課本後發現卡片放錯，noticed 是注意到、發現。","evidence":"Han looked at our textbook and noticed the mistake."},{"type":"main","q":"What helped the pair learn the new words?","options":["Using the model without any word cards","Checking a mistake and drawing the parts","Skipping the quiz and leaving early"],"answer":1,"why":"兩人核對錯誤、聽解釋並畫圖，加深對單字的印象。"},{"type":"detail","q":"Where did they check the correct names?","options":["On a bus timetable","On a hospital door","In their textbook"],"answer":2,"why":"Han 用課本核對，而非靠交通表或門牌。","evidence":"Han looked at our textbook and noticed the mistake."}]},{"id":"a2-easy-badminton-club","level":"A2","band":"easy","title":"My First Club Evening","topic":"參加校園社團","words":107,"paras":["I joined the school badminton club last Thursday. I arrived at the sports hall at six. Twelve students were there. Most students had their own rackets, but I did not have one. The club leader lent me a racket from a large box near the door.","My first partner was a student from another nursing class. Her name was May. We practiced short shots across the net. I missed the first three shots and felt embarrassed. May smiled and gave me time for another try. I hit the next shot across the net. We practiced for an hour and put the club racket back in its box."],"zh":"上週四我第一次參加學校羽球社，六點到體育館，共有十二位同學。我沒自己的球拍，社長從門邊箱子借我一支。搭檔 May 是另一班護生，我們練習短球。我前三球沒打中，有點不好意思，她微笑等我再試。我下一球過網，練一小時後把借來的球拍歸還箱中。","qs":[{"type":"main","q":"What is this story mostly about?","options":["A shopping trip for new rackets","A student’s first badminton club practice","A school contest for club leaders"],"answer":1,"why":"主線是作者第一次參加羽球社、借球拍並和 May 一起練習。"},{"type":"detail","q":"Where did the borrowed racket come from?","options":["May’s school bag","A shop across the road","A box near the door"],"answer":2,"why":"社長從門邊的大箱子拿球拍借作者。","evidence":"The club leader lent me a racket from a large box near the door."},{"type":"detail","q":"How did the writer feel after missing three shots?","options":["Embarrassed","Angry with May","Too tired to stand"],"answer":0,"why":"作者明說 felt embarrassed，是有點不好意思。","evidence":"I missed the first three shots and felt embarrassed."},{"type":"reference","q":"What does \\"its\\" refer to in the last sentence?","options":["The sports hall","The club racket","May’s textbook"],"answer":1,"why":"its box 指借用的社團球拍原本放的箱子。","evidence":"We practiced for an hour and put the club racket back in its box."},{"type":"vocab","q":"What does \\"lent\\" mean?","options":["Sold something at a high price","Threw something into a bin","Let someone use something for a time"],"answer":2,"why":"lend 的過去式 lent 是借給別人使用，之後要歸還。","evidence":"The club leader lent me a racket from a large box near the door."},{"type":"detail","q":"How long did the pair practice?","options":["For an hour","For three hours","For twelve minutes"],"answer":0,"why":"最後一句交代他們練了一小時。","evidence":"We practiced for an hour and put the club racket back in its box."}]},{"id":"a2-easy-family-album","level":"A2","band":"easy","title":"Grandma’s School Photo","topic":"家庭故事","words":113,"paras":["Our teacher gave us a family history project last month. I visited my grandmother on Sunday with a notebook. She opened an old photo album on the dining table. One photo showed her outside a small school. She was fifteen in that picture. Her school bag was on her back.","Grandma told me about her school days. She walked to school with two neighbors every morning. The walk took thirty minutes. Her favorite subject was music, and she sang in the school group. I wrote these details beside a copy of the photo. At home, I added a picture of my own school. The two pictures made a good start for my project."],"zh":"上個月老師出家庭歷史作業，我星期天帶筆記本拜訪阿嬤。她翻出餐桌上的舊相簿，有一張十五歲背書包站在學校外的照片。她以前每天和兩位鄰居步行半小時上學，最愛音樂，也參加學校合唱。我把細節寫在照片影本旁，回家再加上自己學校的照片，開始整理作業。","qs":[{"type":"detail","q":"How old was Grandma in the school photo?","options":["Thirteen","Thirty","Fifteen"],"answer":2,"why":"照片裡的阿嬤十五歲，三十分鐘是走路時間。","evidence":"She was fifteen in that picture."},{"type":"detail","q":"How did Grandma travel to school?","options":["She walked with neighbors.","She took a bus alone.","She rode a bicycle with her sister."],"answer":0,"why":"阿嬤每天與兩位鄰居步行上學。","evidence":"She walked to school with two neighbors every morning."},{"type":"reference","q":"What does \\"these details\\" include?","options":["The writer’s test scores","Grandma’s walk and favorite subject","The price of a new school bag"],"answer":1,"why":"these details 指剛談到的上學路程和最喜歡的科目等資訊。","evidence":"I wrote these details beside a copy of the photo."},{"type":"vocab","q":"What is an \\"album\\" in the passage?","options":["A bag for school books","A list of homework dates","A book for photographs"],"answer":2,"why":"相簿裡有阿嬤以前的照片，album 在此是相簿。","evidence":"She opened an old photo album on the dining table."},{"type":"heading","q":"Which heading fits the second paragraph?","options":["Grandma’s School Life","Lunch at Grandma’s House","Shopping for a New Camera"],"answer":0,"why":"第二段集中描述阿嬤如何上學、喜歡什麼科目。"},{"type":"detail","q":"What did the writer add at home?","options":["A new photo of the neighbors","A picture of the writer’s school","A ticket for Grandma’s bus"],"answer":1,"why":"作者回家補上一張自己學校的照片。","evidence":"At home, I added a picture of my own school."}]},{"id":"a2-easy-volunteer-walk","level":"A2","band":"easy","title":"A Walk for New Volunteers","topic":"醫院志工導覽","words":110,"paras":["Six students from our nursing school visited a hospital on Monday. We joined a short introduction for new volunteers. A worker met us at the main entrance and gave us a map. She marked the information desk with a red circle. Our volunteer work was there, near the front door.","We followed her around the public areas of the building. She showed us the toilets, the lifts and a small cafe. We did not enter any patient rooms during the visit. At the end, she asked us about the location of the lifts. I found them on my map and pointed to the left. She nodded and thanked our group."],"zh":"星期一六位護生到醫院參加新志工說明。工作人員在大門給我們地圖，用紅圈標出我們之後服務的入口附近服務台。她帶我們認識公共區域的廁所、電梯和咖啡店，沒有進病房。最後她問電梯在哪裡，我看地圖指左邊，她點頭謝謝大家。","qs":[{"type":"main","q":"What was the main purpose of the visit?","options":["Learning the hospital’s public locations","Giving medicine to patients","Buying food for a school party"],"answer":0,"why":"這次是認識志工服務區和公共設施，沒有進行臨床工作。"},{"type":"detail","q":"What did the red circle mark?","options":["The cafe menu","The information desk","A patient’s room"],"answer":1,"why":"工作人員用紅圈標出服務台。","evidence":"She marked the information desk with a red circle."},{"type":"detail","q":"Which places did the group not enter?","options":["The public cafe area","The main entrance","Patient rooms"],"answer":2,"why":"文章明確說這次導覽沒有進入病房。","evidence":"We did not enter any patient rooms during the visit."},{"type":"reference","q":"What does \\"them\\" refer to in \\"I found them\\"?","options":["The lifts","The six students","The maps"],"answer":0,"why":"前一句問電梯在哪，them 就是那些電梯。","evidence":"I found them on my map and pointed to the left."},{"type":"vocab","q":"What does \\"nodded\\" mean here?","options":["Walked away without looking","Moved her head to show agreement","Wrote a new map for everyone"],"answer":1,"why":"作者指出電梯後，她點頭表示認同。","evidence":"She nodded and thanked our group."},{"type":"detail","q":"Where was the group’s volunteer work?","options":["Inside the patient rooms","Behind the hospital kitchen","Near the front door"],"answer":2,"why":"文章將志工工作地點放在前門附近的服務台。","evidence":"Our volunteer work was there, near the front door."}]},{"id":"a2-easy-phone-break","level":"A2","band":"easy","title":"One Hour without My Phone","topic":"讀書習慣","words":107,"paras":["I studied for a vocabulary quiz on Tuesday evening. At first, my phone was beside my notebook. I checked a message after every few words. After twenty minutes, I remembered only four new words. I felt unhappy with my progress.","I put the phone inside my desk drawer and closed it. Then I read each word aloud and wrote a short sentence. I worked for one hour without another phone break. My roommate tested me with ten words from the list. I remembered nine of them. I opened the drawer after our practice and answered my messages. This small change made my study time useful that evening."],"zh":"星期二晚上我準備單字小考，手機放在筆記旁，每看幾個字就查訊息，二十分鐘只記住四個字，有些失望。我把手機收進抽屜，改成大聲念字並各寫一句，專心讀一小時。室友抽考十字，我記住九個；練習完才回訊息。那晚小小改變讓讀書更有用。","qs":[{"type":"detail","q":"How many words did the writer remember after the first twenty minutes?","options":["Ten","Four","Nine"],"answer":1,"why":"最初二十分鐘只記住四個字，九個是之後抽考的結果。","evidence":"After twenty minutes, I remembered only four new words."},{"type":"detail","q":"Where did the writer put the phone?","options":["In the roommate’s bag","Under a pillow","In a desk drawer"],"answer":2,"why":"作者把手機放進書桌抽屜。","evidence":"I put the phone inside my desk drawer and closed it."},{"type":"reference","q":"What does \\"them\\" refer to in \\"nine of them\\"?","options":["The ten test words","The phone messages","The writer’s classmates"],"answer":0,"why":"室友用十個字抽考，作者記得其中九個字。","evidence":"I remembered nine of them."},{"type":"vocab","q":"What does \\"progress\\" mean here?","options":["The time of the evening meal","Improvement in learning","The color of the notebook"],"answer":1,"why":"作者在意記住多少單字，progress 指學習上的進步。","evidence":"I felt unhappy with my progress."},{"type":"main","q":"What change helped the writer that evening?","options":["Answering every message immediately","Reading only four words aloud","Putting the phone away during study"],"answer":2,"why":"先收起手機，再念字造句，讓那晚練習有較好的結果。"},{"type":"detail","q":"Who tested the writer at the end?","options":["The roommate","The English teacher","A younger brother"],"answer":0,"why":"文章說室友從字表選十個字來抽考。","evidence":"My roommate tested me with ten words from the list."}]},{"id":"a2-easy-school-sale","level":"A2","band":"easy","title":"Clothes for the School Sale","topic":"校園二手義賣","words":110,"paras":["Our class collected clothes for a school sale last month. I brought two clean shirts from home. Both shirts were small for me, but they were still in good condition. My friend Wen brought a blue jacket. We put the clothes on a long table in our classroom.","Four students checked the sizes on the labels. Another group wrote simple price cards. I folded the shirts and placed them beside other small clothes. On the sale day, a first year student bought one of my shirts. She liked its bright green color. Our class counted the money at the end of the day. We used it for new library books."],"zh":"上個月班上為校園二手義賣募集衣物。我帶兩件乾淨但已太小的襯衫，文帶一件藍外套，都仍完好。四位同學查標籤尺寸，另一組寫價牌，我摺衣放到小尺寸區。義賣當天一位一年級同學買走綠襯衫，喜歡它的鮮豔顏色。大家最後點錢，拿來添購圖書館的書。","qs":[{"type":"detail","q":"Why did the writer bring the shirts?","options":["They were dirty and torn.","They belonged to the library.","They were too small but still good."],"answer":2,"why":"襯衫已太小，但仍乾淨完好，適合義賣。","evidence":"Both shirts were small for me, but they were still in good condition."},{"type":"detail","q":"What did Wen bring?","options":["A blue jacket","A green school bag","Four new books"],"answer":0,"why":"文帶的是藍色外套，不是作者的綠襯衫。","evidence":"My friend Wen brought a blue jacket."},{"type":"reference","q":"What does \\"it\\" mean in the last sentence?","options":["The long classroom table","The money from the sale","The green shirt"],"answer":1,"why":"前一句說清點款項，it 指義賣所得的錢。","evidence":"We used it for new library books."},{"type":"vocab","q":"What does \\"condition\\" mean in \\"good condition\\"?","options":["The name of the owner","The number on the price card","The state of the clothes"],"answer":2,"why":"good condition 表示衣物保存狀況良好。","evidence":"Both shirts were small for me, but they were still in good condition."},{"type":"main","q":"What did the class do?","options":["Sold old clothes to buy library books","Bought new clothes for every student","Sold library books for new sports equipment"],"answer":0,"why":"同學整理舊衣義賣，最後把所得用在圖書館書籍。"},{"type":"detail","q":"What did four students check?","options":["The books’ titles","The clothing sizes","The buyers’ addresses"],"answer":1,"why":"四位同學查看衣物標籤上的尺寸。","evidence":"Four students checked the sizes on the labels."}]},{"id":"a2-mid-study-room","level":"A2","band":"mid","title":"Room A or Room B?","topic":"討論室選擇","words":124,"paras":["Our English group needs a room for next Friday. There are five students in the group. We will practice a short talk about nursing school. The library has two rooms for small groups. Room A is beside the main desk. It has four chairs and a large screen. It is closer to the entrance than room B.","Room B is at the end of the hall. It has six chairs and a small whiteboard. It has no screen, but our talk only needs paper pictures. We are going to choose room B because everyone can have a seat. It is also quieter than room A. I will book it this afternoon. Each student will bring one picture and a few words about school life."],"zh":"五位同學下週五要練習介紹護理學校的英文短講。圖書館 A 室近入口、有大螢幕但只有四張椅子；B 室在走廊底，有六張椅子和白板，沒有螢幕但較安靜。短講只需紙本圖片，所以大家選 B 室，讓每人都有座位。作者下午訂房，每人準備一張圖及簡短內容。","qs":[{"type":"detail","q":"How many students will practice together?","options":["Five","Four","Six"],"answer":0,"why":"小組共有五人；四和六分別是兩間房的椅子數。","evidence":"There are five students in the group."},{"type":"detail","q":"What does room B have instead of a large screen?","options":["A television","A small whiteboard","A piano"],"answer":1,"why":"B 室有小白板，沒有螢幕。","evidence":"It has six chairs and a small whiteboard."},{"type":"reference","q":"What does \\"it\\" mean in \\"I will book it\\"?","options":["The library’s main desk","A large screen","Room B"],"answer":2,"why":"作者選定 B 室，接著說要預訂它。","evidence":"I will book it this afternoon."},{"type":"vocab","q":"What does \\"book\\" mean in this passage?","options":["Arrange to use a room","Read a story aloud","Buy a new textbook"],"answer":0,"why":"book 在這裡是動詞，意思是預訂。","evidence":"I will book it this afternoon."},{"type":"evidence","q":"Which sentence best explains why five students can use room B?","options":["It is closer to the entrance than room B.","It has six chairs and a small whiteboard.","The library has two rooms for small groups."],"answer":1,"why":"B 室有六張椅子，可容納五人；位置和圖書館用途不能證明座位足夠。","evidence":"It has six chairs and a small whiteboard."},{"type":"main","q":"Why is room B a good choice for this group?","options":["It has the biggest screen in the library.","It is next to the entrance and the main desk.","It has enough seats and fits their simple talk."],"answer":2,"why":"他們只需紙本圖，B 室座位夠又安靜；大螢幕和入口位置不是選它的原因。"}]},{"id":"a2-mid-museum-bus","level":"A2","band":"mid","title":"Two Buses for a Class Trip","topic":"校外參訪交通","words":130,"paras":["Our class is going to visit a health museum on Saturday. The visit starts at ten in the morning. We can take bus six or bus nine from the station. Bus six leaves at eight thirty and arrives at nine fifteen. Bus nine leaves at nine and arrives at nine forty. The later bus is faster, but it is usually more crowded.","Both buses cost thirty dollars for each student. We will take bus six because our class has twenty people. We will have time for a snack near the museum. Our teacher will meet us at the museum entrance at nine forty. I will carry the class list in my bag. The return trip will be at two, and we will use the same bus stop outside the museum."],"zh":"班上星期六十點要參觀健康博物館。有六號與九號公車可搭：六號八點半出發、九點十五分到；九號九點出發、九點四十分到，較快但通常更擁擠。兩班票價都是三十元。全班二十人選六號，提早到能吃點東西，再於九點四十分到入口跟老師集合。作者帶名單，下午兩點從館外原站搭車回去。","qs":[{"type":"main","q":"Why will the class take the earlier bus?","options":["It arrives after the museum visit begins.","It is usually less crowded for their large group.","It costs less than the later bus."],"answer":1,"why":"早班較不擁擠，適合二十人；兩班票價相同。"},{"type":"detail","q":"What time will the teacher meet the class?","options":["At eight thirty","At ten thirty","At nine forty"],"answer":2,"why":"老師約九點四十分在入口碰面。","evidence":"Our teacher will meet us at the museum entrance at nine forty."},{"type":"reference","q":"What does \\"it\\" refer to in \\"it is usually more crowded\\"?","options":["The later bus","The museum entrance","The class list"],"answer":0,"why":"it 指前面提到較晚出發的那班公車。","evidence":"The later bus is faster, but it is usually more crowded."},{"type":"vocab","q":"What does \\"crowded\\" mean here?","options":["Very low in price","Full of people","Far from the station"],"answer":1,"why":"crowded 形容車上人多、擁擠，不是在講票價。","evidence":"The later bus is faster, but it is usually more crowded."},{"type":"evidence","q":"Which sentence shows that price is not the reason for the bus choice?","options":["Bus six leaves at eight thirty and arrives at nine fifteen.","The return trip will be at two, and we will use the same bus stop outside the museum.","Both buses cost thirty dollars for each student."],"answer":2,"why":"兩班每位學生都收三十元，所以費用相同。","evidence":"Both buses cost thirty dollars for each student."},{"type":"detail","q":"Where will the class take the bus home?","options":["At the same stop outside the museum","Inside the museum cafe","At a different train station"],"answer":0,"why":"最後一句說回程使用博物館外同一個站牌。","evidence":"The return trip will be at two, and we will use the same bus stop outside the museum."}]},{"id":"a2-mid-room-plan","level":"A2","band":"mid","title":"A New Plan for Our Room","topic":"宿舍空間","words":130,"paras":["My roommate and I are going to move our furniture on Sunday. Our room is small, and the space near the door is very narrow. My desk stands beside her bed. Her chair sometimes blocks the path to our clothes shelf. We drew two room plans on a sheet of paper last night.","In the first plan, both desks are beside the window. That area is brighter in the daytime, but the desks are too wide for the wall. In the second plan, one desk is by the window and the other is near the back wall. This plan leaves a wider path from the door. We will choose the second plan. First, we will put our books in boxes. Our friend will help with the furniture on Sunday afternoon."],"zh":"室友和我星期天打算移動家具。房間小，門口很窄，椅子有時擋住走到衣櫃的路，昨晚畫了兩種配置。第一種把兩桌放窗邊，白天較亮，但牆面不夠寬。第二種一桌窗邊、一桌後牆，可留較寬通道，所以選第二種。我們先把書裝箱，朋友週日下午幫忙搬家具。","qs":[{"type":"detail","q":"What sometimes blocks the path?","options":["A box from their friend","The window curtain","The roommate’s chair"],"answer":2,"why":"文章說室友的椅子有時擋住往衣物架的路。","evidence":"Her chair sometimes blocks the path to our clothes shelf."},{"type":"detail","q":"Why will they not use the first plan?","options":["The two desks are too wide for the wall.","The window area is too dark.","They have only one desk."],"answer":0,"why":"兩桌加起來對那面牆太寬，不是窗邊太暗。","evidence":"That area is brighter in the daytime, but the desks are too wide for the wall."},{"type":"reference","q":"What does \\"This plan\\" refer to?","options":["The first room plan","The second room plan","The plan for Sunday lunch"],"answer":1,"why":"This plan 緊接在第二種配置後，指那個安排。","evidence":"This plan leaves a wider path from the door."},{"type":"vocab","q":"What does \\"narrow\\" mean?","options":["Not clean","Not quiet","Not wide"],"answer":2,"why":"narrow 是狹窄，後面 wider path 也提供對照。","evidence":"Our room is small, and the space near the door is very narrow."},{"type":"evidence","q":"Which sentence explains the main benefit of the second plan?","options":["This plan leaves a wider path from the door.","We drew two room plans on a sheet of paper last night.","First, we will put our books in boxes."],"answer":0,"why":"第二種配置讓門口通道更寬，這是它的主要好處。","evidence":"This plan leaves a wider path from the door."},{"type":"main","q":"What are the roommates trying to improve?","options":["The price of new furniture","The space for moving around their room","The number of people in the dorm"],"answer":1,"why":"兩人重新安排現有家具，目的是讓房內通道更好走。"}]},{"id":"a2-mid-english-club","level":"A2","band":"mid","title":"A Short Talk at English Club","topic":"英文練習計畫","words":129,"paras":["I will give a short talk at our English club next month. Last year, I only listened during club meetings. This time, I am going to speak about my nursing school day. My talk will have three parts: classes, lunch and dorm life. I will use six photos from my phone.","My friend Tina gave a talk last month. Her topic was her family’s shop. She spoke slowly and used simple words. Her talk was easier to follow than the long video in our last meeting. I will practice with her every Tuesday. She will hold up a card at the end of five minutes. That is the time limit for each talk. I feel nervous, but I am also excited about sharing my own story with the group."],"zh":"我下個月要在英文社短講，去年只聽大家說，這次打算用六張照片介紹護校的一天，分上課、午餐和宿舍。朋友 Tina 上個月講家裡的店，講慢、用簡單字，比社團上次的長影片容易懂。我每週二和她練習，她在五分鐘到時舉牌，提醒每人時限。我緊張也期待分享自己的故事。","qs":[{"type":"main","q":"What is the writer preparing for?","options":["A five minute talk about nursing school life","A long video about Tina’s family","An exam about hospital medicines"],"answer":0,"why":"整篇是準備校園生活短講，Tina 的故事是參考經驗。"},{"type":"detail","q":"How many parts will the talk have?","options":["Six","Three","Five"],"answer":1,"why":"內容有上課、午餐、宿舍三部分，六是照片張數。","evidence":"My talk will have three parts: classes, lunch and dorm life."},{"type":"reference","q":"What does \\"That\\" mean in \\"That is the time limit\\"?","options":["Every Tuesday","The next month","Five minutes"],"answer":2,"why":"前一句的五分鐘就是每人短講的時限。","evidence":"That is the time limit for each talk."},{"type":"vocab","q":"What is a \\"time limit\\"?","options":["The longest allowed time","The first day of a month","The number of weekly meetings"],"answer":0,"why":"time limit 是允許使用的時間上限。","evidence":"That is the time limit for each talk."},{"type":"evidence","q":"Which sentence shows Tina’s clear speaking style?","options":["She will hold up a card at the end of five minutes.","She spoke slowly and used simple words.","Her topic was her family’s shop."],"answer":1,"why":"說得慢且用簡單字，直接說明 Tina 的表達方式。","evidence":"She spoke slowly and used simple words."},{"type":"detail","q":"When will the writer practice with Tina?","options":["Every Friday","Only on the day of the talk","Every Tuesday"],"answer":2,"why":"文章安排每週二一起練習。","evidence":"I will practice with her every Tuesday."}]},{"id":"a2-mid-handwashing-poster","level":"A2","band":"mid","title":"A Clear Handwashing Poster","topic":"校園洗手衛教","words":131,"paras":["Our nursing class will make a handwashing poster for the school dining room. The poster is about washing hands at home and school. We are going to use large pictures with short sentences. They will be easier to read than a page of tiny words.","The pictures will show each part of the process. First, we wet our hands under clean running water. We add soap and rub our palms, the backs of our hands, between our fingers and under our nails. We scrub for at least twenty seconds. Then we rinse well under clean running water. Finally, we dry our hands with a clean towel or an air dryer.","Our teacher will check the words and pictures on Friday. We will put the finished poster beside the dining room sink."],"zh":"護理班要在餐廳洗手台旁貼洗手海報，介紹家中和學校的洗手方式，用大圖與短句方便閱讀。先用乾淨流動水濕手，再加肥皂搓揉手掌、手背、指縫和指甲下方，至少搓二十秒；用乾淨流動水沖淨，再以乾淨毛巾或烘手機弄乾。老師週五確認內容後張貼。","qs":[{"type":"main","q":"What is the class preparing?","options":["A plan for new kitchen furniture","A clear poster about washing hands","A list of meals for the school dining room"],"answer":1,"why":"整篇說明如何製作清楚的洗手海報，以及海報裡的洗手步驟。"},{"type":"detail","q":"How long does the poster say to scrub?","options":["Exactly five seconds","Until the towel is wet","At least twenty seconds"],"answer":2,"why":"至少搓洗二十秒指搓洗這個步驟，不是所有步驟總共二十秒。","evidence":"We scrub for at least twenty seconds."},{"type":"reference","q":"What does \\"They\\" refer to in the first paragraph?","options":["Large pictures with short sentences","The students’ dining tables","The school’s small towels"],"answer":0,"why":"They 接在大圖搭配短句的句子後，指這種呈現內容。","evidence":"They will be easier to read than a page of tiny words."},{"type":"vocab","q":"What does \\"rinse\\" mean here?","options":["Cover hands with a towel","Wash the soap away with water","Add more soap to dry hands"],"answer":1,"why":"rinse 是用水沖洗，這裡在搓洗後把肥皂沖乾淨。","evidence":"Then we rinse well under clean running water."},{"type":"evidence","q":"Which sentence shows a choice of two ways to dry hands?","options":["First, we wet our hands under clean running water.","We will put the finished poster beside the dining room sink.","Finally, we dry our hands with a clean towel or an air dryer."],"answer":2,"why":"最後可用乾淨毛巾，也可用烘手機，是兩種擦乾／弄乾方式。","evidence":"Finally, we dry our hands with a clean towel or an air dryer."},{"type":"detail","q":"Where will the poster go?","options":["Beside the dining room sink","On the classroom ceiling","Inside a student’s bag"],"answer":0,"why":"最後一句寫明張貼在餐廳洗手台旁。","evidence":"We will put the finished poster beside the dining room sink."}]},{"id":"a2-mid-health-talk","level":"A2","band":"mid","title":"A Talk in Two Languages","topic":"校園健康活動","words":136,"paras":["Our school is going to hold a health talk next Wednesday. A nurse will speak in the main hall at one. The talk will be in Chinese, with short English phrases on the screen. Nursing students can hear the ideas and learn some useful English at the same time.","The school first planned the talk for a small classroom. Now more than eighty students want to attend. The main hall is larger and has more seats. There will be a desk near its door for question cards. Students can write a question during the talk and put it in a box. The nurse will answer some of the questions at the end. I will arrive with my classmate at twelve forty. We want seats near the screen because the English words are important for our practice."],"zh":"學校下週三一點辦健康講座，由護理師中文說明，螢幕搭配簡短英文，讓護生同時練習英語。原訂小教室，因超過八十人想參加，改到座位更多的大廳。門邊放提問卡，大家寫好投入盒中，護理師最後回答部分問題。我和同學十二點四十分到，想坐近螢幕看清英文。","qs":[{"type":"detail","q":"Why did the school choose the main hall?","options":["The classroom has no door.","The nurse cannot speak Chinese.","More than eighty students want to attend."],"answer":2,"why":"參加人數增加，大廳較大且座位較多。","evidence":"Now more than eighty students want to attend."},{"type":"detail","q":"How can students send a question to the nurse?","options":["Write it on a card and put it in a box","Call the nurse’s home during the talk","Write it on the main screen"],"answer":0,"why":"現場提供提問卡，寫完放入盒子。","evidence":"Students can write a question during the talk and put it in a box."},{"type":"reference","q":"What does \\"its\\" mean in \\"near its door\\"?","options":["The box’s","The main hall’s","The small classroom’s"],"answer":1,"why":"談話地點已改到大廳，its door 是大廳的門。","evidence":"There will be a desk near its door for question cards."},{"type":"vocab","q":"What does \\"attend\\" mean here?","options":["Choose the next speaker","Translate every word","Go to the event"],"answer":2,"why":"attend a talk 是到場參加講座。","evidence":"Now more than eighty students want to attend."},{"type":"evidence","q":"Which sentence explains the writer’s choice of seats?","options":["We want seats near the screen because the English words are important for our practice.","A nurse will speak in the main hall at one.","The nurse will answer some of the questions at the end."],"answer":0,"why":"最後一句明說想靠近螢幕是為了練習英文。","evidence":"We want seats near the screen because the English words are important for our practice."},{"type":"main","q":"What is special about this school talk?","options":["It teaches students only through an English movie.","It combines health information with English practice.","Every student will speak for an hour."],"answer":1,"why":"講座以中文講解並搭配英文短語，將健康內容和英語練習結合。"}]},{"id":"a2-mid-appointment-cards","level":"A2","band":"mid","title":"Two Appointment Cards","topic":"實習英文練習","words":130,"paras":["Our nursing teacher is planning a speaking activity for Friday. Each pair will use an appointment card in English. One student will be the visitor, and the other will work at an imaginary clinic desk. They will practice questions about times and places.","The teacher showed us two possible cards today. The first card has the visitor’s name, the room number and a date. The second card has all that information plus the appointment time and the building name. It is more useful for our practice because the visitor can ask about several details. The teacher will print the second card for everyone.","My partner and I are going to practice slowly. We will check each answer against the card. The activity is about clear communication, not real patient care."],"zh":"護理老師安排週五英文角色練習，每組一人當訪客、一人當模擬診所櫃台，練習詢問時間和地點。第一種卡只有姓名、診間號碼和日期；第二種多了預約時間、棟別，能練習更多細節，所以老師選第二種。我和搭檔打算慢慢練、逐一核對答案。這是溝通演練，不涉及真實病人照護。","qs":[{"type":"main","q":"What is the main goal of the activity?","options":["Practicing clear questions and answers","Choosing medicine for real patients","Measuring everyone’s body temperature"],"answer":0,"why":"最後一句將活動目標定在清楚溝通，不是真實醫療處置。"},{"type":"detail","q":"What extra information is on the second card?","options":["The clinic’s medicine prices","The time and building name","The visitor’s favorite food"],"answer":1,"why":"第二張比第一張多預約時間與建築名稱。","evidence":"The second card has all that information plus the appointment time and the building name."},{"type":"reference","q":"What does \\"It\\" refer to in \\"It is more useful\\"?","options":["The imaginary clinic desk","The teacher’s phone","The second card"],"answer":2,"why":"前一句介紹第二張卡，It 接著描述它較適合練習。","evidence":"It is more useful for our practice because the visitor can ask about several details."},{"type":"vocab","q":"What does \\"imaginary\\" mean here?","options":["Used for practice and not real","Closed for the whole month","Too far away to visit"],"answer":0,"why":"imaginary clinic 是設定出來的模擬診所，不是真實櫃台。","evidence":"One student will be the visitor, and the other will work at an imaginary clinic desk."},{"type":"evidence","q":"Which sentence shows that the pair will check accuracy?","options":["The teacher showed us two possible cards today.","We will check each answer against the card.","Our nursing teacher is planning a speaking activity for Friday."],"answer":1,"why":"兩人把每個答案和卡片核對，就是檢查資訊是否正確。","evidence":"We will check each answer against the card."},{"type":"detail","q":"When will the class do the activity?","options":["On Monday","Next month","On Friday"],"answer":2,"why":"開頭說老師正安排週五的口說活動。","evidence":"Our nursing teacher is planning a speaking activity for Friday."}]},{"id":"a2-mid-volunteer-message","level":"A2","band":"mid","title":"A Message to the Volunteer Office","topic":"實習時間安排","words":133,"paras":["Dear volunteer team, I am a nursing student at South College. Thank you for the information about Saturday work at the hospital’s information desk. I am going to join the afternoon group. The morning group starts at eight and finishes at eleven. I have an English class from nine to eleven, so those times are not possible for me.","The afternoon group works from one to four. That schedule fits my class. The hospital is farther from my school than from my dorm, but there is a direct bus from school. I will take it after lunch. My first visit will be next Saturday. I will bring my student card and a notebook. Your message asks new volunteers to wear plain dark trousers. I have a suitable pair. Thank you for your help."],"zh":"親愛的志工團隊：我是南方學院的護生，想參加週六醫院服務台下午班。早班八點到十一點，與我九點到十一點的英文課衝突；下午一點到四點適合。醫院距學校比距宿舍遠，但學校有直達公車，我午餐後搭車。下週六第一次到，會帶學生證和筆記本，也已備好通知要求的素色深長褲。謝謝協助。","qs":[{"type":"detail","q":"Why can the student not join the morning group?","options":["The student works at the library until four.","The student has an English class.","The hospital opens only at noon."],"answer":1,"why":"英文課九點到十一點，和八點到十一點的早班重疊。","evidence":"I have an English class from nine to eleven, so those times are not possible for me."},{"type":"detail","q":"How long is the afternoon volunteer period?","options":["Two hours","Four hours","Three hours"],"answer":2,"why":"下午一點到四點共三小時。","evidence":"The afternoon group works from one to four."},{"type":"reference","q":"What does \\"it\\" refer to in \\"I will take it\\"?","options":["The direct bus","The dark trousers","The student card"],"answer":0,"why":"上一句提到從學校出發的直達公車，it 指該班公車。","evidence":"I will take it after lunch."},{"type":"vocab","q":"What does \\"suitable\\" mean here?","options":["Too small to wear","Right for the stated need","More expensive than all others"],"answer":1,"why":"通知要求素色深長褲，suitable 表示符合要求、合適。","evidence":"I have a suitable pair."},{"type":"evidence","q":"Which sentence shows the student already has the requested clothing?","options":["My first visit will be next Saturday.","I will bring my student card and a notebook.","I have a suitable pair."],"answer":2,"why":"I have a suitable pair 表示已有合適的褲子，不只說要帶學生證。","evidence":"I have a suitable pair."},{"type":"heading","q":"Which subject line fits this message?","options":["Joining the Saturday Afternoon Group","Changing Every Volunteer’s Uniform","Canceling All English Classes"],"answer":0,"why":"信件主旨是選擇週六下午志工班並說明準備事項。"}]},{"id":"a2-hard-visit-notebook","level":"A2","band":"hard","title":"A Notebook for the Clinic Visit","topic":"陪家人準備就醫","words":146,"paras":["My mother has a clinic appointment on Thursday, and I will go with her. She sometimes forgets her questions during a visit. This week, she has written two questions in a small notebook. She has also made a list of her medicines and vitamins. We will bring both items to the clinic.","Before we leave home, we will check the appointment time together. At the clinic, my mother will explain her concerns in her own words. I will listen and take notes with her permission. If we do not understand an instruction, we will ask the doctor for an explanation. We will not guess its meaning.","After the visit, we will read our notes together. My mother wants to remember the next steps. The notebook has space for new questions too. Our plan gives her a way to prepare and a way to review the visit."],"zh":"媽媽星期四要看診，我會陪她去。她有時忘記要問什麼，這次先寫兩個問題，也列出藥物和維他命清單。出門前一起確認時間；看診時讓媽媽自己說明關心的事，經她同意我再幫忙記錄。不懂指示就請醫師解釋，不自己猜。回家後一起看筆記，記住下一步，也留空間記新問題。","qs":[{"type":"detail","q":"Why will the family bring both a notebook and a medicine list?","options":["To ask the doctor to write a school report","To avoid speaking during the whole visit","To remember questions and share medicine information"],"answer":2,"why":"前段一項準備記錄問題，另一項列藥物；合起來兼顧提問與分享用藥資訊。","evidence":"She has also made a list of her medicines and vitamins."},{"type":"detail","q":"How will the notebook help at two different times?","options":["It holds questions before the visit and notes for review afterward.","It replaces the appointment card and pays the clinic bill.","It gives a diagnosis at home and chooses medicine later."],"answer":0,"why":"前段先寫問題，後段又一起讀看診筆記，需要整合兩段線索。","evidence":"After the visit, we will read our notes together."},{"type":"reference","q":"What does \\"its\\" refer to in \\"its meaning\\"?","options":["The notebook’s color","An instruction","The appointment date"],"answer":1,"why":"前一句談聽不懂的指示，its meaning 就是該指示的意思。","evidence":"We will not guess its meaning."},{"type":"vocab","q":"What does \\"review\\" mean in the last sentence?","options":["Change the doctor’s name","Make every question shorter","Look at information again"],"answer":2,"why":"看診後再讀筆記，review 在此是再次查看、複習資訊。","evidence":"Our plan gives her a way to prepare and a way to review the visit."},{"type":"evidence","q":"Which sentence shows how they will deal with unclear information?","options":["If we do not understand an instruction, we will ask the doctor for an explanation.","Before we leave home, we will check the appointment time together.","The notebook has space for new questions too."],"answer":0,"why":"聽不懂就請醫師解釋，這句直接說明處理方式。","evidence":"If we do not understand an instruction, we will ask the doctor for an explanation."},{"type":"main","q":"What is the passage mainly about?","options":["Teaching the writer to make medical decisions alone","Preparing for a visit and understanding the next steps","Choosing a clinic by comparing its prices"],"answer":1,"why":"文章貫穿就診前準備、現場詢問及事後複習，沒有自行診斷或決定治療。"}]},{"id":"b1-e-orientation-route","level":"B1","band":"easy","title":"A Practice Trip Before Placement","topic":"實習準備","words":168,"paras":["Mina was starting her first hospital placement on Monday, so she tried the journey on Saturday. The bus stopped near the hospital, but the student entrance was on the other side of the building. She followed a visitor sign and reached the wrong door.","A member of staff showed her the student entrance on a map. Mina wrote the correct street name beside the meeting time in her notebook. She also took a photo of the public entrance sign, without including any patients or staff.","At home, she checked the bus timetable again. The early bus did not run on Sundays, but it did run on weekdays. She chose that bus for Monday and planned extra time for the walk. Her roommate suggested sharing a taxi, but Mina wanted to know a route she could use every week.","On Monday she arrived before her teacher. The practice trip did not remove all her nerves, but it left her with one less problem to solve on a busy morning."],"zh":"Mina 下週一要第一次到醫院實習，所以週六先試走路線。公車站離醫院不遠，但學生入口在建築另一側，她一開始走錯門。工作人員在地圖上指出入口，她記下街名，也只拍了沒有病人或工作人員的公共入口標示。回家查班表後，她選了平日有開的早班公車，並預留步行時間。室友提議搭計程車，但她想熟悉每週都能使用的路線。週一她比老師早到，仍然緊張，但不用再煩惱怎麼找路。","qs":[{"type":"main","q":"What is the main point of the story?","options":["Trying a journey early can make a new placement easier.","Students should always travel by taxi.","Hospital visitors must use the student entrance."],"answer":0,"why":"文章從試走路線、發現問題，到週一順利抵達，重點是事先準備的幫助。"},{"type":"detail","q":"Why did Mina reach the wrong door?","options":["Her teacher gave her the wrong time.","She followed a visitor sign.","The bus driver changed the route."],"answer":1,"why":"第一段明確說她跟著訪客標示走。","evidence":"She followed a visitor sign and reached the wrong door."},{"type":"reference","q":"What does \\"that bus\\" in paragraph 3 refer to?","options":["The taxi her roommate suggested","A bus that runs only on Sundays","The early bus that runs on weekdays"],"answer":2,"why":"that bus 承接前一句提到的早班公車。","evidence":"The early bus did not run on Sundays, but it did run on weekdays."},{"type":"vocab","q":"What does \\"route\\" mean in this story?","options":["A way of travelling from one place to another","A place to buy a ticket","A list of hospital rules"],"answer":0,"why":"她要找的是每週可使用的交通路線。","evidence":"Her roommate suggested sharing a taxi, but Mina wanted to know a route she could use every week."},{"type":"evidence","q":"Which conclusion is supported by the final sentence?","options":["Mina no longer needed her teacher.","Mina still felt nervous after planning the journey.","Mina solved every problem at the hospital."],"answer":1,"why":"最後一句說行前試走沒有消除所有緊張，只少了一個問題。","evidence":"The practice trip did not remove all her nerves, but it left her with one less problem to solve on a busy morning."},{"type":"detail","q":"What did Mina write next to the meeting time?","options":["Her roommate's phone number","The taxi fare","The correct street name"],"answer":2,"why":"第二段說她把正確街名寫在集合時間旁邊。","evidence":"Mina wrote the correct street name beside the meeting time in her notebook."},{"type":"evidence","q":"Why was a regular bus route useful to Mina?","options":["She expected to make the journey repeatedly.","She planned to become a bus driver.","She wanted to avoid all walking."],"answer":0,"why":"她說想找每週可使用的路線，可推知這不是只去一次。","evidence":"Her roommate suggested sharing a taxi, but Mina wanted to know a route she could use every week."}]},{"id":"b1-e-questions-before-home","level":"B1","band":"easy","title":"Three Questions Before Going Home","topic":"出院溝通","words":173,"paras":["Mr Chen was pleased to hear that he could go home after his hospital stay. His daughter, Mei, was pleased too, but she wanted to understand the plan before they left. During the morning, she wrote three questions on a small card.","Her first question was about the new medicine. She asked the nurse to explain when her father should take it. Her second question was about the next appointment. The nurse showed them the date and telephone number on the discharge sheet.","Mei then asked who they should contact if they had a problem at home. The nurse pointed to a different number and explained when to use it. Mei wrote a short note beside each number so she would not confuse them later.","Before leaving, Mr Chen explained the medicine plan in his own words. He missed one point, so the nurse explained it again. Mei kept the card with the discharge sheet. She felt that asking questions was part of preparing for home, rather than a sign of being difficult."],"zh":"陳先生要出院了，女兒 Mei 很高興，但想先弄清楚照護計畫。她用小卡記下三個問題：新藥怎麼服用、下次回診，以及回家遇到問題要聯絡誰。護理師指出出院單上的日期和不同聯絡電話，她分別加註說明。離院前，陳先生用自己的話說明用藥安排，漏了一點後，護理師再解釋一次。Mei 把卡片與出院單收在一起，也覺得提問是準備返家的重要部分，不是在找麻煩。","qs":[{"type":"main","q":"Why did Mei prepare a question card?","options":["To ask for a different hospital room","To understand the plan for care after leaving hospital","To replace the nurse's discharge sheet"],"answer":1,"why":"三個問題都和返家後的安排有關。"},{"type":"detail","q":"What was Mei's second question about?","options":["The price of a small card","The visitor entrance","The next appointment"],"answer":2,"why":"第二段直接指出第二題是下次回診。","evidence":"Her second question was about the next appointment."},{"type":"reference","q":"What does \\"them\\" in \\"confuse them later\\" refer to?","options":["The different telephone numbers","The new medicines","The hospital rooms"],"answer":0,"why":"前文是兩個用途不同的電話號碼。","evidence":"Mei wrote a short note beside each number so she would not confuse them later."},{"type":"vocab","q":"What does \\"discharge\\" mean in \\"discharge sheet\\"?","options":["Starting a new job","Leaving hospital after a stay","Buying medicine at a shop"],"answer":1,"why":"整篇在談離院返家，discharge 是出院。","evidence":"The nurse showed them the date and telephone number on the discharge sheet."},{"type":"evidence","q":"What suggests that the first explanation was not fully understood?","options":["Mei wrote three questions before the visit.","The nurse showed them an appointment date.","Mr Chen missed one point when he explained the plan."],"answer":2,"why":"漏掉一點，護理師必須再解釋，直接支持尚未完全理解。","evidence":"He missed one point, so the nurse explained it again."},{"type":"detail","q":"Where did Mei keep the question card?","options":["With the discharge sheet","Inside the hospital room","At the appointment desk"],"answer":0,"why":"第四段說她把小卡和出院單放在一起。","evidence":"Mei kept the card with the discharge sheet."},{"type":"evidence","q":"How did Mei view asking questions at the end?","options":["As something that only nurses should do","As a useful part of getting ready for home","As proof that her father could not go home"],"answer":1,"why":"最後一句明確表達她對提問的正面看法。","evidence":"She felt that asking questions was part of preparing for home, rather than a sign of being difficult."}]},{"id":"b1-e-campus-handwashing","level":"B1","band":"easy","title":"A Missing Step at the Sink","topic":"手部清潔","words":183,"paras":["At a school health event, two nursing students watched a handwashing demonstration. Their teacher asked them to describe the order of the actions, not to judge the person. The volunteer wet her hands, added soap, rubbed them quickly, and then rinsed them.","Jun noticed that she spent only a few seconds rubbing. He checked the teaching card before speaking. It said to scrub with soap for at least twenty seconds, including the backs of the hands, between the fingers, and under the nails. The twenty seconds described the scrubbing time, not the whole process.","The volunteer tried again while Jun used a timer. After rinsing with clean running water, she dried her hands with a clean towel. His partner pointed out that the towel was an important part of the demonstration too.","Later, the students made a short poster for the school sink. They used one clear picture for each action instead of a long paragraph. Their teacher checked the finished poster before it went on the wall. The aim was to make the sequence easy to remember during an ordinary school day."],"zh":"學校健康活動中，兩位護生觀察洗手示範。老師要他們描述動作順序，而不是批評示範者。Jun 發現對方搓洗時間太短，先核對教學卡，才說明用肥皂搓洗至少 20 秒，包含手背、指縫和指甲下；20 秒指搓洗時間，不是全程。對方再練習一次，沖淨後用乾淨毛巾擦乾。學生之後做了一張每步一圖的海報，由老師確認，幫助大家在學校記住日常洗手順序。","qs":[{"type":"main","q":"What problem did the students identify?","options":["The school had no running water.","The teacher wanted a longer health event.","One part of the handwashing demonstration was too short."],"answer":2,"why":"Jun 發現的是搓洗時間只有幾秒。"},{"type":"detail","q":"What does the twenty-second recommendation describe?","options":["The scrubbing time","The entire school event","Only the drying time"],"answer":0,"why":"文章特別區分搓洗時間與整個過程。","evidence":"The twenty seconds described the scrubbing time, not the whole process."},{"type":"reference","q":"Who does \\"she\\" in \\"she dried her hands\\" refer to?","options":["Jun's partner","The volunteer","The teacher"],"answer":1,"why":"前文正在描述志工再次示範的動作。","evidence":"After rinsing with clean running water, she dried her hands with a clean towel."},{"type":"vocab","q":"What is a \\"sequence\\"?","options":["A special kind of soap","A rule about classroom noise","A set of actions in a particular order"],"answer":2,"why":"海報逐步呈現動作，sequence 指先後順序。","evidence":"The aim was to make the sequence easy to remember during an ordinary school day."},{"type":"evidence","q":"What shows that Jun checked his advice before giving it?","options":["He read the teaching card before speaking.","He used a timer after the second attempt.","He drew the poster without help."],"answer":0,"why":"先核對卡片的動作直接支持答案。","evidence":"He checked the teaching card before speaking."},{"type":"detail","q":"Who checked the final poster?","options":["The volunteer's family","The teacher","The school bus driver"],"answer":1,"why":"海報貼出前由老師檢查。","evidence":"Their teacher checked the finished poster before it went on the wall."},{"type":"evidence","q":"Why did the students choose pictures rather than a long paragraph?","options":["They wanted to remove some washing steps.","They thought all written advice was wrong.","They wanted people to remember the steps easily."],"answer":2,"why":"最後一句明說目的是讓順序容易記住。","evidence":"The aim was to make the sequence easy to remember during an ordinary school day."}]},{"id":"b1-e-library-room","level":"B1","band":"easy","title":"The Right Room for the Task","topic":"讀書方法","words":184,"paras":["Kai and Amy planned to practise an English patient introduction in the library. They found two seats in the silent reading area and opened their notebooks. After their first short exchange, a librarian came over and explained that speaking practice belonged in the discussion rooms.","The students checked the booking screen. The small rooms were full until four, so they had forty minutes to use in another way. Kai suggested reading their lines silently and marking unfamiliar words first. Amy agreed and looked up two words in her learner dictionary.","At four they moved to a discussion room. One student played a fictional patient while the other gave an introduction. They changed roles after each attempt and wrote down one point to improve. They did not use a real patient's name or private story.","By the end, both students knew their opening sentences better. They also learned that choosing a study place depends on the task. The quiet area helped them prepare, but they needed a discussion room to practise aloud. Next time they planned to book that room before coming to the library."],"zh":"Kai 和 Amy 想在圖書館練習英文自我介紹，卻先坐進安靜閱讀區。館員提醒口說應在討論室進行，但小房間要四點才有空。他們利用等待的 40 分鐘先默讀、標出不熟的字並查字典。進討論室後，兩人輪流扮演護生與虛構病人，不使用真實病人資料。這次他們學到：安靜區適合準備，討論室才適合一起出聲練習，下次應先預約。","qs":[{"type":"main","q":"What did Kai and Amy learn about study spaces?","options":["Different tasks may need different spaces.","All library rooms are silent areas.","Speaking practice does not need preparation."],"answer":0,"why":"文章比較默讀準備與出聲對話所需的空間。"},{"type":"detail","q":"How long did they have before a room became available?","options":["Four hours","Forty minutes","Ten minutes"],"answer":1,"why":"第二段直接給出等待時間。","evidence":"The small rooms were full until four, so they had forty minutes to use in another way."},{"type":"reference","q":"What does \\"that room\\" in the last sentence mean?","options":["The silent reading area","A hospital patient room","A discussion room"],"answer":2,"why":"上文說明練口說需要可對話的房間。","evidence":"The quiet area helped them prepare, but they needed a discussion room to practise aloud."},{"type":"vocab","q":"What does \\"fictional\\" mean here?","options":["Invented for the exercise","Taken from a real hospital record","Unable to understand English"],"answer":0,"why":"下一句強調沒有使用真實病人資料，可推知情境是虛構的。","evidence":"They did not use a real patient's name or private story."},{"type":"evidence","q":"Which conclusion about their waiting time is supported?","options":["They left the library and missed their booking.","They used it to prepare for speaking practice.","They spent it interviewing real patients."],"answer":1,"why":"Kai 建議先默讀並標出陌生單字，顯示等待時間用於準備。","evidence":"Kai suggested reading their lines silently and marking unfamiliar words first."},{"type":"detail","q":"When did they change roles?","options":["Only after leaving the library","Before reading any sentences","After each attempt"],"answer":2,"why":"第三段說每次嘗試後交換角色。","evidence":"They changed roles after each attempt and wrote down one point to improve."},{"type":"evidence","q":"Why did they want to book ahead next time?","options":["The room they needed was not immediately available.","The library had banned all students.","Their teacher required a larger audience."],"answer":0,"why":"小房間四點前都滿了，支持先預約可避免再次等待。","evidence":"The small rooms were full until four, so they had forty minutes to use in another way."}]},{"id":"b1-e-pressure-practice","level":"B1","band":"easy","title":"Before the Blood Pressure Reading","topic":"生命徵象練習","words":182,"paras":["During a supervised skills class, Lin prepared to measure her classmate's blood pressure. Her classmate had just finished a conversation and wanted to begin at once. The teacher asked them to pause and review their preparation checklist.","They allowed at least five minutes of quiet rest before the reading. The classmate sat with his back supported, his feet flat on the floor, and his legs uncrossed. Lin checked the cuff size with her teacher and placed it on the bare upper arm. The arm rested on a support at heart level.","Lin nearly asked a question while the monitor was working. Then she remembered that the person should remain still and avoid talking during the measurement. She saved her question for afterwards and recorded the result according to the class instructions.","The teacher did not focus only on the number on the screen. She also asked Lin to explain the preparation and body position. Lin realised that a familiar machine did not remove the need for careful technique. Next time, she put the checklist beside the equipment before her partner sat down."],"zh":"老師指導的技術課中，Lin 準備替剛結束一段談話的同學量血壓。老師請他們先檢查準備：安靜休息至少五分鐘，背部有支撐、雙腳平放且不交叉；核對壓脈帶尺寸，放在裸露上臂，手臂支撐於心臟高度。量測時 Lin 想問問題，隨即記起應保持安靜不動，等量完再問。老師不只看數字，也要她說明準備與姿勢，讓她理解熟悉機器仍需要正確操作。","qs":[{"type":"main","q":"What is the central lesson of the passage?","options":["The displayed number is the only important part.","Careful preparation matters when using a familiar monitor.","Students should avoid all practice with equipment."],"answer":1,"why":"老師同時重視準備、姿勢與讀值，不只看螢幕。"},{"type":"detail","q":"Where was the cuff placed?","options":["Over a thick sleeve","Around the wrist in a pocket","On the bare upper arm"],"answer":2,"why":"第二段明確寫裸露上臂。","evidence":"Lin checked the cuff size with her teacher and placed it on the bare upper arm."},{"type":"reference","q":"Who is \\"She\\" in \\"She also asked Lin\\"?","options":["The teacher","Lin's classmate","A hospital visitor"],"answer":0,"why":"前一句主詞是 the teacher。","evidence":"The teacher did not focus only on the number on the screen."},{"type":"vocab","q":"What does \\"pause\\" mean in the first paragraph?","options":["Increase the speed of an action","Stop briefly before continuing","Finish the whole course"],"answer":1,"why":"老師要求先停一下，檢查準備。","evidence":"The teacher asked them to pause and review their preparation checklist."},{"type":"evidence","q":"Why did Lin wait to ask her question?","options":["She could not remember any English words.","Her teacher had left the classroom.","Talking could interfere with the measurement procedure."],"answer":2,"why":"文章明說量測時應不動、不說話，因此等量完再問。","evidence":"Then she remembered that the person should remain still and avoid talking during the measurement."},{"type":"detail","q":"How was the arm positioned?","options":["Supported at heart level","Hanging below the chair","Raised above the head"],"answer":0,"why":"第二段最後一句寫手臂在心臟高度獲得支撐。","evidence":"The arm rested on a support at heart level."},{"type":"evidence","q":"What change did Lin plan for her next attempt?","options":["She would skip preparation to save time.","She would prepare the checklist before seating her partner.","She would decide the result before starting."],"answer":1,"why":"最後一句直接描述下次的具體調整。","evidence":"Next time, she put the checklist beside the equipment before her partner sat down."}]},{"id":"b1-e-medicine-list","level":"B1","band":"easy","title":"The Bag That Helped at the Appointment","topic":"用藥溝通","words":184,"paras":["Before her father's appointment, Ning helped him make a list of the medicines he used. At first, he named only the tablets from the hospital. Ning asked about products from the local pharmacy and the vitamins beside the kitchen window.","They added those items to the list too. For each product, they copied the name and the instructions from its label. One label was difficult to read, so they put that container in a bag instead of guessing. Her father kept the list in the same bag.","At the appointment, the pharmacist reviewed the list and checked the unclear container. She asked about the times when he took each product and answered his questions. Ning listened, but she let her father describe his own routine first. She wrote down the explanation he wanted to remember.","On the way home, her father said the list had made the conversation easier. It had not replaced professional advice; it had helped the pharmacist see the full picture. Ning planned to update it after changes discussed with his care team, rather than treating it as a school task."],"zh":"Ning 陪爸爸看診前整理用藥清單。爸爸原先只提醫院開的藥，她也詢問藥局買的產品和維生素。他們抄下名稱與標籤指示；有一瓶標籤看不清楚，就帶原容器請藥師確認，不自己猜。看診時，藥師核對清單與容器，爸爸先說自己的用藥習慣，Ning 再記下想記住的說明。清單沒有取代專業建議，而是讓藥師看見完整資訊；之後與照護團隊討論任何變更，也會更新清單。","qs":[{"type":"main","q":"How did the medicine list help?","options":["It allowed Ning to change the doses herself.","It replaced the need for the appointment.","It gave the pharmacist a fuller picture of the father's routine."],"answer":2,"why":"清單的用途是補齊資訊，文章明說沒有取代專業建議。"},{"type":"detail","q":"What did they do with the hard-to-read label?","options":["They brought the original container.","They guessed from the tablet colour.","They left that product off the list."],"answer":0,"why":"標籤看不清楚時，直接把容器放進袋子。","evidence":"One label was difficult to read, so they put that container in a bag instead of guessing."},{"type":"reference","q":"What does \\"those items\\" refer to?","options":["Only the hospital tablets","Pharmacy products and vitamins","The bag and the kitchen window"],"answer":1,"why":"承接前段提到的藥局產品與維生素。","evidence":"Ning asked about products from the local pharmacy and the vitamins beside the kitchen window."},{"type":"vocab","q":"What does \\"reviewed\\" mean in paragraph 3?","options":["Threw away immediately","Sold to another person","Examined carefully"],"answer":2,"why":"藥師核對清單及容器，reviewed 是仔細檢視。","evidence":"At the appointment, the pharmacist reviewed the list and checked the unclear container."},{"revision":1,"type":"evidence","q":"What shows that Ning supported her father's participation?","options":["She let him describe his own routine first.","She hid the list from him.","She told him to stop asking questions."],"answer":0,"why":"第三段說她先讓爸爸描述自己的習慣。","evidence":"Ning listened, but she let her father describe his own routine first."},{"type":"detail","q":"What did Ning copy for each product?","options":["Only its colour","Its name and label instructions","The pharmacy's opening hours"],"answer":1,"why":"第二段清楚列出名稱與標籤指示。","evidence":"For each product, they copied the name and the instructions from its label."},{"type":"evidence","q":"Why should the list be updated later?","options":["Every label becomes wrong after one day.","The pharmacist cannot read old handwriting.","The care team may discuss changes to the medicines."],"answer":2,"why":"最後一句把更新清單與照護團隊討論的變更連在一起。","evidence":"Ning planned to update it after changes discussed with his care team, rather than treating it as a school task."}]},{"id":"b1-e-hot-day-plan","level":"B1","band":"easy","title":"Moving the Activity Indoors","topic":"健康活動規劃","words":181,"paras":["A nursing class planned an outdoor welcome game for new students. The forecast showed a very hot afternoon. The organisers met again because the original plan included a long walk around the campus.","Some students wanted to keep the plan because the outdoor route was already on the posters. Others suggested moving the main activities to a cool room. They agreed that changing a poster was easier than asking everyone to stay outside in uncomfortable heat.","The team booked a room near drinking water and sent a clear message about the new location. They also placed a large notice at the old meeting point. One organiser stayed there briefly to guide anyone who missed the message. The short campus walk became an optional activity at a cooler time on another day.","During the event, the students used a map and photos to introduce the campus. New students still learned where the library and skills rooms were. Afterwards, the team discussed the change in its planning notes. They decided that a plan needed room for weather and participant comfort, not just activities."],"zh":"護理班原本要辦戶外迎新遊戲，但天氣預報顯示午後很熱，原計畫又有長時間校園步行。有人不想改已印好的海報，其他人建議轉移到涼爽室內。最後大家決定改地點，傳訊息、在舊集合處貼公告，並安排一人短暫指引漏看通知的人。校園步行改成另一天較涼時的自由參加活動。迎新仍用地圖和照片介紹校園，也讓主辦者學到計畫須考慮天候與參與者感受。","qs":[{"type":"main","q":"Why was the event plan changed?","options":["The forecast made the long outdoor activity unsuitable.","The new students disliked all games.","The school permanently closed the campus."],"answer":0,"why":"改動是因為預期天氣炎熱，且原活動需長時間在戶外。"},{"type":"detail","q":"Where was a large notice placed?","options":["Inside every student's bag","At the old meeting point","At a different hospital"],"answer":1,"why":"第三段交代舊集合點設有大型公告。","evidence":"They also placed a large notice at the old meeting point."},{"type":"reference","q":"Who are \\"They\\" in the final sentence?","options":["The weather reporters","The hospital patients","The organising team"],"answer":2,"why":"前一句是活動團隊討論規劃紀錄。","evidence":"Afterwards, the team discussed the change in its planning notes."},{"type":"vocab","q":"What does \\"optional\\" mean?","options":["People can choose whether to join.","Everyone must join twice.","The activity has already happened."],"answer":0,"why":"optional 指可自行選擇參加。","evidence":"The short campus walk became an optional activity at a cooler time on another day."},{"type":"evidence","q":"What suggests that some people might not read the message?","options":["The organisers cancelled all notices.","An organiser waited at the old location to guide them.","The class refused to use a map."],"answer":1,"why":"特別安排人員協助漏看訊息的人，支持此推論。","evidence":"One organiser stayed there briefly to guide anyone who missed the message."},{"type":"detail","q":"How did students introduce the campus indoors?","options":["With a long outdoor race","With only a written exam","With a map and photos"],"answer":2,"why":"第四段第一句給出方式。","evidence":"During the event, the students used a map and photos to introduce the campus."},{"type":"evidence","q":"What did the team value more than keeping the original poster?","options":["Participants' comfort in the hot weather","Using every outdoor photo","Finishing the event without any discussion"],"answer":0,"why":"團隊認為改海報比讓大家在熱天不舒服地待在戶外容易。","evidence":"They agreed that changing a poster was easier than asking everyone to stay outside in uncomfortable heat."}]},{"id":"b1-e-english-buddy","level":"B1","band":"easy","title":"A Small Goal for an English Partner","topic":"赴美英文準備","words":182,"paras":["Ting wanted to work as a nurse in the United States in the future, but long English conversations still felt difficult. She joined a school language club and met Daniel, who was also learning English. At their first meeting, they tried to discuss hospital jobs and soon ran out of words.","Their club teacher suggested a smaller goal. For the next meeting, each student prepared a short introduction and two questions about school. They agreed to practise for fifteen minutes before checking unfamiliar phrases together. This gave both students a clear task instead of a general promise to improve.","At the second meeting, Ting spoke slowly and used simple sentences. Daniel waited until she finished before asking his questions. When neither student knew a word, they wrote it down for the teacher rather than inventing a confident answer.","After several meetings, they added a fictional patient greeting to their practice. They still made mistakes, but they could see progress in their notes. Ting understood that her distant goal required many steps. For now, one clear conversation was a useful place to begin."],"zh":"Ting 希望未來赴美當護理師，但英文長對話仍很吃力。她在語言社認識同樣學英文的 Daniel，一開始談醫院工作很快就詞窮。老師建議縮小目標：各準備自我介紹和兩個學校相關問題，先練十五分鐘，再一起查不熟的說法。他們輪流說話，遇到兩人都不知道的字就記下來問老師。幾次後才加入虛構的病人問候。雖然還會犯錯，Ting 能從筆記看見進步，也知道遠大目標要一步一步來。","qs":[{"type":"main","q":"What helped Ting and Daniel improve their practice?","options":["Pretending that they knew every word","Choosing a small, clear goal for each meeting","Starting with long talks about every nursing topic"],"answer":1,"why":"由大題目縮小成具體對話，是文章重點。"},{"type":"detail","q":"What did each student prepare for the second meeting?","options":["A complete nursing job interview","A real patient's medical history","An introduction and two school questions"],"answer":2,"why":"第二段交代每人準備的內容。","evidence":"For the next meeting, each student prepared a short introduction and two questions about school."},{"type":"reference","q":"What does \\"This\\" at the end of paragraph 2 refer to?","options":["Their specific plan for the next practice","Ting's future move to the United States","A promise to stop making mistakes"],"answer":0,"why":"This 承接前面的明確練習安排。","evidence":"This gave both students a clear task instead of a general promise to improve."},{"type":"vocab","q":"What does \\"distant\\" describe in \\"her distant goal\\"?","options":["A goal inside another classroom","A goal that is still far in the future","A goal that is already complete"],"answer":1,"why":"文章把長期赴美目標與眼前的小對話對照。","evidence":"Ting understood that her distant goal required many steps."},{"type":"evidence","q":"How did Daniel make room for Ting to speak?","options":["He answered all her questions himself.","He corrected every word immediately.","He waited for her to finish."],"answer":2,"why":"第三段直接描述他等待 Ting 說完。","evidence":"Daniel waited until she finished before asking his questions."},{"type":"detail","q":"What did they do when neither knew a word?","options":["Recorded it as a question for the teacher","Used a real patient's records","Stopped attending the club"],"answer":0,"why":"第三段說他們記下來，之後問老師。","evidence":"When neither student knew a word, they wrote it down for the teacher rather than inventing a confident answer."},{"type":"evidence","q":"What shows that their practice became slightly more challenging?","options":["They stopped keeping notes.","They later added a fictional patient greeting.","They removed every school question permanently."],"answer":1,"why":"加入新的護理問候情境，表示在原練習上增加難度。","evidence":"After several meetings, they added a fictional patient greeting to their practice."}]},{"id":"b1-m-night-light","level":"B1","band":"mid","title":"A Safer Path at Home","topic":"居家防跌","words":214,"paras":["During a supervised visit, Bo met a woman who worried about falling on her way to the bathroom. Her daughter had bought a bright lamp, but the switch was behind a chair and difficult to reach from the bed. The student noticed that the problem was not simply the amount of light.","With the woman's agreement, the team looked at the route she used at night. A loose rug and a box of magazines were found beside the doorway. These objects narrowed the walking space, although the middle of the room looked tidy. The woman explained that she kept the magazines nearby because she enjoyed reading before sleep.","The nurse discussed ways to reduce the hazards without removing the woman's favourite activity. They agreed to put the magazines on a low shelf and keep the path clear. The daughter also arranged a light with a switch her mother could reach easily. The nurse explained that home changes were one part of a wider fall-prevention plan.","At the next visit, Bo asked whether the new arrangement was convenient. He did not assume a tidy photograph proved the room worked well. The woman still enjoyed her magazines and was happier with the route. Bo learned to consider how someone actually used a space before suggesting changes."],"zh":"社區訪視中，Bo 遇到一位擔心夜間上廁所跌倒的女士。女兒買了亮燈，但開關在椅子後面，從床上很難碰到。團隊經她同意檢視實際路線，發現門邊鬆動地毯與雜誌箱占空間。護理師沒有直接取消她睡前閱讀的習慣，而是一起討論把雜誌移到矮架、保持通道淨空，以及調整燈具開關。回訪時，Bo 詢問是否真的方便，而不只看房間照片是否整齊，學會先了解使用者生活再提建議。","qs":[{"type":"main","q":"What is the writer mainly showing through Bo's experience?","options":["A bright lamp solves every fall risk.","Older adults should give up reading at night.","Safety changes should fit the way a person uses a space."],"answer":2,"why":"故事強調實際生活需求，而非只看亮度或整齊程度。"},{"type":"detail","q":"Why was the original lamp difficult to use?","options":["Its switch was behind a chair.","It was placed outside the house.","Its colour was too dark."],"answer":0,"why":"第一段直接說明開關的位置與使用困難。","evidence":"Her daughter had bought a bright lamp, but the switch was behind a chair and difficult to reach from the bed."},{"type":"reference","q":"What does \\"These objects\\" refer to?","options":["The bed and the bathroom","The rug and the box of magazines","The light and its switch"],"answer":1,"why":"指前一句找到的地毯與雜誌箱。","evidence":"A loose rug and a box of magazines were found beside the doorway."},{"type":"vocab","q":"What are \\"hazards\\" in this passage?","options":["Things that cost the most","Activities people enjoy","Things that may cause harm"],"answer":2,"why":"上下文談防跌與清空走道，hazards 是危險因素。","evidence":"The nurse discussed ways to reduce the hazards without removing the woman's favourite activity."},{"type":"evidence","q":"Why did the team keep the magazines in the room?","options":["Reading was important to the woman's routine.","The nurse needed them for a test.","The daughter refused every change."],"answer":0,"why":"她表示喜歡睡前閱讀，因此方案保留這個習慣。","evidence":"The woman explained that she kept the magazines nearby because she enjoyed reading before sleep."},{"type":"detail","q":"What did the nurse say about changes to the home?","options":["They made every fall impossible.","They were one part of a wider prevention plan.","They replaced all other care."],"answer":1,"why":"文章沒有承諾完全不會跌倒，只說是整體計畫的一部分。","evidence":"The nurse explained that home changes were one part of a wider fall-prevention plan."},{"type":"evidence","q":"What does Bo's question at the next visit suggest?","options":["He only wanted a new photograph.","He had forgotten the purpose of the first visit.","He wanted to check whether the changes worked in daily life."],"answer":2,"why":"他回訪詢問便利性，顯示在確認實際使用結果。","evidence":"At the next visit, Bo asked whether the new arrangement was convenient."}]},{"id":"b1-m-clear-leaflet","level":"B1","band":"mid","title":"When a Shorter Leaflet Said More","topic":"健康資訊","words":213,"paras":["A student group was asked to improve a practice leaflet about preparing for a clinic visit. The original page contained several long paragraphs and words that the group rarely used in conversation. Although the information was accurate, some classmates could not quickly find the action they needed to take.","Sara suggested replacing every medical word with a short word. Her partner disagreed because some important names still needed to appear. They decided to explain necessary terms in ordinary language and place one main action under each heading. The telephone number was moved from the middle of a paragraph to a separate line near the end.","The new page was tested with two classmates who had not helped write it. Instead of asking whether it looked attractive, the group asked them to find the appointment details and describe what to bring. One classmate found the list immediately, but the other confused the clinic address with the contact address. The group changed those labels before making another copy.","Their teacher praised the testing process rather than the number of words they had removed. A shorter page was useful only if its message remained complete and easy to follow. The students kept both versions in their project folder to show why each change had been made."],"zh":"學生受託修改一份就診準備練習單。原版資訊正確，但段落太長、用語不熟，讀者不容易找到要做的事。Sara 原本想把所有醫學詞換掉，後來與夥伴決定保留必要名稱並用白話解釋，每個標題只放一個主要行動，電話另列。兩位沒有參與撰寫的同學測試新版，發現有人把診所地址與聯絡地址混淆，團隊便修改標示。老師肯定的是測試與改善過程，而非單純刪字；簡短仍要保留完整訊息。","qs":[{"type":"main","q":"What is the purpose of this story?","options":["To show how testing can improve a health leaflet","To prove that all medical terms are unnecessary","To recommend the most colourful page design"],"answer":0,"why":"文章描述修改、測試及再次調整，重點是讀者能否使用資訊。"},{"type":"detail","q":"Where was the telephone number placed in the new version?","options":["Only on the back of a photograph","On a separate line near the end","Inside the longest paragraph"],"answer":1,"why":"第二段直接描述電話的新位置。","evidence":"The telephone number was moved from the middle of a paragraph to a separate line near the end."},{"type":"reference","q":"Who does \\"them\\" in \\"the group asked them\\" refer to?","options":["The members who wrote the first draft","The clinic doctors","The two classmates testing the page"],"answer":2,"why":"前一句介紹未參與撰寫、協助測試的同學。","evidence":"The new page was tested with two classmates who had not helped write it."},{"type":"vocab","q":"What does \\"accurate\\" mean in paragraph 1?","options":["Correct and reliable","Very short","Expensive to print"],"answer":0,"why":"文章說內容雖正確，仍可能不好找重點。","evidence":"Although the information was accurate, some classmates could not quickly find the action they needed to take."},{"type":"evidence","q":"What shows that a clear appearance was not enough?","options":["The group used a project folder.","A reader confused two addresses on the revised page.","The page contained a telephone number."],"answer":1,"why":"新版仍發生地址混淆，表示還需要檢查理解。","evidence":"One classmate found the list immediately, but the other confused the clinic address with the contact address."},{"type":"detail","q":"Why were both versions kept?","options":["To send different instructions to every patient","To avoid explaining the project to the teacher","To show the reasons for the changes"],"answer":2,"why":"最後一句明說保留兩版的目的。","evidence":"The students kept both versions in their project folder to show why each change had been made."},{"type":"evidence","q":"Why did the teacher value the testing process?","options":["A short page still had to communicate its complete message.","The teacher wanted the students to remove every heading.","The testing made the page longer by accident."],"answer":0,"why":"倒數第二句提供評估標準：完整且容易遵循，而非只求短。","evidence":"A shorter page was useful only if its message remained complete and easy to follow."}]},{"id":"b1-m-wound-call","level":"B1","band":"mid","title":"A Note Beside the Telephone","topic":"術後返家溝通","words":217,"paras":["Before leaving hospital after surgery, Mrs Wu received instructions about caring for her wound. The nurse explained which changes should be reported and wrote the contact number on the discharge sheet. Mrs Wu's son placed the sheet beside the telephone at home, where both of them could find it.","Two days later, Mrs Wu noticed more redness and pain near the wound. She wondered whether she should wait for her appointment at the end of the week. Her son read the instructions with her and suggested contacting the care team promptly. They did not decide on a treatment themselves or use an old medicine from the cupboard.","During the call, Mrs Wu described the changes and when they had started. Her son helped locate the appointment details but let her answer questions about her symptoms. The team told her what to do next according to her situation. She wrote down that advice and repeated the important details to check her understanding.","Later, the son noticed that the sheet also explained whom to contact outside usual opening hours. He marked that section so it would be easier to find. The family had not used the paper to make a diagnosis. They had used it to recognise a reason for seeking professional advice and to prepare a clear conversation."],"zh":"吳太太術後出院前，護理師說明傷口出現哪些變化要通報，並寫下聯絡方式。兒子把出院單放在家中電話旁。兩天後，她發現傷口附近更紅、更痛，原想等到回診，讀過指示後便立即聯絡照護團隊，沒有自行用舊藥。通話時，她描述變化與開始時間，兒子協助找資料，仍讓她自己說症狀。她記下並覆述團隊建議。家人也標出非一般上班時間的聯絡方法；這張紙是協助求助與溝通，不是讓他們自行診斷。","qs":[{"type":"main","q":"What role did the discharge sheet play?","options":["It allowed the family to diagnose an infection alone.","It helped the family contact the care team about a change.","It replaced every future appointment."],"answer":1,"why":"文章強調辨識求助理由與清楚溝通。"},{"type":"detail","q":"What changes did Mrs Wu notice?","options":["A new name on the sheet","A broken telephone","More redness and pain near the wound"],"answer":2,"why":"第二段開頭列出她觀察到的變化。","evidence":"Two days later, Mrs Wu noticed more redness and pain near the wound."},{"type":"reference","q":"What does \\"that advice\\" refer to?","options":["The care team's instructions during the call","The son's guess about a diagnosis","An old medicine label"],"answer":0,"why":"前一句是團隊依她情況告訴她下一步。","evidence":"The team told her what to do next according to her situation."},{"type":"vocab","q":"What does \\"promptly\\" mean in paragraph 2?","options":["Only after the next appointment","Without unnecessary delay","Without asking any questions"],"answer":1,"why":"上下文是不要拖到週末回診，應及時聯絡。","evidence":"Her son read the instructions with her and suggested contacting the care team promptly."},{"type":"evidence","q":"What shows that the family avoided guessing a treatment?","options":["They placed the sheet near a telephone.","They kept the cupboard in the house.","They did not use old medicine or choose treatment themselves."],"answer":2,"why":"第二段最後一句直接支持這點。","evidence":"They did not decide on a treatment themselves or use an old medicine from the cupboard."},{"type":"detail","q":"What other contact information did the son mark?","options":["Help outside usual opening hours","A new taxi company","The hospital shop's number"],"answer":0,"why":"第四段說他找到非一般上班時間的聯絡資訊。","evidence":"Later, the son noticed that the sheet also explained whom to contact outside usual opening hours."},{"type":"evidence","q":"Why did Mrs Wu repeat the important details?","options":["To decide whether the team was too busy","To check that she understood the advice","To change the instructions herself"],"answer":1,"why":"文章明確說她覆述是為了確認理解。","evidence":"She wrote down that advice and repeated the important details to check her understanding."}]},{"id":"b1-m-interpreter-practice","level":"B1","band":"mid","title":"Helping Without Changing the Message","topic":"口譯溝通","words":216,"paras":["In a classroom exercise, a nursing student named Yan played a patient who preferred to speak Chinese. Another student played a nurse, and their teacher acted as a trained interpreter. The fictional situation involved questions about a new symptom, so the group needed to keep the information clear.","At first, the student nurse looked at the interpreter whenever she spoke. She also asked three questions in one long sentence. The teacher stopped the exercise and suggested speaking directly to the patient, with a short pause after each question. Yan said this made it easier to know when it was her turn to answer.","During the next attempt, the nurse listened to the full interpreted answer before asking another question. When a word was unclear, she asked for clarification instead of guessing its meaning. She noticed that a familiar phrase could carry a different meaning in a health conversation. The teacher reminded the class that knowing two languages was not the same as having training for this role.","Afterwards, the students discussed the conversation rather than judging Yan's English. They wrote down two useful habits: allowing time for interpretation and checking unclear points. The exercise was designed to develop communication skills, not to certify students as interpreters. Each participant practised a different role during the following lesson."],"zh":"模擬課中，Yan 扮演偏好說中文的病人，同學扮護理師，老師扮受訓口譯員。護理師起先只看口譯員，還把三個問題擠成一句。老師建議直接對病人說話，每個問題後留短暫停頓。第二次練習，護理師等完整口譯回答後再提問，遇到不清楚的字就確認，不用猜的。老師提醒雙語能力與角色訓練不同。課後大家檢討的是溝通方式，而非批評 Yan 的英文；這是學習溝通，並不是讓學生取得口譯資格。","qs":[{"type":"main","q":"What was the main aim of the exercise?","options":["To test whether Yan should stop using Chinese","To qualify every student as an interpreter","To practise clearer communication through an interpreter"],"answer":2,"why":"最後一段清楚界定練習目的與限制。"},{"type":"detail","q":"What problem occurred during the first attempt?","options":["The nurse asked three questions in one long sentence.","The patient left before any question.","The interpreter refused to join."],"answer":0,"why":"第二段直接列出這個問題。","evidence":"She also asked three questions in one long sentence."},{"type":"reference","q":"What does \\"this role\\" mean in paragraph 3?","options":["The school librarian's role","The interpreter's role","The bus driver's role"],"answer":1,"why":"前文持續談口譯及其所需訓練。","evidence":"The teacher reminded the class that knowing two languages was not the same as having training for this role."},{"type":"vocab","q":"What does \\"clarification\\" mean here?","options":["A decision to end all conversation","A translation certificate","An explanation that makes meaning clearer"],"answer":2,"why":"遇到不清楚的字時，她要求解釋。","evidence":"When a word was unclear, she asked for clarification instead of guessing its meaning."},{"type":"evidence","q":"Why did the pauses help Yan?","options":["They showed her when she could answer.","They removed the need for interpretation.","They made every question unnecessary."],"answer":0,"why":"Yan 說停頓讓她更容易知道何時輪到自己。","evidence":"Yan said this made it easier to know when it was her turn to answer."},{"type":"detail","q":"What did the nurse do before asking another question in the second attempt?","options":["Looked up a real patient record","Listened to the complete interpreted answer","Asked Yan to change languages"],"answer":1,"why":"第三段開頭說先聽完口譯回答。","evidence":"During the next attempt, the nurse listened to the full interpreted answer before asking another question."},{"type":"evidence","q":"What conclusion about the course is supported?","options":["Only Yan was allowed to practise another role.","Students were already professional interpreters.","Participation did not provide interpreter certification."],"answer":2,"why":"文章明說課程不負責認證口譯資格。","evidence":"The exercise was designed to develop communication skills, not to certify students as interpreters."}]},{"id":"b1-m-simulation-checklist","level":"B1","band":"mid","title":"The Checklist Beside the Model","topic":"模擬技術課","words":214,"paras":["The dressing exercise in Leo's nursing class was performed on a training model, not a patient. Before starting, each pair was given the school's approved checklist and a set of practice materials. Leo had watched a short video the evening before and felt ready to begin quickly.","His partner, Eva, noticed that the order in the video differed from the order on their checklist. She did not assume that either version could be copied without checking. Instead, she asked the instructor which procedure applied to the equipment in their classroom. The instructor reviewed the steps and explained the reason for the difference.","After the explanation, Leo carried out the exercise while Eva followed the checklist. She marked the step where he paused, then saved her comments until the agreed feedback point. The pair repeated that part with the instructor's guidance. Their second attempt was slower, but Leo could explain what he was doing at each stage.","In his reflection, Leo wrote that remembering a video was not enough to demonstrate a skill. He needed to connect the instructions with the actual task and ask about differences. Eva added that a checklist supported practice but did not replace supervision. They planned another session using the same approved materials so they could compare their progress fairly."],"zh":"Leo 的傷口敷料練習使用模型，不是真病人，每組都有學校核准的步驟表與材料。他看過影片，以為可以快速開始，但 Eva 發現影片順序與課堂表單不同，便請老師確認哪個流程適用於現場器材。老師解釋後，Leo 操作，Eva 照表記錄，並在約定時間回饋。他們在指導下重練卡住的地方。第二次速度較慢，Leo 卻能說清楚每一步。兩人理解影片記憶與清單都不能取代釐清問題及老師指導。","qs":[{"type":"main","q":"What did Leo learn from the exercise?","options":["He needed to understand the procedure, not only remember a video.","Every video should be ignored.","Fast practice always shows the best skill."],"answer":0,"why":"他在反思中強調理解實際任務與確認差異。"},{"type":"detail","q":"What was used instead of a patient?","options":["A photograph of a real patient","A training model","A student's medical record"],"answer":1,"why":"首句清楚說明練習對象是模型。","evidence":"The dressing exercise in Leo's nursing class was performed on a training model, not a patient."},{"type":"reference","q":"What does \\"that part\\" in paragraph 3 refer to?","options":["The whole video soundtrack","The final page of the reflection","The step where Leo had paused"],"answer":2,"why":"前一句 Eva 標記 Leo 停頓的步驟。","evidence":"She marked the step where he paused, then saved her comments until the agreed feedback point."},{"type":"vocab","q":"What does \\"applied to\\" mean in paragraph 2?","options":["Was appropriate for","Was written on the outside of","Was paid for by"],"answer":0,"why":"Eva 想確認適用於課堂器材的流程。","evidence":"Instead, she asked the instructor which procedure applied to the equipment in their classroom."},{"type":"evidence","q":"What suggests that the slower attempt involved better understanding?","options":["Leo finished before every other student.","Leo could explain his actions at every stage.","Eva stopped using the checklist entirely."],"answer":1,"why":"能說明每一步，比單純變慢更能支持理解改善。","evidence":"Their second attempt was slower, but Leo could explain what he was doing at each stage."},{"type":"detail","q":"Who explained the difference between the two procedures?","options":["The video company's driver","A patient in the ward","The instructor"],"answer":2,"why":"第二段最後一句明確寫老師檢視並說明。","evidence":"The instructor reviewed the steps and explained the reason for the difference."},{"type":"evidence","q":"What did Eva believe about checklists?","options":["They could help practice without replacing supervision.","They allowed students to practise on patients alone.","They were useful only after graduation."],"answer":0,"why":"她的反思說明清單能支持練習，但不能取代老師的指導。","evidence":"Eva added that a checklist supported practice but did not replace supervision."}]},{"id":"b1-m-quiet-ward","level":"B1","band":"mid","title":"Listening Before Changing the Ward","topic":"病房環境","words":217,"paras":["For a student project, a ward team collected comments about noise at night. Several patients mentioned conversations near the doors, while others said light from the corridor disturbed them more. The students were surprised because their first idea had been to write a poster about quiet voices only.","They were reminded that some sounds came from necessary care and equipment. Alarms were not to be turned off simply to make the area quieter. Any concern about a device had to be reported to the responsible nurse. The project therefore focused on things the team could discuss safely, such as where routine conversations took place.","A short meeting was held with patients and staff who wanted to contribute. One patient suggested moving ordinary staff discussions away from the doorway. Another asked how to request help with light during rest periods. The nurse explained the available choices and checked that each suggestion fitted the patient's care needs.","The students recorded the suggestions separately from the final decisions. They could not promise that every request would be possible, but they could explain what had been considered. Their final report described listening as part of improving the environment. It also noted that comfort and necessary care had to be considered together, rather than treating silence as the only measure of success."],"zh":"病房團隊收集夜間噪音意見，有人困擾於門邊交談，有人更受走廊燈光影響，讓原本只想做輕聲海報的學生重新思考。老師提醒必要照護與器材也會發出聲音，不能為了安靜關掉警報，器材疑慮須告知負責護理師。病人與工作人員討論一般談話的位置、休息時燈光協助等，護理師核對是否符合個別照護需求。學生分開記錄建議和最後決策，不承諾全部可行；改善環境須兼顧舒適與必要照護。","qs":[{"type":"main","q":"What changed the students' approach?","options":["Every patient asked for the same poster.","Patients described different sources of discomfort.","The team decided that equipment was unnecessary."],"answer":1,"why":"患者提出的不只聲音，也有燈光，促使計畫調整。"},{"type":"detail","q":"What should happen if there is a concern about a device?","options":["A student should switch it off without asking.","It should be hidden from the patient.","It should be reported to the responsible nurse."],"answer":2,"why":"第二段直接給出處理方式。","evidence":"Any concern about a device had to be reported to the responsible nurse."},{"type":"reference","q":"What does \\"each suggestion\\" refer to?","options":["Ideas raised during the patient and staff meeting","The names of every device","The students' exam questions"],"answer":0,"why":"第三段是會議中提出的改善建議。","evidence":"The nurse explained the available choices and checked that each suggestion fitted the patient's care needs."},{"type":"vocab","q":"What does \\"contribute\\" mean in paragraph 3?","options":["Pay for every piece of equipment","Take part by offering ideas","Leave before the meeting starts"],"answer":1,"why":"會議邀請願意參與、提供想法的人。","evidence":"A short meeting was held with patients and staff who wanted to contribute."},{"type":"evidence","q":"Why was a poster about quiet voices insufficient?","options":["No one could read any posters.","All conversations had already stopped.","Some patients were more troubled by corridor light."],"answer":2,"why":"首段指出部分人更在意走廊燈光。","evidence":"Several patients mentioned conversations near the doors, while others said light from the corridor disturbed them more."},{"type":"detail","q":"How were suggestions and final decisions recorded?","options":["Separately","Only as a single promise","They were not recorded at all."],"answer":0,"why":"第四段明確說分開紀錄。","evidence":"The students recorded the suggestions separately from the final decisions."},{"type":"evidence","q":"Which statement best matches the report's conclusion?","options":["Success means removing every hospital sound.","A quiet environment must also allow necessary care.","Comfort should never be discussed with patients."],"answer":1,"why":"最後一句把舒適與必要照護放在一起考量。","evidence":"It also noted that comfort and necessary care had to be considered together, rather than treating silence as the only measure of success."}]},{"id":"b1-m-allergy-label","level":"B1","band":"mid","title":"The Wrapper Was Part of the Plan","topic":"食物過敏","words":216,"paras":["A nursing class organised a small study meeting and asked members about food needs before buying snacks. One student, Lisa, said that she had a food allergy and preferred to check packages herself. The organiser thanked her and kept the original wrappers instead of putting every snack into unlabelled bowls.","On the day of the meeting, a classmate offered Lisa a biscuit that looked similar to one she had eaten before. She read the current ingredient list rather than relying on its appearance. The recipe on a familiar product can change, so a previous experience does not settle every later choice. Because she was uncertain about that biscuit, she chose not to eat it.","The organiser did not ask another student to guess whether it was safe. Instead, he offered Lisa the space to follow her own care plan and decide about her food. The group also avoided describing a food as suitable for everyone simply because it contained no visible nuts. Questions about uncertain ingredients were directed to someone who could provide reliable product information.","After the meeting, Lisa said the clear labels had made participation easier. She had not wanted a public discussion of her medical history. A simple question in advance and access to accurate information had helped her make her own decision."],"zh":"護理班辦讀書會前先詢問飲食需求。Lisa 有食物過敏，希望自己確認包裝，因此主辦者保留原包裝，不把點心全部倒進無標示的碗。有人給她看似吃過的餅乾，她仍核對當次成分，因為配方可能改變；不確定時就不吃。主辦者不請同學猜安全性，也不因看不到堅果就說人人都能吃，而是讓 Lisa 依自己的照護計畫選擇，必要時詢問能提供可靠成分資訊的人。她感謝資訊可取得，也不希望公開討論自己的病史。","qs":[{"type":"main","q":"What made the meeting easier for Lisa?","options":["Being asked to describe her full medical history publicly","Other students choosing every snack for her","Having information and space to make her own food choices"],"answer":2,"why":"文章重點是尊重選擇並提供可查核的資訊。"},{"type":"detail","q":"Why were the original wrappers kept?","options":["Lisa wanted to check package information herself.","The organiser wanted to count empty packets.","The classroom had no rubbish bin."],"answer":0,"why":"首段說她偏好自己看包裝，主辦者因而保留。","evidence":"One student, Lisa, said that she had a food allergy and preferred to check packages herself."},{"type":"reference","q":"What does \\"it\\" in \\"she chose not to eat it\\" mean?","options":["The ingredient list","The biscuit","The meeting plan"],"answer":1,"why":"該段一直談那片成分不確定的餅乾。","evidence":"Because she was uncertain about that biscuit, she chose not to eat it."},{"type":"vocab","q":"What does \\"relying on\\" mean in paragraph 2?","options":["Writing a label on","Moving away from","Depending on"],"answer":2,"why":"她沒有只依靠外觀判斷，而是讀成分。","evidence":"She read the current ingredient list rather than relying on its appearance."},{"type":"evidence","q":"Why was eating a similar product earlier not enough?","options":["A product's recipe can change.","All biscuits contain the same ingredients.","Packages are never useful for food choices."],"answer":0,"why":"第三句明確指出熟悉產品的配方也可能更動。","evidence":"The recipe on a familiar product can change, so a previous experience does not settle every later choice."},{"type":"detail","q":"What did the organiser avoid asking classmates to do?","options":["Bring their study notes","Guess whether a food was safe for Lisa","Keep the original wrappers"],"answer":1,"why":"第三段開頭說他沒有請同學猜安全性。","evidence":"The organiser did not ask another student to guess whether it was safe."},{"type":"evidence","q":"What can be inferred about Lisa's privacy preference?","options":["She wanted to hide every food label.","She wanted the organiser to announce her history.","She wanted practical support without discussing all her medical details."],"answer":2,"why":"她不想公開談病史，但歡迎清楚標示與事前詢問。","evidence":"She had not wanted a public discussion of her medical history."}]},{"id":"b1-m-feedback-round","level":"B1","band":"mid","title":"A Different Partner, a Different Question","topic":"學習回饋","words":209,"paras":["In an English workshop, nursing students brought short explanations of classroom tasks. The teacher arranged three feedback rounds, with a different partner in each round. Students first thought that repeating the same explanation would be boring, but the questions changed each time.","In the first round, Ada's partner understood the topic but could not tell which action came first. Ada added a time word to the opening sentence. In the second round, another partner noticed a term that had not been explained. She kept the necessary term and added a simple meaning beside it.","The final partner was asked to describe the task without looking at Ada's paper. His description included the correct order but missed the reason for one action. Ada realised that her revision had improved the sequence without explaining every important connection. She added a short reason and checked it with the teacher before changing her final version.","At the end, the class compared the original and revised explanations. The teacher did not ask them to count how many comments they had received. Instead, they identified which comments had led to a clear improvement and explained why. Ada left with fewer changes than some classmates, but she could show how each helped readers follow her meaning."],"zh":"護理學生英文工作坊分三輪，每輪換不同夥伴聽同一份課堂任務說明。Ada 第一輪發現順序不清楚，便加時間詞；第二輪發現術語未解釋，保留必要術語並補白話意思。第三位夥伴不看稿重述時，順序說對了，卻漏掉一個動作的原因，她才發現因果連結還不清楚，於是補理由並請老師確認。最後大家比較修改前後，重點不是收到多少意見，而是每個改動如何幫助讀者理解。","qs":[{"type":"main","q":"What is the main lesson about feedback?","options":["Its value depends on how it improves understanding.","More comments always mean a better explanation.","A repeated explanation never produces new information."],"answer":0,"why":"結尾強調每項改動的效果，而非評論數量。"},{"type":"detail","q":"What did Ada add after the first round?","options":["A new patient name","A time word","A longer title only"],"answer":1,"why":"第一輪發現先後不清，因此加時間詞。","evidence":"Ada added a time word to the opening sentence."},{"type":"reference","q":"What does \\"each\\" in the last sentence refer to?","options":["Each nursing student's name","Each workshop room","Each change Ada made"],"answer":2,"why":"最後一句談她的修改清單。","evidence":"Ada left with fewer changes than some classmates, but she could show how each helped readers follow her meaning."},{"type":"vocab","q":"What does \\"sequence\\" mean here?","options":["The order of actions","The price of the workshop","A list of difficult terms"],"answer":0,"why":"該段提到 correct order，與 sequence 相呼應。","evidence":"Ada realised that her revision had improved the sequence without explaining every important connection."},{"type":"evidence","q":"What showed that the reason for an action was still unclear?","options":["The first partner knew the topic.","The final partner left it out when describing the task.","Ada used a different pen."],"answer":1,"why":"第三輪重述漏掉原因，反映該連結尚未說清楚。","evidence":"His description included the correct order but missed the reason for one action."},{"type":"detail","q":"Who checked Ada's added reason before her final version?","options":["A hospital patient","The first partner's family","The teacher"],"answer":2,"why":"第三段最後一句說她先與老師核對。","evidence":"She added a short reason and checked it with the teacher before changing her final version."},{"type":"evidence","q":"Why did changing partners help?","options":["Different listeners noticed different problems.","Each partner gave Ada the same complete answer.","The partners removed the need for revision."],"answer":0,"why":"第一段說每次提問都不同，後文呈現順序、用語、原因三種問題。","evidence":"Students first thought that repeating the same explanation would be boring, but the questions changed each time."}]},{"id":"b1-m-health-post","level":"B1","band":"mid","title":"Before Sharing the Health Post","topic":"健康資訊判讀","words":214,"paras":["A class group received a message claiming that a new drink could prevent every common illness. The message included a dramatic picture and a link to the sales page. Several students wanted to share it with their families because it sounded simple and helpful.","Nora opened the page but did not forward the message immediately. She looked for the author, the date of review, and links to the evidence behind the claim. The page named the company, but she could not find a clear explanation of how its health information was checked. The large customer comments did not answer that question.","Nora compared the claim with information from a public health organisation and brought the difference to class. Her teacher explained that a professional-looking website could still have a commercial purpose. The class discussed why an attractive story was not the same as reliable evidence. They also considered whether the page fairly described limitations instead of promising a perfect result.","Nora decided not to share the original claim as health advice. She wrote a short message encouraging classmates to check sources before passing on similar posts. Her aim was not to diagnose anyone or choose treatment for a relative. It was to slow the sharing process enough to ask useful questions about the information."],"zh":"班級群組收到一則宣稱某飲品能預防所有常見疾病的訊息，連結也販售該飲品。Nora 沒有立刻轉傳，而是找作者、審查日期與證據來源，發現找不到內容如何審核的清楚說明，顧客留言也無法回答。她拿公共衛生機構資料比較，並在課堂討論網站即使看似專業仍可能以銷售為目的。最後她不把原宣稱當健康建議轉傳，而是提醒同學查來源；目的不是替親友診斷或選治療，而是讓資訊傳播前多一點查核。","qs":[{"type":"main","q":"What is the writer encouraging readers to do?","options":["Trust every message with a dramatic picture","Evaluate health claims before sharing them","Choose treatment from customer comments"],"answer":1,"why":"故事示範轉傳前查作者、日期、證據與目的。"},{"type":"detail","q":"What was sold on the linked page?","options":["Nursing textbooks","Tickets to a school event","The drink mentioned in the message"],"answer":2,"why":"首段說連結頁面販售該飲品。","evidence":"The message included a dramatic picture and a link to the sales page."},{"type":"reference","q":"What does \\"that question\\" refer to in paragraph 2?","options":["How the page's health information was checked","How many classmates had phones","Where Nora kept her school notes"],"answer":0,"why":"承接前一句對資訊審查方式的疑問。","evidence":"The page named the company, but she could not find a clear explanation of how its health information was checked."},{"type":"vocab","q":"What does \\"commercial\\" mean here?","options":["Always written by a hospital","Related to selling products or services","Available only in another language"],"answer":1,"why":"頁面販售產品，commercial 指商業銷售用途。","evidence":"Her teacher explained that a professional-looking website could still have a commercial purpose."},{"type":"evidence","q":"What shows that Nora wanted evidence beyond advertising?","options":["She liked the dramatic picture.","She counted the largest customer comments.","She searched for sources behind the claim."],"answer":2,"why":"她查看宣稱背後證據連結，顯示不只看廣告。","evidence":"She looked for the author, the date of review, and links to the evidence behind the claim."},{"type":"detail","q":"What did Nora decide about the original claim?","options":["Not to share it as health advice","To present it as a proven cure","To ask relatives to replace their treatment"],"answer":0,"why":"第四段首句明確寫她的決定。","evidence":"Nora decided not to share the original claim as health advice."},{"type":"evidence","q":"What can be concluded about a polished website?","options":["It cannot be selling anything.","Its appearance does not establish the quality of its evidence.","It always describes every limitation fairly."],"answer":1,"why":"老師指出外觀專業仍可能有商業目的，外觀不足以證明可信。","evidence":"Her teacher explained that a professional-looking website could still have a commercial purpose."}]},{"id":"b1-h-record-choice","level":"B1","band":"hard","title":"A Record That Someone Will Use","topic":"就診準備","words":243,"paras":["A community nursing class compared two ways of recording symptoms before an appointment: a phone app and a paper notebook. The teacher asked students to judge how useful each method would be for a particular person, rather than choose a winner for everyone. They worked with a fictional older adult who lived with his daughter.","One group supported the app because entries could be organised by date and found quickly. The daughter could help her father enter a short note when he needed assistance. However, he sometimes left his phone charging in another room and forgot the password. A useful feature offered little help if he could not open the record.","Another group preferred a notebook that could stay beside his usual chair. He already used paper to remember shopping, so this method felt familiar. Yet loose sheets were easily misplaced, and a long page of unrelated details might be difficult to discuss during a short visit. The group suggested a bound notebook with clear dates and space for questions.","The class finally chose the notebook for this example, while keeping the app as an option for a different person. Their teacher stressed that neither format could diagnose a symptom or replace professional advice. The record was intended to support a conversation with the care team. Students planned to ask the fictional user to find one entry and explain it, because choosing a format was only the first step towards making it useful."],"zh":"社區護理課比較看診前用手機或筆記本記錄症狀。支持手機的一組覺得按日期找資料方便，但情境中的長者有時找不到充電中的手機，也忘記密碼。支持紙本的一組認為長者已習慣寫購物清單，但散頁容易遺失、內容太雜也不利看診討論，所以提議有裝訂、標日期並留問題欄的筆記本。全班依這位虛構使用者選紙本，並沒有說它適合所有人。兩種工具都不能診斷或取代專業建議；重點是使用者真的找得到、說得清楚。","qs":[{"type":"main","q":"Why does the passage compare the two formats?","options":["To prove that phone apps cannot store dates","To recommend paper for every patient","To show that a useful choice depends on the person using it"],"answer":2,"why":"老師要求按個人情況判斷，結論也沒有宣布所有人都適用同一方式。"},{"type":"detail","q":"What problem did the fictional adult have with his phone?","options":["He sometimes forgot the password.","His daughter refused all help.","The app could not display any dates."],"answer":0,"why":"第二段直接指出密碼問題。","evidence":"However, he sometimes left his phone charging in another room and forgot the password."},{"type":"reference","q":"What does \\"this method\\" in paragraph 3 refer to?","options":["Charging a phone in another room","Using a paper notebook","Asking the teacher to diagnose symptoms"],"answer":1,"why":"前句提出筆記本，後句以購物紙本習慣說明熟悉度。","evidence":"Another group preferred a notebook that could stay beside his usual chair."},{"type":"vocab","q":"What does \\"misplaced\\" mean in paragraph 3?","options":["Printed in several different colours","Reviewed carefully by a professional","Put somewhere and then difficult to find"],"answer":2,"why":"散頁的缺點是容易找不到，並非內容被修改。","evidence":"Yet loose sheets were easily misplaced, and a long page of unrelated details might be difficult to discuss during a short visit."},{"type":"evidence","q":"What supports testing the record with the user after choosing it?","options":["The students still needed to know whether he could find and explain an entry.","The students had already proved that every app was unsafe.","The teacher wanted to stop all symptom recording."],"answer":0,"why":"最後一句把實際查找與說明列為下一步，可推知選好工具還不夠。","evidence":"Students planned to ask the fictional user to find one entry and explain it, because choosing a format was only the first step towards making it useful."},{"type":"tfng","q":"The class selected the notebook for every person in the community.","options":["True","False","Not Given"],"answer":1,"why":"文章只為這個例子選筆記本，並保留手機供其他人選擇。","evidence":"The class finally chose the notebook for this example, while keeping the app as an option for a different person."},{"type":"detail","q":"What was the record meant to support?","options":["A diagnosis made by the daughter alone","A decision to cancel all appointments","A conversation with the care team"],"answer":2,"why":"最後一段直接說用途是協助與照護團隊對話。","evidence":"The record was intended to support a conversation with the care team."}]},{"id":"b1-h-teachback-time","level":"B1","band":"hard","title":"Time for One More Explanation","topic":"照護溝通","words":235,"paras":["During a nursing seminar, students discussed whether a final understanding check was worth the extra time before a patient went home. The example involved a new care instruction that had already been explained and written on a sheet. Some students felt that asking another question would repeat work when the ward was busy.","Maggie supported asking the person to describe the plan in their own words. She argued that a polite nod did not show which parts were understood. In the example, a patient correctly remembered the appointment day but confused two contact numbers. A brief explanation of the difference could help before the person left.","Ben agreed with the goal but worried about the way the check might sound. If a nurse presented it like a school test, a patient might feel embarrassed. He suggested explaining that the nurse wanted to check how clearly the information had been given. The patient should also be able to refer to the written sheet while answering.","The teacher said that both concerns could guide a better conversation. The nurse could focus on the most important actions, listen without blame, and explain unclear points again. Another check would then show whether the new explanation had helped. The class did not measure how many minutes the process saved or added. Instead, it practised a respectful way to discover a misunderstanding that a simple yes or no question might miss."],"zh":"護理研討課討論出院前再確認理解是否值得花時間。有同學認為已經口頭說明並發單張，再問很重複。Maggie 認為點頭不代表每點都懂，讓病人用自己的話說，能發現回診日期記對、聯絡電話卻搞混的情況。Ben 支持目的，但擔心像學校考試讓病人難堪，建議說明是在確認護理師自己講得清不清楚，也允許查看單張。老師建議聚焦重要行動、不責備，釐清後再確認。課堂沒有測算省下幾分鐘，而是在練習尊重病人的理解確認方式。","qs":[{"type":"main","q":"What is the main issue discussed?","options":["How to check understanding usefully and respectfully","How to remove every written instruction","How to test a patient's memory for an exam"],"answer":0,"why":"正反意見都圍繞理解確認的用途、時間與說法。"},{"type":"detail","q":"What did the example patient confuse?","options":["The patient's own name","Two contact numbers","Every appointment day"],"answer":1,"why":"第二段最後兩句說明混淆的是聯絡電話。","evidence":"In the example, a patient correctly remembered the appointment day but confused two contact numbers."},{"type":"reference","q":"What does \\"both concerns\\" refer to?","options":["Printing costs and the weather","The patient's age and the hospital address","Finding misunderstanding and avoiding embarrassment"],"answer":2,"why":"前兩段分別提出理解問題與被考試的感受。","evidence":"The teacher said that both concerns could guide a better conversation."},{"type":"vocab","q":"What does \\"without blame\\" mean here?","options":["Without treating the misunderstanding as someone's fault","Without listening to the patient's answer","Without using any written information"],"answer":0,"why":"老師強調尊重地聆聽，再改善說明。","evidence":"The nurse could focus on the most important actions, listen without blame, and explain unclear points again."},{"type":"evidence","q":"Why did Ben suggest explaining the purpose of the check?","options":["He wanted to hide all misunderstandings.","He wanted to avoid making the patient feel tested.","He believed patients must answer without a sheet."],"answer":1,"why":"上一句指出若像學校考試，病人可能覺得難堪。","evidence":"If a nurse presented it like a school test, a patient might feel embarrassed."},{"type":"tfng","q":"The passage recommends allowing patients to refer to the written sheet during the check.","options":["True","False","Not Given"],"answer":0,"why":"第三段明確說可參考書面資料回答。","evidence":"The patient should also be able to refer to the written sheet while answering."},{"type":"evidence","q":"What can be concluded about the activity's timing results?","options":["The passage provides no measured time comparison.","The process always saved exactly five minutes.","The process was proved to take no extra time."],"answer":0,"why":"文中直接說班級沒有量測增加或節省的分鐘數。","evidence":"The class did not measure how many minutes the process saved or added."}]},{"id":"b1-h-classroom-balance","level":"B1","band":"hard","title":"Which Lessons Belong Online?","topic":"護理學習方式","words":237,"paras":["A nursing school asked a class to suggest which parts of a future course could be studied online. The students were not being asked to remove supervised practice or change professional requirements. Their task was to compare ways of preparing for the same classroom activities and explain the reasons for their choices.","Yun favoured short recorded explanations that students could watch before a lesson. She travelled a long distance to school and liked being able to pause a recording at an unfamiliar word. She also thought a replay could help when she revised after class. However, her internet connection at home sometimes interrupted the sound.","Peter preferred meeting in a classroom because he could ask a question as soon as it arose. He learned from hearing classmates describe mistakes that he had not considered. Yet he accepted that a single live explanation could move too quickly for some learners. A student who needed more time might miss the next idea while writing down the first.","The group proposed a combination: brief recordings for preparation, followed by classroom discussion and the planned supervised practice. It also asked for written summaries that could be read when a connection failed. The teacher said the plan would need to be tried with actual students before its usefulness could be judged. The proposal therefore included a short review after two weeks, asking what learners could explain and where they still needed help."],"zh":"護理學校請學生比較課前準備方式，沒有要取消指導下的實作或改變專業要求。Yun 喜歡短錄影，可以在不熟的字暫停、課後重看，也方便通勤者，但家中網路有時中斷。Peter 喜歡現場立即提問、聽同學的不同問題，卻承認一次講解可能太快，邊抄前一點就漏掉下一點。小組提出短錄影、現場討論與原定指導實作並用，加上斷線時可看的文字摘要。老師要求先試行，再於兩週後了解學生能說明什麼、仍卡在哪裡。","qs":[{"type":"main","q":"What does the group propose?","options":["Replacing all practical lessons with videos","Combining recordings with discussion and supervised practice","Choosing one format before asking any learners"],"answer":1,"why":"最後一段提出各方式搭配的方案。"},{"type":"detail","q":"Why did Yun like recorded explanations?","options":["They removed all internet problems.","They meant she never needed to revise.","She could pause at an unfamiliar word."],"answer":2,"why":"第二段明確提出暫停功能。","evidence":"She travelled a long distance to school and liked being able to pause a recording at an unfamiliar word."},{"type":"reference","q":"What does \\"it\\" in \\"as soon as it arose\\" refer to?","options":["A question","A written summary","A journey to school"],"answer":0,"why":"前半句說可立刻提出 a question。","evidence":"Peter preferred meeting in a classroom because he could ask a question as soon as it arose."},{"type":"vocab","q":"What does \\"revised\\" mean in paragraph 2?","options":["Changed the school's address","Studied material again","Cancelled a future lesson"],"answer":1,"why":"此處是學生課後複習，而非修改文件。","evidence":"She also thought a replay could help when she revised after class."},{"type":"evidence","q":"What shows that Peter recognised a weakness in live explanations?","options":["He wanted every question answered online.","He refused to listen to classmates.","He accepted that their pace could be too fast for some learners."],"answer":2,"why":"第三段直接承認一次現場講解可能過快。","evidence":"Yet he accepted that a single live explanation could move too quickly for some learners."},{"type":"tfng","q":"Most students in the school already had reliable home internet.","options":["True","False","Not Given"],"answer":2,"why":"文章只提 Yun 個人的連線會中斷，沒有全校學生的比例。","evidence":"However, her internet connection at home sometimes interrupted the sound."},{"type":"detail","q":"What would the review after two weeks ask about?","options":["How many new buildings the school owned","What learners could explain and where they needed help","Which students wanted to become teachers"],"answer":1,"why":"最後一句清楚列出追蹤項目。","evidence":"The proposal therefore included a short review after two weeks, asking what learners could explain and where they still needed help."}]},{"id":"b1-h-volunteer-roster","level":"B1","band":"hard","title":"A Fair Roster for the Health Fair","topic":"志工與實習規劃","words":235,"paras":["A student club planned a weekend health information fair with qualified staff supervising the health activities. Students would welcome visitors, explain where to queue, and organise printed materials. Before the event, the club had to decide how to share the morning and afternoon duties among volunteers with different schedules.","The organiser first suggested giving everyone an equal number of hours. This seemed fair because no student would carry a much longer shift than another. However, two members had already booked compulsory placement activities on Saturday morning. They could help later but could not simply move those appointments to another day.","One volunteer proposed allowing members to arrive whenever they were free. Others worried that this would leave the entrance empty at busy times. Someone also needed to show the next volunteer where the materials were kept and explain any changes to the visitor route. A completely flexible arrangement could make these handovers difficult.","The club agreed to collect availability first and assign named time slots afterwards. Members could exchange a slot only after another person agreed and the organiser updated the shared roster. A short overlap between shifts would give volunteers time to pass on information. The final plan did not give every person the same starting time, but it made each responsibility clear. At the next meeting, the club would review both the hours worked and the periods when visitors had waited without help."],"zh":"學生社團辦健康資訊活動，由合格人員負責健康活動的指導，學生協助接待、排隊與資料整理。最初提議每人相同時數，但有同學週六上午已排定必修實習，不能任意更動。有人主張有空再到，其他人擔心尖峰時入口沒人，也不利交接。最後先收集可服務時間，再指定時段；換班須有人接手並由召集人更新名單。班次短暫重疊便於交接。公平不必是同樣起始時間，還要責任清楚，事後也檢討工時與訪客等不到協助的時段。","qs":[{"type":"main","q":"Which idea best explains the final plan?","options":["Fairness means giving everyone an identical start time.","Volunteer duties should be decided only after visitors arrive.","Fairness should consider availability as well as clear coverage."],"answer":2,"why":"最後方案兼顧個人時間與每個時段有人負責。"},{"type":"detail","q":"Why could two members not take the first suggested morning shift?","options":["They had compulsory placement activities.","They had already finished all volunteer duties.","They were responsible for writing the final review."],"answer":0,"why":"第二段說兩人已有必修實習活動。","evidence":"However, two members had already booked compulsory placement activities on Saturday morning."},{"type":"reference","q":"What does \\"these handovers\\" refer to?","options":["Moving compulsory appointments to another day","Passing information and materials between volunteers","Giving health advice without supervision"],"answer":1,"why":"前句描述讓接班者知道資料位置與路線變更。","evidence":"Someone also needed to show the next volunteer where the materials were kept and explain any changes to the visitor route."},{"type":"vocab","q":"What does \\"roster\\" mean in the final paragraph?","options":["A leaflet giving advice to visitors","A report describing what happened last year","A schedule showing who will work at each time"],"answer":2,"why":"前文說指定時段與換班後更新，所以 roster 是工作班表。","evidence":"Members could exchange a slot only after another person agreed and the organiser updated the shared roster."},{"type":"evidence","q":"Why was complete flexibility rejected?","options":["Visitors might arrive when nobody was covering the entrance.","It would give every member too many compulsory appointments.","It prevented the organiser from collecting any availability."],"answer":0,"why":"志工擔心忙碌時入口沒有人，直接支持指定責任時段的需要。","evidence":"Others worried that this would leave the entrance empty at busy times."},{"type":"tfng","q":"A member could exchange a slot without telling the organiser.","options":["True","False","Not Given"],"answer":1,"why":"交換班次須先有人同意，且召集人要更新共用班表。","evidence":"Members could exchange a slot only after another person agreed and the organiser updated the shared roster."},{"type":"detail","q":"What would the review include besides the hours worked?","options":["The number of staff cars in the car park","The cost of changing every placement appointment","Times when visitors waited without assistance"],"answer":2,"why":"最後一句直接列出這個檢討項目。","evidence":"At the next meeting, the club would review both the hours worked and the periods when visitors had waited without help."}]},{"id":"b1-h-correction-choice","level":"B1","band":"hard","title":"When Should a Partner Correct You?","topic":"英文溝通練習","words":243,"paras":["Two nursing students disagreed about how to correct each other during English speaking practice. They were preparing fictional conversations for class, and neither wanted to practise with real patient information. Their disagreement was about timing: should a partner stop every error immediately, or wait until the speaker had finished?","Ivy preferred immediate correction because she worried about repeating the same mistake many times. For example, she often used a present tense when describing something that had happened yesterday. A quick reminder helped her notice the pattern. However, she sometimes lost the rest of her story when her partner interrupted several sentences in a row.","Sam preferred to hear a complete message before giving feedback. He thought this allowed the speaker to practise connecting ideas and dealing with a moment of uncertainty. Ivy agreed that flow mattered, but she noticed another problem: by the end, they sometimes forgot the exact sentence that needed attention. General advice such as being more careful did not show her what to change.","Their teacher suggested agreeing on one focus before each attempt. During a fluency round, the listener could note a short example and discuss it afterwards. During a tense practice round, an agreed signal could invite the speaker to try the sentence again. The students used both approaches in later sessions. They learned that useful correction depended on the aim of the activity and the specific help a partner needed, rather than one rule for every conversation."],"zh":"兩位護生用虛構情境練英文，爭論該立即打斷糾錯，還是說完再回饋。Ivy 喜歡立即提醒，以免一直把昨天的事說成現在式，但多次被打斷也會忘記原來的故事。Sam 想先聽完整訊息，練習連接想法與應付不確定；不過等到最後，有時已記不起需要修改的原句，「再小心一點」太籠統。老師建議先約定本次重點：流暢練習先記例句、結束後討論；時態練習可用約定訊號請對方重說。兩人之後依練習目的選擇回饋時機。","qs":[{"type":"main","q":"What does the story suggest about correction?","options":["Its timing should fit the purpose of the practice.","It should always interrupt every sentence.","It is unnecessary when students know each other."],"answer":0,"why":"結論強調依活動目的與夥伴需要調整。"},{"type":"detail","q":"What mistake did Ivy often make?","options":["Using a fictional name instead of a real one","Using a present tense for an event from yesterday","Forgetting to invite her partner to class"],"answer":1,"why":"第二段具體說明她常犯的時態錯誤。","evidence":"For example, she often used a present tense when describing something that had happened yesterday."},{"type":"reference","q":"What does \\"this\\" in \\"He thought this allowed\\" refer to?","options":["Giving a signal after every word","Preparing a list of real patients","Listening to a complete message before giving feedback"],"answer":2,"why":"承接 Sam 喜歡先聽完整訊息再回饋的方式。","evidence":"Sam preferred to hear a complete message before giving feedback."},{"type":"vocab","q":"What does \\"specific\\" mean in the final sentence?","options":["Clear and particular","Very frequent","Given to a large crowd"],"answer":0,"why":"文中以具體原句對比「再小心一點」這類籠統建議。","evidence":"They learned that useful correction depended on the aim of the activity and the specific help a partner needed, rather than one rule for every conversation."},{"type":"evidence","q":"What supports Ivy's concern about waiting too long to comment?","options":["Sam refused to discuss grammar in any session.","They sometimes forgot the exact sentence needing correction.","Their teacher never listened to their practice."],"answer":1,"why":"第三段明說到最後可能已忘記確切原句。","evidence":"Ivy agreed that flow mattered, but she noticed another problem: by the end, they sometimes forgot the exact sentence that needed attention."},{"type":"tfng","q":"The pair used both correction approaches in later sessions.","options":["True","False","Not Given"],"answer":0,"why":"第四段直接指出後來兩種方式都有使用。","evidence":"The students used both approaches in later sessions."},{"type":"detail","q":"What could the listener do during a fluency round?","options":["Note an example and discuss it after the attempt","Stop the speaker after every word","Avoid giving any feedback after the attempt"],"answer":0,"why":"第四段給出流暢練習的建議做法。","evidence":"During a fluency round, the listener could note a short example and discuss it afterwards."}]},{"id":"b1-h-hospital-directions","level":"B1","band":"hard","title":"A Map for More Than One Visitor","topic":"醫院導引","words":238,"paras":["A hospital volunteer team reviewed directions from a public entrance to a teaching room. The room was used for scheduled family information sessions, and new visitors often stopped at the desk to ask for help. The team wanted to make the route easier without assuming that everyone used the same kind of information.","A student proposed a large code that visitors could scan with a phone to open a map. The map could be updated without printing another page, and users could enlarge the text. Several volunteers liked this idea. Others pointed out that a phone might have a flat battery or no connection inside the building.","Another volunteer suggested arrows on paper signs at every turning point. These would be visible to people who never opened the online map. However, signs from several departments already filled the entrance wall. Adding more without reviewing the existing ones might make the important direction harder to find, rather than easier.","The team tested a small combination of clear signs, an optional online map, and help at the desk. Two volunteers followed the route without earlier instructions and described where they hesitated. The team then moved one sign and changed a room label that differed from the appointment message. Its report did not claim that the new design would work for every visitor. It recommended checking the route again when rooms changed and continuing to ask visitors what information they needed."],"zh":"醫院志工團隊檢查公共入口到衛教教室的路線，希望不同使用習慣的訪客都找得到。有人提議掃碼看地圖，更新容易，也能放大文字，但手機可能沒電或沒網路。另一人提議每個轉角貼箭頭，卻發現入口已滿是不同單位的公告，再加可能更混亂。團隊試用少量清楚標示、可選用的網路地圖和服務台協助，請未先看過指示的志工實走。測試後調整標示位置，以及與預約訊息不一致的教室名稱，並建議空間變動時重查、持續聽取訪客需要。","qs":[{"type":"main","q":"What is the purpose of comparing the two ideas?","options":["To decide which visitors should be refused help","To choose directions that work through more than one method","To prove that every paper sign causes confusion"],"answer":1,"why":"正反比較後提出標示、地圖與人員協助的組合。"},{"type":"detail","q":"What problem could stop someone using the online map?","options":["A large screen with clear text","An updated room label","A phone with no battery power"],"answer":2,"why":"第二段明列手機沒電或無連線。","evidence":"Others pointed out that a phone might have a flat battery or no connection inside the building."},{"type":"reference","q":"What does \\"These\\" at the start of paragraph 3's second sentence mean?","options":["The paper signs with arrows","The online maps on phones","The family information sessions"],"answer":0,"why":"代名詞接續前一句的紙本箭頭標示。","evidence":"Another volunteer suggested arrows on paper signs at every turning point."},{"type":"vocab","q":"What does \\"hesitated\\" mean in paragraph 4?","options":["Arrived earlier than expected","Paused because they were unsure","Printed a new appointment message"],"answer":1,"why":"試走者回報哪裡不確定、停頓，讓團隊改善指示。","evidence":"Two volunteers followed the route without earlier instructions and described where they hesitated."},{"type":"evidence","q":"Why might adding more signs make the route less clear?","options":["The teaching room had no scheduled sessions.","Visitors had been told never to read signs.","The entrance wall already held many departmental signs."],"answer":2,"why":"第三段指出牆上原有許多公告，是增加混亂的原因。","evidence":"However, signs from several departments already filled the entrance wall."},{"type":"tfng","q":"The online map cost less than all the paper signs.","options":["True","False","Not Given"],"answer":2,"why":"文章說電子地圖可以免重印就更新，也能放大文字；全文都沒有提供電子地圖與紙本指標的成本比較。","evidence":"The map could be updated without printing another page, and users could enlarge the text."},{"type":"detail","q":"Why was one room label changed?","options":["Every visitor had requested a longer name.","It did not match the appointment message.","The room was closed permanently."],"answer":1,"why":"第四段說標示與預約訊息不同。","evidence":"The team then moved one sign and changed a room label that differed from the appointment message."}]},{"id":"b1-h-walking-club","level":"B1","band":"hard","title":"A Challenge With More Than One Goal","topic":"社區健康活動","words":239,"paras":["A college walking club considered publishing a weekly table of members' step counts. Supporters hoped that a friendly competition would encourage students to join each other during free periods. The club leader asked for comments before introducing the table, because the activity was meant to welcome people with different abilities and schedules.","One member, Rob, liked clear numbers that showed his progress. He said that comparing totals with a friend helped him remember the activity on busy days. He wanted the table to include names so members could congratulate each other. However, several people were uncomfortable sharing personal activity information with the whole club.","Nora raised a different concern. Some members worked long shifts, while others had mobility needs or individual advice from their care teams. A single target might not suit all of them, and a ranking could reward free time as well as effort. She proposed letting members choose suitable personal goals and describe one change they had managed.","The club decided to try an optional progress board without a public ranking. People could share a chosen goal or join walks without posting any result. The leader made clear that club activities did not replace individual health advice. After a month, the club would ask both regular walkers and people who had stopped attending whether the arrangement felt welcoming. It wanted to learn about participation, rather than judge success only by the highest number on a screen."],"zh":"大學健走社想公布每週步數排行，支持者希望友善競爭能增加參與。Rob 喜歡數字看得出進步，也想公開名字彼此鼓勵，但有人不願分享個人活動資訊。Nora 提醒成員工時、行動能力與個別照護建議不同，單一目標未必合適，排行也可能反映空閒時間。她建議自選合適目標、分享自己做到的改變。社團最後試行自願進度板，不公開排名，也可只參加不張貼。活動不能取代個別健康建議，之後會詢問持續參與者及停止參與者，了解是否讓大家願意加入。","qs":[{"type":"main","q":"What is the main reason for changing the original proposal?","options":["The club could no longer count steps on any device.","Every member had asked for a stricter competition.","The club wanted to include people with different needs."],"answer":2,"why":"意見涉及隱私、時間與能力差異，最後目標是包容參與。"},{"type":"detail","q":"Why did Rob like comparing totals with a friend?","options":["It helped him remember the activity when busy.","It replaced every other personal goal.","It allowed him to decide another person's care plan."],"answer":0,"why":"第二段直接說明比較數字對他的幫助。","evidence":"He said that comparing totals with a friend helped him remember the activity on busy days."},{"type":"reference","q":"Who does \\"them\\" in \\"all of them\\" refer to?","options":["The care teams in every hospital","Club members with different situations","The names on Rob's phone"],"answer":1,"why":"前句介紹工時、行動需求與照護建議不同的成員。","evidence":"Some members worked long shifts, while others had mobility needs or individual advice from their care teams."},{"type":"vocab","q":"What does \\"ranking\\" mean here?","options":["A private explanation from a care team","A list of suitable meeting places","An order from the highest result to the lowest"],"answer":2,"why":"文章把排名與最高數字相比，ranking 指依結果排序。","evidence":"A single target might not suit all of them, and a ranking could reward free time as well as effort."},{"type":"evidence","q":"What suggests that posting a result was not required?","options":["Members could join walks without posting anything.","Rob wanted everyone's name on the first table.","The club planned to count every private journey."],"answer":0,"why":"最後一段明說可以參加健走、不張貼結果。","evidence":"People could share a chosen goal or join walks without posting any result."},{"type":"tfng","q":"The leader said the club could replace personal health advice.","options":["True","False","Not Given"],"answer":1,"why":"文中明確說社團活動不能取代個別健康建議。","evidence":"The leader made clear that club activities did not replace individual health advice."},{"type":"detail","q":"Whose opinions would the club seek after a month?","options":["Only the person with the highest number","Only members of the care teams","Regular walkers and people who had stopped attending"],"answer":2,"why":"最後一段列出兩種參與狀況的人。","evidence":"After a month, the club would ask both regular walkers and people who had stopped attending whether the arrangement felt welcoming."}]},{"id":"b1-h-family-updates","level":"B1","band":"hard","title":"Planning a Family Update","topic":"家屬溝通","words":240,"paras":["In a classroom scenario, a patient expected a longer hospital stay and wanted a cousin to receive updates. Several other relatives also asked for news. The student group had to suggest a communication plan while respecting the fictional patient's wishes and the care team's procedures. The exercise did not give students permission to share real information.","One student favoured inviting all the relatives to the same discussion. This could reduce repeated explanations and allow everyone to hear the same message. Another student pointed out that the patient had chosen one cousin, not the whole family. A large meeting might also leave less room for the patient to ask a private question.","A second proposal was to give the chosen cousin a clear way to contact the team at an agreed time. Supporters thought this would make routine communication easier to organise. However, the cousin should not be treated as the person who could answer every question about the patient's preferences. The patient still needed opportunities to speak and change the communication arrangement.","The group recommended first confirming what the patient wanted shared and with whom, following the setting's procedures. The responsible staff could then agree on an appropriate contact plan and explain how urgent concerns should be raised. A routine update time was not meant to delay reporting a new concern. The teacher praised the distinction between making communication more organised and allowing convenience to decide who received personal information."],"zh":"課堂情境中，一位需要較長住院的病人希望表親接收近況，其他親屬也想知道。有人提議一次找齊所有人，減少重複說明，但另一人指出病人只選了一人，大型會談也可能不方便提出私密問題。另一方案是讓選定的表親按約定方式聯絡團隊，但仍須讓病人自己表達、調整安排，不能把表親當成所有偏好的代言人。團隊建議先依所在機構程序確認分享內容與對象，再由負責人員安排聯絡方式；例行近況時間不應延誤通報新的疑慮。","qs":[{"type":"main","q":"What principle guides the final recommendation?","options":["Organised communication should still respect the patient's choices.","The largest family group should decide all arrangements.","Convenience should determine who receives every detail."],"answer":0,"why":"最後強調安排方便與病人分享意願須分清楚。"},{"type":"detail","q":"Whom had the patient chosen to receive updates?","options":["Every relative who called","A cousin","The whole student group"],"answer":1,"why":"首句直接交代病人選的是表親。","evidence":"In a classroom scenario, a patient expected a longer hospital stay and wanted a cousin to receive updates."},{"type":"reference","q":"What does \\"This\\" in paragraph 2 refer to?","options":["Letting students share real patient records","Waiting until every question became urgent","Inviting all the relatives to one discussion"],"answer":2,"why":"承接前句一次邀所有家屬討論的提案。","evidence":"One student favoured inviting all the relatives to the same discussion."},{"type":"vocab","q":"What does \\"preferences\\" mean in paragraph 3?","options":["Personal wishes and choices","The visiting hours of every hospital","Medical terms written on a notice"],"answer":0,"why":"此處指病人自己想要的安排。","evidence":"However, the cousin should not be treated as the person who could answer every question about the patient's preferences."},{"type":"evidence","q":"Why was a meeting with the whole family questioned?","options":["No family member wanted to hear any update.","The patient had selected one cousin rather than everyone.","The patient had asked students to publish all details."],"answer":1,"why":"第二段直接提出提案與病人選擇不符。","evidence":"Another student pointed out that the patient had chosen one cousin, not the whole family."},{"type":"tfng","q":"The agreed routine update time was ten o'clock each morning.","options":["True","False","Not Given"],"answer":2,"why":"文章只提出約定時間，沒有給出確切時刻。","evidence":"A second proposal was to give the chosen cousin a clear way to contact the team at an agreed time."},{"type":"detail","q":"What should happen before choosing a contact plan?","options":["Confirm what the patient wants shared and with whom","Let the students send a message to every relative","Ask the cousin to remove the patient from discussions"],"answer":0,"why":"最後一段先確認內容與對象，再安排聯絡。","evidence":"The group recommended first confirming what the patient wanted shared and with whom, following the setting's procedures."}]},{"id":"b1-h-course-budget","level":"B1","band":"hard","title":"Choosing a Course You Can Attend","topic":"英文學習規劃","words":245,"paras":["Annie was comparing two ways to improve her English before a future nursing career abroad. One was an evening course with a fixed timetable and teacher feedback. The other was a free conversation group run by students. She could not comfortably fit both into her placement schedule, so she wrote down the advantages and limits of each.","The course offered regular lessons and a clear sequence of topics. Annie liked knowing what to prepare each week and having someone explain recurring mistakes. However, the classroom was far from her placement hospital. If a placement ended late, she would miss the beginning of a lesson even after paying for the full session.","The conversation group met near her dormitory and did not charge a fee. Its members could practise everyday topics in a relaxed setting, but they were not always able to explain grammar questions. Annie had also noticed that attendance changed each week. A friendly atmosphere alone would not guarantee practice with the nursing communication topics she wanted to study.","Before deciding, she asked the course organiser about its actual timetable and tried one meeting of the student group. She then chose the group for the current term and kept a list of grammar questions for her school teacher. She planned to reconsider the course when her placement schedule changed. Her decision was based on the practice she could realistically attend now, not on assuming that the cheapest or most expensive option was always better."],"zh":"Annie 為未來赴海外從事護理工作準備英文，比較有固定進度與教師回饋的晚間課，以及免費學生會話社團。晚間課能解釋常犯錯誤，但離實習醫院遠，若下班晚就會付費卻遲到。社團靠近宿舍、氣氛輕鬆且免費，卻未必能解答文法、每週出席也不同，不一定涵蓋她想練的護理溝通。她先查實際課表、試參加社團，這學期選能穩定出席的社團，把文法問題留給學校老師，實習時間改變再評估課程；選擇依當前需要與可行性，不只看價格。","qs":[{"type":"main","q":"What does Annie's decision illustrate?","options":["The free option always provides the best grammar teaching.","A learning option should fit present needs and practical limits.","A paid course is useful only for people who live abroad."],"answer":1,"why":"結論依目標、交通與實習時間選擇，沒有把價格當唯一標準。"},{"type":"detail","q":"What attracted Annie to the evening course?","options":["A location inside her dormitory","A guarantee that placement would finish early","A clear topic sequence and help with recurring mistakes"],"answer":2,"why":"第二段說明固定進度與教師解釋的優點。","evidence":"Annie liked knowing what to prepare each week and having someone explain recurring mistakes."},{"type":"reference","q":"What does \\"Its members\\" in paragraph 3 refer to?","options":["Members of the student conversation group","Organisers of the evening course","Staff at the placement hospital"],"answer":0,"why":"上一句剛介紹宿舍附近的會話社團。","evidence":"The conversation group met near her dormitory and did not charge a fee."},{"type":"vocab","q":"What does \\"recurring\\" mean in paragraph 2?","options":["Already corrected permanently","Happening repeatedly","Unrelated to language"],"answer":1,"why":"Annie 想請人解釋反覆出現的錯誤。","evidence":"Annie liked knowing what to prepare each week and having someone explain recurring mistakes."},{"type":"evidence","q":"Why did Annie plan to review her choice later?","options":["The passage says the group would close permanently.","Her teacher refused all grammar questions.","Her placement schedule could change."],"answer":2,"why":"文章明確說實習時程改變時再考慮課程。","evidence":"She planned to reconsider the course when her placement schedule changed."},{"type":"tfng","q":"Annie attended a student-group meeting before making her choice.","options":["True","False","Not Given"],"answer":0,"why":"最後一段第一句說她先試參加一次，再決定。","evidence":"Before deciding, she asked the course organiser about its actual timetable and tried one meeting of the student group."},{"type":"detail","q":"How would she seek help with grammar during the current term?","options":["Expect every group member to be a grammar expert","Keep questions to ask her school teacher","Stop writing down any language problems"],"answer":1,"why":"最後一段交代她把問題留給學校老師。","evidence":"She then chose the group for the current term and kept a list of grammar questions for her school teacher."}]},{"id":"b2-easy-library-access","level":"B2","band":"easy","title":"A Library Card Without a Phone","topic":"數位服務與公平使用","words":259,"ielts":true,"paras":["At a fictional nursing college, the library introduced an app for reserving books. Students could check availability before travelling to campus, and staff received fewer telephone enquiries. The launch report described the service as convenient. However, that description mainly reflected the experience of students who had already downloaded the app and successfully created an account. It said little about people who stopped before that point.","The library kept a second route open: students could reserve the same books at the desk with their student cards. A librarian also offered short help sessions, but attending one was optional. The aim was to make the digital service useful without turning smartphone ownership into a condition for borrowing. Both routes used the same waiting list, so neither group received priority.","To investigate remaining barriers, staff initially sent a questionnaire through the app. A student representative pointed out that this method would miss some of the people experiencing the greatest difficulty. Staff therefore added paper forms near the entrance and invited comments during ordinary desk visits. They did not ask students to write account passwords or other private login information on either form. Students could leave either form unsigned if they preferred.","The revised evaluation counted unfinished requests as well as successful reservations. It also recorded the time staff spent helping users. A shorter queue at the desk could indicate improvement, but it could also mean that some students had given up. The library therefore treated convenience as a question to investigate, rather than a quality that every new digital tool automatically possessed."],"zh":"一所虛構護理學院推出借書預約應用程式，學生能先查館藏，電話詢問也變少，但開辦報告主要反映已成功下載、註冊者的經驗，沒有充分了解中途放棄的人。\\n\\n圖書館保留用學生證在櫃檯預約的方式，並提供可自由參加的操作協助。兩種管道共用同一份候補名單，沒有誰優先，借書也不以擁有智慧型手機為條件。\\n\\n一開始只透過應用程式發問卷，學生代表指出這會漏掉使用最困難的人，因此增加入口紙本表單與櫃檯訪談，兩種表單都不收密碼等登入隱私，學生也可選擇不署名。\\n\\n後續除了成功預約，也記錄未完成的申請與協助所花時間。櫃檯排隊變短可能是改善，也可能有人放棄，因此是否方便必須實際查證，不能因為工具新就直接認定。","qs":[{"type":"heading","q":"Which heading best fits paragraph B (paragraph 2)?","options":["Giving app users first choice of every book","Replacing student cards with private passwords","Keeping more than one route to the same service"],"answer":2,"why":"第二段說明保留櫃檯與數位兩條管道，並共用候補順序。"},{"type":"tfng","q":"Statement: Students using the desk and the app joined the same waiting list.","options":["True","False","Not Given"],"answer":0,"why":"文中直接說兩條管道共用名單，因此沒有任一方優先。","evidence":"Both routes used the same waiting list, so neither group received priority."},{"type":"tfng","q":"Statement: Every student had to own a smartphone to reserve a book.","options":["True","False","Not Given"],"answer":1,"why":"文章明說目標是不把擁有智慧型手機變成借書條件，與敘述相反。","evidence":"The aim was to make the digital service useful without turning smartphone ownership into a condition for borrowing."},{"type":"tfng","q":"Statement: A local software company developed the library app.","options":["True","False","Not Given"],"answer":2,"why":"文章交代圖書館推出預約用 App，全文都沒說由哪家公司開發，或開發者是不是本地業者。","evidence":"At a fictional nursing college, the library introduced an app for reserving books."},{"type":"detail","q":"Why were paper forms added?","options":["An app-only survey could miss people who struggled to use the app.","Students using the app were forbidden to give feedback.","Paper responses automatically contained more accurate passwords."],"answer":0,"why":"只在應用程式內調查，會漏掉無法順利用的人，因此補上紙本與現場回饋。","evidence":"A student representative pointed out that this method would miss some of the people experiencing the greatest difficulty."},{"type":"vocab","q":"In paragraph C, \\"barriers\\" refers to…","options":["rules that give all students guaranteed reservations","difficulties that prevent people from using the service","shelves that separate different kinds of books"],"answer":1,"why":"這裡的 barriers 是使用服務遇到的障礙，不是實體書架。"},{"type":"evidence","q":"Why is a shorter desk queue not enough to prove success?","options":["The article establishes that all queues are harmful.","Only the length of the waiting list can ever be measured.","It may result from people abandoning the service."],"answer":2,"why":"作者提出另一種可能：排隊少是因有人放棄，所以不能單看隊伍長度。","evidence":"A shorter queue at the desk could indicate improvement, but it could also mean that some students had given up."},{"type":"main","q":"What is the main lesson of the passage?","options":["Evaluate whether a service works for people who face difficulties as well as successful users.","Judge a library entirely by how few telephone calls it receives.","Remove older service channels as soon as an app is launched."],"answer":0,"why":"全文從成功使用者以外的人出發，說明多管道與更完整評估的重要。"},{"type":"tfng","q":"Statement: Students could return the paper form without writing their names.","options":["True","False","Not Given"],"answer":0,"why":"第三段說紙本或 App 表格都可以不署名。","evidence":"Students could leave either form unsigned if they preferred.","additional":true}]},{"id":"b2-easy-repair-cafe","level":"B2","band":"easy","title":"What Counts as a Successful Repair?","topic":"維修活動與資源使用","words":262,"ielts":true,"paras":["A community centre in this fictional example held a repair afternoon instead of a sale of new products. Residents brought damaged household items, while volunteers supplied tools and explained possible repairs. The organisers hoped to reduce unnecessary disposal, but they did not promise that every object would leave in working order. The event was also intended to help people understand why an item had failed.","One visitor brought a coat with a loose button. Another arrived with a lamp that repeatedly stopped working. Volunteers could demonstrate simple clothing repairs, but they referred electrical faults beyond their competence to qualified repairers. Saying that a job required different expertise was part of the service, not evidence that a volunteer had failed. Visitors remained responsible for deciding whether to seek further help.","At first, the organisers planned to report only the number of repaired objects. They later recognised that this measure ignored useful outcomes. A person might learn that an item needed an unavailable part, or discover a suitable professional service. The final record therefore separated completed repairs, referrals and explanations without repairs. It did not combine all three categories under a single claim that everything had been fixed.","Access also mattered. Residents with heavy objects could not always carry them to the centre, and the afternoon schedule excluded some workers. The next event offered advance questions by telephone, although transport support was still unresolved. The organisers concluded that a repair programme required more than enthusiastic volunteers. Clear limits, honest reporting and practical access were also needed before the activity could serve the wider community."],"zh":"這個虛構社區以維修下午取代新品販售，居民帶來損壞物品，志工提供工具與說明，希望減少不必要的丟棄，也幫助人了解故障原因，但不保證全部修好。\\n\\n有人帶來鈕扣鬆脫的外套，也有人帶來時好時壞的燈。志工可示範簡單衣物修補，超出能力的電器故障則轉介合格維修人員。說明能力界線也是服務的一部分；是否進一步找人維修由訪客決定。\\n\\n主辦者原先只想記錄修好的件數，後來發現知道缺少零件、找到專業協助也有價值，因此分開列出完成維修、轉介與只有說明三類，沒有把全部都算成已修好。\\n\\n搬不動重物的人與下午要上班的人仍可能無法參加。下次提供事前電話詢問，但運輸協助尚未解決。活動要服務更多人，除了熱心志工，也需要清楚界線、誠實成果紀錄與實際可及性。","qs":[{"type":"heading","q":"Which heading best fits paragraph C (paragraph 3)?","options":["Counting every conversation as a completed repair","Why volunteers should stop offering explanations","Recording different kinds of useful outcomes"],"answer":2,"why":"第三段區分修好、轉介與說明，避免一種數字掩蓋不同成果。"},{"type":"tfng","q":"Statement: The organisers promised that every item would be repaired.","options":["True","False","Not Given"],"answer":1,"why":"開頭明確否定這個保證，所以是 False，而不是沒提到。","evidence":"The organisers hoped to reduce unnecessary disposal, but they did not promise that every object would leave in working order."},{"type":"tfng","q":"Statement: The final record separated completed repairs from referrals.","options":["True","False","Not Given"],"answer":0,"why":"原文把完成維修、轉介與未維修的說明分開記錄。","evidence":"The final record therefore separated completed repairs, referrals and explanations without repairs."},{"type":"tfng","q":"Statement: Each qualified repairer charged the same fee.","options":["True","False","Not Given"],"answer":2,"why":"文章提到轉介專業人員，卻沒有比較費用，也沒有說價格相同或不同。","evidence":"Volunteers could demonstrate simple clothing repairs, but they referred electrical faults beyond their competence to qualified repairers."},{"type":"detail","q":"Which access problem remained unresolved?","options":["Helping residents transport heavy items","Finding a name for the community centre","Allowing anyone to ask questions by telephone"],"answer":0,"why":"最後一段說已提供電話詢問，但運輸支援仍未解決。","evidence":"The next event offered advance questions by telephone, although transport support was still unresolved."},{"type":"vocab","q":"In paragraph B, \\"competence\\" means…","options":["the amount of money available for publicity","the knowledge and ability needed to do a task safely","the total number of visitors attending an event"],"answer":1,"why":"這裡指是否具備處理該種故障的專業能力。"},{"type":"evidence","q":"Why can a referral count as a useful outcome?","options":["It proves that the object is already working perfectly.","It guarantees that no replacement part will be needed.","It connects a visitor with expertise that the event cannot provide."],"answer":2,"why":"知道合適的專業服務，即使現場未修好，也可能幫助訪客下一步處理。","evidence":"A person might learn that an item needed an unavailable part, or discover a suitable professional service."},{"type":"main","q":"What does the passage argue about judging this programme?","options":["Both its practical limits and its range of outcomes should be considered.","Every unsuccessful repair means the entire event should close.","Only the number of donated tools matters."],"answer":0,"why":"全文同時談能力範圍、成果分類與參與障礙，不能只看修好件數。"},{"type":"tfng","q":"Statement: Transport for heavy objects had already been arranged for the next event.","options":["True","False","Not Given"],"answer":1,"why":"末段說下一次可事先打電話問問題，但搬運支援仍沒找到解法。","evidence":"The next event offered advance questions by telephone, although transport support was still unresolved.","additional":true}]},{"id":"b2-easy-heat-room","level":"B2","band":"easy","title":"A Cool Room That People Can Reach","topic":"熱浪與公共空間","words":256,"ielts":true,"paras":["During a fictional campus planning exercise, a nursing class proposed opening an air-conditioned room during very hot weather. The students first focused on posters reminding people to stay cool. Their teacher asked a different question: what if a person understood the message but had no suitable place to go? The class then shifted its attention from awareness alone to practical access.","The proposed room was near a bus stop and opened before the busiest midday period. Visitors did not need a student account to enter. A printed map showed the entrance, and staff checked that the route could be used by people with mobility difficulties. These arrangements were intended to make the service usable, rather than simply announce that a room existed somewhere on campus.","The health information remained general. Older adults and people taking some medicines can be more vulnerable to heat. Advice about fluids may need to be individualised for someone whose clinician has limited their intake. Student volunteers would therefore explain the room's facilities and contact staff when help was needed; they would not change medicines or give each visitor a fixed drinking target.","Finally, the class considered how to evaluate the proposal. Counting visitors would show use, but not whether everyone who needed the room could reach it. Interviews might identify an inconvenient closing time or confusion about eligibility. A low attendance figure could mean low demand, poor publicity or an access problem. The exercise taught the students to investigate those possibilities before calling the service either a success or a failure."],"zh":"在一個虛構校園規劃練習中，護理班想在炎熱天氣開放冷氣休息室。最初只注意提醒保持涼爽的海報，老師卻問：如果人知道提醒，卻沒地方去呢？於是他們轉向實際使用的障礙。\\n\\n規劃的房間靠近公車站，在中午最忙時段之前開放，不必有學生帳號；紙本地圖標出入口，工作人員也檢查行動不便者能否使用路線。目的不是只有公告房間存在，而是讓人真的能到達。\\n\\n衛教維持一般資訊：長者及使用某些藥物者可能較怕熱，若醫療人員有限制飲水，補充水分需依個別情況討論。學生志工只介紹設施、需要時聯絡工作人員，不調整藥物，也不給所有人相同飲水目標。\\n\\n評估不能只看來訪人數，還要了解需要者能否到達。訪談可能發現關門時間不便或資格不清；低使用量可能來自需求少、宣傳不足或使用障礙，必須先查證再判斷成敗。","qs":[{"type":"heading","q":"Which heading best fits paragraph B (paragraph 2)?","options":["Turning a location into an accessible service","Replacing staff with medical software","Restricting entry to nursing students"],"answer":0,"why":"第二段介紹交通、開門時間、入口與行動可及性的具體安排。"},{"type":"tfng","q":"Statement: Visitors would need a student account to enter the room.","options":["True","False","Not Given"],"answer":1,"why":"原文明確說不需要學生帳號，與敘述相反。","evidence":"Visitors did not need a student account to enter."},{"type":"tfng","q":"Statement: The proposed room would open before the busiest midday period.","options":["True","False","Not Given"],"answer":0,"why":"第二段直接交代預計在中午最忙時段前開放。","evidence":"The proposed room was near a bus stop and opened before the busiest midday period."},{"type":"tfng","q":"Statement: The room would contain exactly twenty chairs.","options":["True","False","Not Given"],"answer":2,"why":"文中說明房間位置與時段，沒有提椅子數量；不能由有休息室推知座位數。","evidence":"The proposed room was near a bus stop and opened before the busiest midday period."},{"type":"detail","q":"What would student volunteers avoid doing?","options":["Explaining where the room’s facilities were","Changing visitors’ medicines or setting one drinking target for everyone","Contacting staff when help was needed"],"answer":1,"why":"第三段清楚限制學生角色，不讓學生調藥或統一指定個人飲水量。","evidence":"Student volunteers would therefore explain the room's facilities and contact staff when help was needed; they would not change medicines or give each visitor a fixed drinking target."},{"type":"vocab","q":"In paragraph A, \\"awareness\\" refers to…","options":["the number of windows in a room","permission to change another person’s treatment","knowing about a message or problem"],"answer":2,"why":"段落把知道保持涼爽的提醒，與真正有地方可去作比較。"},{"type":"evidence","q":"Why would low attendance need further investigation?","options":["Several different explanations could produce the same low figure.","It would prove that hot weather never causes difficulties.","It would show that every visitor had another cooling option."],"answer":0,"why":"少人來可能有不同原因，不能直接判定沒有需求。","evidence":"A low attendance figure could mean low demand, poor publicity or an access problem."},{"type":"main","q":"What is the central planning lesson?","options":["A poster is always enough when its words are accurate.","Health messages should be accompanied by attention to usable access.","Attendance should never be recorded for public services."],"answer":1,"why":"全文從宣傳轉向實際能否使用，也保留多面向評估。"},{"type":"tfng","q":"Statement: Student volunteers would set the same water intake target for all visitors.","options":["True","False","Not Given"],"answer":1,"why":"第三段說學生志工不會給每位訪客固定的飲水目標。","evidence":"they would not change medicines or give each visitor a fixed drinking target.","additional":true}]},{"id":"b2-easy-leaflet","level":"B2","band":"easy","title":"The Leaflet That Readers Could Use","topic":"衛教文字與理解","words":256,"ielts":true,"paras":["A fictional clinic asked a student group to review an information leaflet about preparing for a routine appointment. The original page contained correct details, but important instructions were hidden among long paragraphs. Several readers could repeat the clinic's telephone number yet could not explain what they needed to bring. The students realised that including information was different from making it easy to use.","They moved the main preparation message to the top and separated the remaining information with clear headings. Unfamiliar administrative expressions were replaced with everyday words where the meaning stayed accurate. A short checklist grouped the items needed for the visit. The group did not remove necessary information merely to achieve a shorter page, and a clinician checked the revised wording before anyone used it.","Next, volunteers read the draft and explained the next steps in their own words. The students presented this as a test of the leaflet, not a test of the readers' intelligence. When different people misunderstood the same sentence, the group revised that sentence instead of simply telling everyone to read more carefully. Comments about text size and the order of information were recorded as well.","The final version still had limits. Some visitors needed another language or an accessible format, and a leaflet could not answer every individual question. The clinic therefore kept a clear route for asking staff for help. The project showed why plain language is more than replacing difficult words: readers also need to find the right message, understand its purpose and know what action follows."],"zh":"一間虛構診所請學生檢查例行門診的準備說明。資訊本身正確，但重要內容藏在長段落中；有人能背電話，卻不知道要帶什麼，顯示有寫出資訊不等於容易使用。\\n\\n學生把主要準備事項放最上方，增加清楚標題，在意思正確的前提下換成日常用語，並把攜帶物品整理成短清單。他們不為了縮短頁數而刪去必要內容，修訂版也先由臨床人員確認。\\n\\n志工讀草稿後用自己的話說明下一步；學生強調這是在測說明單，而不是測讀者聰不聰明。若多人誤解同一句，就修改句子，也記錄字體大小與資訊順序的意見。\\n\\n最後仍有人需要其他語言或無障礙格式，說明單也不能回答每個人的問題，因此保留詢問工作人員的方式。清楚文字除了簡單字彙，也要讓人找到重點、理解目的並知道下一步。","qs":[{"type":"heading","q":"Which heading best fits paragraph C (paragraph 3)?","options":["Checking the document through readers’ explanations","Ranking visitors by intelligence","Collecting telephone numbers for advertising"],"answer":0,"why":"第三段用讀者能否說明下一步來檢查文字是否清楚。"},{"type":"tfng","q":"Statement: A clinician reviewed the revised wording before the leaflet was used.","options":["True","False","Not Given"],"answer":0,"why":"第二段末句明說臨床人員先確認修訂內容。","evidence":"The group did not remove necessary information merely to achieve a shorter page, and a clinician checked the revised wording before anyone used it."},{"type":"tfng","q":"Statement: The group removed necessary details whenever doing so shortened the page.","options":["True","False","Not Given"],"answer":1,"why":"原文明確說不會只為了縮短頁數而移除必要資訊。","evidence":"The group did not remove necessary information merely to achieve a shorter page, and a clinician checked the revised wording before anyone used it."},{"type":"tfng","q":"Statement: The original leaflet had been written by the clinic manager.","options":["True","False","Not Given"],"answer":2,"why":"文章描述原稿的樣子，沒有交代作者身分；不能由診所使用就推出是經理撰寫。","evidence":"The original page contained correct details, but important instructions were hidden among long paragraphs."},{"type":"detail","q":"What did the students do when several readers misunderstood one sentence?","options":["They excluded those readers from the project.","They revised the sentence.","They removed every heading from the page."],"answer":1,"why":"同一句被多人誤解時，學生修改文字，而非怪讀者不夠仔細。","evidence":"When different people misunderstood the same sentence, the group revised that sentence instead of simply telling everyone to read more carefully."},{"type":"vocab","q":"In paragraph D, \\"accessible format\\" means a form that…","options":["contains the greatest possible number of technical words","can be opened only by the leaflet’s original author","people with relevant access needs can use"],"answer":2,"why":"這裡是在說不同讀者需要能使用的呈現形式，例如適合其閱讀需求的格式。"},{"type":"evidence","q":"Why did the clinic retain a route to staff assistance?","options":["Written material could not address every person’s question.","The final leaflet contained no information at all.","Only staff were permitted to read the instructions."],"answer":0,"why":"最後一段指出不同語言、格式與個別問題，說明保留人工協助的理由。","evidence":"Some visitors needed another language or an accessible format, and a leaflet could not answer every individual question."},{"type":"main","q":"Which statement best expresses the passage’s message?","options":["Accurate information is automatically easy for every reader to use.","Useful health information requires clear organisation and checks of understanding.","A short page always communicates better than a longer one."],"answer":1,"why":"文章把正確、可找到、可理解與可行動連在一起，並反對只求短。"},{"type":"tfng","q":"Statement: All readers in the group had already used an earlier version of the leaflet.","options":["True","False","Not Given"],"answer":2,"why":"文章交代志工看草稿的方式，全文沒交代他們以前有沒有用過舊版。","evidence":"Next, volunteers read the draft and explained the next steps in their own words.","additional":true}]},{"id":"b2-easy-recorded-lessons","level":"B2","band":"easy","title":"A Recording Is Only Part of a Lesson","topic":"教育科技與學習","words":264,"ielts":true,"paras":["In this fictional course, a nursing teacher began recording short explanations so students could review them after placement. The recordings were useful for learners whose travel schedules made an extra meeting difficult. They could pause an unfamiliar phrase and listen again. However, the teacher did not assume that opening a video meant understanding the explanation or being ready to use it independently.","Each recording was accompanied by an outline and captions. During review, a student noticed that one caption confused two similar technical words. The teacher corrected it and added a visible revision date. This experience reminded the class that supporting materials also needed checking. A recording could preserve an explanation, but an inaccurate caption might preserve an error just as effectively for later viewers. Printed outlines were available for students with limited internet access.","Students then completed a short task using the idea in a new example. Instead of submitting a screenshot showing that the video had played, they explained one choice they had made. A weekly question session remained available for difficulties the recording did not resolve. Students were allowed to bring an unfinished attempt, because the teacher wanted to see where their reasoning stopped.","The course evaluation considered these attempts alongside viewing information. Replaying a section could mean interest, confusion or an interruption, so the number of views was not treated as a direct measure of learning. The teacher retained the recordings while changing the follow-up activities. The goal was not to choose between technology and teaching, but to connect convenient access with opportunities to check, question and apply an explanation."],"zh":"在這個虛構課程中，護理教師錄製短講解，讓學生實習後複習，交通安排不便者可以暫停、重聽。但老師不把開過影片等同已理解或能獨立運用。\\n\\n每段錄影附大綱與字幕；一位學生發現字幕混淆兩個技術名詞，老師修正並標出日期。這提醒大家輔助教材也需查核，錄影能保存說明，也可能一再傳播錯誤；網路不便的學生也能取得紙本大綱。\\n\\n學生再用新例子做短練習，交代自己的選擇，而不是上傳播放完畢的截圖。每週仍有提問時段，也能帶未完成的作答，讓老師看出思考卡在哪裡。\\n\\n評估同時看作答與觀看資訊。重播可能因有興趣、不理解或被打斷，觀看次數不是學會程度的直接指標。課程保留錄影並調整後續活動，目標是把便利取得和查核、提問、應用連起來。","qs":[{"type":"heading","q":"Which heading best fits paragraph B (paragraph 2)?","options":["Removing every caption from the course","Using viewing totals to replace student work","Checking the accuracy of supporting materials"],"answer":2,"why":"第二段的字幕錯誤與修訂日期，說明輔助材料也需要檢查。"},{"type":"tfng","q":"Statement: Students could bring unfinished attempts to the weekly question session.","options":["True","False","Not Given"],"answer":0,"why":"第三段最後一句直接說可以帶未完成嘗試，讓老師看出推理停在哪。","evidence":"Students were allowed to bring an unfinished attempt, because the teacher wanted to see where their reasoning stopped."},{"type":"tfng","q":"Statement: The teacher treated every extra video view as proof of additional learning.","options":["True","False","Not Given"],"answer":1,"why":"文章說觀看次數未被當成學習的直接衡量，明確與敘述相反。","evidence":"Replaying a section could mean interest, confusion or an interruption, so the number of views was not treated as a direct measure of learning."},{"type":"tfng","q":"Statement: The videos were filmed with a camera purchased by the students.","options":["True","False","Not Given"],"answer":2,"why":"開頭說教師錄製講解，未說相機來源或由誰購買。","evidence":"In this fictional course, a nursing teacher began recording short explanations so students could review them after placement."},{"type":"detail","q":"What was added when the caption error was corrected?","options":["A visible revision date","A requirement to stop asking questions","A list of students who had failed the course"],"answer":0,"why":"第二段說修訂字幕後標示可看見的修訂日期。","evidence":"The teacher corrected it and added a visible revision date."},{"type":"vocab","q":"In paragraph C, \\"resolve\\" means…","options":["hide from other learners","deal with successfully or make clear","make more permanent"],"answer":1,"why":"問答時段處理錄影還沒解決的困難，resolve 在此是解決。"},{"type":"evidence","q":"Why did the teacher ask students to explain a new example?","options":["A screenshot contains all the reasoning needed for assessment.","Students could demonstrate understanding without doing any task.","An explanation of a choice provides evidence beyond simply playing a video."],"answer":2,"why":"老師要看學生如何應用和選擇，單純播放或截圖不足以顯示理解。","evidence":"Instead of submitting a screenshot showing that the video had played, they explained one choice they had made."},{"revision":1,"type":"main","q":"What approach does the passage support?","options":["Use recordings together with activities that reveal understanding.","Use replay data to decide which ideas students have mastered.","Improve recordings by making accurate captions the principal measure of learning."],"answer":0,"why":"全文介紹錄影的便利和字幕品質，也強調觀看紀錄看不出理解程度，須透過提問與運用內容的新作答來確認。"},{"type":"tfng","q":"Statement: Learners with limited internet access could obtain printed outlines.","options":["True","False","Not Given"],"answer":0,"why":"第二段明確寫到印好的大綱可供網路不便的學生。","evidence":"Printed outlines were available for students with limited internet access.","additional":true}]},{"id":"b2-easy-bus-information","level":"B2","band":"easy","title":"When the Arrival Screen Falls Behind","topic":"交通資訊與判讀","words":262,"ielts":true,"paras":["At a fictional college bus stop, an electronic screen displayed predicted arrival times. Students welcomed the chance to plan their journeys without repeatedly calling the transport office. Yet one rainy afternoon, the display continued to promise a bus in two minutes even after a service disruption. The problem was not the presence of a screen, but the absence of a clear signal that its information was no longer current.","The transport team investigated the data behind the display. The prediction system had stopped receiving fresh vehicle positions, while the last estimate remained visible. Staff changed the design so that an old estimate would be marked as unavailable rather than presented as a live prediction. They also added the time of the latest update, allowing passengers to judge how recently the information had been checked.","A printed timetable remained at the stop. It showed the planned service rather than the exact location of a particular bus. Passengers were told how these two sources differed and where to check official disruption notices. Neither a timetable nor a prediction guaranteed arrival at a precise moment. Keeping the distinction visible was especially useful for students travelling to an unfamiliar placement location.","For evaluation, the team recorded occasions when a displayed estimate stayed unchanged during a disruption. They also asked passengers whether the new warning was understandable. Complaints did not disappear immediately, but staff could investigate them using clearer records. The case illustrates a wider lesson about digital information: a useful system should show uncertainty and missing updates, not merely produce a confident-looking number on every screen."],"zh":"一所虛構學院的公車站顯示預估到站時間，學生原本覺得方便，但一次下雨、服務中斷時，螢幕仍不斷顯示兩分鐘。問題是資訊已過時卻沒有提醒。\\n\\n團隊發現系統沒再收到新的車輛位置，舊估計卻留著，因此改成資料過舊時標示無法取得，並顯示最後更新時間。\\n\\n站牌仍保留紙本時刻表，但它顯示預定班次，不是某班車此刻的位置。乘客得到兩者差別與官方異動公告的查詢方式；兩種資訊都不是保證準時到站，前往陌生實習地點時尤其需要分清。\\n\\n評估記錄中斷時預估時間是否卡住，也問乘客看不看得懂警示。抱怨沒有立刻消失，但更清楚的紀錄有助調查。數位資訊應呈現不確定與缺少更新，不只是一直給出看似肯定的數字。","qs":[{"type":"heading","q":"Which heading best fits paragraph B (paragraph 2)?","options":["Making stale information visible to passengers","Removing the need for official service notices","Guaranteeing that every bus arrives on time"],"answer":0,"why":"第二段處理過期預估值與更新時間，讓使用者知道資訊狀態。"},{"type":"tfng","q":"Statement: The printed timetable showed the exact live position of each bus.","options":["True","False","Not Given"],"answer":1,"why":"原文明說紙本表列的是計畫班次，而非特定公車的位置。","evidence":"It showed the planned service rather than the exact location of a particular bus."},{"type":"tfng","q":"Statement: The revised display included the time of the latest update.","options":["True","False","Not Given"],"answer":0,"why":"團隊把最後更新時間加入畫面，供乘客判讀資料新舊。","evidence":"They also added the time of the latest update, allowing passengers to judge how recently the information had been checked."},{"type":"tfng","q":"Statement: The service disruption was caused by a damaged bridge.","options":["True","False","Not Given"],"answer":2,"why":"文中說服務中斷與資料停止更新，但沒有交代中斷的交通原因，不能自行補成橋梁受損。","evidence":"The prediction system had stopped receiving fresh vehicle positions, while the last estimate remained visible."},{"type":"detail","q":"What would happen to an estimate that was no longer current?","options":["It would always be replaced by the number two.","It would be described as a guaranteed arrival time.","It would be marked as unavailable."],"answer":2,"why":"第二段說舊預估改為顯示無法取得，避免冒充即時預測。","evidence":"Staff changed the design so that an old estimate would be marked as unavailable rather than presented as a live prediction."},{"type":"vocab","q":"In paragraph A, \\"current\\" means…","options":["moving through an electrical wire","up to date","located nearest to the college gate"],"answer":1,"why":"這裡討論資訊是否仍是最新狀態，current 指即時、未過時。"},{"type":"evidence","q":"What can be inferred about a confident-looking number?","options":["Its appearance alone does not establish that the underlying data are fresh.","It proves that the transport team has checked every vehicle personally.","It must always be more accurate than any explanation."],"answer":0,"why":"最後一句指出系統需揭露缺少更新，而非只顯示肯定數字，表示外觀不能證明資料可靠。","evidence":"The case illustrates a wider lesson about digital information: a useful system should show uncertainty and missing updates, not merely produce a confident-looking number on every screen."},{"type":"main","q":"What is the passage mainly concerned with?","options":["Teaching students how to drive a bus in the rain","Proving that printed information is never useful","Helping users distinguish reliable updates from unsupported certainty"],"answer":2,"why":"全文談資料更新、紙本與預測差別，以及如何揭露不確定。"},{"type":"tfng","q":"Statement: The new warning was also issued in a second language.","options":["True","False","Not Given"],"answer":2,"why":"文章提及有新提醒，也問乘客看不看得懂，沒有提是否發布第二種語言。","evidence":"They also asked passengers whether the new warning was understandable.","additional":true}]},{"id":"b2-mid-antibiotics","level":"B2","band":"mid","title":"Why a Prescription Is Not Always the Answer","topic":"抗生素與醫病溝通","words":327,"ielts":true,"paras":["A patient in a fictional clinic expects antibiotics because a previous illness improved after taking them. The clinician begins by asking what the patient hopes the medicine will achieve. This question opens a conversation rather than a disagreement about whether the illness is serious. Wanting relief is understandable, but the name of a familiar medicine does not establish whether it is suitable for a different illness.","Antibiotics treat certain bacterial infections; they do not treat infections caused by viruses. Even some bacterial infections do not require an antibiotic. Unnecessary use can still cause side effects, and misuse or overuse contributes to antimicrobial resistance. Resistance means that microorganisms no longer respond to medicines that previously worked against them. It does not mean that a person's body has become resistant. These distinctions explain why more prescribing is not automatically better care.","In the clinic conversation, the clinician explains the assessment in everyday language and checks what the patient has understood. The patient is also given an individual plan for managing symptoms and told how to seek further assessment if the situation changes. The fictional example supplies no universal waiting period or list of medicines, because those decisions depend on the person's condition. Simply refusing a requested drug without explaining the plan would leave the patient's original concern unanswered.","The clinic later reviews how its information is presented. A poster saying only 'use fewer antibiotics' could imply that these medicines are always undesirable, including when they are needed. Staff instead explain appropriate use: take a prescribed antibiotic exactly as directed, and do not share it or save it for a later illness. They also invite patients to ask about benefits and possible harms. The message links responsible use with access to necessary treatment, rather than presenting one as the opposite of the other. In this way, a decision not to prescribe can still be an active part of care, provided that the patient understands the reasoning and the next steps."],"zh":"虛構診所的一名病人曾服用抗生素後好轉，因此這次也期待拿到。醫師先詢問他希望藥物解決什麼問題，藉此展開對話；想減輕不舒服很合理，但熟悉的藥名不代表適合另一次疾病。\\n\\n抗生素治療某些細菌感染，不能治療病毒感染，甚至部分細菌感染也不需用抗生素。不必要使用仍可能產生副作用，錯誤或過度使用也會促進抗藥性。抗藥性是微生物不再對原本有效的藥物產生反應，不是人的身體變得抗藥，因此開藥多不等於照護更好。\\n\\n醫師用日常語言解釋評估、確認病人理解，提供個別症狀處理計畫與病況改變時的求助方式。本文沒有給所有人通用的等待時間或藥物清單，因為必須依個別狀況決定。若只拒絕開藥、沒有說明照護計畫，病人的擔憂仍未解決。\\n\\n診所也重新檢查宣傳文字。只寫少用抗生素可能讓人誤以為連必要治療都不好，因此改為解釋適當使用：依處方指示服用，不與別人共用，也不留待下次生病自行使用，並鼓勵詢問好處與可能傷害。合理用藥與取得必要治療可以並行；只要理解理由及下一步，不開藥仍能是積極照護的一環。","qs":[{"type":"heading","q":"Which heading best fits paragraph B (paragraph 2)?","options":["A claim that all bacterial illnesses require the same medicine","Distinctions that guide appropriate antibiotic use","A description of how to manufacture antibiotics"],"answer":1,"why":"第二段區分細菌與病毒、抗藥性的意思，以及不必要用藥的問題。"},{"type":"tfng","q":"Statement: Some bacterial infections do not require an antibiotic.","options":["True","False","Not Given"],"answer":0,"why":"第二段明確說即使是部分細菌感染，也不需要抗生素。","evidence":"Even some bacterial infections do not require an antibiotic."},{"type":"tfng","q":"Statement: The passage defines resistance as the human body becoming resistant to medicine.","options":["True","False","Not Given"],"answer":1,"why":"原文直接否定身體本身變得抗藥，前一句把主體說明為微生物。","evidence":"It does not mean that a person's body has become resistant."},{"type":"tfng","q":"Statement: The patient had taken the previous antibiotic for seven days.","options":["True","False","Not Given"],"answer":2,"why":"文章只說先前生病服藥後改善，沒有提供那次療程天數。","evidence":"A patient in a fictional clinic expects antibiotics because a previous illness improved after taking them."},{"type":"detail","q":"Why does the fictional example give no universal waiting period?","options":["Decisions about reassessment depend on the individual condition.","The clinic never reassesses a patient after a consultation.","A previous prescription is enough to determine every later treatment."],"answer":0,"why":"第三段說等待時間與藥物選擇要看個別病況。","evidence":"The fictional example supplies no universal waiting period or list of medicines, because those decisions depend on the person's condition."},{"type":"vocab","q":"In paragraph C, \\"assessment\\" most nearly means…","options":["an agreement to fulfil every request","an advertisement for a particular medicine","an evaluation of the person’s condition"],"answer":2,"why":"這裡 assessment 是對病人狀況的評估，不是保證提供他想要的藥物。"},{"type":"evidence","q":"Why might a poster saying only \\"use fewer antibiotics\\" be misleading?","options":["It would give every patient a complete individual care plan.","It could discourage treatment even when an antibiotic is appropriate.","It would prove that antibiotics never cause side effects."],"answer":1,"why":"第四段指出口號可能使人連需要時也以為藥物不好，因此必須交代適當使用。","evidence":"A poster saying only 'use fewer antibiotics' could imply that these medicines are always undesirable, including when they are needed."},{"type":"detail","q":"What should patients do with an antibiotic prescribed for them?","options":["Follow the directions and avoid sharing or saving it for another illness.","Keep part of every course for an illness that occurs later.","Offer unused medicine to relatives with similar symptoms."],"answer":0,"why":"第四段清楚列出依指示使用、不共用、不留待下次的原則。","evidence":"Staff instead explain appropriate use: take a prescribed antibiotic exactly as directed, and do not share it or save it for a later illness."},{"type":"main","q":"Which conclusion best reflects the passage?","options":["Reducing the number of prescriptions is the only purpose of every consultation.","A prescription is the only evidence that a clinician has taken an illness seriously.","Appropriate prescribing includes explanation, individual planning and access to needed treatment."],"answer":2,"why":"全文把合適用藥與溝通、症狀處理及必要治療連在一起。"},{"type":"tfng","q":"Statement: The clinic invites patients to ask about both the benefits and possible harms.","options":["True","False","Not Given"],"answer":0,"why":"最後一段明確交代診所邀請病人了解抗生素的好處與風險。","evidence":"They also invite patients to ask about benefits and possible harms.","additional":true}]},{"id":"b2-mid-discharge","level":"B2","band":"mid","title":"The Journey Beyond the Ward Door","topic":"出院準備與照護銜接","words":333,"ielts":true,"paras":["During a fictional placement, a nursing student watches a discharge conversation that appears well organised. A folder is handed over, transport is booked and the patient thanks the staff. The student initially assumes that all preparation is complete. Then the patient asks who will answer a question after arriving home. The question reveals a gap between completing hospital tasks and preparing someone to manage the next stage of care.","Discharge planning can involve several people, and arrangements differ between hospitals. Patients should be included in discussions about their needs and the support available. Where care continues after discharge, the plan needs to make responsibilities understandable: who will provide help, how they can be contacted and what happens if difficulties arise. Information about medicines, equipment and follow-up arrangements must also be clear enough for the person to use. A folder alone cannot show whether this has happened.","In the fictional case, the supervising nurse invites the patient to explain the plan in their own words. The patient knows the appointment date but has confused the transport booking with an arrangement for help at home. Rather than treating this as carelessness, the nurse clarifies that these are different services and checks what support has actually been arranged. With the patient's permission, a relative joins the discussion. The student notices that permission matters: family involvement should not be assumed merely because a relative is nearby.","Before the patient leaves, the team identifies the contact named in the plan and checks how to use that route. The student records a learning point without including identifying patient details. Successful discharge is not simply a rapid departure or a tidy set of documents. It is a transition in which information, responsibility and practical arrangements need to connect. The team cannot remove every uncertainty, but it can make the next step clearer and identify questions that require an answer before departure. This perspective changes the student's attention from whether information has been handed over to whether it can support action."],"zh":"一名護生在虛構實習情境中看到出院文件交付、交通預約完成，病人也道謝，因此以為準備好了。直到病人問返家後有疑問要找誰，才發現完成院內工作與準備下一段照護之間仍有落差。\\n\\n出院規劃可能涉及多人，各院做法也不同。病人應參與需求與支援的討論；若出院後仍需照護，計畫要清楚交代誰提供協助、如何聯絡，以及出現困難時怎麼辦。藥物、設備和後續追蹤資訊也要能實際使用，單靠一個資料夾不能證明病人已了解。\\n\\n帶教護理師請病人用自己的話說明計畫。病人知道回診日期，卻把交通安排誤認成到府協助。護理師澄清兩種服務，查核真正安排了哪些支援，而非認定病人粗心；取得病人同意後才邀家屬一起討論。\\n\\n離院前，團隊確認計畫上的聯絡對象與使用方式。護生記下學習重點但不寫可辨識病人的資料。好的出院不只是快速離開或文件整齊，而是資訊、責任及實際安排能銜接；雖然無法消除所有不確定，仍能讓下一步更清楚，並在離院前找出尚待回答的問題。","qs":[{"type":"heading","q":"Which heading best fits paragraph C (paragraph 3)?","options":["Replacing the patient’s choices with a relative’s wishes","Cancelling transport because no one knows the appointment date","Finding and correcting a misunderstanding about support"],"answer":2,"why":"第三段透過病人說明計畫，發現交通與到府支援混淆，再澄清安排。"},{"type":"tfng","q":"Statement: The patient confused transport with help at home.","options":["True","False","Not Given"],"answer":0,"why":"第三段明說病人把交通預約誤當成居家協助。","evidence":"The patient knows the appointment date but has confused the transport booking with an arrangement for help at home."},{"type":"tfng","q":"Statement: The relative joined the discussion without the patient’s permission.","options":["True","False","Not Given"],"answer":1,"why":"原文明說取得病人同意後，家屬才加入。","evidence":"With the patient's permission, a relative joins the discussion."},{"type":"tfng","q":"Statement: The patient lived thirty kilometres from the hospital.","options":["True","False","Not Given"],"answer":2,"why":"文章提到交通與返家，但沒有說住家距離；安排交通不能推出公里數。","evidence":"A folder is handed over, transport is booked and the patient thanks the staff."},{"type":"detail","q":"Which question first showed that preparation might be incomplete?","options":["Who would answer a question after the patient arrived home?","Why had every follow-up appointment been cancelled?","Where could the student buy a new folder?"],"answer":0,"why":"第一段的返家後聯絡疑問揭露準備上的缺口。","evidence":"Then the patient asks who will answer a question after arriving home."},{"type":"vocab","q":"In paragraph D, \\"transition\\" refers to…","options":["a request to keep all care inside the hospital","a change from one stage of care to another","a document that guarantees no further questions"],"answer":1,"why":"出院是從院內進入下一段照護的轉換，不是單指一份文件。"},{"type":"evidence","q":"Why does the nurse ask the patient to explain the plan?","options":["The patient must prove that every medical term has been memorised.","The nurse intends to transfer all responsibility to the student.","Receiving documents does not establish that the arrangements are understood."],"answer":2,"why":"第二段指出資料夾本身不能證明已理解；接著請病人說明，才發現服務混淆。","evidence":"A folder alone cannot show whether this has happened."},{"type":"detail","q":"What is checked immediately before departure?","options":["The contact named in the plan and how to use that contact route","Whether the student has recorded the patient’s identifying details","Whether the relative can rewrite the hospital’s discharge policy"],"answer":0,"why":"最後一段說明團隊確認聯絡對象與使用管道。","evidence":"Before the patient leaves, the team identifies the contact named in the plan and checks how to use that route."},{"type":"main","q":"What shift in thinking does the student make?","options":["From assessing practical support to focusing only on the appearance of documents","From checking that information was delivered to checking that it can guide action","From involving patients to completing all decisions without them"],"answer":1,"why":"最後一句交代注意力從已交付資訊，轉為資訊能否支持實際行動。"},{"type":"tfng","q":"Statement: The student included information that could identify the patient in the learning record.","options":["True","False","Not Given"],"answer":1,"why":"末段說學生寫下學習重點，但沒有記下能識別病人的資訊。","evidence":"The student records a learning point without including identifying patient details.","additional":true}]},{"id":"b2-mid-museum-labels","level":"B2","band":"mid","title":"Whose Story Is Beside the Object?","topic":"博物館與歷史觀點","words":327,"ielts":true,"paras":["A fictional town museum owns a decorated wooden box donated by a wealthy traveller many years ago. Its old label praises the donor and describes the box as a souvenir. When staff prepare a new exhibition, a researcher asks how the traveller obtained it. The museum has a record of the donation, but that record does not explain the earlier transfer. An apparently simple object label becomes a question about the limits of the available evidence.","Staff examine letters, photographs and the original catalogue entry. These sources establish where the traveller displayed the box after returning home, yet none records the circumstances in which it was acquired. A recent assumption that it was purchased is therefore removed from the draft label. The museum also avoids replacing that unsupported claim with an equally unsupported account of theft. Admitting a gap is different from deciding that every possible explanation is equally likely.","Representatives from the community associated with the box contribute another perspective. They explain that similar objects have social meanings that the word 'souvenir' does not communicate. Their contribution is presented with its source identified, alongside the museum's account of what its documents show. The exhibition does not treat one representative as the voice of every member of the community. Instead, it indicates where interpretations differ and invites further information that can be examined.","Some visitors prefer the old label because it was shorter and sounded certain. Others welcome the explanation of what remains unknown. The museum keeps a concise summary beside the box and offers a longer account nearby, allowing different depths of reading. Its purpose is not to make uncertainty disappear through confident wording. It is to distinguish established facts, attributed interpretations and unanswered questions. That distinction allows the label to change when better evidence becomes available without suggesting that careful history requires a permanent, final version of every story. The box remains the same physical object, while the questions asked about it become more precise."],"zh":"虛構小鎮博物館收藏了一位富裕旅人捐贈的木盒，舊標籤讚揚捐贈者並稱它為紀念品。籌備新展覽時，研究者追問旅人如何取得；捐贈紀錄只能證明捐入館內，無法交代更早的轉手過程。\\n\\n信件、照片與舊目錄能確認旅人返家後如何展示木盒，卻沒有取得情況，因此刪掉未獲支持的購買說法，也沒有改寫成同樣缺乏證據的偷竊。承認不知道，不等於宣稱每種解釋機率都一樣。\\n\\n相關社群代表說明同類物品的社會意義，補足「紀念品」沒表達的面向。館方標明觀點來源，與文件可支持的內容並列，也不把一位代表當成整個社群唯一聲音，並開放可進一步查核的新資訊。\\n\\n有訪客偏愛舊標籤的簡短肯定，也有人肯定揭露未知。館方保留簡短摘要，旁邊提供更完整說明，區分確定事實、註明來源的解釋與待解問題。將來有新證據就能修訂；嚴謹歷史不必假裝每個故事都有永遠不變的最終版本。","qs":[{"type":"heading","q":"Which heading best fits paragraph B (paragraph 2)?","options":["Proof that the box was definitely stolen","What the surviving documents can and cannot establish","A list of prices charged by the traveller"],"answer":1,"why":"第二段辨別現存文件能證明展示情況，卻不能證明取得方式。"},{"type":"tfng","q":"Statement: The donation record explained how the traveller originally obtained the box.","options":["True","False","Not Given"],"answer":1,"why":"第一段明確說捐贈紀錄沒有交代更早那次轉手。","evidence":"The museum has a record of the donation, but that record does not explain the earlier transfer."},{"type":"tfng","q":"Statement: The museum identified the source of the community perspective.","options":["True","False","Not Given"],"answer":0,"why":"第三段說社群的說明有標示來源。","evidence":"Their contribution is presented with its source identified, alongside the museum's account of what its documents show."},{"type":"tfng","q":"Statement: The wooden box was originally made in the nineteenth century.","options":["True","False","Not Given"],"answer":2,"why":"開頭說多年前捐贈，沒有交代製作年代；捐入時間也不能當作製作時間。","evidence":"A fictional town museum owns a decorated wooden box donated by a wealthy traveller many years ago."},{"type":"detail","q":"What did staff do with the unsupported claim that the box had been purchased?","options":["They removed it without substituting an unsupported theft claim.","They kept it because a confident label must be correct.","They asked visitors to select whichever history they preferred as fact."],"answer":0,"why":"第二段先刪除購買假設，也避免改成同樣無證據的偷竊說法。","evidence":"The museum also avoids replacing that unsupported claim with an equally unsupported account of theft."},{"type":"vocab","q":"In paragraph D, \\"attributed interpretations\\" are interpretations that…","options":["cannot be changed even when new evidence appears","are accepted as facts without any evidence","are connected explicitly to their source"],"answer":2,"why":"attributed 表示註明由誰提出，不是把觀點直接當成已證實的事實。"},{"type":"evidence","q":"Why is one community representative not treated as speaking for everyone?","options":["The museum has decided that community knowledge is always irrelevant.","The exhibition recognises that interpretations may differ within a community.","The representative was the original owner of every object in the exhibition."],"answer":1,"why":"不把一人當作所有人的聲音，接著指出解釋有差異，可推知館方保留社群內部多樣觀點。","evidence":"Instead, it indicates where interpretations differ and invites further information that can be examined."},{"type":"detail","q":"How does the museum accommodate different depths of reading?","options":["It places a concise summary beside the box and a longer account nearby.","It removes every explanation so visitors must ask the donor.","It limits entry to visitors who have read the original catalogue."],"answer":0,"why":"最後一段直接交代摘要與較長說明並設。","evidence":"The museum keeps a concise summary beside the box and offers a longer account nearby, allowing different depths of reading."},{"type":"main","q":"What is the passage’s main argument about historical labels?","options":["They should present every possible explanation as equally probable.","They should preserve their first version regardless of later evidence.","They should distinguish evidence, interpretations and questions that remain open."],"answer":2,"why":"全文重點是說明證據範圍與觀點來源，並讓新證據可以修正說法。"},{"type":"tfng","q":"Statement: The museum offers every visitor only one account of the box.","options":["True","False","Not Given"],"answer":1,"why":"展品旁有精簡說明，附近另有較詳盡的版本。","evidence":"The museum keeps a concise summary beside the box and offers a longer account nearby","additional":true}]},{"id":"b2-mid-tree-plan","level":"B2","band":"mid","title":"The Work After the Planting Day","topic":"環境規劃與長期照顧","words":329,"ielts":true,"paras":["A fictional town announces a plan to plant trees along a walking route used by students and older residents. The opening event attracts volunteers, photographs and enthusiastic local coverage. Yet the planning officer argues that the ceremony should be treated as a beginning. The council's own proposal says that the intended benefits depend on the trees surviving and developing in suitable locations, not simply on the number placed in the ground that afternoon.","Before choosing sites, the team marks underground services, narrow pavements and entrances that must remain usable. A broad space on a map is not automatically an appropriate planting space. Residents also identify places where people wait outside rather than merely pass through. Their suggestions shift attention towards a bus stop and a public seating area. The final locations reflect these practical observations as well as the appearance of an evenly spaced line of trees.","The budget creates another decision. Spending the full amount on the largest possible number of trees would leave no money for the maintenance described in the proposal. The council therefore chooses a smaller initial group and assigns responsibility for inspections and ongoing care. Local volunteers can report damage, but the plan does not make tree survival depend entirely on unpaid labour. A named council team remains responsible for arranging the work and keeping records.","When reporting progress, the town publishes both the number planted and the number still present at later checks. It explains replacements separately, so repeatedly planting in one failed location cannot silently inflate the achievement. The report also records whether entrances remain clear and whether residents find the selected locations useful. These measures do not provide an instant verdict on every long-term benefit. They do, however, connect the original promise with work that can be followed over time. The project suggests that public enthusiasm becomes more valuable when someone is clearly responsible for what happens after the cameras leave, including the ordinary tasks that rarely appear in launch photographs."],"zh":"虛構小鎮計畫在學生與長者常走的路線種樹，活動有志工、照片與熱烈報導。但規劃人員提醒，典禮只是開始；依計畫書，預期效益取決於樹木能在合適位置存活成長，而不只是當天種下幾棵。\\n\\n選點前，團隊標出地下設施、狹窄人行道與必須保留的出入口。居民補充哪些地方人會停留等待，讓注意力轉向公車站及公共座椅區，而非只追求樹列整齊好看。\\n\\n如果把所有經費花在最多棵數，就沒有計畫中需要的維護費，因此議會先選較少樹木，明定巡查與後續照顧責任。志工可通報損壞，但不把存活完全押在無償勞動上；指定公部門團隊仍需安排工作與保留紀錄。\\n\\n成果報告同時列種植數和後續仍存在的棵數，補種另列，避免同一失敗地點反覆種植卻虛增成果，也檢查入口是否暢通及居民是否認為位置有用。這些指標不能立刻判定全部長期效益，但能把承諾與可追蹤工作連起來。","qs":[{"type":"heading","q":"Which heading best fits paragraph C (paragraph 3)?","options":["Choosing the greatest number regardless of maintenance costs","Reserving resources and assigning long-term responsibility","Making volunteers solely responsible for every tree"],"answer":1,"why":"第三段說明保留維護經費並指定負責團隊。"},{"type":"tfng","q":"Statement: The council spent its entire budget on buying as many trees as possible.","options":["True","False","Not Given"],"answer":1,"why":"原文說選擇較少的第一批，並安排巡查與後續照顧，與花光經費買最多棵相反。","evidence":"The council therefore chooses a smaller initial group and assigns responsibility for inspections and ongoing care."},{"type":"tfng","q":"Statement: Residents’ suggestions directed attention towards places where people wait.","options":["True","False","Not Given"],"answer":0,"why":"第二段說居民指出停留等候的地點，後文舉公車站和座椅區。","evidence":"Residents also identify places where people wait outside rather than merely pass through."},{"type":"tfng","q":"Statement: The trees were all purchased from the same nursery.","options":["True","False","Not Given"],"answer":2,"why":"文章提到選擇第一批樹與責任分工，卻未交代購買來源或苗圃數量。","evidence":"The council therefore chooses a smaller initial group and assigns responsibility for inspections and ongoing care."},{"type":"detail","q":"Why are replacement trees recorded separately?","options":["The council wants to conceal all trees that have died.","Replacement trees are forbidden in the proposal.","Repeated planting in one failed location could otherwise inflate the reported achievement."],"answer":2,"why":"第四段明說另列補種是避免同一地點反覆種植被默默算成更多成果。","evidence":"It explains replacements separately, so repeatedly planting in one failed location cannot silently inflate the achievement."},{"type":"vocab","q":"In paragraph D, \\"inflate\\" means…","options":["make something appear greater than it really is","record a result without changing its meaning","reduce the amount of maintenance required"],"answer":0,"why":"在成果數字的語境，inflate 指使成績看起來被誇大。"},{"type":"evidence","q":"What is implied by retaining a named council team?","options":["The project has no need to keep records of its work.","Public responsibility continues even when volunteers contribute.","Volunteers must personally pay for every future inspection."],"answer":1,"why":"志工參與不取代公部門安排工作與紀錄的責任。","evidence":"A named council team remains responsible for arranging the work and keeping records."},{"type":"detail","q":"Which practical constraints are checked before selecting sites?","options":["The order in which photographers arrive","The colour of every volunteer’s clothing","Underground services, narrow pavements and usable entrances"],"answer":2,"why":"第二段首句列出設施、人行道與入口等選址限制。","evidence":"Before choosing sites, the team marks underground services, narrow pavements and entrances that must remain usable."},{"type":"main","q":"Which contrast shapes the passage?","options":["Visible launch activity versus the continuing work required to fulfil a promise","Public walking routes versus places where nobody is allowed to walk","Experienced volunteers versus a ban on community involvement"],"answer":0,"why":"全文把熱鬧的種植當天與維護、責任、後續成果連起來。"},{"type":"tfng","q":"Statement: The first group of trees included more than one species.","options":["True","False","Not Given"],"answer":2,"why":"原文交代第一批數量較少及如何維護，全文沒說樹種數量。","evidence":"The council therefore chooses a smaller initial group and assigns responsibility for inspections and ongoing care.","additional":true}]},{"id":"b2-mid-repair-design","level":"B2","band":"mid","title":"The Cost Hidden Behind a Sealed Case","topic":"產品設計與維修選擇","words":347,"ielts":true,"paras":["Imagine two fictional laptops offered to a college. Model A is cheaper to purchase and has a thin, sealed case. Model B costs more initially, but its supplier provides replaceable components, repair instructions and prices for common parts. Neither description by itself tells the purchasing team which option will cost less over the period of use. That depends partly on what breaks, what can be repaired and how long a repair takes.","The team asks both suppliers to describe the same situation: a battery fails after the warranty has ended. For Model A, the quotation requires the device to be sent to a central service centre. For Model B, an approved local technician can replace the battery. These are conditions of the fictional offers, not general claims about all thin or repairable computers. The comparison makes an otherwise vague promise of 'easy maintenance' open to specific questions.","Access to a replacement part is only one issue. A part may be listed in a catalogue but unavailable when needed, or priced so highly that replacement is impractical. The college therefore asks how long parts will be supplied and how repairs affect the device's remaining support. It also considers temporary equipment for students whose computers are away. A low repair charge could still be inconvenient if a student loses access during an important assignment.","There are limits to the team's prediction. Future failures cannot be known exactly, so the college compares several plausible situations instead of announcing one certain lifetime cost. It keeps the assumptions visible, including the expected period of use and the number of spare devices available. If those assumptions change, the preferred offer may change too.","The final recommendation treats repairability as a set of practical arrangements rather than a flattering product label. Purchase price remains important, but it is considered alongside continued access, usable repair information and realistic support. This approach does not guarantee that the more expensive model is always better. It explains what evidence would make either choice defensible, which is more useful than choosing on appearance or an unsupported claim about value."],"zh":"想像學院比較兩款虛構筆電：A 購價低、外殼薄且封閉；B 起初較貴，但供應商提供可更換零件、維修說明和價格。光看描述還不知道整段使用期間何者較便宜，因為還要考慮故障項目、能否維修及所需時間。\\n\\n學院請兩家回答同一情境：保固到期後電池壞了。A 報價需送中央維修中心，B 可由認可在地技師更換。這只是虛構報價的條件，不是對所有薄型或可維修電腦的通則，目的是把容易維護的模糊承諾變成可問清楚的條件。\\n\\n零件有列在目錄不代表需要時買得到，也可能太貴。學院因此詢問供應期限、維修對後續支援的影響，並考慮送修期間的備用設備。修理便宜，若重要作業期間無電腦使用，仍可能造成困難。\\n\\n未來故障無法完全預知，所以比較多種合理情境，公開預計使用年限與備用機數等假設；假設改變時，較合適的選擇也可能改變。\\n\\n最後把可維修性看成具體安排，而不是好聽標籤。購價仍重要，但須連同持續使用、可用維修資訊和支援一起看。這不保證貴的永遠好，而是說明需要哪些證據才能支持任一選擇。","qs":[{"type":"heading","q":"Which heading best fits paragraph C (paragraph 3)?","options":["Why the existence of a spare part is not enough","Proof that every spare part is inexpensive","A method for predicting the exact date of every failure"],"answer":0,"why":"第三段補充供貨、價格、支援及送修期間設備等條件，說明有零件還不夠。"},{"type":"tfng","q":"Statement: Model B costs less to purchase than Model A.","options":["True","False","Not Given"],"answer":1,"why":"第一段說 B 初期價格較高，與敘述相反。","evidence":"Model B costs more initially, but its supplier provides replaceable components, repair instructions and prices for common parts."},{"type":"tfng","q":"Statement: Under the fictional offer, a local technician approved for the work can replace Model B’s battery.","options":["True","False","Not Given"],"answer":0,"why":"第二段直接說 B 的電池可由認可在地技師更換。","evidence":"For Model B, an approved local technician can replace the battery."},{"type":"tfng","q":"Statement: Model A’s manufacturer is based in Japan.","options":["True","False","Not Given"],"answer":2,"why":"文章介紹 A 的價格與外殼，沒有提製造商所在地。","evidence":"Model A is cheaper to purchase and has a thin, sealed case."},{"type":"detail","q":"What common situation is put to both suppliers?","options":["A student wanting a different screen colour before purchase","A battery failing after the warranty ends","A college planning to manufacture its own computers"],"answer":1,"why":"第二段用同一保固外電池故障情境作公平比較。","evidence":"The team asks both suppliers to describe the same situation: a battery fails after the warranty has ended."},{"type":"vocab","q":"In paragraph E, a \\"defensible\\" choice is one that…","options":["can never change under any circumstances","must have the lowest initial price","can be supported by reasons and evidence"],"answer":2,"why":"defensible 指可以提出理由與證據支持，不表示永遠不可修正。"},{"type":"evidence","q":"Why might a cheap repair still create a serious inconvenience?","options":["The student may be without a computer at a time when access matters.","Every inexpensive part is guaranteed to fail immediately.","The college has banned the use of temporary equipment."],"answer":0,"why":"第三段指出若送修造成重要作業期間無法使用，低費用仍有代價。","evidence":"A low repair charge could still be inconvenient if a student loses access during an important assignment."},{"type":"detail","q":"What does the college do because future failures are uncertain?","options":["It reports one lifetime cost as completely certain.","It compares several plausible situations and states its assumptions.","It ignores every cost that occurs after purchase."],"answer":1,"why":"第四段明說不宣稱唯一確定成本，而是比較多個合理情境。","evidence":"Future failures cannot be known exactly, so the college compares several plausible situations instead of announcing one certain lifetime cost."},{"type":"main","q":"What is the main purpose of the passage?","options":["To establish that all expensive computers are better than cheaper ones","To argue that purchase price should never be considered","To show how practical evidence can clarify claims about repairability and value"],"answer":2,"why":"全文把維修與價值拆成可查核的安排，沒有預設一定選哪款。"},{"type":"tfng","q":"Statement: In the final recommendation, the price at purchase is still a consideration.","options":["True","False","Not Given"],"answer":0,"why":"最後一段保留買入價格，和持續取得支援、修理資訊等條件一起考量。","evidence":"Purchase price remains important, but it is considered alongside continued access, usable repair information and realistic support.","additional":true}]},{"id":"b2-mid-opening-hours","level":"B2","band":"mid","title":"An Extra Evening at the Advice Desk","topic":"公共服務與時段安排","words":358,"ielts":true,"paras":["The following proposal concerns a fictional college advice desk. It currently closes before many students return from placements. An extra evening session seems an obvious solution, but the staff preparing the proposal want to identify which questions require an appointment and which can be answered another way. Their objective is not simply to keep a door open for longer. It is to help students obtain the kind of assistance they actually need.","Some matters involve a private discussion about personal circumstances. Others concern dates and procedures already listed online, although students report difficulty finding the relevant page. The proposal therefore combines a trial evening session with clearer navigation on the website. Improving the website is not intended to remove personal support. It may allow staff to spend more of the additional session on questions that require a conversation.","Staffing is the main constraint. The desk cannot add evening work indefinitely while expecting the same people to begin at their usual time the next morning. The proposed rota reallocates existing hours and identifies who will cover ordinary daytime duties. Staff are invited to flag conflicts before the trial starts. The document also states that the arrangement will be reviewed rather than becoming permanent merely because it has once appeared on a timetable.","The evaluation will record attendance, waiting time and questions that remain unresolved. It will also ask students who requested an appointment but did not attend about practical barriers. Low attendance might reflect a badly chosen evening, unclear booking instructions or little need for that particular service. These possibilities call for different responses. The proposal consequently avoids setting a rule that any quiet session must immediately be cancelled.","At the end of the trial, the college will compare what was achieved with the staff time required and the effects on daytime access. Keeping the session, moving it or replacing part of it with another form of support will all remain possible. The central commitment is to improve access, not to defend the first schedule regardless of experience. A change of plan can therefore count as learning from the trial rather than proof that trying it was a mistake."],"zh":"這份虛構學院諮詢櫃檯提案指出，許多學生實習回來前櫃檯就關了。但延長時間前，團隊先區分哪些問題需要約談、哪些能用其他方式回答，目標是讓學生得到真正需要的協助。\\n\\n部分事項涉及私人處境，部分只是網站已有卻難找到的日期或流程，因此提案同時試辦晚間時段並改善網站導覽。網站不是要取代個別支持，而是讓人員把更多時間用於需對談的問題。\\n\\n人力是主要限制，不能無限增加晚班又要求隔天照常早到。新班表重新分配現有工時、明定日間工作由誰補位，也讓人員在開始前提出衝突；試辦不會只因排過一次就自動永久化。\\n\\n評估記錄出席、等候與未解決問題，也詢問約了沒來的人遇到什麼障礙。人少可能來自時間不合、預約說明不清或需求少，需要不同處理，因此不把任何冷清時段都直接取消。\\n\\n試辦結束後比較成果、人力成本及對日間服務的影響，可以保留、換時段或改用部分其他服務。承諾是改善使用機會，而非無論結果如何都護著第一份班表；調整也是學習。","qs":[{"type":"heading","q":"Which heading best fits paragraph C (paragraph 3)?","options":["Adding unlimited work without changing the rota","Making additional access compatible with staff capacity","Making the first trial schedule permanent automatically"],"answer":1,"why":"第三段處理工時重分配、日間補位與檢討安排。"},{"type":"tfng","q":"Statement: The proposal uses both an evening session and improved website navigation.","options":["True","False","Not Given"],"answer":0,"why":"第二段直接說提案同時包括兩項改變。","evidence":"The proposal therefore combines a trial evening session with clearer navigation on the website."},{"type":"tfng","q":"Statement: The proposal requires every quiet session to be cancelled immediately.","options":["True","False","Not Given"],"answer":1,"why":"第四段明確說避免這種規則，因人少可能有不同原因。","evidence":"The proposal consequently avoids setting a rule that any quiet session must immediately be cancelled."},{"type":"tfng","q":"Statement: The evening session will take place every Wednesday.","options":["True","False","Not Given"],"answer":2,"why":"文章說明試辦晚間諮詢，但沒有給星期幾。","evidence":"The proposal therefore combines a trial evening session with clearer navigation on the website."},{"type":"detail","q":"Why are some website changes included?","options":["Students have difficulty finding information that is already online.","All private discussions must now take place on public pages.","The advice desk has no plans to offer personal conversations."],"answer":0,"why":"第二段指出資訊雖存在，學生卻難找到，所以改善導覽。","evidence":"Others concern dates and procedures already listed online, although students report difficulty finding the relevant page."},{"type":"vocab","q":"In paragraph C, \\"constraint\\" most nearly means…","options":["a choice that has no practical consequence","a guarantee that a proposal will succeed","a limitation that affects what can be done"],"answer":2,"why":"人力限制可行安排，因此 constraint 是限制條件。"},{"type":"evidence","q":"What does the proposal imply about changing the schedule after the trial?","options":["A revision would necessarily mean the whole trial was pointless.","A revision may show that the college has learned from experience.","The first schedule must be defended even if access becomes worse."],"answer":1,"why":"最後一句說調整可被視為從試辦學習，不必等同最初嘗試錯誤。","evidence":"A change of plan can therefore count as learning from the trial rather than proof that trying it was a mistake."},{"type":"detail","q":"Who will be asked about barriers as part of the evaluation?","options":["Students who requested an appointment but did not attend","Only staff who wrote the original proposal","Only students who never needed the service"],"answer":0,"why":"第四段把已預約但缺席者納入，調查實際障礙。","evidence":"It will also ask students who requested an appointment but did not attend about practical barriers."},{"type":"main","q":"Which aim takes priority over keeping a particular timetable?","options":["Replacing every kind of personal support with a website","Ensuring that every session has exactly the same attendance","Improving students’ access to useful assistance"],"answer":2,"why":"最後一段明說核心承諾是改善使用機會，而不是維護原班表。"},{"type":"tfng","q":"Statement: The college will compare the trial’s results with the staff time it required.","options":["True","False","Not Given"],"answer":0,"why":"末段明說試辦結束後要對照成果、人力與白天服務受到的影響。","evidence":"At the end of the trial, the college will compare what was achieved with the staff time required and the effects on daytime access.","additional":true},{"type":"tfng","q":"Statement: Moving the session is ruled out when the trial ends.","options":["True","False","Not Given"],"answer":1,"why":"試辦之後仍可保留、移動時段，或用另一種方式提供部分支援。","evidence":"Keeping the session, moving it or replacing part of it with another form of support will all remain possible.","additional":true}]},{"id":"b2-mid-survey","level":"B2","band":"mid","title":"The Voices Outside the Survey","topic":"問卷與代表性","words":360,"ielts":true,"paras":["Suppose a fictional college asks students to complete an online survey about the dining hall. Of the one hundred students who reply, seventy say they are satisfied. The headline 'seventy per cent of respondents are satisfied' accurately describes those replies. Changing it to 'seventy per cent of all students are satisfied' introduces a different claim. The second statement requires reasons to believe that the respondents adequately represent the wider student population.","Participation may be connected to the experience being measured. Students who regularly eat in the dining hall might notice the survey link more often. Students who avoid the hall because the opening hours do not suit them could be less visible. Alternatively, particularly dissatisfied students might be eager to respond. The passage does not establish which pattern occurred in the fictional survey; these are possibilities that explain why voluntary responses need careful interpretation.","The college can investigate by comparing the respondents with the groups it hoped to hear from. For example, it might check whether students living away from campus are missing from the responses. Any such comparison should use only information relevant to the evaluation and handle it appropriately. A reminder through another channel may broaden participation, but it cannot guarantee that every remaining difference disappears. Adding more replies from the same narrow group might increase the total without improving coverage.","Question wording matters too. Asking whether students appreciate the 'excellent new dining hall' invites agreement with a positive description before their experience has been explored. A more neutral question asks how satisfied or dissatisfied they are and allows them to explain why. The response choices should also provide a way to indicate that the student has not used the service. Otherwise, an apparent opinion might be a guess made because none of the options fits.","The final report therefore names the responding group, explains how replies were collected and states important gaps. The result can still inform decisions without being presented as a perfect portrait of everyone. A useful survey does not become worthless because it has limitations. Its value depends partly on making those limitations visible so that a reader can judge what the findings support."],"zh":"假設虛構學院調查餐廳，100 名回覆者中 70 名滿意。「70％回覆者滿意」符合資料，但改成「全校學生 70％滿意」就多了一個需要證據的推論：回覆者能否代表所有學生。\\n\\n是否參與可能與被測量的經驗有關。常吃餐廳者較容易看到連結，因營業時間不合而不去的人可能較少出現；也可能特別不滿的人更願意回覆。本文沒有認定虛構調查實際屬於哪一種，而是指出自願回覆需謹慎解讀。\\n\\n學院可比較回覆者與原本想涵蓋的群體，例如校外住宿者是否缺席；只使用評估相關資訊並妥善處理。換管道提醒可能擴大參與，但不保證消除所有差異；同一小群體多填幾份，不一定改善涵蓋範圍。\\n\\n措辭也重要：先稱餐廳很優秀再問喜不喜歡，會先帶入正面評價。中性題目可問滿意或不滿意程度及原因，也提供未使用服務的選項，避免受訪者因沒有合適答案而猜。\\n\\n最終報告說明回覆群體、蒐集方法與重要缺口。有限制不等於毫無價值；揭露限制能讓讀者判斷結果可以支持哪些決策。","qs":[{"type":"heading","q":"Which heading best fits paragraph B (paragraph 2)?","options":["Possible links between experience and willingness to respond","A calculation of the dining hall’s annual profit","Proof that only dissatisfied students replied"],"answer":0,"why":"第二段列出不同回覆傾向的可能原因，但未認定哪種已發生。"},{"type":"tfng","q":"Statement: Seventy of the one hundred respondents were satisfied in the fictional example.","options":["True","False","Not Given"],"answer":0,"why":"第一段的假設數字是 100 人回覆、其中 70 人滿意。","evidence":"Of the one hundred students who reply, seventy say they are satisfied."},{"type":"tfng","q":"Statement: More responses from the same narrow group always improve coverage.","options":["True","False","Not Given"],"answer":1,"why":"第三段指出同一小群體增加回覆，可能只增加總量而沒有改善涵蓋。","evidence":"Adding more replies from the same narrow group might increase the total without improving coverage."},{"type":"tfng","q":"Statement: The college had exactly two thousand enrolled students.","options":["True","False","Not Given"],"answer":2,"why":"文章提供回覆者人數，但沒有全校註冊人數；兩者不能混用。","evidence":"Of the one hundred students who reply, seventy say they are satisfied."},{"type":"detail","q":"Which response option does the passage recommend including?","options":["An option requiring everyone to praise the new dining hall","An option asking every respondent for unrelated private information","An option for students who have not used the service"],"answer":2,"why":"第四段說未使用者也需有能正確作答的選項。","evidence":"The response choices should also provide a way to indicate that the student has not used the service."},{"type":"vocab","q":"In paragraph C, \\"coverage\\" refers to…","options":["the colour and design of the questionnaire’s first page","how well the responses include the intended groups","the amount of food served at each meal"],"answer":1,"why":"本段比較回覆者與想涵蓋的學生群體，coverage 指涵蓋程度。"},{"type":"evidence","q":"Why is the wider claim about all students harder to justify?","options":["It assumes that the responding group represents people who did not reply.","No survey result can ever contribute to a decision.","The arithmetic seventy divided by one hundred is incorrect."],"answer":0,"why":"第一段指出從回覆者擴到全校，需要代表性的支持。","evidence":"The second statement requires reasons to believe that the respondents adequately represent the wider student population."},{"type":"detail","q":"What information should the final report make clear?","options":["Only the positive findings that favour the dining hall","The assumption that every unanswered question means satisfaction","Who responded, how replies were collected and where important gaps remain"],"answer":2,"why":"最後一段直接列出報告應交代的群體、方式及缺口。","evidence":"The final report therefore names the responding group, explains how replies were collected and states important gaps."},{"type":"main","q":"What does the passage encourage readers to do?","options":["Reject every survey that contains any limitation","Use survey findings while judging the scope and limits of the evidence","Treat a larger response total as automatic proof of representativeness"],"answer":1,"why":"全文主張保留調查用途，同時理解代表性、措辭與限制。"},{"type":"tfng","q":"Statement: The final report identifies how responses were collected.","options":["True","False","Not Given"],"answer":0,"why":"最後報告說明資料來自哪一群人、回覆如何收集、資料缺少什麼。","evidence":"The final report therefore names the responding group, explains how replies were collected and states important gaps.","additional":true}]},{"id":"b2-hard-roster","level":"B2","band":"hard","title":"Fairness on a Nursing Rota","topic":"護理排班與公平分工","words":446,"ielts":true,"paras":["In a fictional hospital exercise, a nursing team is asked to redesign its monthly rota. The first suggestion is attractively simple: divide weekend duties equally among all staff. Everyone would receive the same number, and the result could be checked at a glance. However, the exercise soon reveals that one visible total cannot capture every responsibility or constraint. Staff work different contracted hours, bring different experience and have previously agreed arrangements that the planner must consider.","The team separates requirements from preferences. Required coverage and an appropriate combination of skills must be established through the hospital's staffing process before individual requests are considered. A preference for a particular day off cannot by itself determine whether a shift is adequately staffed. Conversely, labelling every personal need as a mere preference would overlook arrangements that the organisation has already committed to respect. The fictional exercise does not prescribe a universal staffing ratio; it examines how decisions are explained within an existing local process.","Staff then discuss what they mean by a fair share. Equal numbers of weekend duties might be a useful starting point, but the team also considers contracted hours and the pattern of recent assignments. Someone who has repeatedly accepted an unpopular shift may reasonably ask how that contribution is recorded. The group does not agree that every inconvenience can be converted into a single numerical score. It does agree that the planner should be able to explain why two apparently similar requests receive different responses.","A draft rota is shared before publication, with a limited period for identifying overlooked conflicts. Staff can raise personal circumstances privately rather than describing them to the whole team. Changes are recorded with a reason, while sensitive details are kept separate from the public schedule. A late change made without explanation could otherwise look like favouritism even when there is a legitimate reason. Transparency therefore concerns the decision process and relevant criteria; it does not require exposing everyone's private information.","The trial is reviewed after a month. The team considers uncovered shifts, repeated changes and staff accounts of how the arrangement worked. It does not treat the absence of complaints as proof that everyone found the process fair, because some people may be reluctant to object. The exercise ends without a claim that one rota can satisfy every request. Its more modest achievement is a process in which essential coverage, previous commitments and individual contributions are considered consistently. Disagreement may remain, but it can be discussed against stated reasons instead of guesses about who received special treatment. That makes fairness something the team can examine and improve, rather than a quality declared by the person who writes the final timetable."],"zh":"在虛構醫院排班練習中，團隊先提議每人平均分配週末班，數字看起來公平且容易檢查。但大家的契約工時、經驗及已同意的安排不同，單一總數不能呈現所有限制與責任。\\n\\n團隊先區分必要條件與偏好。需依院內人力程序確認基本覆蓋與適當技能組合，再處理個別希望休假的日期；另一方面，也不能把組織已承諾尊重的個人安排全降格為一般偏好。本文不提供通用護病比，而是討論既有地方程序如何說明決策。\\n\\n公平分擔可從相同週末班數開始，但還要看契約工時與近期分配。常接受不受歡迎班別者會在意付出是否留下紀錄。團隊沒有把每種不便都轉成單一分數，卻同意兩個看似相同的要求得到不同答覆時，排班者應能解釋理由。\\n\\n正式公布前先給草案，讓人提出遺漏的衝突，也保留私下說明個人情況的管道。變更要記錄理由，敏感細節另存。透明是說明程序與相關準則，不是公開所有人的隱私。\\n\\n一個月後，團隊檢查缺班、反覆變更與同仁經驗，不把無人抱怨當成人人滿意。練習沒有保證滿足全部要求，而是建立一致考量基本人力、先前承諾及個別付出的程序。仍可能不同意，但可以根據明確理由討論，而非猜測誰被特別照顧。","qs":[{"type":"heading","q":"Which heading best fits paragraph B (paragraph 2)?","options":["Establishing requirements before weighing requests","Replacing all local staffing processes with a fixed ratio","Giving every personal preference priority over coverage"],"answer":0,"why":"第二段先確立必須的人力條件，再談偏好，同時尊重已承諾的安排。"},{"type":"tfng","q":"Statement: The exercise proposes the same staffing ratio for every hospital.","options":["True","False","Not Given"],"answer":1,"why":"第二段明確表示不訂通用人力比例，而是討論既有地方程序。","evidence":"The fictional exercise does not prescribe a universal staffing ratio; it examines how decisions are explained within an existing local process."},{"type":"tfng","q":"Statement: Staff can raise personal circumstances without addressing the entire team.","options":["True","False","Not Given"],"answer":0,"why":"第四段明說可私下提出，而不是對全體說明。","evidence":"Staff can raise personal circumstances privately rather than describing them to the whole team."},{"type":"tfng","q":"Statement: An independent reviewer will compare the trial rota with earlier rotas.","options":["True","False","Not Given"],"answer":2,"why":"文章說一個月後會檢討試辦，但沒有說由獨立審查者比較過去班表；不能把有檢討推成已指定外部比較。","evidence":"The trial is reviewed after a month."},{"type":"detail","q":"Which factors complicate a simple equal division of weekend duties?","options":["A rule requiring all staff to work identical hours","A complete absence of local requirements for coverage","Different contracted hours, experience and previous agreements"],"answer":2,"why":"第一段列出工時、經驗與先前安排等差異。","evidence":"Staff work different contracted hours, bring different experience and have previously agreed arrangements that the planner must consider."},{"type":"vocab","q":"In paragraph D, \\"favouritism\\" means…","options":["explaining the same criteria to everyone","giving someone an unfair advantage because they are preferred","keeping personal health details confidential"],"answer":1,"why":"favouritism 指偏袒，與程序一致或保護隱私不同。"},{"type":"evidence","q":"Why is the absence of complaints insufficient evidence of fairness?","options":["Some staff may hesitate to express disagreement.","The team has forbidden all private feedback.","Every silent staff member has approved every decision."],"answer":0,"why":"第五段指出有些人可能不願反對，所以沉默不等於同意。","evidence":"It does not treat the absence of complaints as proof that everyone found the process fair, because some people may be reluctant to object."},{"type":"detail","q":"How are schedule changes and sensitive details handled?","options":["All personal circumstances are printed on the public timetable.","Changes are made without any record to protect the planner.","Reasons for changes are recorded, while sensitive details are kept separately."],"answer":2,"why":"第四段區分可問責的理由紀錄與不必公開的個人資料。","evidence":"Changes are recorded with a reason, while sensitive details are kept separate from the public schedule."},{"type":"evidence","q":"What does the passage imply about transparency?","options":["Fairness requires publication of every employee’s personal circumstances.","People need understandable reasons without unrestricted access to private details.","A private discussion makes any decision impossible to explain."],"answer":1,"why":"透明針對程序及準則，並不要求揭露全部隱私，兩者可以並存。","evidence":"Transparency therefore concerns the decision process and relevant criteria; it does not require exposing everyone's private information."},{"type":"main","q":"Which outcome does the exercise claim?","options":["A more consistent and explainable decision process despite remaining disagreement","Proof that one numerical measure captures every aspect of fairness","A guarantee that no staff member will ever dislike a shift"],"answer":0,"why":"結尾是較謙抑的程序改善，不是完美排班或單一數字保證公平。"},{"type":"tfng","q":"Statement: The rota is reviewed before the first month of the trial is complete.","options":["True","False","Not Given"],"answer":1,"why":"末段明說這項班表試行滿一個月後才評估。","evidence":"The trial is reviewed after a month.","additional":true}]},{"id":"b2-hard-warning-model","level":"B2","band":"hard","title":"When a Warning Needs an Explanation","topic":"醫療科技與人工智慧監督","words":459,"ielts":true,"paras":["A fictional hospital committee is considering software that flags records for clinical review. Its supplier presents an impressive overall accuracy figure, but the committee asks a prior question: what decision will the warning support? A tool intended to draw attention to a record is different from a tool authorised to make a treatment decision. In this proposal, the warning would prompt review by trained staff; it would not diagnose a patient or automatically alter treatment.","The committee examines the evaluation rather than accepting the headline alone. It asks which patients were included, what counted as a correct result and whether important conditions were missed. A hypothetical demonstration makes the issue concrete: among twenty flagged records, reviewers judge four to need the particular follow-up being studied. That observation describes the flagged group only. It does not reveal how many unflagged records also needed follow-up, so it cannot establish that the system found everyone who required attention. The figures are invented for the lesson, not reported results from a real hospital.","Staff consider what happens after a warning appears. If the message has no named recipient or arrives when no one can respond, a technically successful alert may have little practical value. The proposed workflow therefore specifies who reviews it, how the response is documented and how uncertainty is escalated. Staff also need a way to report warnings that appear misleading. The plan does not assume that simply adding more alerts will make care safer; it asks whether the information can be acted on responsibly.","The next issue is change over time. The data available during an earlier evaluation may differ from the records used after deployment. A revised form, a new patient group or a changed recording practice could alter what the software receives. These are possible risks to investigate, not proof that the tool will fail. The committee consequently asks for ongoing monitoring and a clear process for suspending use when a serious concern arises. It also asks who can authorise an update and how users will know that a version has changed.","The proposal reflects broader ethical questions about artificial intelligence in health: oversight, understandable responsibilities, inclusion and protection of personal information. The committee wants meaningful access controls rather than the unrestricted reuse of records simply because they are available. It also requires a route for staff and affected patients to raise concerns. Approval would therefore concern a whole arrangement of people, information and review, not just a number in a supplier's presentation. A warning is useful only within a process that can examine it, respond appropriately and recognise when further evidence is needed. The committee remains open to the tool, while refusing to treat confidence in its marketing as a substitute for evidence about its intended use."],"zh":"虛構醫院委員會考慮導入標記病歷、提醒臨床檢視的軟體。供應商提出漂亮的整體準確度，但委員會先問它要支援什麼決策。本提案由受訓人員檢視警示，不讓軟體自行診斷或調整治療。\\n\\n委員會檢查測試對象、正確結果的定義與漏掉的重要情況。教學假設中，20 份被標記病歷有 4 份經確認需要研究中的特定後續評估；這只描述被標記者，無法知道未被標記者還漏了多少，因此不能宣稱找到所有需要者。數字完全為教學虛構。\\n\\n警示若沒有指定接收者，或出現時沒人處理，即使技術上成功也可能沒實際用途。因此規劃誰檢視、如何記錄回應、不確定時如何往上求助，也讓人員回報誤導警示。增加警示不被直接當成更安全。\\n\\n系統上線後，表單、病人組成或紀錄習慣可能改變輸入資料；這些是待查風險，不是已證明一定失效。因此需要持續監測、嚴重疑慮時暫停的程序，以及更新授權和版本通知。\\n\\n提案也討論人工智慧的倫理問題：監督、責任、包容及個資保護。資料不能只因拿得到就任意再利用，也要讓人員與受影響病人提出疑慮。核准的是整套人員、資訊及檢視流程，而不只是簡報上的一個數字；保持開放也必須要求符合用途的證據。","qs":[{"type":"heading","q":"Which heading best fits paragraph B (paragraph 2)?","options":["Why results for flagged records cannot reveal every missed case","A comparison of twenty real hospitals","Evidence that the system found all patients needing review"],"answer":0,"why":"第二段用虛構數字說明，被標記群體的結果不能告訴我們未標記者漏了多少。"},{"type":"tfng","q":"Statement: The proposed software would automatically change treatment after every warning.","options":["True","False","Not Given"],"answer":1,"why":"第一段明說提醒受訓人員檢視，不會自動改變治療。","evidence":"In this proposal, the warning would prompt review by trained staff; it would not diagnose a patient or automatically alter treatment."},{"type":"tfng","q":"Statement: The numerical demonstration is invented for teaching.","options":["True","False","Not Given"],"answer":0,"why":"第二段最後一句明確交代數字是課程虛構，非真實醫院研究。","evidence":"The figures are invented for the lesson, not reported results from a real hospital."},{"type":"tfng","q":"Statement: The committee has already compared the tool’s performance across three hospitals.","options":["True","False","Not Given"],"answer":2,"why":"文章說委員會檢視評估內容，未交代測試醫院數或已完成跨院比較；問題清單不等於這項研究已做完。","evidence":"The committee examines the evaluation rather than accepting the headline alone."},{"type":"detail","q":"In the hypothetical demonstration, how many flagged records required the particular follow-up?","options":["All twenty","Sixteen out of twenty","Four out of twenty"],"answer":2,"why":"第二段的教學數字是 20 份警示中有 4 份需要該特定追蹤，不能把剩下 16 份當成需要者。","evidence":"A hypothetical demonstration makes the issue concrete: among twenty flagged records, reviewers judge four to need the particular follow-up being studied."},{"type":"vocab","q":"In paragraph C, \\"escalated\\" means that uncertainty is…","options":["hidden so that the warning appears certain","referred through an appropriate route for further support or review","converted automatically into a treatment order"],"answer":1,"why":"語境是在不確定時透過適當管道請更進一步協助或檢視。"},{"type":"evidence","q":"Why is a named recipient important?","options":["A warning has limited value if responsibility for responding is unclear.","The software must replace every other communication route.","A named recipient makes every algorithmic result correct."],"answer":0,"why":"第三段指出沒人負責或無法回應，技術上發出的警示仍可能沒有實際價值。","evidence":"If the message has no named recipient or arrives when no one can respond, a technically successful alert may have little practical value."},{"type":"detail","q":"Which change could alter the information received by the system?","options":["A higher overall accuracy figure in the supplier’s presentation","The committee’s decision to name who reviews each warning","A revised form or a change in recording practice"],"answer":2,"why":"第四段列出表單、病人群體、紀錄方式改變，可能改變軟體收到的資料；廠商的整體準確率和誰來審閱警示，都不會改變輸入的資料。","evidence":"A revised form, a new patient group or a changed recording practice could alter what the software receives."},{"type":"evidence","q":"What follows from not knowing the outcomes among unflagged records?","options":["The demonstration proves there were no missed cases.","The demonstration cannot show that all relevant cases were detected.","The four reviewed cases must be false warnings."],"answer":1,"why":"第二段明說不知道未標記群體，便不能判定找到了所有需要關注者。","evidence":"It does not reveal how many unflagged records also needed follow-up, so it cannot establish that the system found everyone who required attention."},{"type":"main","q":"What does the committee regard as the proper object of approval?","options":["The tool together with its workflow, oversight and information safeguards","The unrestricted collection of any records that happen to be available","The supplier’s accuracy headline without further questions"],"answer":0,"why":"結尾將核准對象界定為完整安排，而非單一數字。"},{"type":"tfng","q":"Statement: The route for raising concerns includes an anonymous option.","options":["True","False","Not Given"],"answer":2,"why":"最後一段明說員工和受影響的病人都能反映顧慮，全文沒有交代是否可匿名。","evidence":"It also requires a route for staff and affected patients to raise concerns.","additional":true}]},{"id":"b2-hard-recycling","level":"B2","band":"hard","title":"Two Percentages, Two Different Stories","topic":"回收數據與比較","words":452,"ielts":true,"paras":["A fictional town publishes a headline announcing a forty per cent recycling rate. A neighbouring town reports forty-five per cent, and a local discussion immediately declares the second programme superior. Before accepting that conclusion, a student asks what each percentage counts. A percentage is a relationship between quantities, not a complete description of an environmental programme. Without knowing the numerator, denominator and reporting boundary, readers may compare figures that answer different questions.","Consider an invented example in which Town A collects one hundred tonnes of household waste and sends forty tonnes to a recycling processor. Dividing forty by one hundred produces the headline rate of forty per cent. Suppose five of those forty tonnes are subsequently rejected by the processor, leaving thirty-five tonnes recorded as usable material. A rate based on usable material would then be thirty-five per cent of the original collection. Neither calculation is arithmetically wrong, but the labels must distinguish material sent for processing from material accepted as usable. Calling both results simply 'recycled' hides a meaningful difference.","Changes in the denominator create another complication. In a separate invented comparison, Town B previously collected one hundred tonnes and sent forty for processing. It now collects eighty tonnes and sends thirty-six. The amount sent has fallen, while its share of collected waste has risen from forty to forty-five per cent. A higher percentage therefore does not necessarily mean a larger quantity. Nor does the lower quantity by itself prove deterioration, since the report has not yet explained why total collection fell. The numerical pattern is compatible with several accounts that need further evidence.","Reporting boundaries also matter. A household collection figure cannot automatically describe waste from shops, construction sites and every other activity in the town. Comparing a single unusually busy month with another town's full year creates a further mismatch. The student therefore asks both authorities to state the waste included, the period covered and the stage at which material is measured. Where definitions differ, the difference should be explained rather than concealed behind a league table. A comparison can still be informative when its limits are visible.","Finally, the student separates evaluation from accusation. An unclear label is a reason to request a definition, not sufficient evidence that an official deliberately invented a result. Equally, accurate arithmetic does not excuse a description that encourages readers to misunderstand what was measured. The most useful report allows its headline to be checked against quantities and methods. It can then discuss progress, remaining difficulties and future choices without asking one percentage to carry the entire story. The fictional examples do not establish which town has the better environmental policy; they show what must be clarified before that judgement can be defended."],"zh":"虛構 A 鎮公布回收率 40％，鄰鎮公布 45％，大家立刻認為後者較好。學生先問：兩個百分比到底在算什麼？若不知道分子、分母與報告涵蓋範圍，可能是在比較不同問題。\\n\\n假設 A 鎮收集 100 公噸家戶垃圾，40 公噸送往處理廠，送處理比例就是 40％；其中又有 5 公噸被退除，留下 35 公噸可用材料，若用可用量計算就是原收集量的 35％。兩種數學都沒錯，但要清楚區分送處理與接受為可用材料，不能都只籠統叫已回收。\\n\\n另一個獨立假設是 B 鎮原先收 100、送處理 40，現在收 80、送處理 36。送處理量下降，但比例由 40％升至 45％。比例高不一定量更大，量低也不能單獨證明退步，因為尚未解釋總收集量為何下降。\\n\\n家戶資料不能自動代表商店、建築等所有活動；一個特別忙的月份與另一鎮全年也不能直接相比。因此要交代垃圾範圍、期間及在哪個處理階段計量，有不同定義就說明，而非藏在排行榜後。\\n\\n學生也區分評估與指控：標籤不清是追問理由，不足以證明官員故意造假；但算術正確也不能合理化讓讀者誤解的描述。好的報告能追查數量與方法。這些虛構例子沒有決定哪鎮政策較好，而是說明做判斷前必須釐清的事。","qs":[{"type":"heading","q":"Which heading best fits paragraph C (paragraph 3)?","options":["How a rising proportion can accompany a falling quantity","An explanation of why percentages cannot be calculated","Proof that collecting less always means failure"],"answer":0,"why":"第三段用 40／100 與 36／80 說明量降、比例卻升的可能。"},{"type":"tfng","q":"Statement: In Town A’s example, all forty tonnes sent for processing were accepted as usable.","options":["True","False","Not Given"],"answer":1,"why":"其中 5 公噸被退除，只剩 35 可用，明確不是全部 40。","evidence":"Suppose five of those forty tonnes are subsequently rejected by the processor, leaving thirty-five tonnes recorded as usable material."},{"type":"tfng","q":"Statement: Town B’s amount sent for processing fell while its percentage rose.","options":["True","False","Not Given"],"answer":0,"why":"第三段直接總結量下降、比例從 40％升為 45％。","evidence":"The amount sent has fallen, while its share of collected waste has risen from forty to forty-five per cent."},{"type":"tfng","q":"Statement: Town A pays the processing company a fee of fifty dollars per tonne.","options":["True","False","Not Given"],"answer":2,"why":"文章交代送處理量，沒有提供收費方式或單價。","evidence":"Consider an invented example in which Town A collects one hundred tonnes of household waste and sends forty tonnes to a recycling processor."},{"type":"detail","q":"What percentage of Town A’s original collection is recorded as usable after rejection?","options":["Forty-five per cent","Five per cent","Thirty-five per cent"],"answer":2,"why":"原收 100，40 中退除 5，留下 35，因此是 35％。","evidence":"A rate based on usable material would then be thirty-five per cent of the original collection."},{"type":"vocab","q":"In paragraph A, \\"denominator\\" is the quantity that…","options":["is always larger in the town judged to perform better","forms the total against which the measured part is compared","shows only material rejected by the processor"],"answer":1,"why":"分母是計算比例時拿來比較的總體量，文中例子是總收集量。"},{"type":"evidence","q":"Why can the fall in Town B’s quantity not prove deterioration on its own?","options":["The reason for the fall in total collection is still unknown.","The report has already proved that every household produced no waste.","Thirty-six tonnes is mathematically greater than forty tonnes."],"answer":0,"why":"第三段說尚未解釋總量下降原因，不能只據此判定變差。","evidence":"Nor does the lower quantity by itself prove deterioration, since the report has not yet explained why total collection fell."},{"type":"detail","q":"Which three features should authorities state to make figures more comparable?","options":["Only the town’s population, mayor’s name and slogan","The colour of bins, the paper size and the headline font","The waste included, the reporting period and the measurement stage"],"answer":2,"why":"第四段列出比較必需釐清的三項。","evidence":"The student therefore asks both authorities to state the waste included, the period covered and the stage at which material is measured."},{"type":"evidence","q":"What is the author’s position on an unclear label?","options":["It always proves that the underlying quantities were invented.","It warrants clarification but does not alone establish deliberate dishonesty.","It should be ignored whenever the division is correct."],"answer":1,"why":"最後一段區分追問定義與直接指控造假，同時不容許誤導描述。","evidence":"An unclear label is a reason to request a definition, not sufficient evidence that an official deliberately invented a result."},{"revision":1,"type":"main","q":"What is the passage chiefly teaching?","options":["How to establish what percentage comparisons can legitimately show","How to use the amount accepted by processors to rank towns’ recycling performance","Why a decline in total waste collection is the main explanation for changes in recycling rates"],"answer":0,"why":"處理後可用量與收集量都可能影響比率，全文提醒比較前須核對計量階段、範圍和期間，現在的例子不足以替城鎮排名或確定變動原因。"},{"type":"tfng","q":"Statement: The student asks the authorities to state the period covered by their figures.","options":["True","False","Not Given"],"answer":0,"why":"第四段說要交代涵蓋期間，才有辦法比較。","evidence":"The student therefore asks both authorities to state the waste included, the period covered and the stage at which material is measured.","additional":true}]},{"id":"b2-hard-consent","level":"B2","band":"hard","title":"More Than a Signature","topic":"知情同意與溝通","words":462,"ielts":true,"paras":["In a fictional teaching discussion, a student says that consent is complete when a patient signs the form. The tutor asks the group to imagine a signed page that the patient has not understood. Would the signature alone show that a meaningful decision had been made? The question shifts attention from the presence of a document to the process it is supposed to record. Forms can support good practice, but a completed box is not a direct measurement of understanding.","The lesson uses the NHS explanation of consent as its reference. That guidance describes valid consent in terms of a voluntary, informed choice made by someone who has the capacity to make the decision. Relevant information includes expected benefits, risks, reasonable alternatives and what may happen without the proposed treatment. The passage focuses on communication with an adult who can make this decision; it does not attempt to cover emergency exceptions or every country's legal rules. This stated scope matters because a brief classroom example cannot settle all the situations encountered in practice.","The fictional patient understands why a procedure is offered but believes that signing means there is no longer any opportunity to ask questions. The clinician corrects that misunderstanding and invites the patient to describe the remaining concern. A family member offers an opinion, yet the conversation returns to what the patient wants to understand. Listening to relatives can be valuable without allowing their enthusiasm or anxiety to become pressure on the person deciding. The aim is an informed choice, not merely agreement with the clinician's preferred option.","The tutor then asks how students would check their explanation. Asking 'Do you understand?' may produce a polite yes without revealing what the patient believes will happen. Inviting the patient to explain the options in their own words can expose a missing connection. If the explanation was unclear, the response is to clarify it and allow further questions, not to criticise the patient for failing a test. In this invented exercise, no procedure begins while the team is still clarifying what the patient has agreed to.","The discussion ends by returning to documentation. A useful record should reflect the decision and the conversation supporting it, according to the relevant local process. It should not turn a complicated exchange into an unsupported claim that every possible question has been resolved forever. The NHS guidance also recognises that a person may withdraw previous consent before a procedure. The class therefore treats consent as communication linked to a decision at a particular time. The signature remains part of the record where a written form is required, but its value depends on the understanding and voluntary choice behind it. The difference is subtle on a checklist and substantial in the experience of the person receiving care."],"zh":"虛構課堂中，學生認為病人簽表就完成同意。老師請大家想像一張病人沒理解卻已簽名的表單，問簽名能否單獨證明有意義的決定，讓焦點從文件轉回文件應記錄的溝通過程。\\n\\n課程以 NHS 的同意說明為依據：有效同意涉及有能力作此決定的人，自願且知情地選擇；相關資訊包括好處、風險、合理替代方案與不接受治療可能如何。本文只討論能作決定的成人溝通，不試圖涵蓋急救例外或各國所有法律。\\n\\n虛構病人了解為何建議處置，卻以為簽名後就不能提問。臨床人員澄清並請他說明擔憂；家人提供意見，但討論仍回到病人想理解什麼。家人參與可以有價值，但不能把支持或焦慮變成壓力，目標是知情選擇而非只取得同意。\\n\\n只問懂不懂可能得到客氣的是，卻看不出真正理解。請病人用自己的話說明選項，有助發現遺漏；若說明不清就再解釋、再讓他問，不是責怪病人考試失敗。本虛構練習在釐清同意內容前不開始處置。\\n\\n紀錄應依相關在地程序反映決定與溝通，不能宣稱所有問題永遠解決。NHS 也指出處置前可以撤回先前同意。因此同意與特定時間的決定和溝通連在一起；需要書面表單時簽名仍有位置，但價值來自背後的理解與自願。","qs":[{"type":"heading","q":"Which heading best fits paragraph B (paragraph 2)?","options":["The reference framework and the limits of the example","An explanation of how all emergencies must be treated","A complete account of every country’s consent law"],"answer":0,"why":"第二段說明採用 NHS 框架，並明確限定為有決策能力成人的溝通情境。"},{"type":"tfng","q":"Statement: The passage claims to explain every country’s legal rules on consent.","options":["True","False","Not Given"],"answer":1,"why":"第二段明說不涵蓋每個國家的法律，因此是直接相反。","evidence":"The passage focuses on communication with an adult who can make this decision; it does not attempt to cover emergency exceptions or every country's legal rules."},{"type":"tfng","q":"Statement: The fictional patient believes signing removes the opportunity to ask questions.","options":["True","False","Not Given"],"answer":0,"why":"第三段首句直接描述這個誤解。","evidence":"The fictional patient understands why a procedure is offered but believes that signing means there is no longer any opportunity to ask questions."},{"type":"tfng","q":"Statement: The clinician gives the patient a translated leaflet during the discussion.","options":["True","False","Not Given"],"answer":2,"why":"文章說臨床人員澄清並邀請病人說明擔憂，沒有交代是否使用說明單或翻譯版本。","evidence":"The clinician corrects that misunderstanding and invites the patient to describe the remaining concern."},{"type":"detail","q":"Which information is included in the reference framework?","options":["Only the date and location of the procedure","A guarantee that every proposed treatment will be successful","Benefits, risks, reasonable alternatives and what may happen without treatment"],"answer":2,"why":"第二段列出決策所需相關資訊，沒有保證治療結果。","evidence":"Relevant information includes expected benefits, risks, reasonable alternatives and what may happen without the proposed treatment."},{"type":"vocab","q":"In paragraph A, \\"meaningful\\" most nearly means…","options":["written in the largest possible handwriting","based on real understanding and choice","completed as quickly as possible"],"answer":1,"why":"這裡問的是決定是否有實質理解與選擇，不只是形式簽名。"},{"type":"evidence","q":"Why might a simple yes to \\"Do you understand?\\" be insufficient?","options":["It may be polite without showing the patient’s actual understanding.","It establishes that no further explanation is possible.","It always proves that the patient wants to refuse treatment."],"answer":0,"why":"第四段指出客氣答應未必揭露病人以為會發生什麼。","evidence":"Asking 'Do you understand?' may produce a polite yes without revealing what the patient believes will happen."},{"type":"detail","q":"What does the NHS guidance cited at the end recognise?","options":["A signature prevents any later change of mind.","Relatives must always choose on behalf of an adult with capacity.","Previous consent may be withdrawn before a procedure."],"answer":2,"why":"末段引用 NHS 說明，可在處置前撤回先前同意。","evidence":"The NHS guidance also recognises that a person may withdraw previous consent before a procedure."},{"type":"evidence","q":"What can be inferred about family involvement in this example?","options":["It transfers the decision automatically to the most enthusiastic relative.","It can contribute to discussion while the patient’s voluntary choice remains central.","It makes further explanation to the patient unnecessary."],"answer":1,"why":"第三段說家人意見有價值，但不能變成對決定者施壓。","evidence":"Listening to relatives can be valuable without allowing their enthusiasm or anxiety to become pressure on the person deciding."},{"type":"main","q":"What distinction is central to the passage?","options":["Recording consent versus establishing the understanding and voluntary choice the record should reflect","Making clinical information longer versus making every decision faster","Using paper forms versus banning all written documentation"],"answer":0,"why":"全文強調簽名紀錄背後的溝通與選擇，沒有否定書面紀錄本身。"},{"type":"tfng","q":"Statement: In the classroom exercise, the procedure begins before the team has clarified what the patient agreed to.","options":["True","False","Not Given"],"answer":1,"why":"第四段明說，團隊還在釐清病人同意的內容時，不會開始處置。","evidence":"In this invented exercise, no procedure begins while the team is still clarifying what the patient has agreed to.","additional":true}]},{"id":"b2-hard-essay-feedback","level":"B2","band":"hard","title":"Fast Feedback and a Fair Judgement","topic":"寫作教學與自動評量","words":456,"ielts":true,"paras":["A fictional language college trials a tool that gives immediate feedback on essays. Students value receiving comments before the next class, especially when they are unsure about a sentence they have just written. The teaching team, however, separates two proposed uses: helping a learner revise a draft and assigning a final course grade. A tool that is useful for generating a question or suggesting a revision has not thereby demonstrated that it can make a sufficiently reliable final judgement.","The college's own rubric includes answering the task, organising an argument and using language clearly. To explore the tool, teachers prepare contrasting examples. One essay uses fluent sentences but avoids the question; another expresses a relevant argument in simpler English. In the invented trial, the tool praises the first essay's surface fluency without noticing its missing response to the task. This single example does not establish how every automated system behaves. It shows why the particular tool must be checked against all the criteria it is expected to assess, rather than only the features that are easiest to display.","Students are taught to treat a suggestion as something to examine. If the tool proposes a replacement phrase, they ask whether the new wording preserves their intended meaning. They can accept a useful correction, reject an unsuitable one or bring an uncertain case to the teacher. The activity requires a brief explanation of one revision, so submitting a polished result alone is not enough. The teacher wants evidence that the learner understands the change, not merely evidence that the software can produce a smoother sentence.","Evaluation includes a varied collection of drafts, rather than only essays that are already well organised. Teachers compare the feedback with the stated rubric and discuss disagreements. They also check whether comments are understandable to learners at the intended level. A technically correct explanation can still be unhelpful if it relies on terminology the student has not learned. The college does not assume that agreement with one teacher proves permanent accuracy; the review process must itself remain open to correction.","Privacy and access are considered alongside educational value. Students are told what material may be submitted, and the college provides a route for obtaining feedback without a personal subscription. The trial uses invented personal examples instead of asking students to disclose sensitive experiences to a system. At its conclusion, teachers retain the tool for supported drafting while keeping responsibility for final assessment. That decision is specific to the evidence gathered in this fictional trial. It neither rejects every possible educational use of automation nor treats speed as a substitute for a defensible judgement. The central question is whether each proposed use is supported, understood and answerable to the people whose learning it affects."],"zh":"虛構語言學院試用即時作文回饋工具，學生喜歡不用等下次上課就收到意見。但教師先區分協助改草稿與決定期末成績兩種用途；會提建議不代表已證明能可靠地做最終評量。\\n\\n該校自訂評分規準包括回應題目、論證組織與清楚語言。教師準備流暢卻離題、簡單卻切題的對照文章。虛構試用中，工具稱讚前者表面流暢卻漏看離題。單一例子不能推論所有系統，但說明必須查核工具是否涵蓋所有預定評分項目。\\n\\n學生把建議當成要檢查的內容，確認替代語句有沒有保留原意，可以接受、拒絕或請教老師。作業需簡述一項修改理由，單交漂亮成果不夠，因為老師要知道學生理解改動，而不只是軟體能修得順。\\n\\n評估包含不同品質草稿，教師依規準比較與討論分歧，也檢查說明是否符合學習者程度。技術上正確但全是沒學過的術語仍可能沒幫助；與一位老師一致也不代表永遠正確，檢查程序本身仍可修正。\\n\\n學院也處理隱私及使用門檻，說明可提交什麼，並提供不用個人訂閱也能獲得回饋的管道；用虛構個人例子，不要求揭露敏感經驗。最後保留工具輔助草稿，教師仍負責最終評量。這只適用本次虛構試用證據，重點是各用途能否被支持、理解並接受問責，而非把速度直接當可靠判斷。","qs":[{"type":"heading","q":"Which heading best fits paragraph B (paragraph 2)?","options":["A claim that all automated systems make identical errors","Proof that fluent sentences always answer the task","Testing the tool against the full assessment rubric"],"answer":2,"why":"第二段以對照文章檢查工具是否注意所有規準，並限定單一試用例子的範圍。"},{"type":"tfng","q":"Statement: The tool identified the first sample essay’s failure to answer the task.","options":["True","False","Not Given"],"answer":1,"why":"原文明說工具稱讚流暢，卻沒注意缺少題目回應。","evidence":"In the invented trial, the tool praises the first essay's surface fluency without noticing its missing response to the task."},{"type":"tfng","q":"Statement: Students must explain at least one revision rather than submit only a polished result.","options":["True","False","Not Given"],"answer":0,"why":"第三段要求簡短說明一項修改，因此只交潤飾成果不夠。","evidence":"The activity requires a brief explanation of one revision, so submitting a polished result alone is not enough."},{"type":"tfng","q":"Statement: Teachers from another institution took part in comparing the tool’s feedback.","options":["True","False","Not Given"],"answer":2,"why":"文章說教師比較回饋與規準，但沒有交代其中是否有其他學校的教師；不能由有教師參與推論其所屬機構。","evidence":"Teachers compare the feedback with the stated rubric and discuss disagreements."},{"type":"detail","q":"What are the two uses separated at the start?","options":["Writing examination questions and arranging classroom seating","Supporting revision and assigning a final course grade","Teaching handwriting and selling printed textbooks"],"answer":1,"why":"第一段明確區分協助草稿修訂與給最終課程成績。","evidence":"The teaching team, however, separates two proposed uses: helping a learner revise a draft and assigning a final course grade."},{"type":"vocab","q":"In paragraph B, \\"surface fluency\\" refers to…","options":["smooth-sounding language that may not show whether the task is answered","a guarantee that every argument is relevant and supported","the physical surface on which an essay is printed"],"answer":0,"why":"這裡指句子看起來順暢，仍可能沒有回應題目。"},{"type":"evidence","q":"Why must learners check a replacement phrase instead of accepting it automatically?","options":["A smoother sentence always has exactly the same meaning.","Every suggested correction is necessarily a deliberate trick.","The revision may fail to preserve what they meant to say."],"answer":2,"why":"第三段要求查核新措辭是否仍保留原意，可推知流暢不保證語意相同。","evidence":"If the tool proposes a replacement phrase, they ask whether the new wording preserves their intended meaning."},{"type":"detail","q":"What arrangement remains after the fictional trial?","options":["Students are required to disclose sensitive personal experiences.","The tool supports drafting, while teachers retain final assessment responsibility.","The tool makes every final grade without teacher involvement."],"answer":1,"why":"最後一段清楚交代保留用途與教師責任。","evidence":"At its conclusion, teachers retain the tool for supported drafting while keeping responsibility for final assessment."},{"type":"evidence","q":"Why might a technically correct comment still be unsuitable?","options":["Its terminology may exceed the learner’s current knowledge.","The tool must give exactly the same comments to every student.","Correct grammar is never relevant to learning a language."],"answer":0,"why":"第四段指出術語若未學過，正確解釋仍可能難以使用。","evidence":"A technically correct explanation can still be unhelpful if it relies on terminology the student has not learned."},{"type":"main","q":"What principle guides the college’s decision?","options":["Reject all technology whenever one example contains an error","Adopt every automatic feature because it produces feedback quickly","Judge each educational use by relevant evidence rather than equating speed with reliability"],"answer":2,"why":"全文針對不同用途蒐集相應證據，既不盲目採用也不一例否定所有工具。"},{"type":"tfng","q":"Statement: Students in the trial need a personal subscription in order to receive feedback.","options":["True","False","Not Given"],"answer":1,"why":"最後一段明說，學校提供不需自己訂閱也能得到回饋的管道。","evidence":"the college provides a route for obtaining feedback without a personal subscription.","additional":true},{"type":"tfng","q":"Statement: The agreement between the reviewers had improved by the end of the trial.","options":["True","False","Not Given"],"answer":2,"why":"文中說教師比較回饋、討論評分差異，沒有提到彼此的一致性是否隨時間提升。","evidence":"Teachers compare the feedback with the stated rubric and discuss disagreements.","additional":true}]},{"id":"b2-hard-urban-heat","level":"B2","band":"hard","title":"Choosing Where Cooling Begins","topic":"城市降溫與公共資源","words":471,"ielts":true,"paras":["A fictional district has enough money to begin one part of a heat-response plan this year. Three proposals compete for attention: shade at busy waiting areas, improvements to selected building roofs and longer opening hours at an existing cooled public room. Each has supporters who can describe a benefit. The planning group decides that choosing well requires a more precise question than which idea sounds most environmentally ambitious. It needs to know who would benefit, when the benefit would become available and what continued work each option would require.","The group first examines how places are used. A photograph of an empty sunny square may look more dramatic than a narrow bus stop, yet residents spend long periods waiting at the stop. A neighbourhood average also cannot show every situation within it. People working outside, travelling between services or living in rooms that become very hot may face different practical problems. The group therefore combines location information with accounts of daily routines, rather than assuming that one map fully describes everyone's exposure.","General health guidance adds another consideration. Older adults and people affected by certain health conditions or medicines can be especially vulnerable during extreme heat. Access to a cooler place may therefore matter even when a person already understands public warnings. The planning exercise does not provide individual medical advice or tell residents to change their medicines. Instead, it asks whether the public arrangements make it realistic to follow general advice, including for people who cannot easily travel across the district.","Timing and responsibility change the comparison between proposals. One option might provide a usable benefit this season, while another requires a longer installation period. These are assumptions that the local proposal must verify, not fixed properties of every project of that type. The cooled room, for example, already exists, but longer hours would require staff, reliable access and a clear operating budget. A new facility that closes precisely when residents need it would not fulfil its stated purpose. Similarly, an installation cannot be evaluated solely on its opening day if its usefulness depends on maintenance.","The final proposal combines an initial action with a schedule for further investigation, rather than declaring one measure a complete solution. It states which groups are expected to benefit and which needs remain outside the first phase. Public feedback will examine those gaps as well as satisfaction among current users. This matters because a successful service for people who can reach it may coexist with persistent barriers for those who cannot. The district's decision is consequently framed as a choice under constraints, open to revision as evidence improves. The fictional case offers no universal ranking of roofs, shade and cooled rooms. It demonstrates that environmental ambition becomes more accountable when linked to people, timing, access and the resources needed to keep a promise working."],"zh":"虛構行政區今年只有預算先做熱應變計畫的一部分，候選方案包括等候區遮蔭、部分屋頂改善與延長既有冷氣公共空間的開放時間。選擇不能只比哪個聽起來最有環保企圖，還要問誰受益、何時受益、後續需做什麼。\\n\\n團隊先看場所如何被使用。空無一人的大廣場照片可能比狹窄公車站醒目，但居民會在站牌久候；區域平均也無法呈現戶外工作、往返服務或住在悶熱房間等不同處境，因此結合位置資訊與日常活動，避免只靠一張圖。\\n\\n一般衛教指出，長者與受某些疾病或藥物影響者在酷熱時可能特別脆弱；即使知道警告，仍需要能到達較涼的地方。本文不提供個人治療建議，也不叫居民調藥，而是檢查公共安排是否讓一般建議真正可行，包括交通不便者。\\n\\n方案的時程與責任也不同，有的可能當季可用，有的安裝較久；這是地方提案需查證的假設，不是所有同類工程的固定性質。既有冷氣房延長開門仍要人力、可靠進出與預算，開放時間不合需求就無法達成目的，需維護的設施也不能只看啟用當天。\\n\\n最後提案列出先做的措施與後續調查，說明哪些群體受益、哪些需求仍未涵蓋，並蒐集未能使用者的回饋。成功服務到一部分人，仍可能同時存在別人的障礙。案例不提供屋頂、遮蔭、冷氣房的通用排名，而是把環境承諾與人、時程、可及性和持續資源連起來。","qs":[{"type":"heading","q":"Which heading best fits paragraph B (paragraph 2)?","options":["Understanding exposure through the way people use places","Selecting a project only from the most dramatic photograph","Assuming a neighbourhood average describes every resident"],"answer":0,"why":"第二段把場所使用方式與日常活動納入，指出照片或平均值的限制。"},{"type":"tfng","q":"Statement: The passage establishes a universal ranking of the three cooling measures.","options":["True","False","Not Given"],"answer":1,"why":"末段明說案例沒有提供三者通用排名。","evidence":"The fictional case offers no universal ranking of roofs, shade and cooled rooms."},{"type":"tfng","q":"Statement: Extending the cooled room’s hours would require staffing and an operating budget.","options":["True","False","Not Given"],"answer":0,"why":"第四段列出延長開放需要人力、可靠使用與清楚營運預算。","evidence":"The cooled room, for example, already exists, but longer hours would require staff, reliable access and a clear operating budget."},{"type":"tfng","q":"Statement: Residents ranked the three proposals through a postal ballot.","options":["True","False","Not Given"],"answer":2,"why":"文章說團隊結合居民日常活動經驗與位置資訊，沒有說用郵寄投票替三方案排序。","evidence":"The group therefore combines location information with accounts of daily routines, rather than assuming that one map fully describes everyone's exposure."},{"type":"detail","q":"Which location is used to illustrate long periods of waiting?","options":["An empty exhibition hall","A narrow bus stop","A private rooftop terrace"],"answer":1,"why":"第二段對比空曠廣場與居民久候的狹窄站牌。","evidence":"A photograph of an empty sunny square may look more dramatic than a narrow bus stop, yet residents spend long periods waiting at the stop."},{"type":"vocab","q":"In paragraph E, \\"persistent\\" barriers are barriers that…","options":["have been fully removed by the first action","appear only in a planning photograph","continue to exist over time"],"answer":2,"why":"persistent 表示持續存在，指某些人仍無法使用服務。"},{"type":"evidence","q":"Why are current users’ opinions not sufficient to assess the entire plan?","options":["People unable to reach the service may still face unmet needs.","Current users are necessarily mistaken about their own experience.","The plan explicitly forbids gathering feedback from residents."],"answer":0,"why":"第五段說服務好已能到達的人，仍可能留下其他人的障礙，因此要看缺口。","evidence":"This matters because a successful service for people who can reach it may coexist with persistent barriers for those who cannot."},{"type":"detail","q":"What does the final proposal specify beyond the initial action?","options":["A guarantee that no future revision will be necessary","A schedule for further investigation and needs outside the first phase","A requirement that every resident change their medicines"],"answer":1,"why":"最後一段先提後續調查時程，再交代首期未涵蓋的需求。","evidence":"The final proposal combines an initial action with a schedule for further investigation, rather than declaring one measure a complete solution."},{"type":"evidence","q":"What does the discussion of installation time imply?","options":["All shade projects are slower than all roof projects.","Any project that takes more than one season must be abandoned.","The timing of benefits must be checked for the actual local proposal."],"answer":2,"why":"第四段強調時程是地方方案需查證的假設，不是同類工程一律如此。","evidence":"These are assumptions that the local proposal must verify, not fixed properties of every project of that type."},{"type":"main","q":"What makes the district’s decision more accountable?","options":["Connecting stated benefits with particular people, access, timing and ongoing resources","Selecting the proposal with the most ambitious publicity language","Treating one successful opening day as proof of permanent effectiveness"],"answer":0,"why":"全文把承諾轉成可追蹤的對象、時程、使用及維持條件。"},{"type":"tfng","q":"Statement: Feedback will be collected on barriers identified beyond the first phase.","options":["True","False","Not Given"],"answer":0,"why":"末段說第一階段還碰不到的需求也會納入蒐集意見，不只詢問現有使用者。","evidence":"Public feedback will examine those gaps as well as satisfaction among current users.","additional":true}]},{"id":"b2-hard-patient-portal","level":"B2","band":"hard","title":"Seeing a Record and Understanding It","topic":"病人入口網站與病歷理解","words":468,"ielts":true,"paras":["In a fictional clinic, a patient portal allows people to read selected documents between appointments. Some patients appreciate being able to revisit information when they are no longer trying to remember everything said in a consultation. Others encounter an unfamiliar abbreviation or a letter they expected to see but cannot find. The clinic discovers that making records visible creates new opportunities for participation, while also creating a need to explain what the display does and does not contain.","The design team separates three questions. Can the person enter the portal? Can they locate the relevant record? Can they understand what the record means for their next step? A successful login answers only the first. For a patient looking for a follow-up letter, the absence of that letter on the screen does not by itself establish that no plan exists. The interface should make the scope of available records and the appropriate enquiry route clear. Otherwise, a gap in the display may be mistaken for a definite statement about care.","Existing NHS App guidance illustrates several practical issues without defining how every portal operates. Some providers do not share all hospital documents through the app, and users are directed to contact the relevant provider when expected information cannot be found. The guidance also warns that downloaded health documents may be visible to other people on a shared device. These reminders concern the limits of the displayed collection and the privacy of copies outside it. They do not mean that every missing document has the same explanation or that a portal password automatically protects a copy saved elsewhere.","In the fictional clinic, a patient notices an incorrect date in a record and uses the stated contact route to request a check. The clinic explains who will review the query and how a response will be provided. It does not ask the patient to silently rewrite the clinical record, nor does it treat the query as an accusation against staff. A discrepancy becomes something to investigate through a visible process. The team also offers help by telephone or in person, recognising that digital access should not become a condition for asking a question about one's care.","The evaluation therefore goes beyond counting activated accounts. It examines unresolved enquiries, difficulty finding documents and whether users understand the available support. Staff consider how to provide explanations without exposing private information in messages visible to other people. The aim is neither to hide all complex material nor to assume that immediate access makes every term self-explanatory. A portal can support a more informed conversation when its boundaries, correction routes and privacy implications are understandable. The fictional case presents access as the start of a relationship with information, not the final proof that the information is complete, correctly understood or safely handled in every setting."],"zh":"虛構診所讓病人透過入口網站閱讀部分文件，有人能在門診後重新看資訊，也有人遇到不懂的縮寫或找不到預期的信件。把病歷開放可增加參與，但也需要解釋畫面包含什麼、不包含什麼。\\n\\n團隊區分能登入、能找到資料，以及能理解對下一步的意義三件事。登入成功只回答第一項。找不到追蹤信件，不等於沒有照護計畫；介面需說明可見紀錄範圍及詢問管道，以免把顯示缺口誤認為照護的確定結論。\\n\\nNHS App 指引提供實務例子，但不代表所有網站都相同：部分服務提供者不會透過 App 分享全部醫院文件，找不到預期資訊時需聯絡相關單位；下載的健康文件在共用裝置上也可能被他人看見。這些提醒關於資料集合範圍及外部副本隱私，不表示所有缺件原因相同，也不表示登入密碼能保護已複製出去的檔案。\\n\\n虛構病人發現日期錯誤，依管道提出查核。診所說明由誰檢視及如何回覆，不讓病人默默改寫臨床紀錄，也不把詢問直接當作指控。團隊保留電話及現場協助，不讓數位登入成為詢問自身照護的必要條件。\\n\\n評估除了啟用帳號數，也看未解決詢問、找資料的困難及是否知道支援管道，並考慮訊息隱私。目的不是藏起複雜內容，也不是以為一開放就人人懂；清楚界線、修正途徑與隱私意義，才能支持更充分的對話。","qs":[{"type":"heading","q":"Which heading best fits paragraph B (paragraph 2)?","options":["Distinguishing entry, finding information and understanding it","Measuring understanding only through successful logins","Treating every missing letter as a cancelled care plan"],"answer":0,"why":"第二段將登入、找到與理解分開，避免把第一步完成當全部完成。"},{"type":"tfng","q":"Statement: The passage treats a successful login as proof that the patient understands the record.","options":["True","False","Not Given"],"answer":1,"why":"原文說登入只回答是否能進入，並不能回答理解。","evidence":"A successful login answers only the first."},{"type":"tfng","q":"Statement: The fictional clinic offers telephone and in-person help.","options":["True","False","Not Given"],"answer":0,"why":"第四段明說除數位管道外，也有電話與現場協助。","evidence":"The team also offers help by telephone or in person, recognising that digital access should not become a condition for asking a question about one's care."},{"type":"tfng","q":"Statement: The clinic promises to answer every correction query within two working days.","options":["True","False","Not Given"],"answer":2,"why":"文章說會交代誰查核及如何回覆，但沒有承諾兩個工作天或其他固定期限。","evidence":"The clinic explains who will review the query and how a response will be provided."},{"type":"detail","q":"What risk concerning downloaded documents is mentioned?","options":["They are automatically deleted before anyone can read them.","They can be read only while the portal is open.","Other people may see them on a shared device."],"answer":2,"why":"第三段引述 NHS 提醒，共用裝置可能讓他人看到已下載健康文件。","evidence":"The guidance also warns that downloaded health documents may be visible to other people on a shared device."},{"type":"vocab","q":"In paragraph D, \\"discrepancy\\" refers to…","options":["a guaranteed act of deliberate dishonesty","a difference or inconsistency that needs checking","a new password issued to every user"],"answer":1,"why":"此處 discrepancy 指病歷日期出現不一致，需要查核，並不直接等於故意錯誤。"},{"type":"evidence","q":"What can be inferred when a follow-up letter is not visible?","options":["More information is needed before concluding that no plan exists.","The portal contains every document held anywhere in the health system.","The patient’s entire care plan must have been cancelled."],"answer":0,"why":"第二段明說畫面缺信不能單獨證明沒有計畫，須查詢其範圍與原因。","evidence":"For a patient looking for a follow-up letter, the absence of that letter on the screen does not by itself establish that no plan exists."},{"type":"detail","q":"How does the fictional clinic respond to a query about an incorrect date?","options":["It tells the patient to overwrite the clinical record without review.","It removes every route for contacting staff about records.","It explains who will review it and how a response will be given."],"answer":2,"why":"第四段直接描述查核負責人與回覆流程。","evidence":"The clinic explains who will review the query and how a response will be provided."},{"type":"evidence","q":"Why should activated account totals not be the sole measure of success?","options":["They prove that telephone help has become unnecessary.","They do not show whether users can locate information or resolve questions.","They establish that every copied document remains private."],"answer":1,"why":"第五段另查未解決問題與尋找資料的困難，顯示帳號數沒有涵蓋這些實際成果。","evidence":"It examines unresolved enquiries, difficulty finding documents and whether users understand the available support."},{"revision":1,"type":"main","q":"Which idea best captures the passage’s view of access?","options":["It is an opportunity that needs clear boundaries, support and privacy safeguards.","Its main value is to show patients which follow-up decisions have already been made.","Its benefits depend chiefly on how many records each provider adds to the portal."],"answer":0,"why":"全文說明開放資料能促進對話，也要講清楚資料範圍、查詢與更正管道，並保護下載副本的隱私。單靠畫面沒有某份文件不能判斷是否有後續計畫。"},{"type":"tfng","q":"Statement: The clinic asked the patient to silently rewrite the clinical record.","options":["True","False","Not Given"],"answer":1,"why":"診所安排查核並說明回應方式，沒有要求病人自行改寫紀錄。","evidence":"It does not ask the patient to silently rewrite the clinical record","additional":true}]},{"id":"b2-hard-scholarship","level":"B2","band":"hard","title":"Did the Grant Make the Difference?","topic":"教育補助與因果推論","words":465,"ielts":true,"paras":["A fictional college wants to know whether a small travel grant helps students complete a demanding placement. In an invented classroom dataset, eighteen of twenty grant recipients finish the placement, compared with fourteen of twenty students who receive no grant. The completion rates are therefore ninety and seventy per cent, a difference of twenty percentage points. The difference is clear. Its explanation is less certain, because the groups were not created by random allocation and may differ in ways that also affect completion.","Applications required students to submit documents before the placement began. Those able to complete the process early might already have more reliable support or fewer competing demands. Alternatively, the college might have prioritised students facing the greatest difficulty. Either pattern could affect the comparison, but the dataset alone does not establish which occurred. The analyst must inspect the selection process rather than invent a convenient story about it. Observing that two groups differ is not the same as isolating the contribution of one payment.","The team next asks what the grant is intended to change. A payment could help with travel costs, but a late payment might arrive after a student has already missed essential journeys. The evaluation should therefore record timing and whether the assistance reached the expense it was meant to address. It should also distinguish completion from other possible outcomes, such as reduced financial pressure. A programme could make a meaningful difference to students without changing every outcome in the same way, although that claim would require its own evidence.","For a future trial, the college considers a clearer comparison among eligible applicants when there are not enough places in the programme for everyone. Any allocation process would need an appropriate ethical and administrative review. Random allocation, where justified and feasible, could reduce systematic differences in how groups are formed, but it would not remove every practical problem. Missing follow-up information, changes in the programme and uncertainty from small numbers would still need attention. The passage proposes questions for a better evaluation, not permission to withhold existing support from students.","The final report keeps the observed figures and the causal conclusion separate. It can accurately state that recipients had a higher completion rate in this invented dataset. It cannot, from those figures alone, claim that the grant caused the entire difference. Nor does the uncertainty prove that the grant had no effect. The sensible next step is to identify which additional evidence could distinguish competing explanations and improve the programme. A cautious conclusion may sound less decisive than a promotional headline, but it gives the college a firmer basis for deciding what to continue, change or investigate. The purpose of evaluation is to make support more useful, not merely to supply the most flattering interpretation of an attractive result."],"zh":"虛構學院想知道交通補助是否幫助完成實習。教學資料中，20 名領取者有 18 名完成，20 名未領取者有 14 名完成，分別是 90％與 70％，差 20 個百分點。差異確實存在，但兩組不是隨機形成，其他差異也可能影響完成情況。\\n\\n申請需在實習前交文件，能早完成者可能本來支援較多、負擔較少；也可能學院優先給最困難者。資料本身不能證明哪一種發生，必須看選擇程序，而不能編一個方便解釋的故事。兩組不同，不等於已隔離出一筆補助的影響。\\n\\n團隊再問補助預期改變什麼。錢能幫交通費，但若太晚發，學生可能已錯過重要行程，因此需記錄時點與是否真正處理目標支出，也應區分完成率與財務壓力等其他成果。計畫可能改善其中一些而非全部，但各項主張都要證據。\\n\\n未來若名額不足，可考慮在合格申請者中建立更清楚的比較，任何分配都須適當倫理與行政審查。合宜可行的隨機分配能減少組成方式的系統差異，但缺失追蹤、計畫改變與小樣本不確定仍需處理；本文不是允許剝奪原有支援。\\n\\n報告把觀察數字與因果結論分開：可說領取者完成率較高，不能只憑這些數字宣稱全部差異由補助造成，也不能因不確定就說補助沒效果。下一步是找能區分不同解釋的證據，讓支援更有用，而不是只挑最好看的解讀。","qs":[{"type":"heading","q":"Which heading best fits paragraph B (paragraph 2)?","options":["Proof that every recipient already had more support","A calculation showing that the completion rates are identical","How selection into the groups could affect the comparison"],"answer":2,"why":"第二段提出選擇程序造成差異的兩種可能，並要求查證而非假定。"},{"type":"tfng","q":"Statement: The observed figures alone establish that the grant caused the entire completion-rate difference.","options":["True","False","Not Given"],"answer":1,"why":"最後一段直接否定只靠這些數字就能作出完整因果歸因。","evidence":"It cannot, from those figures alone, claim that the grant caused the entire difference."},{"type":"tfng","q":"Statement: In the invented data, eighteen out of twenty recipients completed the placement.","options":["True","False","Not Given"],"answer":0,"why":"開頭明確交代這組教學數字。","evidence":"In an invented classroom dataset, eighteen of twenty grant recipients finish the placement, compared with fourteen of twenty students who receive no grant."},{"type":"tfng","q":"Statement: Applicants had to submit travel-cost records before the college selected recipients.","options":["True","False","Not Given"],"answer":2,"why":"文章要求先交文件，但未列文件種類；不能自行認定包含交通支出紀錄。","evidence":"Applications required students to submit documents before the placement began."},{"type":"detail","q":"What is the difference between the two completion rates?","options":["Twenty percentage points","Twenty per cent of the recipient rate","Four percentage points"],"answer":0,"why":"90％減 70％是 20 個百分點；人數差 4 不能當成 4 個百分點。","evidence":"The completion rates are therefore ninety and seventy per cent, a difference of twenty percentage points."},{"type":"vocab","q":"In paragraph E, \\"causal\\" refers to…","options":["whether a report contains any descriptive information","whether one factor brings about an outcome","whether two numbers can be written as percentages"],"answer":1,"why":"causal 指因果關係，超過單純描述兩組數值差異。"},{"type":"evidence","q":"Why does the timing of payment matter to the evaluation?","options":["Any payment automatically guarantees completion regardless of when it arrives.","The dataset proves that all recipients received their money too late.","Support arriving after essential journeys are missed may not address the intended barrier."],"answer":2,"why":"第三段指出若錢太晚，原本要解決的交通障礙可能已造成後果；這是需調查的情況，不是已知全員如此。","evidence":"A payment could help with travel costs, but a late payment might arrive after a student has already missed essential journeys."},{"type":"detail","q":"Which issues would still need attention even with random allocation?","options":["Missing follow-up data, programme changes and uncertainty from small numbers","No issues, because random allocation removes all uncertainty","Only the colour of the application form"],"answer":0,"why":"第四段明列即使隨機分配仍存在的實務與統計限制。","evidence":"Missing follow-up information, changes in the programme and uncertainty from small numbers would still need attention."},{"type":"evidence","q":"What does uncertainty about the cause allow the report to conclude?","options":["The entire observed difference must have been caused by the grant.","The effect remains unresolved; uncertainty does not establish that the effect is zero.","The grant definitely had no effect on any student."],"answer":1,"why":"末段指出不能把不確定轉成無效的證明，也不能反過來全部歸因。","evidence":"Nor does the uncertainty prove that the grant had no effect."},{"type":"main","q":"What is the passage’s central distinction?","options":["A large grant versus a small grant with a known universal effect","Describing data versus refusing to use any evidence","An observed difference versus evidence that identifies its cause"],"answer":2,"why":"全文利用虛構資料區分描述差異與推論原因，並提出改善評估的方向。"},{"type":"tfng","q":"Statement: The final report says the grant cannot have made any difference at all.","options":["True","False","Not Given"],"answer":1,"why":"結尾說資料不足以確定津貼造成全部差異，也不能據此認定津貼毫無效果。","evidence":"Nor does the uncertainty prove that the grant had no effect.","additional":true}]}]`);export{e as default};
